const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const flapStrength = -10;
const gapHeight = 150;
const pipeWidth = 70;
const pipeGap = 120;
const birdSize = 30;
const birdX = 50;
let birdY = canvas.height / 2;
let birdVelocity = 0;
let score = 0;
let pipes = [];
let lastPipeTime = 0;
let pipeInterval = 1500; // milliseconds

function getRandomGapY() {
    return Math.random() * (canvas.height - gapHeight - 200) + 100;
}

function addPipe() {
    const gapY = getRandomGapY();
    pipes.push({
        x: canvas.width,
        y: gapY,
        passed: false
    });
}

function update() {
    birdVelocity += gravity;
    birdY += birdVelocity;

    if (birdY < 0 || birdY > canvas.height) {
        gameOver();
    }

    const now = Date.now();
    if (now - lastPipeTime > pipeInterval) {
        lastPipeTime = now;
        addPipe();
    }

    pipes.forEach(pipe => {
        pipe.x -= 2;
        if (pipe.x + pipeWidth < birdX && !pipe.passed) {
            pipe.passed = true;
            score++;
        }
        if (birdX < pipe.x + pipeWidth && birdX + birdSize > pipe.x &&
            (birdY < pipe.y || birdY + birdSize > pipe.y + gapHeight)) {
            gameOver();
        }
    });

    pipes = pipes.filter(pipe => pipe.x > -pipeWidth);
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw bird
    ctx.fillStyle = 'yellow';
    ctx.fillRect(birdX, birdY, birdSize, birdSize);

    // Draw pipes
    ctx.fillStyle = 'green';
    pipes.forEach(pipe => {
        ctx.fillRect(pipe.x, 0, pipeWidth, pipe.y);
        ctx.fillRect(pipe.x, pipe.y + gapHeight, pipeWidth, canvas.height);
    });

    // Draw score
    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText('Score: ' + score, 10, 30);
}

function gameOver() {
    ctx.fillStyle = 'red';
    ctx.font = '48px Arial';
    ctx.fillText('Game Over!', canvas.width / 2 - 100, canvas.height / 2);
    clearInterval(gameLoop);
    canvas.addEventListener('click', restartGame);
}

function restartGame() {
    birdY = canvas.height / 2;
    birdVelocity = 0;
    score = 0;
    pipes = [];
    lastPipeTime = 0;
    canvas.removeEventListener('click', restartGame);
    gameLoop = setInterval(step, 16); // roughly 60 FPS
}

function step() {
    update();
    draw();
}

canvas.addEventListener('click', () => birdVelocity = flapStrength);

let gameLoop = setInterval(step, 16); // roughly 60 FPS
```

