class Skill {
  constructor(name, level = 1) {
    this.name = name;
    this.level = level;
  }

  levelUp() {
    this.level++;
    console.log(`${this.name} leveled up to level ${this.level}`);
  }
}

class Experience {
  constructor(totalExp = 0) {
    this.totalExp = totalExp;
  }

  addExp(exp) {
    this.totalExp += exp;
    console.log(`Added ${exp} experience. Total: ${this.totalExp}`);
  }
}

class LevelUp {
  constructor(skill, experience, levelThreshold = 1000) {
    this.skill = skill;
    this.experience = experience;
    this.levelThreshold = levelThreshold;
  }

  checkLevelUp() {
    if (this.experience.totalExp >= this.levelThreshold) {
      this.skill.levelUp();
      this.experience.totalExp -= this.levelThreshold;
      console.log(`Experience threshold reached. Remaining experience: ${this.experience.totalExp}`);
    }
  }
}

class Economy {
  constructor(money = 1000) {
    this.money = money;
  }

  canAfford(price) {
    return this.money >= price;
  }

  debit(price) {
    if (this.canAfford(price)) {
      this.money -= price;
      console.log(`Debited ${price} money. Remaining: ${this.money}`);
      return true;
    } else {
      console.log(`Not enough money to afford ${price}. Current money: ${this.money}`);
      return false;
    }
  }
}

class Inventory {
  constructor(items = []) {
    this.items = items;
  }

  addItem(item) {
    this.items.push(item);
    console.log(`Added item to inventory: ${item}`);
  }
}

class Store {
  constructor(prices, economy, inventory) {
    this.prices = prices;
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(itemName) {
    const price = this.prices[itemName];
    if (price !== undefined && this.economy.debit(price)) {
      this.inventory.addItem(itemName);
      console.log(`Purchased ${itemName} for ${price}.`);
    } else {
      console.log(`Purchase failed for ${itemName}.`);
    }
  }
}

// Demo
const economy = new Economy();
const inventory = new Inventory();
const prices = { skillBook: 200, experiencePotion: 100 };
const store = new Store(prices, economy, inventory);

const skill = new Skill('Fireball');
const experience = new Experience();
const levelUp = new LevelUp(skill, experience);

// Purchase items
store.purchase('skillBook'); // Should succeed
store.purchase('experiencePotion'); // Should succeed
store.purchase('skillBook'); // Should succeed

// Add experience
experience.addExp(500);
experience.addExp(600);

// Check level up
levelUp.checkLevelUp();
