class DialogueSystem {
    constructor() {
        this.dialogues = {};
    }

    addDialogue(key, text) {
        this.dialogues[key] = text;
    }

    getDialogue(key) {
        return this.dialogues[key] || "No dialogue found.";
    }
}

// Flags System
class FlagsSystem {
    constructor() {
        this.flags = {};
    }

    setFlag(key, value) {
        this.flags[key] = value;
    }

    getFlag(key) {
        return this.flags[key] || false;
    }
}

// Quest System
class QuestSystem {
    constructor() {
        this.quests = {};
    }

    addQuest(key, description) {
        this.quests[key] = { description, completed: false };
    }

    completeQuest(key) {
        if (this.quests[key]) {
            this.quests[key].completed = true;
        }
    }

    getQuestStatus(key) {
        const quest = this.quests[key];
        return quest ? `${quest.description} - ${quest.completed ? 'Completed' : 'Incomplete'}` : "Quest not found.";
    }
}

// Coordinator to wire systems together
class GameCoordinator {
    constructor() {
        this.dialogueSystem = new DialogueSystem();
        this.flagsSystem = new FlagsSystem();
        this.questSystem = new QuestSystem();
    }

    startGame() {
        console.log(this.dialogueSystem.getDialogue('start'));
        this.flagsSystem.setFlag('gameStarted', true);
        this.questSystem.addQuest('findTreasure', 'Find the hidden treasure in the forest.');
    }

    completeQuest() {
        this.questSystem.completeQuest('findTreasure');
        console.log(this.questSystem.getQuestStatus('findTreasure'));
        console.log(this.dialogueSystem.getDialogue('questComplete'));
    }
}

// Runnable demo
