const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const FPS = 60;
const FIXED_TIMESTEP = 1000 / FPS;
let accumulator = 0;
let lastFrameTime = performance.now();

const PLANT_GROWTH_SPEED = 0.1;
const OPPONENT_PLANT_GROWTH_SPEED = 0.08;

class Plant {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.height = 0;
    this.growSpeed = PLANT_GROWTH_SPEED;
  }

  update(dt) {
    this.height += this.growSpeed * dt;
  }

  draw() {
    ctx.fillStyle = 'green';
    ctx.fillRect(this.x, this.y - this.height, 10, this.height);
  }
}

class Opponent {
  constructor() {
    this.plants = [];
    for (let i = 0; i < 5; i++) {
      this.plants.push(new Plant(100 + i * 20, 500));
    }
  }

  update(dt) {
    this.plants.forEach(plant => {
      plant.growSpeed = OPPONENT_PLANT_GROWTH_SPEED;
      plant.update(dt);
    });
  }

  draw() {
    this.plants.forEach(plant => plant.draw());
  }
}

const player = {
  plants: [],
  addPlant(x, y) {
    this.plants.push(new Plant(x, y));
  },
  update(dt) {
    this.plants.forEach(plant => plant.update(dt));
  },
  draw() {
    this.plants.forEach(plant => plant.draw());
  }
};

const opponent = new Opponent();

canvas.addEventListener('click', (event) => {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;
  player.addPlant(x, y);
});

function gameLoop() {
  const now = performance.now();
  const dt = now - lastFrameTime;
  lastFrameTime = now;
  accumulator += dt;

  while (accumulator >= FIXED_TIMESTEP) {
    player.update(FIXED_TIMESTEP);
    opponent.update(FIXED_TIMESTEP);
    accumulator -= FIXED_TIMESTEP;
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  player.draw();
  opponent.draw();

  requestAnimationFrame(gameLoop);
}

gameLoop();
