const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore'), 10) : 0;
let fish = [];
let gameRunning = false;
let lastTime = 0;

const fishImage = new Image();
fishImage.src = 'https://via.placeholder.com/50/FF0000/FFFFFF?text=Fish';

function resizeCanvas() {
  const dpr = window.devicePixelRatio || 1;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);

class Fish {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.size = 50;
    this.speed = Math.random() * 2 + 1;
  }

  draw() {
    ctx.drawImage(fishImage, this.x, this.y, this.size, this.size);
  }

  update() {
    this.y += this.speed;
    if (this.y > canvas.height) {
      this.y = -this.size;
      this.x = Math.random() * (canvas.width - this.size);
    }
  }

  isCaught(mouseX, mouseY) {
    return mouseX > this.x && mouseX < this.x + this.size &&
           mouseY > this.y && mouseY < this.y + this.size;
  }
}

function createFish() {
  if (Math.random() < 0.05) {
    fish.push(new Fish(Math.random() * (canvas.width - 50), -50));
  }
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  fish.forEach(fish => {
    fish.update();
    fish.draw();
  });

  createFish();

  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 20);
  ctx.fillText(`High Score: ${highScore}`, 10, 40);
}

function gameLoop(timestamp) {
  if (!gameRunning) return;
  const deltaTime = timestamp - lastTime;
  lastTime = timestamp;

  update();
  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', (event) => {
  if (!gameRunning) return;

  const rect = canvas.getBoundingClientRect();
  const mouseX = event.clientX - rect.left;
  const mouseY = event.clientY - rect.top;

  fish = fish.filter(fish => {
    if (fish.isCaught(mouseX, mouseY)) {
      score++;
      return false;
    }
    return true;
  });

  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore);
  }
});

function startGame() {
  score = 0;
  fish = [];
  gameRunning = true;
  lastTime = performance.now();
  requestAnimationFrame(gameLoop);
}

function stopGame() {
  gameRunning = false;
}

startGame();
