class RarityTable {
  constructor(rarityMap) {
    this.rarityMap = rarityMap;
  }

  getRandomItem() {
    const totalWeight = Object.values(this.rarityMap).reduce((sum, weight) => sum + weight, 0);
    let random = Math.random() * totalWeight;
    for (const [item, weight] of Object.entries(this.rarityMap)) {
      random -= weight;
      if (random < 0) {
        return item;
      }
    }
    return null; // This should never happen if the rarityMap is properly normalized
  }
}

class Loot {
  constructor(rarityTable) {
    this.rarityTable = rarityTable;
  }

  generateLoot() {
    return this.rarityTable.getRandomItem();
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
  }

  displayInventory() {
    return JSON.stringify(this.items, null, 2);
  }
}

// Demo
const rarityMap = {
  'Common': 50,
  'Uncommon': 30,
  'Rare': 15,
  'Epic': 4,
  'Legendary': 1
};

const rarityTable = new RarityTable(rarityMap);
const lootSystem = new Loot(rarityTable);
const inventorySystem = new Inventory();

for (let i = 0; i < 100; i++) {
  const item = lootSystem.generateLoot();
  inventorySystem.addItem(item);
}

console.log('Inventory:', inventorySystem.displayInventory());
