class Dialogue {
  constructor(flags, quest) {
    this.flags = flags;
    this.quest = quest;
  }

  startDialogue() {
    if (this.flags.getFlag('metNPC') === false) {
      console.log("NPC: Hello! I've been expecting you.");
      this.flags.setFlag('metNPC', true);
    } else if (this.flags.getFlag('metNPC') === true && !this.quest.isQuestComplete('fetchItem')) {
      console.log("NPC: How's the quest going?");
    } else {
      console.log("NPC: Thanks for your help!");
    }
  }
}

class Flags {
  constructor() {
    this.flags = {};
  }

  setFlag(flag, value) {
    this.flags[flag] = value;
  }

  getFlag(flag) {
    return this.flags[flag];
  }
}

class Quest {
  constructor(flags) {
    this.flags = flags;
    this.quests = {};
  }

  startQuest(questName) {
    if (!this.quests[questName]) {
      console.log(`Quest started: ${questName}`);
      this.quests[questName] = false;
    } else {
      console.log(`Quest already started: ${questName}`);
    }
  }

  completeQuest(questName) {
    if (this.quests[questName]) {
      console.log(`Quest completed: ${questName}`);
      this.quests[questName] = true;
    } else {
      console.log(`Quest not found: ${questName}`);
    }
  }

  isQuestComplete(questName) {
    return this.quests[questName] || false;
  }
}

// Demo
const flags = new Flags();
const quest = new Quest(flags);
const dialogue = new Dialogue(flags, quest);

quest.startQuest('fetchItem');
dialogue.startDialogue(); // Should trigger first dialogue
dialogue.startDialogue(); // Should trigger second dialogue
quest.completeQuest('fetchItem');
dialogue.startDialogue(); // Should trigger third dialogue
