const canvas = document.createElement('canvas');
canvas.width = 300;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const BLOCK_SIZE = 30;
const GRID_WIDTH = canvas.width / BLOCK_SIZE;
const GRID_HEIGHT = canvas.height / BLOCK_SIZE;

class Block {
    constructor(x, y, color) {
        this.x = x;
        this.y = y;
        this.color = color;
    }

    draw() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x * BLOCK_SIZE, this.y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
    }

    moveDown() {
        this.y++;
    }
}

class Tetromino {
    constructor(x, y, blocks) {
        this.x = x;
        this.y = y;
        this.blocks = blocks.map(block => new Block(block[0] + x, block[1] + y, 'blue'));
    }

    draw() {
        this.blocks.forEach(block => block.draw());
    }

    moveDown() {
        this.blocks.forEach(block => block.moveDown());
    }

    moveLeft() {
        this.blocks.forEach(block => block.x--);
    }

    moveRight() {
        this.blocks.forEach(block => block.x++);
    }

    rotate() {
        const center = this.blocks[Math.floor(this.blocks.length / 2)];
        this.blocks = this.blocks.map(block => {
            const dx = block.x - center.x;
            const dy = block.y - center.y;
            return new Block(center.x - dy, center.y + dx, block.color);
        });
    }

    canMoveDown() {
        return this.blocks.every(block => block.y + 1 < GRID_HEIGHT && !this.collidesWithBlock(block.x, block.y + 1));
    }

    canMoveLeft() {
        return this.blocks.every(block => block.x - 1 >= 0 && !this.collidesWithBlock(block.x - 1, block.y));
    }

    canMoveRight() {
        return this.blocks.every(block => block.x + 1 < GRID_WIDTH && !this.collidesWithBlock(block.x + 1, block.y));
    }

    collidesWithBlock(x, y) {
        return grid[y] && grid[y][x];
    }
}

const SHAPES = [
    [[0, 0], [1, 0], [2, 0], [3, 0]], // I
    [[0, 0], [0, 1], [1, 1], [2, 1]], // O
    [[0, 0], [1, 0], [1, 1], [2, 1]], // T
    [[0, 0], [0, 1], [1, 0], [1, 1]], // S
    [[0, 1], [1, 0], [1, 1], [2, 0]], // Z
    [[0, 1], [1, 1], [1, 0], [2, 0]], // J
    [[0, 0], [1, 0], [1, 1], [2, 1]]  // L
];

let grid = Array.from({ length: GRID_HEIGHT }, () => Array(GRID_WIDTH).fill(null));
let currentTetromino = null;
let nextTetromino = null;
let score = 0;
let highScore = localStorage.getItem('highScore') || 0;
let lastTime = 0;
const TIME_STEP = 1000 / 5; // 5 blocks per second

function resetTetromino() {
    currentTetromino = nextTetromino;
    nextTetromino = new Tetromino(Math.floor(GRID_WIDTH / 2) - 2, 0, SHAPES[Math.floor(Math.random() * SHAPES.length)]);
    if (!currentTetromino.canMoveDown()) {
        gameover();
    }
}

function gameover() {
    ctx.fillStyle = 'red';
    ctx.font = '30px Arial';
    ctx.fillText('Game Over', 50, canvas.height / 2);
    if (score > highScore) {
        highScore = score;
        localStorage.setItem('highScore', highScore);
    }
    score = 0;
    grid = Array.from({ length: GRID_HEIGHT }, () => Array(GRID_WIDTH).fill(null));
    resetTetromino();
}

function lockTetromino() {
    currentTetromino.blocks.forEach(block => {
        grid[block.y][block.x] = block;
    });
    removeFullRows();
    resetTetromino();
}

function removeFullRows() {
    let fullRows = [];
    grid.forEach((row, y) => {
        if (row.every(block => block)) {
            fullRows.push(y);
        }
    });

    fullRows.forEach(row => {
        grid.splice(row, 1);
        grid.unshift(Array(GRID_WIDTH).fill(null));
    });

    score += fullRows.length * 100;
}

function update(time) {
    const deltaTime = time - lastTime;
    lastTime = time;

    if (currentTetromino && currentTetromino.canMoveDown()) {
        currentTetromino.moveDown();
    } else if (currentTetromino) {
        lockTetromino();
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawGrid();
    currentTetromino?.draw();
    nextTetromino?.draw();
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`High Score: ${highScore}`, 10, 60);

    if (deltaTime >= TIME_STEP) {
        update(time);
    } else {
        requestAnimationFrame(time => update(time + deltaTime));
    }
}

function drawGrid() {
    ctx.strokeStyle = '#ddd';
    for (let x = 0; x < GRID_WIDTH; x++) {
        for (let y = 0; y < GRID_HEIGHT; y++) {
            ctx.strokeRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
            if (grid[y][x]) {
                grid[y][x].draw();
            }
        }
    }
}

document.addEventListener('keydown', event => {
    if (currentTetromino) {
        switch (event.key) {
            case 'ArrowLeft':
                if (currentTetromino.canMoveLeft()) {
                    currentTetromino.moveLeft();
                }
                break;
            case 'ArrowRight':
                if (currentTetromino.canMoveRight()) {
                    currentTetromino.moveRight();
                }
                break;
            case 'ArrowDown':
                if (currentTetromino.canMoveDown()) {
                    currentTetromino.moveDown();
                }
                break;
            case 'ArrowUp':
                currentTetromino.rotate();
                break;
        }
    }
});

resetTetromino();
nextTetromino = new Tetromino(Math.floor(GRID_WIDTH / 2) - 2, 0, SHAPES[Math.floor(Math.random() * SHAPES.length)]);
requestAnimationFrame(update);
