const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio || 1;
function resizeCanvas() {
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  canvas.style.width = window.innerWidth + 'px';
  canvas.style.height = window.innerHeight + 'px';
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

const asteroids = [];
const bullets = [];
const ship = { x: canvas.width / 2, y: canvas.height / 2, angle: 0, speed: 0, r: 5 };
let combo = 0;
let score = 0;
let gameRunning = true;

function random(min, max) {
  return Math.random() * (max - min) + min;
}

function createAsteroid(x, y, r, speed, angle) {
  return { x, y, r, speed, angle };
}

function updateAsteroids() {
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.x += a.speed * Math.cos(a.angle);
    a.y += a.speed * Math.sin(a.angle);
    if (a.x < -a.r || a.x > canvas.width + a.r || a.y < -a.r || a.y > canvas.height + a.r) {
      asteroids.splice(i, 1);
    }
  }
}

function drawAsteroids() {
  for (const a of asteroids) {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
    ctx.fillStyle = 'gray';
    ctx.fill();
    ctx.closePath();
  }
}

function createBullet(x, y, angle, speed) {
  return { x, y, angle, speed, r: 2 };
}

function updateBullets() {
  for (let i = bullets.length - 1; i >= 0; i--) {
    const b = bullets[i];
    b.x += b.speed * Math.cos(b.angle);
    b.y += b.speed * Math.sin(b.angle);
    if (b.x < -b.r || b.x > canvas.width + b.r || b.y < -b.r || b.y > canvas.height + b.r) {
      bullets.splice(i, 1);
    }
  }
}

function drawBullets() {
  for (const b of bullets) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fillStyle = 'white';
    ctx.fill();
    ctx.closePath();
  }
}

function updateShip() {
  ship.x += ship.speed * Math.cos(ship.angle);
  ship.y += ship.speed * Math.sin(ship.angle);
  ship.x = (ship.x + canvas.width) % canvas.width;
  ship.y = (ship.y + canvas.height) % canvas.height;
}

function drawShip() {
  ctx.beginPath();
  ctx.moveTo(ship.x + ship.r * Math.cos(ship.angle - Math.PI / 3), ship.y + ship.r * Math.sin(ship.angle - Math.PI / 3));
  ctx.lineTo(ship.x + ship.r * Math.cos(ship.angle + Math.PI / 3), ship.y + ship.r * Math.sin(ship.angle + Math.PI / 3));
  ctx.lineTo(ship.x + ship.r * Math.cos(ship.angle + Math.PI), ship.y + ship.r * Math.sin(ship.angle + Math.PI));
  ctx.fillStyle = 'green';
  ctx.fill();
  ctx.closePath();
}

function checkCollisions() {
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    for (let j = bullets.length - 1; j >= 0; j--) {
      const b = bullets[j];
      const dx = a.x - b.x;
      const dy = a.y - b.y;
      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance < a.r + b.r) {
        bullets.splice(j, 1);
        asteroids.splice(i, 1);
        score += 10 * combo;
        combo++;
        break;
      }
    }
    const dx = a.x - ship.x;
    const dy = a.y - ship.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < a.r + ship.r) {
      gameRunning = false;
    }
  }
}

function drawScore() {
  ctx.font = '20px Arial';
  ctx.fillStyle = 'white';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Combo: ${combo}`, 10, 60);
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  if (gameRunning) {
    updateShip();
    updateAsteroids();
    updateBullets();
    checkCollisions();
    drawShip();
    drawAsteroids();
    drawBullets();
    drawScore();
  } else {
    ctx.font = '40px Arial';
    ctx.fillStyle = 'red';
    ctx.fillText('Game Over', canvas.width / 2 - 80, canvas.height / 2);
  }
  requestAnimationFrame(gameLoop);
}

function startGame() {
  for (let i = 0; i < 10; i++) {
    asteroids.push(createAsteroid(random(0, canvas.width), random(0, canvas.height), random(10, 30), random(0.5, 2), random(0, Math.PI * 2)));
  }
  gameRunning = true;
  score = 0;
  combo = 0;
  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowUp') {
    ship.speed += 0.1;
  } else if (e.key === 'ArrowDown') {
    ship.speed -= 0.1;
  } else if (e.key === 'ArrowLeft') {
    ship.angle -= 0.05;
  } else if (e.key === 'ArrowRight') {
    ship.angle += 0.05;
  } else if (e.key === ' ') {
    bullets.push(createBullet(ship.x + ship.r * Math.cos(ship.angle), ship.y + ship.r * Math.sin(ship.angle), ship.angle, 5));
  }
});

canvas.addEventListener('keyup', (e) => {
  if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
    ship.speed = 0;
  }
});

