class EnemyPool {
  constructor() {
    this.pool = [];
    for (let i = 0; i < 5; i++) {
      this.pool.push(`Enemy ${i + 1}`);
    }
  }

  acquireEnemy() {
    if (this.pool.length === 0) {
      console.log("No enemies available in the pool.");
      return null;
    }
    return this.pool.pop();
  }

  releaseEnemy(enemy) {
    this.pool.push(enemy);
    console.log(`Released enemy back to the pool: ${enemy}`);
  }
