class Pricing {
    constructor(pricingData) {
        this.pricingData = pricingData;
    }

    getBasePrice(item) {
        return this.pricingData[item] || 0;
    }

    applyDiscount(price, discount) {
        return price * (1 - (discount / 100));
    }
}

class Demand {
    constructor(demandData) {
        this.demandData = demandData;
    }

    getDemand(item) {
        return this.demandData[item] || 0;
    }

    calculatePriceImpact(price, demand) {
        return price * (1 + (demand / 100));
    }
}

class Store {
    constructor(pricingSystem, demandSystem) {
        this.pricingSystem = pricingSystem;
        this.demandSystem = demandSystem;
    }

    sellItem(item, discount = 0) {
        const basePrice = this.pricingSystem.getBasePrice(item);
        const demand = this.demandSystem.getDemand(item);
        const discountedPrice = this.pricingSystem.applyDiscount(basePrice, discount);
        const finalPrice = this.demandSystem.calculatePriceImpact(discountedPrice, demand);
        return finalPrice;
    }
}

