class Hunger {
  constructor(initialLevel = 100) {
    this.level = initialLevel;
  }

  eat(amount = 10) {
    this.level = Math.min(100, this.level + amount);
    console.log(`Ate ${amount} units of food. Hunger level: ${this.level}`);
  }

  consume(amount = 5) {
    this.level = Math.max(0, this.level - amount);
    console.log(`Consumed ${amount} units of food. Hunger level: ${this.level}`);
  }
}

class Energy {
  constructor(initialLevel = 100) {
    this.level = initialLevel;
  }

  rest(amount = 10) {
    this.level = Math.min(100, this.level + amount);
    console.log(`Rested ${amount} units. Energy level: ${this.level}`);
  }

  use(amount = 5) {
    this.level = Math.max(0, this.level - amount);
    console.log(`Used ${amount} units of energy. Energy level: ${this.level}`);
  }
}

class Clock {
  constructor() {
    this.time = 0;
  }

  tick() {
    this.time += 1;
    console.log(`Time has passed. Current time: ${this.time}`);
  }

  isTimeForMeal() {
    return this.time % 6 === 0; // Every 6 ticks
  }

  isTimeForRest() {
    return this.time % 8 === 0; // Every 8 ticks
  }
}

