class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return this.ingredients;
  }
}

class Crafting {
  constructor(recipes) {
    this.recipes = new Map();
    recipes.forEach(recipe => {
      this.recipes.set(recipe.getName(), recipe);
    });
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.get(recipeName);
    if (!recipe) return false;

    const ingredients = recipe.getIngredients();
    for (const [ingredient, quantity] of Object.entries(ingredients)) {
      if (inventory.getQuantity(ingredient) < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName, inventory) {
    if (!this.canCraft(recipeName, inventory)) {
      throw new Error(`Cannot craft ${recipeName}`);
    }

    const recipe = this.recipes.get(recipeName);
    const ingredients = recipe.getIngredients();
    for (const [ingredient, quantity] of Object.entries(ingredients)) {
      inventory.decreaseQuantity(ingredient, quantity);
    }

    return recipe.getName();
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  addItem(item, quantity = 1) {
    this.items.set(item, (this.items.get(item) || 0) + quantity);
  }

  getQuantity(item) {
    return this.items.get(item) || 0;
  }

  decreaseQuantity(item, quantity) {
    if (this.getQuantity(item) < quantity) {
      throw new Error(`Not enough ${item}`);
    }
    this.items.set(item, this.getQuantity(item) - quantity);
  }
}

class Economy {
  constructor(prices) {
    this.prices = prices; // { itemName: price }
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  debit(item, quantity) {
    const price = this.getPrice(item);
    if (quantity * price > this.getTotalMoney()) {
      throw new Error(`Not enough money`);
    }
    // Simulate debiting money
    console.log(`Debited ${quantity * price} for ${quantity} ${item}(s)`);
  }

  getTotalMoney() {
    // Simulate total money in the economy
    return 1000; // arbitrary value for demonstration
  }
}

class Store {
  constructor(inventory, economy) {
    this.inventory = inventory;
    this.economy = economy;
  }

  purchase(item, quantity) {
    const price = this.economy.getPrice(item);
    if (price * quantity > this.economy.getTotalMoney()) {
      throw new Error(`Item ${item} is too expensive`);
    }

    this.economy.debit(item, quantity);
    this.inventory.addItem(item, quantity);
    console.log(`Purchased ${quantity} ${item}(s)`);
  }
}

