class Tile {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.walkable = true;
        this.color = Math.random() > 0.5 ? '#00FF00' : '#FF0000';
    }

    draw() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x * TILE_SIZE, this.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    }

    click() {
        if (this.walkable) {
            this.color = '#0000FF';
            this.walkable = false;
            combo++;
            if (lastTileClicked && lastTileClicked.walkable) {
                combo = 1; // Reset combo if last tile was not walkable
            }
            lastTileClicked = this;
        }
    }
}

function createRoom() {
    for (let y = 0; y < ROOM_HEIGHT; y++) {
        for (let x = 0; x < ROOM_WIDTH; x++) {
            tiles.push(new Tile(x, y));
        }
    }
}

function drawRoom() {
    tiles.forEach(tile => tile.draw());
    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Combo: ${combo}x`, 10, 30);
}

canvas.addEventListener('click', (event) => {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((event.clientX - rect.left) / TILE_SIZE);
    const y = Math.floor((event.clientY - rect.top) / TILE_SIZE);
    const tile = tiles.find(t => t.x === x && t.y === y);
    if (tile) {
        tile.click();
    }
});

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawRoom();
    requestAnimationFrame(gameLoop);
}

createRoom();
gameLoop();
