const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');

const player = {
  x: 50,
  y: canvas.height - 100,
  width: 50,
  height: 50,
  speed: 5,
  jumping: false,
  velocity: 0,
  gravity: 1.5
};

const opponent = {
  x: canvas.width - 100,
  y: canvas.height - 100,
  width: 50,
  height: 50,
  speed: 2,
  jumping: false,
  velocity: 0,
  gravity: 1.5
};

const groundLevel = canvas.height - 100;

function drawRect(obj, color) {
  ctx.fillStyle = color;
  ctx.fillRect(obj.x, obj.y, obj.width, obj.height);
}

function updatePlayer() {
  if (player.jumping) {
    player.velocity += player.gravity;
    player.y += player.velocity;
    if (player.y + player.height >= groundLevel) {
      player.y = groundLevel - player.height;
      player.jumping = false;
      player.velocity = 0;
    }
  }
}

function updateOpponent() {
  if (opponent.jumping) {
    opponent.velocity += opponent.gravity;
    opponent.y += opponent.velocity;
    if (opponent.y + opponent.height >= groundLevel) {
      opponent.y = groundLevel - opponent.height;
      opponent.jumping = false;
      opponent.velocity = 0;
    }
  } else {
    if (Math.random() < 0.05) {
      opponent.jumping = true;
      opponent.velocity = -15;
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawRect(player, 'blue');
  drawRect(opponent, 'red');
  requestAnimationFrame(draw);
}

function jump(obj) {
  if (!obj.jumping) {
    obj.jumping = true;
    obj.velocity = -15;
  }
}

document.addEventListener('keydown', (e) => {
  if (e.code === 'Space') {
    jump(player);
  }
});

function gameLoop() {
  updatePlayer();
  updateOpponent();
  draw();
}

gameLoop();
