const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const targetText = "Type as fast as you can!";
let currentText = '';
let startTime;
let combo = 0;
let multiplier = 1;
let maxCombo = 0;
let gameRunning = false;

function startGame() {
    currentText = '';
    startTime = Date.now();
    combo = 0;
    multiplier = 1;
    gameRunning = true;
    requestAnimationFrame(gameLoop);
}

function gameLoop() {
    if (!gameRunning) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '30px Arial';
    ctx.fillText('Target: ' + targetText, 10, 50);
    ctx.fillText('Typed: ' + currentText, 10, 100);
    ctx.fillText('Combo: ' + combo + 'x', 10, 150);
    ctx.fillText('Multiplier: ' + multiplier, 10, 200);
    ctx.fillText('Max Combo: ' + maxCombo, 10, 250);

    const elapsed = (Date.now() - startTime) / 1000;
    ctx.fillText('Time: ' + elapsed.toFixed(2) + 's', 10, 300);

    requestAnimationFrame(gameLoop);
}

function checkInput(event) {
    if (!gameRunning) return;

    const inputChar = event.key;
    if (inputChar === targetText[currentText.length]) {
        currentText += inputChar;
        combo++;
        maxCombo = Math.max(maxCombo, combo);
        multiplier = 1 + Math.floor(combo / 10);
    } else {
        combo = 0;
        multiplier = 1;
    }

    if (currentText === targetText) {
        gameRunning = false;
        alert('You win! Your time: ' + (Date.now() - startTime) / 1000 + 's with a multiplier of ' + multiplier);
    }
}

canvas.addEventListener('keydown', checkInput);

startGame();
