const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio;
function resizeCanvas() {
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

let player = {
    x: 50,
    y: canvas.height - 50,
    width: 20,
    height: 20,
    speed: 5
};

let obstacles = [];
let obstacleSpeed = 5;
let obstacleWidth = 30;
let obstacleHeight = 30;
let obstacleInterval = 1000;
let lastObstacleTime = 0;

let countdown = 10;
let countdownInterval = 1000;
let countdownStartTime = Date.now();

function createObstacle() {
    obstacles.push({
        x: canvas.width,
        y: Math.random() * (canvas.height - obstacleHeight),
        width: obstacleWidth,
        height: obstacleHeight
    });
}

function updateCountdown() {
    let currentTime = Date.now();
    let elapsedTime = (currentTime - countdownStartTime) / 1000;
    countdown = Math.max(0, 10 - Math.floor(elapsedTime));
    if (countdown === 0) {
        clearInterval(countdownIntervalId);
    }
}

let countdownIntervalId = setInterval(updateCountdown, countdownInterval);

function drawCountdown() {
    ctx.font = '30px Arial';
    ctx.fillStyle = 'red';
    ctx.fillText(`Start in: ${countdown}`, canvas.width / 2 - 50, canvas.height / 2);
}

function updateGame() {
    if (countdown === 0) {
        if (Date.now() - lastObstacleTime > obstacleInterval) {
            createObstacle();
            lastObstacleTime = Date.now();
        }

        obstacles.forEach(obstacle => {
            obstacle.x -= obstacleSpeed;
            if (obstacle.x + obstacle.width < 0) {
                obstacles.shift();
            }
        });

        if (obstacles.some(obstacle => {
            return (player.x < obstacle.x + obstacle.width &&
                    player.x + player.width > obstacle.x &&
                    player.y < obstacle.y + obstacle.height &&
                    player.y + player.height > obstacle.y);
        })) {
            alert('Game Over!');
            document.location.reload();
        }
    }
}

function drawPlayer() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.width, player.height);
}

function drawObstacles() {
    ctx.fillStyle = 'red';
    obstacles.forEach(obstacle => {
        ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
    });
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    updateGame();
    if (countdown > 0) {
        drawCountdown();
    } else {
        drawPlayer();
        drawObstacles();
    }
    requestAnimationFrame(gameLoop);
}

gameLoop();

canvas.addEventListener('click', () => {
    if (countdown > 0) {
        countdownStartTime = Date.now();
    } else {
        player.y = Math.max(0, player.y - player.speed);
    }
});

window.addEventListener('keydown', (e) => {
    if (e.code === 'Space' && countdown > 0) {
        countdownStartTime = Date.now();
    }
});

window.addEventListener('keydown', (e) => {
    if (e.code === 'ArrowUp') {
        player.y = Math.max(0, player.y - player.speed);
    }
});

window.addEventListener('keydown', (e) => {
    if (e.code === 'ArrowDown') {
        player.y = Math.min(canvas.height - player.height, player.y + player.speed);
    }
});
