    this.hungerLevel = Math.max(0, this.hungerLevel - amount);
  }

  getHungerLevel() {
    return this.hungerLevel;
  }
}

class Energy {
  constructor() {
    this.energyLevel = 50; // 0 to 100
  }

  rest(amount = 10) {
    this.energyLevel = Math.min(100, this.energyLevel + amount);
  }

  getEnergyLevel() {
    return this.energyLevel;
  }
}

class Clock {
  constructor() {
    this.time = 0; // In hours, starts at 0
  }

  tick() {
    this.time += 1;
  }

  getTime() {
    return this.time;
  }
}

class Coordinator {
  constructor() {
    this.hungerSystem = new Hunger();
    this.energySystem = new Energy();
    this.clockSystem = new Clock();
  }

  simulateDay() {
    for (let i = 0; i < 24; i++) {
      this.clockSystem.tick();

      if (this.clockSystem.getTime() % 4 === 0) {
        this.energySystem.rest();
      }

      if (this.clockSystem.getTime() % 6 === 0) {
        this.hungerSystem.eat();
      }

      console.log(`Hour ${this.clockSystem.getTime()}: Hunger=${this.hungerSystem.getHungerLevel()}, Energy=${this.energySystem.getEnergyLevel()}`);
    }
  }
