class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, callback) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(callback => callback(data));
    }
  }
}

class Spawner {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('spawnEnemy', this.spawnEnemy.bind(this));
  }

  spawnEnemy() {
    console.log('Spawner: Spawning an enemy...');
    this.eventBus.emit('enemySpawned', { type: 'basic', health: 100 });
  }
}

class EnemyPool {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.pool = [];
    this.eventBus.subscribe('enemySpawned', this.handleEnemySpawned.bind(this));
    this.eventBus.subscribe('enemyDestroyed', this.handleEnemyDestroyed.bind(this));
  }

  handleEnemySpawned(enemy) {
    console.log('EnemyPool: Adding enemy to pool:', enemy);
    this.pool.push(enemy);
  }

  handleEnemyDestroyed(enemy) {
    console.log('EnemyPool: Removing enemy from pool:', enemy);
    this.pool = this.pool.filter(e => e !== enemy);
  }
}

class Score {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.score = 0;
    this.eventBus.subscribe('enemyDestroyed', this.handleEnemyDestroyed.bind(this));
  }

  handleEnemyDestroyed(enemy) {
    console.log('Score: Enemy destroyed, adding points.');
    this.score += 10;
    console.log('Score: Current score is', this.score);
  }
}

