class Trade {
  constructor() {
    this.resources = { gold: 0, wood: 0, food: 0 };
  }

  // Public API
  getResources() {
    return { ...this.resources };
  }

  // Public API
  trade(resource, amount, price) {
    if (this.resources[resource] >= amount) {
      this.resources[resource] -= amount;
      this.resources.gold += price;
      return true;
    }
    return false;
  }
}

class Reputation {
  constructor() {
    this.standing = 50; // Initial reputation standing
  }

  // Public API
  getStanding() {
    return this.standing;
  }

  // Public API
  influence(amount) {
    this.standing += amount;
    if (this.standing < 0) this.standing = 0;
    if (this.standing > 100) this.standing = 100;
  }
}

class Faction {
  constructor() {
    this.allies = [];
    this.enemies = [];
  }

  // Public API
  getAllies() {
    return [...this.allies];
  }

  // Public API
  getEnemies() {
    return [...this.enemies];
  }

  // Public API
  makeAllies(factionName) {
    if (!this.enemies.includes(factionName)) {
      this.allies.push(factionName);
    }
  }

  // Public API
  declareWar(factionName) {
    if (!this.allies.includes(factionName)) {
      this.enemies.push(factionName);
    }
  }
}

class Coordinator {
  constructor() {
    this.trade = new Trade();
    this.reputation = new Reputation();
    this.faction = new Faction();
  }

  // Public API
  performTrade(resource, amount, price) {
    const success = this.trade.trade(resource, amount, price);
    if (success) {
      this.reputation.influence(5); // Trading positively influences reputation
    } else {
      this.reputation.influence(-5); // Failed trade negatively influences reputation
    }
    return success;
  }

  // Public API
  makeAllies(factionName) {
    this.faction.makeAllies(factionName);
  }

  // Public API
  declareWar(factionName) {
    this.faction.declareWar(factionName);
  }

  // Public API
  getStatus() {
    return {
      resources: this.trade.getResources(),
      reputation: this.reputation.getStanding(),
      allies: this.faction.getAllies(),
      enemies: this.faction.getEnemies(),
    };
  }
}

// Demo
const coordinator = new Coordinator();

