class Trade {
  constructor() {
    this.resources = { gold: 0, wood: 0, food: 0 };
  }

  // Public API
  buy(resource, amount) {
    this.resources[resource] += amount;
    console.log(`Bought ${amount} ${resource}. Total: ${this.resources[resource]}`);
  }

  sell(resource, amount) {
    if (this.resources[resource] >= amount) {
      this.resources[resource] -= amount;
      console.log(`Sold ${amount} ${resource}. Remaining: ${this.resources[resource]}`);
      return true;
    } else {
      console.log(`Not enough ${resource} to sell.`);
      return false;
    }
  }

  getResources() {
    return { ...this.resources };
  }
}

class Reputation {
  constructor() {
    this.standing = 0;
  }

  // Public API
  improve(amount) {
    this.standing += amount;
    console.log(`Reputation improved by ${amount}. Total: ${this.standing}`);
  }

  degrade(amount) {
    this.standing -= amount;
    console.log(`Reputation degraded by ${amount}. Total: ${this.standing}`);
  }

  getStanding() {
    return this.standing;
  }
}

class Faction {
  constructor() {
    this.allies = new Set();
    this.enemies = new Set();
  }

  // Public API
  allyWith(factionName) {
    this.allies.add(factionName);
    console.log(`Allied with ${factionName}. Total allies: ${this.allies.size}`);
  }

  declareWar(factionName) {
    this.enemies.add(factionName);
    console.log(`Declared war on ${factionName}. Total enemies: ${this.enemies.size}`);
  }

  getAllies() {
    return new Set(this.allies);
  }

  getEnemies() {
    return new Set(this.enemies);
  }
}

// Top-level coordinator
class GameCoordinator {
  constructor() {
    this.tradeSystem = new Trade();
    this.reputationSystem = new Reputation();
    this.factionSystem = new Faction();
  }

  // Public API
  conductTrade(resource, amount) {
    this.tradeSystem.buy(resource, amount);
  }

  improveReputation(amount) {
    this.reputationSystem.improve(amount);
  }

  declareWarOnFaction(factionName) {
    this.factionSystem.declareWar(factionName);
