class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item] || null;
  }

  setPrice(item, price) {
    if (price >= 0) {
      this.prices[item] = price;
    }
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      if (this.items[item]) {
        this.items[item] += quantity;
      } else {
        this.items[item] = quantity;
      }
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
    }
  }

  getInventory() {
    return { ...this.items };
  }
}

