    ctx.fillStyle = this.color;
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
    ctx.fill();
  }
}

class Enemy extends Entity {
  constructor(x, y) {
    super(x, y);
    this.radius = 10;
    this.color = 'red';
    this.speed = 2;
    this.health = 1;
  }

  update() {
    this.x -= this.speed;
    if (this.x < 0) {
      lives--;
      enemies.splice(enemies.indexOf(this), 1);
    }
  }
}

class Tower extends Entity {
  constructor(x, y) {
    super(x, y);
    this.radius = 20;
    this.color = 'blue';
    this.range = 100;
    this.damage = 1;
    this.cooldown = 50;
    this.timer = 0;
  }

  attack() {
    const target = enemies.find(e => {
      const distance = Math.sqrt((this.x - e.x) ** 2 + (this.y - e.y) ** 2);
      return distance < this.range;
    });
    if (target) {
      target.health -= this.damage;
      if (target.health <= 0) {
        gold += 10;
        enemies.splice(enemies.indexOf(target), 1);
      }
    }
  }

  update() {
    this.timer++;
    if (this.timer >= this.cooldown) {
      this.attack();
      this.timer = 0;
    }
  }
}

class PowerUp extends Entity {
  constructor(x, y) {
    super(x, y);
    this.radius = 5;
    this.color = 'green';
    this.type = Math.random() > 0.5 ? 'gold' : 'health';
  }

  collect() {
    if (this.type === 'gold') {
      gold += 50;
    } else {
      lives += 3;
    }
    powerUps.splice(powerUps.indexOf(this), 1);
  }
}

