```js
// 2048-style slide game with particle burst effect on key events
// Rendered on an HTML5 canvas with a fixed timestep main loop

const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const boardSize = 4;
const cellSize = canvas.width / boardSize;
const particleCount = 10;
const maxParticles = 50;
let particles = [];

const board = Array.from({ length: boardSize }, () => Array(boardSize).fill(0));
let score = 0;
let newGame = true;

function initBoard() {
  board[Math.floor(Math.random() * boardSize)][Math.floor(Math.random() * boardSize)] = 2;
  board[Math.floor(Math.random() * boardSize)][Math.floor(Math.random() * boardSize)] = 2;
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = '#333';
  ctx.lineWidth = 2;

  for (let y = 0; y < boardSize; y++) {
    for (let x = 0; x < boardSize; x++) {
      ctx.strokeRect(x * cellSize, y * cellSize, cellSize, cellSize);
      const value = board[y][x];
      if (value !== 0) {
        ctx.fillStyle = `hsl(${255 - (value / 2048) * 255}, 100%, 50%)`;
        ctx.fillRect(x * cellSize + 2, y * cellSize + 2, cellSize - 4, cellSize - 4);
        ctx.fillStyle = '#fff';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = 'bold 24px Arial';
        ctx.fillText(value.toString(), x * cellSize + cellSize / 2, y * cellSize + cellSize / 2);
      }
    }
  }

  ctx.fillStyle = '#333';
  ctx.font = 'bold 24px Arial';
  ctx.fillText(`Score: ${score}`, canvas.width - 120, 30);
}

function spawnParticle(x, y) {
  if (particles.length < maxParticles) {
    for (let i = 0; i < particleCount; i++) {
      particles.push({
        x: x * cellSize + cellSize / 2,
        y: y * cellSize + cellSize / 2,
        size: Math.random() * 3 + 1,
        dx: (Math.random() - 0.5) * 2,
        dy: (Math.random() - 0.5) * 2,
        life: 50
      });
    }
  }
}

function updateParticles() {
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.dx;
    p.y += p.dy;
    p.life--;
    if (p.life <= 0) {
      particles.splice(i, 1);
    }
  }
}

function drawParticles() {
  ctx.fillStyle = '#fff';
  for (const p of particles) {
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
    ctx.fill();
  }
}

function slide(direction) {
  let moved = false;
  const [dx, dy] = direction === 'up' ? [0, -1] : direction === 'down' ? [0, 1] : direction === 'left' ? [-1, 0] : [1, 0];
  for (let y = 0; y < boardSize; y++) {
    for (let x = 0; x < boardSize; x++) {
      let cx = x, cy = y;
      while (true) {
        const nx = cx + dx, ny = cy + dy;
        if (nx < 0 || nx >= boardSize || ny < 0 || ny >= boardSize) break;
        if (board[ny][nx] === 0) {
          board[ny][nx] = board[cy][cx];
          board[cy][cx] = 0;
          cx = nx; cy = ny;
          moved = true;
        } else if (board[ny][nx] === board[cy][cx]) {
          board[ny][nx] *= 2;
          board[cy][cx] = 0;
          score += board[ny][nx];
          spawnParticle(nx, ny);
          moved = true;
          break;
        } else {
          break;
        }
      }
    }
  }
  if (moved) {
    const emptyCells = [];
    for (let y = 0; y < boardSize; y++) {
      for (let x = 0; x < boardSize; x++) {
        if (board[y][x] === 0) emptyCells.push([x, y]);
      }
    }
    if (emptyCells.length > 0) {
      const [x, y] = emptyCells[Math.floor(Math.random() * emptyCells.length)];
      board[y][x] = 2;
    }
  }
  return moved;
}

function checkGameOver() {
  for (let y = 0; y < boardSize; y++) {
    for (let x = 0; x < boardSize; x++) {
      if (board[y][x] === 0) return false;
      if (x > 0 && board[y][x] === board[y][x - 1]) return false;
      if (y > 0 && board[y][x] === board[y - 1][x]) return false;
    }
  }
  return true;
}

function gameLoop() {
  if (newGame) {
    initBoard();
    newGame = false;
  }
  drawBoard();
  updateParticles();
  drawParticles();
  if (checkGameOver()) {
    alert(`Game Over! Your score: ${score}`);
    newGame = true;
  }
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowUp':
      if (slide('up')) {
        spawnParticle(Math.floor(Math.random() * boardSize), 0);
      }
      break;
    case 'ArrowDown':
      if (slide('down')) {
        spawnParticle(Math.floor(Math.random() * boardSize), boardSize - 1);
      }
      break;
    case 'ArrowLeft':
      if (slide('left')) {
        spawnParticle(0, Math.floor(Math.random() * boardSize));
      }
      break;
    case 'ArrowRight':
      if (slide('right')) {
        spawnParticle(boardSize - 1, Math.floor(Math.random() * boardSize));
      }
      break;
    case 'r':
      newGame = true;
      score = 0;
      break;
  }
});

gameLoop();
