function gameLoop(currentTime) {
  const dt = currentTime - lastTime;
  lastTime = currentTime;

  if (keys['ArrowRight'] || keys['d']) {
    player.dx = player.speed;
  } else if (keys['ArrowLeft'] || keys['a']) {
    player.dx = -player.speed;
  } else {
    player.dx = 0;
  }

  update(dt);
  render();

  requestAnimationFrame(gameLoop);
}

