class Wallet {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    addMoney(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    removeMoney(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Shop {
    constructor() {
        this.items = {
            'sword': 50,
            'potion': 10,
            'shield': 30
        };
    }

    getItemPrice(itemName) {
        return this.items[itemName] || null;
    }

    listItems() {
        return Object.keys(this.items);
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(itemName, quantity) {
        if (quantity > 0) {
            this.items[itemName] = (this.items[itemName] || 0) + quantity;
            return true;
        }
        return false;
    }

    removeItem(itemName, quantity) {
        if (this.items[itemName] && this.items[itemName] >= quantity) {
            this.items[itemName] -= quantity;
            if (this.items[itemName] === 0) {
                delete this.items[itemName];
            }
            return true;
        }
        return false;
    }

    getInventory() {
        return this.items;
    }
}

class GameCoordinator {
    constructor() {
        this.wallet = new Wallet(100);
        this.shop = new Shop();
        this.inventory = new Inventory();
    }

    buyItem(itemName) {
        const price = this.shop.getItemPrice(itemName);
        if (price !== null && this.wallet.removeMoney(price)) {
            this.inventory.addItem(itemName, 1);
            console.log(`Bought ${itemName} for ${price} gold. Remaining balance: ${this.wallet.getBalance()} gold.`);
            return true;
        }
        console.log(`Failed to buy ${itemName}.`);
        return false;
    }

    listInventory() {
        console.log('Inventory:', this.inventory.getInventory());
    }

    listShopItems() {
        console.log('Shop items:', this.shop.listItems());
    }
}

