// Typing Speed Game with Basic AI Opponent

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');

const words = ['javascript', 'programming', 'developer', 'coding', 'typingspeed'];
let playerInput = '';
let playerScore = 0;
let aiInput = '';
let aiScore = 0;
let currentWordIndex = 0;
let startTime;
let timer;
let aiTypingInterval;

function randomWord() {
    return words[Math.floor(Math.random() * words.length)];
}

function resetGame() {
    playerInput = '';
    aiInput = '';
    currentWordIndex = 0;
    startTime = Date.now();
}

function startGame() {
    resetGame();
    aiTypingInterval = setInterval(aiType, 200);
    timer = requestAnimationFrame(gameLoop);
}

function aiType() {
    if (aiInput.length < words[currentWordIndex].length) {
        aiInput += words[currentWordIndex][aiInput.length];
    } else {
        aiScore++;
        currentWordIndex++;
        aiInput = '';
    }
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '24px Arial';
    ctx.fillText(`Player Score: ${playerScore}`, 20, 50);
    ctx.fillText(`AI Score: ${aiScore}`, canvas.width - 200, 50);

    const currentTime = Date.now();
    const elapsedTime = (currentTime - startTime) / 1000;
    ctx.fillText(`Elapsed Time: ${elapsedTime.toFixed(2)}s`, canvas.width / 2 - 100, 50);

    ctx.fillText(words[currentWordIndex], canvas.width / 2 - words[currentWordIndex].length * 10, 100);
    ctx.fillText(playerInput, canvas.width / 2 - playerInput.length * 10, 150);
    ctx.fillText(aiInput, canvas.width / 2 - aiInput.length * 10, 200);

    if (playerInput === words[currentWordIndex]) {
        playerScore++;
        currentWordIndex++;
        playerInput = '';
        startTime = Date.now();
    }

    if (currentWordIndex >= words.length) {
        clearInterval(aiTypingInterval);
        cancelAnimationFrame(timer);
        ctx.fillText('Game Over!', canvas.width / 2 - 50, 300);
        ctx.fillText(`Final Score: ${playerScore}`, canvas.width / 2 - 60, 350);
        ctx.fillText(`AI Final Score: ${aiScore}`, canvas.width / 2 - 80, 400);
    } else {
        timer = requestAnimationFrame(gameLoop);
    }
}

canvas.addEventListener('keydown', (e) => {
    if (e.key === 'Backspace') {
        playerInput = playerInput.slice(0, -1);
    } else if (e.key.length === 1 && /[a-zA-Z]/.test(e.key)) {
        playerInput += e.key;
    }
});

startGame();
