const highScoreKey = 'typingSpeedHighScore';
let highScore = localStorage.getItem(highScoreKey) ? parseInt(localStorage.getItem(highScoreKey)) : 0;
let score = 0;
let targetText = generateRandomText();
let currentInput = '';
let startTime = null;
let gameRunning = false;

function generateRandomText() {
    const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    let text = '';
    for (let i = 0; i < 20; i++) {
        text += characters.charAt(Math.floor(Math.random() * characters.length));
    }
    return text;
}

function startGame() {
    score = 0;
    targetText = generateRandomText();
    currentInput = '';
    startTime = Date.now();
    gameRunning = true;
}

function update() {
    if (!gameRunning) return;

    const elapsed = (Date.now() - startTime) / 1000;
    score = Math.floor(elapsed * 5); // 5 characters per second

    if (currentInput === targetText) {
        gameRunning = false;
        if (score > highScore) {
            highScore = score;
            localStorage.setItem(highScoreKey, highScore);
        }
        setTimeout(startGame, 2000); // Restart game after 2 seconds
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '30px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText('High Score: ' + highScore, 10, 30);
    ctx.fillText('Score: ' + score, 10, 70);
    ctx.fillText('Type: ' + targetText, 10, 110);
    ctx.fillText(currentInput, 10, 150);
}

function handleInput(event) {
    if (event.key === 'Backspace') {
        currentInput = currentInput.slice(0, -1);
    } else if (event.key.length === 1) {
        currentInput += event.key;
    }
}

canvas.addEventListener('keydown', handleInput);
startGame();

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

gameLoop();
