// Constants
const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

const player = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  size: 10,
  speed: 5,
  color: 'blue'
};

const enemies = [];
const bullets = [];
const enemySpeed = 2;
const waveInterval = 2000;
let waveCount = 1;
let score = 0;
let gameLoop;

// Functions
function spawnEnemies() {
  for (let i = 0; i < waveCount * 2; i++) {
    const enemy = {
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height,
      size: 10,
      color: 'red'
    };
    enemies.push(enemy);
  }
}

function updatePlayer() {
  if (keys.ArrowUp && player.y > 0) player.y -= player.speed;
  if (keys.ArrowDown && player.y < canvas.height) player.y += player.speed;
  if (keys.ArrowLeft && player.x > 0) player.x -= player.speed;
  if (keys.ArrowRight && player.x < canvas.width) player.x += player.speed;
}

function updateBullets() {
  for (let i = bullets.length - 1; i >= 0; i--) {
    bullets[i].y -= 5;
    if (bullets[i].y < 0) {
      bullets.splice(i, 1);
    }
  }
}

function updateEnemies() {
  for (let i = enemies.length - 1; i >= 0; i--) {
    const enemy = enemies[i];
    const dx = player.x - enemy.x;
    const dy = player.y - enemy.y;
    const distance = Math.sqrt(dx * dx + dy * dy);

    if (distance < player.size + enemy.size) {
      // Collision detected
      enemies.splice(i, 1);
      score += 10;
    } else {
      enemy.x += (dx / distance) * enemySpeed;
      enemy.y += (dy / distance) * enemySpeed;
    }
  }
}

function drawPlayer() {
  ctx.fillStyle = player.color;
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.size, 0, Math.PI * 2);
  ctx.fill();
}

function drawBullets() {
  ctx.fillStyle = 'white';
  bullets.forEach(bullet => {
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, 2, 0, Math.PI * 2);
    ctx.fill();
  });
}

function drawEnemies() {
  ctx.fillStyle = enemies.color;
  enemies.forEach(enemy => {
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.size, 0, Math.PI * 2);
    ctx.fill();
  });
}

function drawScore() {
  ctx.font = '20px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function gameLoopFunc() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  updatePlayer();
  updateBullets();
  updateEnemies();
  drawPlayer();
  drawBullets();
  drawEnemies();
  drawScore();
  gameLoop = requestAnimationFrame(gameLoopFunc);
}

function startGame() {
  spawnEnemies();
  gameLoop = requestAnimationFrame(gameLoopFunc);
  setInterval(spawnEnemies, waveInterval);
}

function shootBullet() {
  const bullet = {
    x: player.x,
    y: player.y - player.size
  };
  bullets.push(bullet);
}

// Event Listeners
const keys = {};
window.addEventListener('keydown', (e) => {
  keys[e.key] = true;
  if (e.key === ' ') shootBullet();
});

window.addEventListener('keyup', (e) => {
  keys[e.key] = false;
});

// Start the game
startGame();
