// Match-3 Game
const canvas = document.createElement('canvas');
canvas.width = 360;
canvas.height = 360;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const boardSize = 8;
const cellSize = canvas.width / boardSize;
const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF'];
let board = [];
let score = 0;
let gameOver = false;

function initBoard() {
    for (let i = 0; i < boardSize; i++) {
        board[i] = [];
        for (let j = 0; j < boardSize; j++) {
            board[i][j] = Math.floor(Math.random() * colors.length);
        }
    }
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < boardSize; i++) {
        for (let j = 0; j < boardSize; j++) {
            ctx.fillStyle = colors[board[i][j]];
            ctx.fillRect(i * cellSize, j * cellSize, cellSize, cellSize);
            ctx.strokeStyle = '#000';
            ctx.strokeRect(i * cellSize, j * cellSize, cellSize, cellSize);
        }
    }
    ctx.fillStyle = '#000';
    ctx.fillText(`Score: ${score}`, 10, 20);
}

function swap(i1, j1, i2, j2) {
    [board[i1][j1], board[i2][j2]] = [board[i2][j2], board[i1][j1]];
}

function checkMatches() {
    let matches = [];
    for (let i = 0; i < boardSize; i++) {
        for (let j = 0; j < boardSize - 2; j++) {
            if (board[i][j] === board[i][j + 1] && board[i][j] === board[i][j + 2]) {
                matches.push([i, j], [i, j + 1], [i, j + 2]);
            }
        }
    }
    for (let j = 0; j < boardSize; j++) {
        for (let i = 0; i < boardSize - 2; i++) {
            if (board[i][j] === board[i + 1][j] && board[i][j] === board[i + 2][j]) {
                matches.push([i, j], [i + 1, j], [i + 2, j]);
            }
        }
    }
    return matches;
}

function removeMatches(matches) {
    matches.forEach(([i, j]) => {
        board[i][j] = -1;
    });
    score += matches.length;
}

function dropCandies() {
    for (let i = boardSize - 1; i >= 0; i--) {
        for (let j = boardSize - 1; j >= 0; j--) {
            if (board[i][j] === -1) {
                for (let k = i; k > 0; k--) {
                    board[k][j] = board[k - 1][j];
                }
                board[0][j] = Math.floor(Math.random() * colors.length);
            }
        }
    }
}

function update() {
    if (gameOver) return;
    const matches = checkMatches();
    if (matches.length > 0) {
        removeMatches(matches);
        dropCandies();
    } else {
        gameOver = true;
    }
}

function gameLoop() {
    update();
    drawBoard();
    requestAnimationFrame(gameLoop);
}

initBoard();
gameLoop();

canvas.addEventListener('click', (e) => {
    if (gameOver) return;
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / cellSize);
    const y = Math.floor((e.clientY - rect.top) / cellSize);
    if (selected === null) {
        selected = [x, y];
    } else {
        const [sx, sy] = selected;
        if (Math.abs(x - sx) + Math.abs(y - sy) === 1) {
            swap(sx, sy, x, y);
            const matches = checkMatches();
            if (matches.length > 0) {
                removeMatches(matches);
                dropCandies();
            } else {
                swap(x, y, sx, sy);
            }
        }
        selected = null;
    }
});

