const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

const cardWidth = 100;
const cardHeight = 150;
const margin = 10;
const numPairs = 8;
const cards = [];
let flippedCards = [];
let isFlipping = false;
let particleSystems = [];

function Card(x, y, value) {
    this.x = x;
    this.y = y;
    this.value = value;
    this.flipped = false;
    this.color = 'lightblue';
}

Card.prototype.draw = function() {
    ctx.fillStyle = this.flipped ? this.color : 'white';
    ctx.fillRect(this.x, this.y, cardWidth, cardHeight);
    if (this.flipped) {
        ctx.fillStyle = 'black';
        ctx.font = '20px Arial';
        ctx.fillText(this.value, this.x + cardWidth / 2 - 10, this.y + cardHeight / 2 + 10);
    }
};

Card.prototype.checkCollision = function(x, y) {
    return x > this.x && x < this.x + cardWidth && y > this.y && y < this.y + cardHeight;
};

function createCardPairs() {
    const values = [];
    for (let i = 0; i < numPairs; i++) {
        values.push(i);
        values.push(i);
    }
    shuffleArray(values);
    let index = 0;
    for (let y = margin; y < canvas.height - cardHeight - margin; y += cardHeight + margin) {
        for (let x = margin; x < canvas.width - cardWidth - margin; x += cardWidth + margin) {
            cards.push(new Card(x, y, values[index++]));
        }
    }
}

function shuffleArray(array) {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
}

function checkForMatch() {
    if (flippedCards.length === 2) {
        isFlipping = true;
        if (flippedCards[0].value === flippedCards[1].value) {
            flippedCards[0].color = 'lightgreen';
            flippedCards[1].color = 'lightgreen';
            flippedCards[0].flipped = true;
            flippedCards[1].flipped = true;
            setTimeout(() => {
                flippedCards = [];
                isFlipping = false;
            }, 1000);
        } else {
            setTimeout(() => {
                flippedCards[0].flipped = false;
                flippedCards[1].flipped = false;
                flippedCards = [];
                isFlipping = false;
            }, 1000);
        }
        particleSystems.push(new ParticleSystem(flippedCards[0].x + cardWidth / 2, flippedCards[0].y + cardHeight / 2));
        particleSystems.push(new ParticleSystem(flippedCards[1].x + cardWidth / 2, flippedCards[1].y + cardHeight / 2));
    }
}

function ParticleSystem(x, y) {
    this.x = x;
    this.y = y;
    this.particles = [];
    for (let i = 0; i < 50; i++) {
        this.particles.push({
            x: x,
            y: y,
            vx: (Math.random() - 0.5) * 5,
            vy: (Math.random() - 0.5) * 5,
            size: Math.random() * 2 + 1,
            color: `rgba(255, 255, 255, ${Math.random()})`
        });
    }
}

ParticleSystem.prototype.update = function() {
    for (let particle of this.particles) {
        particle.x += particle.vx;
        particle.y += particle.vy;
        particle.vy += 0.1; // gravity
        particle.size *= 0.95; // fade out
        if (particle.size < 0.1) {
            this.particles.splice(this.particles.indexOf(particle), 1);
        }
    }
};

ParticleSystem.prototype.draw = function() {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let particle of this.particles) {
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
        ctx.fillStyle = particle.color;
        ctx.fill();
    }
    ctx.restore();
};

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let card of cards) {
        card.draw();
    }
    for (let system of particleSystems) {
        system.update();
        system.draw();
    }
    particleSystems = particleSystems.filter(system => system.particles.length > 0);
    requestAnimationFrame(update);
}

canvas.addEventListener('click', function(event) {
    if (isFlipping) return;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    for (let card of cards) {
        if (!card.flipped && card.checkCollision(x, y)) {
            card.flipped = true;
            flippedCards.push(card);
            checkForMatch();
            break;
        }
    }
});

createCardPairs();
update();
