    this.skill = skill;
  }

  canLevelUp() {
    return this.skill.experiencePoints >= this.skill.level * 100;
  }

  levelUp() {
    if (this.canLevelUp()) {
      this.skill.levelUp();
      this.skill.experiencePoints -= this.skill.level * 100;
      console.log(`Level up successful for ${this.skill.name}`);
    } else {
