// Typing Speed Game with Combo Multiplier

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
let ctx = canvas.getContext('2d');

function setCanvasSize() {
    canvas.width = window.innerWidth * devicePixelRatio;
    canvas.height = window.innerHeight * devicePixelRatio;
    ctx = canvas.getContext('2d');
    ctx.scale(devicePixelRatio, devicePixelRatio);
}

window.addEventListener('resize', setCanvasSize);
setCanvasSize();

const words = ['hello', 'world', 'javascript', 'canvas', 'combo', 'typing', 'speed'];
let currentWordIndex = 0;
let currentWord = words[currentWordIndex];
let typedChars = '';
let startTime = Date.now();
let combo = 0;
let score = 0;

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '32px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText(currentWord, canvas.width / 2 - ctx.measureText(currentWord).width / 2, canvas.height / 2);
    ctx.fillText(typedChars, canvas.width / 2 - ctx.measureText(typedChars).width / 2, canvas.height / 2 + 40);
    ctx.fillText(`Score: ${score}`, 10, 40);
    ctx.fillText(`Combo: x${combo}`, 10, 80);
    requestAnimationFrame(draw);
}

function resetWord() {
    currentWordIndex = (currentWordIndex + 1) % words.length;
    currentWord = words[currentWordIndex];
    typedChars = '';
    combo = 0;
}

function updateScore() {
    const timeTaken = (Date.now() - startTime) / 1000;
    const baseScore = Math.max(0, Math.ceil(10 - timeTaken));
    score += baseScore * combo;
    startTime = Date.now();
}

document.addEventListener('keydown', (e) => {
    if (e.key === currentWord[typedChars.length]) {
        typedChars += e.key;
        if (typedChars === currentWord) {
            updateScore();
            resetWord();
        }
    } else if (e.key === 'Backspace') {
        typedChars = typedChars.slice(0, -1);
    } else if (e.key === ' ') {
        if (typedChars === currentWord) {
            updateScore();
            resetWord();
        }
    }
    combo = typedChars === currentWord ? combo + 1 : 0;
});

draw();
