class Pricing {
  constructor(basePrice, priceIncrease) {
    this.basePrice = basePrice;
    this.priceIncrease = priceIncrease;
  }

  getPrice(stockLevel) {
    return this.basePrice + (this.priceIncrease * stockLevel);
  }
}

class Demand {
  constructor(baseDemand, demandDrop) {
    this.baseDemand = baseDemand;
    this.demandDrop = demandDrop;
  }

  getDemand(price) {
    return Math.max(0, this.baseDemand - (price * this.demandDrop));
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.stockLevel = 10; // Initial stock level
  }

  updatePrice() {
    return this.pricing.getPrice(this.stockLevel);
  }

  updateDemand(price) {
    return this.demand.getDemand(price);
  }

