const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let width = window.innerWidth;
let height = window.innerHeight;
canvas.width = width * devicePixelRatio;
canvas.height = height * devicePixelRatio;
ctx.scale(devicePixelRatio, devicePixelRatio);

const maze = {
  width: 16,
  height: 16,
  grid: [],
  generate: function() {
    this.grid = Array.from({ length: this.height }, () => Array(this.width).fill(1));
    const stack = [{ x: Math.floor(this.width / 2), y: Math.floor(this.height / 2) }];
    this.grid[stack[0].y][stack[0].x] = 0;
    while (stack.length > 0) {
      const { x, y } = stack[stack.length - 1];
      const neighbors = [];
      if (x > 1 && this.grid[y][x - 2] === 1) neighbors.push({ x: x - 2, y });
      if (x < this.width - 2 && this.grid[y][x + 2] === 1) neighbors.push({ x: x + 2, y });
      if (y > 1 && this.grid[y - 2][x] === 1) neighbors.push({ x, y: y - 2 });
      if (y < this.height - 2 && this.grid[y + 2][x] === 1) neighbors.push({ x, y: y + 2 });
      if (neighbors.length > 0) {
        const { x: nx, y: ny } = neighbors[Math.floor(Math.random() * neighbors.length)];
        this.grid[(y + ny) / 2][(x + nx) / 2] = 0;
        this.grid[ny][nx] = 0;
        stack.push({ x: nx, y: ny });
      } else {
        stack.pop();
      }
    }
  }
};
maze.generate();

const player = {
  x: 1,
  y: 1,
  width: 1,
  height: 1,
  speed: 2,
  move: function(dx, dy) {
    const nx = this.x + dx;
    const ny = this.y + dy;
    if (nx >= 0 && nx < maze.width - 1 && ny >= 0 && ny < maze.height - 1 &&
        maze.grid[ny][nx] === 0 && maze.grid[ny + dy][nx + dx] === 0) {
      this.x = nx;
      this.y = ny;
    }
  }
};

const keys = {};
window.addEventListener('keydown', (e) => keys[e.key] = true);
window.addEventListener('keyup', (e) => keys[e.key] = false);

let pointerDown = false;
let lastPointerX = 0, lastPointerY = 0;
canvas.addEventListener('mousedown', (e) => {
  pointerDown = true;
  lastPointerX = e.clientX;
  lastPointerY = e.clientY;
});
canvas.addEventListener('mouseup', () => pointerDown = false);
canvas.addEventListener('mousemove', (e) => {
  if (pointerDown) {
    const dx = (e.clientX - lastPointerX) / devicePixelRatio;
    const dy = (e.clientY - lastPointerY) / devicePixelRatio;
    player.move(dx * player.speed, dy * player.speed);
    lastPointerX = e.clientX;
    lastPointerY = e.clientY;
  }
});

function draw() {
  ctx.clearRect(0, 0, width, height);
  for (let y = 0; y < maze.height; y++) {
    for (let x = 0; x < maze.width; x++) {
      if (maze.grid[y][x] === 1) {
        ctx.fillStyle = 'black';
        ctx.fillRect(x, y, 1, 1);
      }
    }
  }
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);
}

function gameLoop() {
  if (keys['ArrowUp'] || keys['w']) player.move(0, -player.speed);
  if (keys['ArrowDown'] || keys['s']) player.move(0, player.speed);
  if (keys['ArrowLeft'] || keys['a']) player.move(-player.speed, 0);
  if (keys['ArrowRight'] || keys['d']) player.move(player.speed, 0);
  draw();
  requestAnimationFrame(gameLoop);
}

window.addEventListener('resize', () => {
  width = window.innerWidth;
  height = window.innerHeight;
  canvas.width = width * devicePixelRatio;
  canvas.height = height * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
});

gameLoop();
