// Constants
const CANVAS_SIZE = 400;
const CARD_SIZE = 100;
const GAP = 10;
const TOTAL_CARDS = 16;
const CARDS_PER_ROW = 4;

// HTML5 Canvas setup
const canvas = document.createElement('canvas');
canvas.width = CANVAS_SIZE;
canvas.height = CANVAS_SIZE;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game state
let cards = [];
let flippedCards = [];
let matchedPairs = 0;
let cardImages = [];
let isFlipping = false;

// Load images
function loadImages() {
  const images = [
    'https://via.placeholder.com/100x100?text=1',
    'https://via.placeholder.com/100x100?text=2',
    'https://via.placeholder.com/100x100?text=3',
    'https://via.placeholder.com/100x100?text=4'
  ];
  images.forEach(img => {
    const image = new Image();
    image.src = img;
    cardImages.push(image);
    cardImages.push(image);
  });
  shuffle(cardImages);
}

// Shuffle array
function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
}

// Card class
class Card {
  constructor(x, y, image) {
    this.x = x;
    this.y = y;
    this.image = image;
    this.flipped = false;
    this.matched = false;
  }

  draw() {
    ctx.strokeStyle = 'black';
    ctx.strokeRect(this.x, this.y, CARD_SIZE, CARD_SIZE);
    if (this.flipped || this.matched) {
      ctx.drawImage(this.image, this.x, this.y, CARD_SIZE, CARD_SIZE);
    }
  }

  flip() {
    this.flipped = true;
  }

  unflip() {
    this.flipped = false;
  }

  match() {
    this.matched = true;
  }

  isOver(x, y) {
    return x > this.x && x < this.x + CARD_SIZE && y > this.y && y < this.y + CARD_SIZE;
  }
}

// Initialize game
function init() {
  loadImages();
  for (let i = 0; i < TOTAL_CARDS; i++) {
    const row = Math.floor(i / CARDS_PER_ROW);
    const col = i % CARDS_PER_ROW;
    const x = col * (CARD_SIZE + GAP);
    const y = row * (CARD_SIZE + GAP);
    cards.push(new Card(x, y, cardImages[i]));
  }
}

// Check for matches
function checkForMatch() {
  if (flippedCards.length === 2) {
    isFlipping = true;
    setTimeout(() => {
      if (flippedCards[0].image === flippedCards[1].image) {
        flippedCards[0].match();
        flippedCards[1].match();
        matchedPairs++;
      } else {
        flippedCards[0].unflip();
        flippedCards[1].unflip();
      }
      flippedCards = [];
      isFlipping = false;
    }, 1000);
  }
}

// Game loop
function gameLoop() {
  ctx.clearRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);
  cards.forEach(card => card.draw());
  if (matchedPairs === TOTAL_CARDS / 2) {
    alert('Congratulations! You won!');
    init();
  }
  requestAnimationFrame(gameLoop);
}

// Event listeners
canvas.addEventListener('click', (e) => {
  const rect = canvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  if (isFlipping) return;
  cards.forEach(card => {
    if (card.isOver(x, y) && !card.flipped && !card.matched) {
      card.flip();
      flippedCards.push(card);
      checkForMatch();
    }
  });
});

document.addEventListener('keydown', (e) => {
  if (isFlipping) return;
  const key = e.key.toLowerCase();
  if (key === 'arrowright') {
    const index = cards.findIndex(card => card.flipped);
    if (index !== -1 && index % CARDS_PER_ROW !== CARDS_PER_ROW - 1) {
      cards[index].unflip();
      cards[index + 1].flip();
      flippedCards = [cards[index + 1]];
      checkForMatch();
    }
  } else if (key === 'arrowleft') {
    const index = cards.findIndex(card => card.flipped);
    if (index !== -1 && index % CARDS_PER_ROW !== 0) {
      cards[index].unflip();
      cards[index - 1].flip();
      flippedCards = [cards[index - 1]];
      checkForMatch();
    }
  } else if (key === 'arrowup') {
    const index = cards.findIndex(card => card.flipped);
    if (index !== -1 && index >= CARDS_PER_ROW) {
      cards[index].unflip();
      cards[index - CARDS_PER_ROW].flip();
      flippedCards = [cards[index - CARDS_PER_ROW]];
      checkForMatch();
    }
  } else if (key === 'arrowdown') {
    const index = cards.findIndex(card => card.flipped);
    if (index !== -1 && index < TOTAL_CARDS - CARDS_PER_ROW) {
      cards[index].unflip();
      cards[index + CARDS_PER_ROW].flip();
      flippedCards = [cards[index + CARDS_PER_ROW]];
      checkForMatch();
    }
  }
});

// Start game
init();
gameLoop();
