class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor() {
    this.prices = {
      apple: 1,
      banana: 2,
      carrot: 3
    };
  }

  getPrice(item) {
    return this.prices[item] || null;
  }

  buyItem(item, amount) {
    const price = this.getPrice(item);
    if (price !== null) {
      return price * amount;
    }
    return null;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, amount) {
    if (amount > 0) {
      this.items[item] = (this.items[item] || 0) + amount;
      return true;
    }
    return false;
  }

  removeItem(item, amount) {
    if (amount > 0 && this.items[item] >= amount) {
      this.items[item] -= amount;
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Coordinator {
  constructor() {
    this.bank = new Bank();
    this.market = new Market();
    this.inventory = new Inventory();
  }

  buyFromMarket(item, amount) {
    const price = this.market.buyItem(item, amount);
    if (price !== null && this.bank.withdraw(price)) {
      this.inventory.addItem(item, amount);
      return true;
    }
    return false;
  }

  sellToMarket(item, amount) {
    const price = this.market.getPrice(item);
    if (price !== null && this.inventory.removeItem(item, amount)) {
      this.bank.deposit(price * amount);
      return true;
    }
    return false;
  }

  checkBalance() {
    return this.bank.getBalance();
  }

  checkInventory() {
    return this.inventory.items;
  }
}

// Demo
