console.log("Initial Balance:", coordinator.checkBalance()); // 0
console.log("Initial Inventory:", coordinator.checkInventory()); // {}

console.log("Buying 5 apples:", coordinator.buyFromMarket("apple", 5)); // true
console.log("Balance after buying apples:", coordinator.checkBalance()); // -5
console.log("Inventory after buying apples:", coordinator.checkInventory()); // { apple: 5 }

console.log("Selling 3 apples:", coordinator.sellToMarket("apple", 3)); // true
console.log("Balance after selling apples:", coordinator.checkBalance()); // 2
console.log("Inventory after selling apples:", coordinator.checkInventory()); // { apple: 2 }

console.log("Trying to buy 10 carrots:", coordinator.buyFromMarket("carrot", 10)); // false
console.log("Balance after failed carrot purchase:", coordinator.checkBalance()); // 2
