class Economy {
    constructor() {
        this.balance = 0;
    }

    getBalance() {
        return this.balance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
        }
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }
}

class Store {
    constructor() {
        this.items = {
            apple: { price: 1 },
            bread: { price: 2 },
            cheese: { price: 3 }
        };
    }

    getItemPrice(item) {
        return this.items[item]?.price || null;
    }

    getItems() {
        return Object.keys(this.items);
    }
}

class Inventory {
    constructor() {
        this.contents = {};
    }

    addItem(item, quantity) {
        if (quantity > 0) {
            this.contents[item] = (this.contents[item] || 0) + quantity;
        }
    }

    removeItem(item, quantity) {
        if (quantity > 0 && this.contents[item] >= quantity) {
            this.contents[item] -= quantity;
            return true;
        }
        return false;
    }

    getInventory() {
        return { ...this.contents };
    }
}

class GameCoordinator {
    constructor() {
        this.economy = new Economy();
        this.store = new Store();
        this.inventory = new Inventory();
    }

    buyItem(item, quantity) {
        const price = this.store.getItemPrice(item);
        if (price !== null) {
            const totalCost = price * quantity;
            if (this.economy.withdraw(totalCost)) {
                this.inventory.addItem(item, quantity);
                console.log(`Bought ${quantity} ${item}(s) for ${totalCost}.`);
                return true;
            } else {
                console.log(`Insufficient funds to buy ${quantity} ${item}(s).`);
            }
        } else {
            console.log(`Item "${item}" not available in store.`);
        }
        return false;
    }

    sellItem(item, quantity) {
        if (this.inventory.removeItem(item, quantity)) {
            const price = this.store.getItemPrice(item);
            if (price !== null) {
                const totalEarnings = price * quantity;
                this.economy.deposit(totalEarnings);
                console.log(`Sold ${quantity} ${item}(s) for ${totalEarnings}.`);
                return true;
            }
        } else {
            console.log(`Insufficient ${item}(s) in inventory to sell.`);
        }
        return false;
    }

    showBalance() {
        console.log(`Current balance: ${this.economy.getBalance()}`);
    }

    showInventory() {
        console.log('Current inventory:', this.inventory.getInventory());
    }
}

