const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TILE_SIZE = 32;
const ROOM_WIDTH = 16;
const ROOM_HEIGHT = 12;
const GRAVITY = 0.5;
const JUMP_STRENGTH = -10;

let player = {
    x: TILE_SIZE * 8,
    y: TILE_SIZE * 2,
    width: TILE_SIZE,
    height: TILE_SIZE,
    velocityX: 0,
    velocityY: 0,
    grounded: false
};

let tiles = Array.from({ length: ROOM_HEIGHT }, () => Array(ROOM_WIDTH).fill(0));
tiles[ROOM_HEIGHT - 1].fill(1); // Ground level

let score = 0;
let gameOver = false;
let lastTime = 0;
let accumulator = 0;
const fixedTimeStep = 1 / 60; // 60 FPS

function update(dt) {
    if (gameOver) return;

    // Player input
    let inputX = 0;
    if (keys['ArrowRight']) inputX += 1;
    if (keys['ArrowLeft']) inputX -= 1;
    player.velocityX = inputX * 5; // Move speed

    // Jumping
    if (keys['ArrowUp'] && player.grounded) {
        player.velocityY = JUMP_STRENGTH;
        player.grounded = false;
    }

    // Physics
    player.velocityY += GRAVITY * dt;
    player.x += player.velocityX * dt;
    player.y += player.velocityY * dt;

    // Collision detection
    player.grounded = false;
    for (let y = 0; y < ROOM_HEIGHT; y++) {
        for (let x = 0; x < ROOM_WIDTH; x++) {
            if (tiles[y][x] === 1) {
                let tileX = x * TILE_SIZE;
                let tileY = y * TILE_SIZE;
                if (player.x < tileX + TILE_SIZE && player.x + player.width > tileX &&
                    player.y < tileY + TILE_SIZE && player.y + player.height > tileY) {
                    if (player.velocityY > 0 && player.y + player.height <= tileY) {
                        player.y = tileY - player.height;
                        player.velocityY = 0;
                        player.grounded = true;
                    }
                }
            }
        }
    }

    // Scoring
    score += dt;
    if (player.y > canvas.height) {
        gameOver = true;
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw tiles
    for (let y = 0; y < ROOM_HEIGHT; y++) {
        for (let x = 0; x < ROOM_WIDTH; x++) {
            if (tiles[y][x] === 1) {
                ctx.fillStyle = 'grey';
                ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
            }
        }
    }

    // Draw player
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Draw score
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${Math.floor(score)}`, 10, 30);

    // Draw game over screen
    if (gameOver) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = 'white';
        ctx.font = '40px Arial';
        ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
    }
}

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

function gameLoop(timestamp) {
    let dt = (timestamp - lastTime) / 1000;
    lastTime = timestamp;

    accumulator += dt;
    while (accumulator >= fixedTimeStep) {
        update(fixedTimeStep);
        accumulator -= fixedTimeStep;
    }

    draw();
    requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
