class Trade {
  constructor(money, goods) {
    this.money = money;
    this.goods = goods;
  }

  buy(price, quantity) {
    if (this.money >= price * quantity) {
      this.money -= price * quantity;
      this.goods += quantity;
      return true;
    }
    return false;
  }

  sell(price, quantity) {
    if (this.goods >= quantity) {
      this.money += price * quantity;
      this.goods -= quantity;
      return true;
    }
    return false;
  }

  getBalance() {
    return { money: this.money, goods: this.goods };
  }
}

class Reputation {
  constructor(initialReputation) {
    this.reputation = initialReputation;
  }

  modifyReputation(change) {
    this.reputation += change;
    if (this.reputation < 0) this.reputation = 0;
  }

  getReputation() {
    return this.reputation;
  }
}

class Faction {
  constructor(trade, reputation) {
    this.trade = trade;
    this.reputation = reputation;
  }

  tradeWithOtherFaction(otherFaction, price, quantity) {
    if (this.trade.sell(price, quantity)) {
      otherFaction.trade.buy(price, quantity);
      this.reputation.modifyReputation(1); // Gain reputation for trade
      return true;
    }
    return false;
  }

  stealFromOtherFaction(otherFaction, quantity) {
    if (otherFaction.trade.goods >= quantity) {
      otherFaction.trade.goods -= quantity;
      this.trade.goods += quantity;
      this.reputation.modifyReputation(-2); // Lose reputation for theft
      otherFaction.reputation.modifyReputation(-2); // Other faction loses reputation
      return true;
    }
    return false;
  }

  getFactionStatus() {
    return {
      trade: this.trade.getBalance(),
      reputation: this.reputation.getReputation()
    };
  }
}

