// Order System
class Order {
  constructor(orderId, items) {
    this.orderId = orderId;
    this.items = items;
    this.status = 'received';
  }

  prepare() {
    this.status = 'preparing';
    console.log(`Order ${this.orderId} is being prepared.`);
    return this;
  }

  complete() {
    this.status = 'completed';
    console.log(`Order ${this.orderId} is ready.`);
    return this;
  }

  isCompleted() {
    return this.status === 'completed';
  }
}

// Kitchen System
class Kitchen {
  constructor() {
    this.orders = [];
  }

  receiveOrder(order) {
    this.orders.push(order);
    console.log(`Kitchen received order ${order.orderId}`);
    return this;
  }

  processOrders() {
    this.orders.forEach(order => {
      if (order.status === 'received') {
        order.prepare();
      }
      if (order.status === 'preparing') {
        order.complete();
      }
    });
    return this;
  }

  getAllCompletedOrders() {
    return this.orders.filter(order => order.isCompleted());
  }
}

// Customer System
class Customer {
  constructor(name) {
    this.name = name;
  }

  placeOrder(kitchen, orderId, items) {
    const order = new Order(orderId, items);
    kitchen.receiveOrder(order);
    console.log(`${this.name} placed order ${orderId} with items: ${items.join(', ')}`);
    return order;
  }

  collectOrder(kitchen, order) {
    if (order.isCompleted()) {
      console.log(`${this.name} collected order ${order.orderId}`);
    } else {
      console.log(`${this.name} order ${order.orderId} is not ready yet.`);
    }
  }
}

// Top-level Coordinator
function runGame() {
  const kitchen = new Kitchen();
  const customer = new Customer('Alice');

  // Customer places an order
  const order = customer.placeOrder(kitchen, 1, ['burger', 'fries']);

  // Kitchen processes orders
  kitchen.processOrders();

  // Customer collects the order
  customer.collectOrder(kitchen, order);

  // Customer places another order
  const order2 = customer.placeOrder(kitchen, 2, ['pizza', 'soda']);

  // Kitchen processes orders again
  kitchen.processOrders();

  // Customer collects the second order
  customer.collectOrder(kitchen, order2);
}

// Run the game
runGame();
