class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getPrices() {
    return { ...this.prices };
  }

  buy(item, quantity = 1) {
    const price = this.prices[item];
    if (price !== undefined && quantity > 0) {
      return price * quantity;
    }
    return null;
  }
}

class Inventory {
  constructor(items = {}) {
    this.items = items;
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] !== undefined && quantity > 0 && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

class GameCoordinator {
  constructor() {
    this.bank = new Bank(1000);
    this.market = new Market({ apple: 1, bread: 2, cheese: 3 });
    this.inventory = new Inventory();
  }

  buyItem(item, quantity = 1) {
    const price = this.market.buy(item, quantity);
    if (price !== null && this.bank.withdraw(price)) {
      this.inventory.addItem(item, quantity);
      return true;
    }
    return false;
  }

  sellItem(item, quantity = 1) {
    const price = this.market.getPrices()[item];
    if (price !== undefined && this.inventory.removeItem(item, quantity)) {
      this.bank.deposit(price * quantity);
      return true;
    }
    return false;
  }

  getBankBalance() {
    return this.bank.getBalance();
  }

  getInventory() {
    return this.inventory.getInventory();
  }
}

