    this.level++;
  }
}

class Experience {
  constructor(total = 0) {
    this.total = total;
  }

  addExperience(amount) {
    this.total += amount;
  }
}

class LevelUp {
  constructor() {
    this.requirements = [100, 200, 300, 400, 500];
  }

  checkLevelUp(experience, skill) {
    const requirement = this.requirements[skill.level - 1];
    if (experience.total >= requirement) {
      skill.levelUp();
      experience.addExperience(-requirement);
      return true;
    }
    return false;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
    this.prices = {
      'skillbook': 50,
      'potion': 20
    };
  }

  purchase(item) {
    if (this.prices[item] && this.economy.debit(this.prices[item])) {
      this.inventory.addItem(item);
      return true;
    }
    return false;
  }
}

class Economy {
  constructor(money = 100) {
    this.money = money;
  }

  debit(amount) {
    if (this.money >= amount) {
      this.money -= amount;
      return true;
    }
    return false;
  }

  credit(amount) {
    this.money += amount;
  }

  getBalance() {
    return this.money;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
  }

  getItems() {
    return this.items;
  }
}

