// Rhythm Tap Game with FSM

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let state = 'menu';
let score = 0;
let timeLeft = 60;
let tapInterval = 500; // ms
let lastTapTime = 0;

function resizeCanvas() {
    const pixelRatio = window.devicePixelRatio;
    const width = window.innerWidth;
    const height = window.innerHeight;
    canvas.width = width * pixelRatio;
    canvas.height = height * pixelRatio;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
    ctx.scale(pixelRatio, pixelRatio);
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

function menuState() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '24px Arial';
    ctx.fillStyle = 'black';
    ctx.textAlign = 'center';
    ctx.fillText('Rhythm Tap Game', canvas.width / 2, canvas.height / 2 - 20);
    ctx.fillText('Press any key to start', canvas.width / 2, canvas.height / 2 + 20);
}

function playingState() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '24px Arial';
    ctx.fillStyle = 'black';
    ctx.textAlign = 'center';
    ctx.fillText(`Score: ${score}`, canvas.width / 2, 30);
    ctx.fillText(`Time: ${Math.ceil(timeLeft)}`, canvas.width / 2, 60);

    if (timeLeft > 0) {
        timeLeft -= 0.016; // Roughly 60 FPS
        if (Date.now() - lastTapTime > tapInterval) {
            lastTapTime = Date.now();
            score++;
        }
    } else {
        state = 'gameover';
    }
}

function pausedState() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '24px Arial';
    ctx.fillStyle = 'black';
    ctx.textAlign = 'center';
    ctx.fillText('Paused', canvas.width / 2, canvas.height / 2);
    ctx.fillText('Press P to resume', canvas.width / 2, canvas.height / 2 + 30);
}

function gameoverState() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '24px Arial';
    ctx.fillStyle = 'black';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 20);
    ctx.fillText(`Final Score: ${score}`, canvas.width / 2, canvas.height / 2 + 20);
    ctx.fillText('Press R to restart', canvas.width / 2, canvas.height / 2 + 50);
}

function update() {
    switch (state) {
        case 'menu':
            menuState();
            break;
        case 'playing':
            playingState();
            break;
        case 'paused':
            pausedState();
            break;
        case 'gameover':
            gameoverState();
            break;
    }
}

function handleInput(event) {
    if (state === 'menu') {
        state = 'playing';
    } else if (state === 'playing') {
        if (Date.now() - lastTapTime < tapInterval / 2) {
            score += 2; // Bonus for quick tap
        }
        lastTapTime = Date.now();
    } else if (state === 'paused') {
        state = 'playing';
    } else if (state === 'gameover') {
        state = 'menu';
        score = 0;
        timeLeft = 60;
    }
}

window.addEventListener('keydown', (event) => {
    if (event.key === 'p' || event.key === 'P') {
        if (state === 'playing') {
            state = 'paused';
        } else if (state === 'paused') {
            state = 'playing';
        }
    }
});

window.addEventListener('click', handleInput);
window.addEventListener('keydown', handleInput);

function gameLoop() {
    update();
    requestAnimationFrame(gameLoop);
}

gameLoop();
