  constructor(x, y) {
    super(x, y);
    this.width = 50;
    this.height = 50;
  }

  update(dt) {
    if (keys['ArrowUp']) this.y -= 5 * dt;
    if (keys['ArrowDown']) this.y += 5 * dt;
    if (keys['ArrowLeft']) this.x -= 5 * dt;
    if (keys['ArrowRight']) this.x += 5 * dt;
  }

  draw(ctx) {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

class Enemy extends Entity {
  constructor(x, y) {
    super(x, y);
    this.width = 30;
    this.height = 30;
  }

  update(dt) {
    // Simple AI: move towards the player
    let dx = player.x - this.x;
    let dy = player.y - this.y;
    let dist = Math.sqrt(dx * dx + dy * dy);
    if (dist > 0) {
      this.x += (dx / dist) * 2 * dt;
      this.y += (dy / dist) * 2 * dt;
    }
  }

  draw(ctx) {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

const player = new Player(100, 100);
const enemies = [new Enemy(400, 300), new Enemy(300, 200)];
const keys = {};

document.addEventListener('keydown', (e) => {
  keys[e.key] = true;
});

document.addEventListener('keyup', (e) => {
  keys[e.key] = false;
});

function update(dt) {
  player.update(dt);
  enemies.forEach(enemy => enemy.update(dt));

  // Collision detection
  enemies.forEach(enemy => {
    if (player.x < enemy.x + enemy.width &&
        player.x + player.width > enemy.x &&
        player.y < enemy.y + enemy.height &&
        player.y + player.height > enemy.y) {
      // Enemy hit player, reset score
      currentScore = 0;
    }
  });
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  player.draw(ctx);
  enemies.forEach(enemy => enemy.draw(ctx));

  // Draw score and high score
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${currentScore}`, 10, 30);
  ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

function gameLoop(timestamp) {
  let dt = timestamp - lastTimestamp;
  if (dt >= fixedTimestep) {
    update(dt);
    draw();
    lastTimestamp = timestamp - (dt % fixedTimestep);
    currentScore += 1; // Increase score every frame
    if (currentScore > highScore) {
      highScore = currentScore;
      localStorage.setItem(localStorageKey, highScore);
    }
  }
  requestAnimationFrame(gameLoop);
}

