const gravity = 0.5;
const jumpSpeed = -10;
const playerSpeed = 5;
const aiSpeed = 4;

class Entity {
  constructor(x, y, width, height) {
    this.x = x;
    this.y = y;
    this.width = width;
    this.height = height;
    this.velocityY = 0;
    this.onGround = false;
  }

  update() {
    if (!this.onGround) {
      this.velocityY += gravity;
    }
    this.y += this.velocityY;
    if (this.y + this.height > canvas.height) {
      this.y = canvas.height - this.height;
      this.velocityY = 0;
      this.onGround = true;
    }
  }

  draw() {
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

class Player extends Entity {
  constructor(x, y) {
    super(x, y, 50, 50);
  }

  jump() {
    if (this.onGround) {
      this.velocityY = jumpSpeed;
      this.onGround = false;
    }
  }

  moveLeft() {
    this.x -= playerSpeed;
  }

  moveRight() {
    this.x += playerSpeed;
  }
}

class AI extends Entity {
  constructor(x, y) {
    super(x, y, 50, 50);
  }

  update() {
    if (Math.abs(this.x - player.x) < canvas.width / 2) {
      if (this.x < player.x) {
        this.x += aiSpeed;
      } else if (this.x > player.x) {
        this.x -= aiSpeed;
      }
    }
    super.update();
  }
}

