class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(listener);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(data));
        }
    }
}

class BuildingSystem {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('resourceGenerated', this.onResourceGenerated.bind(this));
    }

    build(buildingType) {
        console.log(`Building ${buildingType}`);
        if (buildingType === 'farm') {
            this.eventBus.emit('resourceGenerated', { type: 'food', amount: 10 });
        }
    }

    onResourceGenerated(data) {
        console.log(`Resource generated: ${data.type} (${data.amount})`);
    }
}

class ResourceSystem {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.resources = {};
        this.eventBus.subscribe('resourceGenerated', this.onResourceGenerated.bind(this));
    }

    onResourceGenerated(data) {
        if (!this.resources[data.type]) {
            this.resources[data.type] = 0;
