// Typing Speed Game with AI Opponent
// Render on an HTML5 canvas with fixed timestep

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const FONT_SIZE = 24;
const TEXT_COLOR = '#000';
const AI_SPEED = 0.01; // AI typing speed as a fraction of the user's speed
const USER_SPEED = 0.02; // User typing speed

let userText = '';
let aiText = '';
let targetText = 'The quick brown fox jumps over the lazy dog';
let userIndex = 0;
let aiIndex = 0;
let lastTime = 0;

function getRandomText() {
    const texts = [
        'The quick brown fox jumps over the lazy dog',
        'Pack my box with five dozen liquor jugs',
        'How vexingly quick daft zebras jump',
        'Sphinx of black quartz, judge my vow',
        'Jackdaws love my big sphinx of quartz'
    ];
    return texts[Math.floor(Math.random() * texts.length)];
}

function update(deltaTime) {
    // User typing
    if (userIndex < targetText.length) {
        userIndex += USER_SPEED * deltaTime;
    }

    // AI typing
    if (aiIndex < targetText.length) {
        aiIndex += AI_SPEED * deltaTime * (Math.random() + 0.5); // AI speed varies slightly
    }

    // Reset if completed
    if (userIndex >= targetText.length) {
        userText = '';
        aiText = '';
        targetText = getRandomText();
        userIndex = 0;
        aiIndex = 0;
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Render target text
    ctx.font = `${FONT_SIZE}px Arial`;
    ctx.fillStyle = TEXT_COLOR;
    ctx.fillText(targetText, 10, 30);

    // Render user text
    ctx.fillStyle = 'green';
    ctx.fillText(targetText.slice(0, Math.floor(userIndex)), 10, 60);

    // Render AI text
    ctx.fillStyle = 'red';
    ctx.fillText(targetText.slice(0, Math.floor(aiIndex)), 10, 90);
}

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;

    update(deltaTime);
    render();

    requestAnimationFrame(gameLoop);
}

// Start the game loop
requestAnimationFrame(gameLoop);

// Listen for user input
document.addEventListener('keydown', (event) => {
    const key = event.key;
    if (userIndex < targetText.length) {
        if (key === targetText.charAt(userIndex)) {
            userIndex++;
        }
    }
});
