            plots.push({
                x: col * (plotSize + plotSpacing),
                y: row * (plotSize + plotSpacing),
                seed: null,
                plantedAt: null
            });
        }
    }
}

function drawPlots() {
    plots.forEach(plot => {
        ctx.fillStyle = plot.seed ? 'green' : 'brown';
        ctx.fillRect(plot.x, plot.y, plotSize, plotSize);
        if (plot.seed) {
            const progress = (Date.now() - plot.plantedAt) / plot.seed.growTime;
            ctx.fillStyle = 'white';
            ctx.fillText(plot.seed.name, plot.x + 5, plot.y + 15);
            ctx.fillStyle = 'yellow';
            ctx.fillRect(plot.x, plot.y + plotSize - 5, plotSize * progress, 5);
        }
    });
}

function drawScore() {
    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
}

function checkForHarvest() {
    plots.forEach(plot => {
        if (plot.seed && Date.now() - plot.plantedAt > plot.seed.growTime) {
            score += plot.seed.value;
            plot.seed = null;
            plot.plantedAt = null;
        }
    });
}

function checkGameOver() {
    if (score >= 100) {
        gameOver = true;
    }
}

function drawGameOver() {
    if (gameOver) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = 'white';
        ctx.font = '48px Arial';
        ctx.fillText('Game Over!', canvas.width / 2 - 100, canvas.height / 2);
        ctx.font = '24px Arial';
        ctx.fillText(`Final Score: ${score}`, canvas.width / 2 - 100, canvas.height / 2 + 50);
    }
}

function onMouseClick(event) {
    if (gameOver) return;
    const x = event.offsetX;
    const y = event.offsetY;
    plots.forEach(plot => {
        if (x > plot.x && x < plot.x + plotSize && y > plot.y && y < plot.y + plotSize) {
            if (!plot.seed) {
                plot.seed = seeds[Math.floor(Math.random() * seeds.length)];
                plot.plantedAt = Date.now();
            }
        }
    });
}

canvas.addEventListener('click', onMouseClick);

function gameLoop(time) {
    if (gameOver) return;
    const deltaTime = time - lastTime;
    if (deltaTime >= FRAME_DURATION) {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        drawPlots();
        drawScore();
        checkForHarvest();
        checkGameOver();
        lastTime = time;
    }
    requestAnimationFrame(gameLoop);
}

initPlots();
requestAnimationFrame(gameLoop);
