const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 300;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const BLOCK_SIZE = 30;
const GRID_WIDTH = canvas.width / BLOCK_SIZE;
const GRID_HEIGHT = canvas.height / BLOCK_SIZE;
const COLORS = ['#FF6347', '#4682B4', '#32CD32', '#FFD700', '#DA70D6'];

let grid = Array.from({ length: GRID_HEIGHT }, () => Array(GRID_WIDTH).fill(null));
let currentPiece = null;
let currentX = 0;
let currentY = 0;
let dropCounter = 0;
let dropInterval = 1000;
let lastTime = 0;
let score = 0;
let comboMultiplier = 1;

function createPiece() {
    const types = ['I', 'J', 'L', 'O', 'S', 'T', 'Z'];
    const type = types[Math.floor(Math.random() * types.length)];
    const color = COLORS[Math.floor(Math.random() * COLORS.length)];

    switch (type) {
        case 'I':
            return [[0, 0], [1, 0], [2, 0], [3, 0]];
        case 'J':
            return [[0, 1], [1, 1], [2, 1], [2, 0]];
        case 'L':
            return [[0, 1], [1, 1], [2, 1], [0, 0]];
        case 'O':
            return [[0, 0], [1, 0], [0, 1], [1, 1]];
        case 'S':
            return [[1, 0], [2, 0], [0, 1], [1, 1]];
        case 'T':
            return [[1, 0], [0, 1], [1, 1], [2, 1]];
        case 'Z':
            return [[0, 0], [1, 0], [1, 1], [2, 1]];
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw grid
    for (let y = 0; y < GRID_HEIGHT; y++) {
        for (let x = 0; x < GRID_WIDTH; x++) {
            if (grid[y][x] !== null) {
                ctx.fillStyle = grid[y][x];
                ctx.fillRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
                ctx.strokeStyle = 'black';
                ctx.strokeRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
            }
        }
    }

    // Draw current piece
    if (currentPiece) {
        ctx.fillStyle = currentPiece.color;
        currentPiece.shape.forEach(([ox, oy]) => {
            const x = currentX + ox;
            const y = currentY + oy;
            ctx.fillRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
            ctx.strokeStyle = 'black';
            ctx.strokeRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
        });
    }
}

function collide() {
    if (currentPiece) {
        return currentPiece.shape.some(([ox, oy]) => {
            const x = currentX + ox;
            const y = currentY + oy;
            return y >= GRID_HEIGHT || x < 0 || x >= GRID_WIDTH || grid[y][x] !== null;
        });
    }
    return false;
}

function freeze() {
    if (currentPiece) {
        currentPiece.shape.forEach(([ox, oy]) => {
            const x = currentX + ox;
            const y = currentY + oy;
            grid[y][x] = currentPiece.color;
        });
        clearLines();
        currentPiece = null;
    }
}

function clearLines() {
    let linesCleared = 0;
    for (let y = GRID_HEIGHT - 1; y >= 0; y--) {
        if (grid[y].every(cell => cell !== null)) {
            grid.splice(y, 1);
            grid.unshift(Array(GRID_WIDTH).fill(null));
            linesCleared++;
        }
    }
    if (linesCleared > 0) {
        score += (linesCleared ** 2) * 100 * comboMultiplier;
        comboMultiplier = Math.min(comboMultiplier + 1, 5);
    } else {
        comboMultiplier = 1;
    }
}

function update(time = 0) {
    const deltaTime = time - lastTime;
    lastTime = time;

    dropCounter += deltaTime;
    if (dropCounter > dropInterval) {
        dropCounter = 0;
        if (!collide()) {
            currentY++;
        } else {
            freeze();
            currentPiece = createPiece();
            currentX = Math.floor(GRID_WIDTH / 2) - Math.floor(currentPiece.shape[0][0]);
            currentY = 0;
            if (collide()) {
                // Game over
                grid = Array.from({ length: GRID_HEIGHT }, () => Array(GRID_WIDTH).fill(null));
                score = 0;
                comboMultiplier = 1;
            }
        }
    }

    draw();
    requestAnimationFrame(update);
}

document.addEventListener('keydown', e => {
    if (currentPiece) {
        switch (e.keyCode) {
            case 37: // Left
                if (!collide(currentPiece.shape.map(([ox, oy]) => [ox - 1, oy]))) currentX--;
                break;
            case 39: // Right
                if (!collide(currentPiece.shape.map(([ox, oy]) => [ox + 1, oy]))) currentX++;
                break;
            case 40: // Down
                if (!collide(currentPiece.shape.map(([ox, oy]) => [ox, oy + 1]))) currentY++;
                break;
            case 38: // Up
                const rotated = currentPiece.shape.map(([x, y]) => [-y, x]);
                if (!collide(rotated)) currentPiece.shape = rotated;
                break;
        }
    }
});

currentPiece = createPiece();
currentX = Math.floor(GRID_WIDTH / 2) - Math.floor(currentPiece.shape[0][0]);
currentY = 0;
currentPiece.color = COLORS[Math.floor(Math.random() * COLORS.length)];
requestAnimationFrame(update);
