class Farm {
    constructor() {
        this.crops = [];
    }

    plantCrop(crop) {
        this.crops.push(crop);
        console.log(`Planted a new crop: ${crop.name}`);
    }

    harvest() {
        const harvestableCrops = this.crops.filter(crop => crop.isReady());
        this.crops = this.crops.filter(crop => !crop.isReady());
        console.log(`Harvested ${harvestableCrops.length} crops.`);
        return harvestableCrops;
    }
}

class Crop {
    constructor(name, growthTime) {
        this.name = name;
        this.growthTime = growthTime;
        this.plantedAt = null;
    }

    plant() {
        this.plantedAt = Date.now();
        console.log(`Crop ${this.name} planted at ${this.plantedAt}`);
    }

    isReady() {
        if (!this.plantedAt) return false;
        const currentTime = Date.now();
        const growthDuration = currentTime - this.plantedAt;
        return growthDuration >= this.growthTime;
    }
}

class Market {
    constructor() {
        this.prices = {};
    }

    setPrice(cropName, price) {
        this.prices[cropName] = price;
        console.log(`Set price for ${cropName}: ${price}`);
    }

    sellCrops(crops) {
        let totalRevenue = 0;
        crops.forEach(crop => {
            if (this.prices[crop.name]) {
                totalRevenue += this.prices[crop.name];
                console.log(`Sold ${crop.name} for ${this.prices[crop.name]}`);
            }
        });
        console.log(`Total revenue: ${totalRevenue}`);
        return totalRevenue;
    }
}

class GameCoordinator {
    constructor() {
        this.farm = new Farm();
        this.market = new Market();
    }

    plantCrop(name, growthTime) {
        const crop = new Crop(name, growthTime);
        crop.plant();
        this.farm.plantCrop(crop);
    }

    setCropPrice(name, price) {
        this.market.setPrice(name, price);
    }

    runGameCycle() {
        const harvestedCrops = this.farm.harvest();
        const revenue = this.market.sellCrops(harvestedCrops);
    }
}

