class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(listener);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(data));
        }
    }
}

class Quest {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('questCompleted', this.onQuestCompleted.bind(this));
    }

    startQuest(questId) {
        console.log(`Starting quest: ${questId}`);
        // Simulate quest completion
        setTimeout(() => {
            this.eventBus.emit('questCompleted', questId);
        }, 2000);
    }

    onQuestCompleted(questId) {
        console.log(`Quest ${questId} completed!`);
        this.eventBus.emit('questReward', questId);
    }
}

class Reward {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('questReward', this.onQuestReward.bind(this));
    }

    onQuestReward(questId) {
        console.log(`Granting reward for quest: ${questId}`);
        // Simulate reward granting
        setTimeout(() => {
            this.eventBus.emit('itemAddedToInventory', { questId, itemId: `item_${questId}` });
        }, 1000);
    }
}

class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('itemAddedToInventory', this.onItemAddedToInventory.bind(this));
        this.items = [];
    }

    onItemAddedToInventory(data) {
        console.log(`Item added to inventory: ${data.itemId}`);
        this.items.push(data.itemId);
    }

    listItems() {
        console.log('Inventory items:', this.items);
    }
}

