const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

const player = {
    x: 50,
    y: canvas.height - 100,
    width: 30,
    height: 30,
    speed: 5,
    jumpForce: 15,
    velocity: 0,
    grounded: false
};

const ground = {
    y: canvas.height - 50,
    height: 50,
    color: '#8BC34A'
};

const obstacles = [];
const obstacleWidth = 30;
const obstacleHeight = 50;
const obstacleSpeed = 5;

let score = 0;
let combo = 1;
let lastJumpTime = 0;
let jumpCooldown = 200; // milliseconds

function createObstacle() {
    const x = canvas.width;
    obstacles.push({ x, y: ground.y - obstacleHeight, width: obstacleWidth, height: obstacleHeight });
}

function updateObstacles() {
    obstacles.forEach(obstacle => {
        obstacle.x -= obstacleSpeed;
    });
    obstacles = obstacles.filter(obstacle => obstacle.x + obstacle.width > 0);
}

function drawObstacles() {
    obstacles.forEach(obstacle => {
        ctx.fillStyle = '#F44336';
        ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
    });
}

function checkCollision() {
    const playerRect = { x: player.x, y: player.y, width: player.width, height: player.height };
    return obstacles.some(obstacle => {
        return !(playerRect.x + playerRect.width < obstacle.x ||
                 playerRect.x > obstacle.x + obstacle.width ||
                 playerRect.y + playerRect.height < obstacle.y ||
                 playerRect.y > obstacle.y + obstacle.height);
    });
}

function updatePlayer() {
    if (player.grounded) {
        player.velocity = 0;
    } else {
        player.velocity += 1;
    }

    player.y += player.velocity;

    if (player.y + player.height > ground.y) {
        player.y = ground.y - player.height;
        player.grounded = true;
    }
}

function drawPlayer() {
    ctx.fillStyle = '#2196F3';
    ctx.fillRect(player.x, player.y, player.width, player.height);
}

function drawGround() {
    ctx.fillStyle = ground.color;
    ctx.fillRect(0, ground.y, canvas.width, ground.height);
}

function drawScore() {
    ctx.fillStyle = '#000';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${score} Combo: x${combo}`, 10, 30);
}

function gameLoop() {
    if (checkCollision()) {
        alert('Game Over! Your score: ' + score);
        document.location.reload();
        return;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    updateObstacles();
    drawObstacles();
    updatePlayer();
    drawPlayer();
    drawGround();
    drawScore();

    requestAnimationFrame(gameLoop);
}

function jump() {
    if (player.grounded && Date.now() - lastJumpTime > jumpCooldown) {
        player.velocity = -player.jumpForce;
        player.grounded = false;
        lastJumpTime = Date.now();
    }
}

document.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
        jump();
    }
});

document.addEventListener('click', () => {
    jump();
});

setInterval(createObstacle, 1000);
gameLoop();
