const highScoreKey = 'typingGameHighScore';
let highScore = localStorage.getItem(highScoreKey) ? parseInt(localStorage.getItem(highScoreKey)) : 0;
let score = 0;
let targetText = generateRandomText(20);
let inputText = '';
let startTime, endTime;
let gameRunning = false;

function generateRandomText(length) {
    const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    let result = '';
    for (let i = 0; i < length; i++) {
        result += characters.charAt(Math.floor(Math.random() * characters.length));
    }
    return result;
}

function resetGame() {
    score = 0;
    targetText = generateRandomText(20);
    inputText = '';
    gameRunning = false;
}

function updateHighScore() {
    if (score > highScore) {
        highScore = score;
        localStorage.setItem(highScoreKey, highScore.toString());
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '30px Arial';
    ctx.fillText('Type:', 50, 50);
    ctx.fillText(targetText, 50, 100);
    ctx.fillText(`Score: ${score}`, 50, 150);
    ctx.fillText(`High Score: ${highScore}`, 50, 200);
    ctx.fillText(`Input: ${inputText}`, 50, 250);
}

function handleInput(event) {
    if (!gameRunning) {
        startTime = Date.now();
        gameRunning = true;
    }
    if (event.key === 'Backspace') {
        inputText = inputText.slice(0, -1);
    } else if (event.key.length === 1) {
        inputText += event.key;
    }
    if (inputText === targetText) {
        endTime = Date.now();
        score = Math.floor((targetText.length / (endTime - startTime)) * 60000);
        updateHighScore();
        resetGame();
    }
}

document.addEventListener('keydown', handleInput);

function gameLoop() {
    draw();
    requestAnimationFrame(gameLoop);
}

gameLoop();
