class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor() {
    this.prices = {
      apple: 1,
      banana: 2,
      orange: 3
    };
  }

  getPrices() {
    return { ...this.prices };
  }

  buy(item, quantity) {
    const price = this.prices[item];
    if (price !== undefined && quantity > 0) {
      return price * quantity;
    }
    return null;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }

  getInventory() {
    return { ...this.items };
  }
}

class GameCoordinator {
  constructor() {
    this.bank = new Bank(100);
    this.market = new Market();
    this.inventory = new Inventory();
  }

  buyItem(item, quantity) {
    const cost = this.market.buy(item, quantity);
    if (cost !== null && this.bank.withdraw(cost)) {
      this.inventory.addItem(item, quantity);
      return true;
    }
    return false;
  }

  getBankBalance() {
    return this.bank.getBalance();
  }

  getInventory() {
    return this.inventory.getInventory();
  }
}

