// Crop Class
class Crop {
  constructor(name, growthTime) {
    this.name = name;
    this.growthTime = growthTime;
    this.state = 'seeded';
    this.timer = null;
  }

  grow() {
    if (this.state === 'seeded') {
      this.state = 'growing';
      this.timer = setTimeout(() => {
        this.state = 'harvestable';
        EventBus.emit('cropHarvestable', this);
      }, this.growthTime);
    }
  }

  harvest() {
    if (this.state === 'harvestable') {
      clearTimeout(this.timer);
      this.state = 'harvested';
      EventBus.emit('cropHarvested', this);
    }
  }
}

// Farm Class
