  constructor() {
    this.crops = [];
    EventBus.subscribe('cropHarvestable', this.onCropHarvestable.bind(this));
    EventBus.subscribe('cropHarvested', this.onCropHarvested.bind(this));
  }

  plantCrop(name, growthTime) {
    const crop = new Crop(name, growthTime);
    this.crops.push(crop);
    crop.grow();
    EventBus.emit('cropPlanted', crop);
  }

  onCropHarvestable(crop) {
    console.log(`Crop ${crop.name} is now harvestable!`);
