const canvas = document.createElement('canvas');
canvas.width = 320;
canvas.height = 480;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const BLOCK_SIZE = 20;
const COLS = canvas.width / BLOCK_SIZE;
const ROWS = canvas.height / BLOCK_SIZE;

const colors = [
  '#FF6347', '#FF4500', '#FFD700', '#7FFFD4', '#4682B4',
  '#8A2BE2', '#FF1493', '#1E90FF', '#228B22', '#FF69B4'
];

let score = 0;
let gameover = false;
let currentBlock = createBlock();
let nextBlock = createBlock();
let board = Array.from({ length: ROWS }, () => Array(COLS).fill(0));

function createBlock() {
  const types = [
    [[1, 1, 1, 1]], // I
    [[1, 1], [1, 1]], // O
    [[1, 1, 0], [0, 1, 1]], // S
    [[0, 1, 1], [1, 1, 0]], // Z
    [[1, 1, 1], [0, 1, 0]], // T
    [[1, 1, 1], [1, 0, 0]], // L
    [[1, 1, 1], [0, 0, 1]]  // J
  ];
  const type = types[Math.floor(Math.random() * types.length)];
  const color = colors[Math.floor(Math.random() * colors.length)];
  return { type, color, x: Math.floor(COLS / 2) - Math.floor(type[0].length / 2), y: 0 };
}

function drawBlock(block) {
  block.type.forEach((row, y) => {
    row.forEach((value, x) => {
      if (value) {
        ctx.fillStyle = block.color;
        ctx.fillRect(block.x * BLOCK_SIZE + x * BLOCK_SIZE, block.y * BLOCK_SIZE + y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
        ctx.strokeStyle = '#000';
        ctx.strokeRect(block.x * BLOCK_SIZE + x * BLOCK_SIZE, block.y * BLOCK_SIZE + y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
      }
    });
  });
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  board.forEach((row, y) => {
    row.forEach((value, x) => {
      if (value) {
        ctx.fillStyle = colors[value - 1];
        ctx.fillRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
        ctx.strokeStyle = '#000';
        ctx.strokeRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
      }
    });
  });
  drawBlock(currentBlock);
}

function moveBlock(dx, dy) {
  if (canMove(currentBlock, dx, dy)) {
    currentBlock.x += dx;
    currentBlock.y += dy;
  } else if (dy === 1) {
    lockBlock();
  }
}

function rotateBlock() {
  const rotated = currentBlock.type[0].map((_, index) =>
    currentBlock.type.map(row => row[index]).reverse()
  );
  if (canMove({ ...currentBlock, type: rotated })) {
    currentBlock.type = rotated;
  }
}

function canMove(block, dx = 0, dy = 0) {
  return block.type.every((row, y) =>
    row.every((value, x) => {
      const newX = block.x + x + dx;
      const newY = block.y + y + dy;
      return value === 0 || (newX >= 0 && newX < COLS && newY < ROWS && board[newY][newX] === 0);
    })
  );
}

function lockBlock() {
  currentBlock.type.forEach((row, y) => {
    row.forEach((value, x) => {
      if (value) {
        board[currentBlock.y + y][currentBlock.x + x] = colors.indexOf(currentBlock.color) + 1;
      }
    });
  });
  clearLines();
  currentBlock = nextBlock;
  nextBlock = createBlock();
  if (!canMove(currentBlock)) {
    gameover = true;
  }
}

function clearLines() {
  for (let y = ROWS - 1; y >= 0; y--) {
    if (board[y].every(value => value !== 0)) {
      board.splice(y, 1);
      board.unshift(Array(COLS).fill(0));
      score += 10;
    }
  }
}

function drawScore() {
  ctx.fillStyle = '#000';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function gameLoop() {
  if (!gameover) {
    moveBlock(0, 1);
    drawBoard();
    drawScore();
    requestAnimationFrame(gameLoop);
  } else {
    ctx.fillStyle = '#000';
    ctx.font = '30px Arial';
    ctx.fillText('Game Over', canvas.width / 2 - 90, canvas.height / 2);
  }
}

document.addEventListener('keydown', e => {
  if (gameover) return;
  switch (e.key) {
    case 'ArrowLeft': moveBlock(-1, 0); break;
    case 'ArrowRight': moveBlock(1, 0); break;
    case 'ArrowDown': moveBlock(0, 1); break;
    case 'ArrowUp': rotateBlock(); break;
  }
});

gameLoop();
