const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 600;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const gridSize = 20;
const tileCount = canvas.width / gridSize;
let snake = [{ x: tileCount / 2, y: tileCount / 2 }];
let direction = { x: 0, y: 0 };
let food = { x: Math.floor(Math.random() * tileCount), y: Math.floor(Math.random() * tileCount) };
let score = 0;
let gameOver = false;
const fixedTimeStep = 1000 / 10; // 1000ms / 10fps
let lastTime = 0;

function drawRect(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * gridSize, y * gridSize, gridSize, gridSize);
}

function drawText(text, x, y, color) {
  ctx.fillStyle = color;
  ctx.font = '20px Arial';
  ctx.fillText(text, x, y);
}

function gameLoop(timestamp) {
  if (gameOver) {
    drawText('Game Over! Score: ' + score, canvas.width / 4, canvas.height / 2, 'red');
    return;
  }

  const deltaTime = timestamp - lastTime;
  if (deltaTime >= fixedTimeStep) {
    lastTime = timestamp;

    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    if (head.x < 0 || head.x >= tileCount || head.y < 0 || head.y >= tileCount || snake.some(segment => segment.x === head.x && segment.y === head.y)) {
      gameOver = true;
    } else {
      snake.unshift(head);
      if (head.x === food.x && head.y === food.y) {
        score++;
        food = { x: Math.floor(Math.random() * tileCount), y: Math.floor(Math.random() * tileCount) };
      } else {
        snake.pop();
      }
    }
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  snake.forEach(segment => drawRect(segment.x, segment.y, 'green'));
  drawRect(food.x, food.y, 'red');
  drawText('Score: ' + score, 10, 20, 'black');

  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', event => {
  switch (event.key) {
    case 'ArrowUp':
      if (direction.y === 0) direction = { x: 0, y: -1 };
      break;
    case 'ArrowDown':
      if (direction.y === 0) direction = { x: 0, y: 1 };
      break;
    case 'ArrowLeft':
      if (direction.x === 0) direction = { x: -1, y: 0 };
      break;
    case 'ArrowRight':
      if (direction.x === 0) direction = { x: 1, y: 0 };
      break;
  }
});

requestAnimationFrame(gameLoop);
