      console.log(`Order ${order.getOrderId()} is preparing.`);
      // Simulate more processing time
      setTimeout(() => {
        order.updateStatus('completed');
        console.log(`Order ${order.getOrderId()} is completed.`);
      }, 2000);
    }, 1000);
  }

  getOrderStatus(orderId) {
