class Pricing {
  constructor(priceData) {
    this.priceData = priceData;
  }

  getPrice(item) {
    return this.priceData[item] || 0;
  }

  setPrice(item, price) {
    this.priceData[item] = price;
  }
}

class Demand {
  constructor(demandData) {
    this.demandData = demandData;
  }

  getDemand(item) {
    return this.demandData[item] || 0;
  }

  adjustDemand(item, change) {
    this.demandData[item] = (this.demandData[item] || 0) + change;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sellItem(item, quantity) {
    const price = this.pricing.getPrice(item);
    const demand = this.demand.getDemand(item);

    if (demand >= quantity) {
      this.demand.adjustDemand(item, -quantity);
      console.log(`Sold ${quantity} of ${item} for ${price * quantity} gold.`);
      return true;
    } else {
      console.log(`Not enough demand for ${item}. Only ${demand} available.`);
      return false;
    }
  }

  restockItem(item, quantity) {
    this.demand.adjustDemand(item, quantity);
    console.log(`Restocked ${quantity} of ${item}.`);
  }
}

// Runnable demo
