const demandData = { sword: 20, shield: 15 };

const pricing = new Pricing(priceData);
const demand = new Demand(demandData);
const store = new Store(pricing, demand);

store.sellItem('sword', 5); // Should sell 5 swords
store.sellItem('shield', 10); // Should sell 10 shields
store.sellItem('shield', 7); // Should not sell 7 shields, only 5 available
store.restockItem('shield', 10); // Restock 10 shields
store.sellItem('shield', 10); // Should now sell 10 shields
