const canvas = document.createElement('canvas');
document.body.appendChild(canvas);

const ctx = canvas.getContext('2d');
let pixelRatio = window.devicePixelRatio || 1;

function resizeCanvas() {
  const { width, height } = window;
  canvas.width = width * pixelRatio;
  canvas.height = height * pixelRatio;
  canvas.style.width = width + 'px';
  canvas.style.height = height + 'px';
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

let farm = Array.from({ length: canvas.height }, () => Array(canvas.width).fill(0));
let isPlowing = false;

function drawFarm() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'green';
  for (let y = 0; y < farm.length; y++) {
    for (let x = 0; x < farm[y].length; x++) {
      if (farm[y][x]) {
        ctx.fillRect(x * pixelRatio, y * pixelRatio, pixelRatio, pixelRatio);
      }
    }
  }
}

canvas.addEventListener('mousedown', () => isPlowing = true);
canvas.addEventListener('mouseup', () => isPlowing = false);
canvas.addEventListener('mousemove', (e) => {
  if (!isPlowing) return;
  const rect = canvas.getBoundingClientRect();
  const x = Math.floor((e.clientX - rect.left) * pixelRatio);
  const y = Math.floor((e.clientY - rect.top) * pixelRatio);
  if (x >= 0 && x < canvas.width && y >= 0 && y < canvas.height) {
    farm[Math.floor(y / pixelRatio)][Math.floor(x / pixelRatio)] = 1;
    drawFarm();
  }
});

document.addEventListener('keydown', (e) => {
  if (e.key === ' ') {
    isPlowing = true;
  }
});

document.addEventListener('keyup', (e) => {
  if (e.key === ' ') {
    isPlowing = false;
  }
});

drawFarm();
