// Tile-based Roguelike Room with Collectible Power-ups

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const devicePixelRatio = window.devicePixelRatio || 1;
canvas.width = window.innerWidth * devicePixelRatio;
canvas.height = window.innerHeight * devicePixelRatio;
ctx.scale(devicePixelRatio, devicePixelRatio);

const tileWidth = 32;
const tileHeight = 32;
const roomWidth = Math.floor(canvas.width / tileWidth);
const roomHeight = Math.floor(canvas.height / tileHeight);

const tiles = [];
const powerUps = [];

function createRoom() {
    for (let y = 0; y < roomHeight; y++) {
        for (let x = 0; x < roomWidth; x++) {
            const tile = Math.random() > 0.8 ? 1 : 0; // 1 for wall, 0 for floor
            tiles.push({ x, y, type: tile });
        }
    }

    // Place power-ups
    for (let i = 0; i < 5; i++) {
        const x = Math.floor(Math.random() * roomWidth);
        const y = Math.floor(Math.random() * roomHeight);
        powerUps.push({ x, y });
    }
}

function drawRoom() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    tiles.forEach(tile => {
        ctx.fillStyle = tile.type === 1 ? '#333' : '#fff'; // Walls are dark, floors are light
        ctx.fillRect(tile.x * tileWidth, tile.y * tileHeight, tileWidth, tileHeight);
    });

    powerUps.forEach(powerUp => {
        ctx.fillStyle = '#ff0'; // Power-ups are yellow
        ctx.fillRect(powerUp.x * tileWidth, powerUp.y * tileHeight, tileWidth, tileHeight);
    });
}

createRoom();
drawRoom();
