const ctx = canvas.getContext('2d');

const TAP_THRESHOLD = 50;
const AI_TAP_DELAY = 300;
const FPS = 60;
const STEP = 1000 / FPS;

let score = 0;
let aiTapTime = 0;
let lastTime = 0;
let tapPosition = { x: 0, y: 0 };
let isTapping = false;

canvas.addEventListener('mousedown', (e) => {
  isTapping = true;
  tapPosition = { x: e.clientX, y: e.clientY };
});

canvas.addEventListener('mouseup', () => {
  isTapping = false;
});

function update(timestamp) {
  const deltaTime = timestamp - lastTime;
  if (deltaTime < STEP) return requestAnimationFrame(update);

  lastTime = timestamp;

  // AI logic
  if (timestamp - aiTapTime > AI_TAP_DELAY) {
    aiTapTime = timestamp;
    const aiX = Math.random() * canvas.width;
    const aiY = Math.random() * canvas.height;
    checkTap(aiX, aiY);
  }

  // Check for player tap
  if (isTapping) {
    checkTap(tapPosition.x, tapPosition.y);
    isTapping = false;
  }

  requestAnimationFrame(update);
}

function checkTap(x, y) {
  const targetX = canvas.width / 2;
  const targetY = canvas.height / 2;
  const distance = Math.sqrt((x - targetX) ** 2 + (y - targetY) ** 2);

  if (distance < TAP_THRESHOLD) {
    score++;
    console.log(`Score: ${score}`);
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw target
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, TAP_THRESHOLD, 0, Math.PI * 2);
  ctx.stroke();

  // Draw score
  ctx.font = '30px Arial';
  ctx.fillText(`Score: ${score}`, 10, 50);

  requestAnimationFrame(render);
}

update(performance.now());
render();
