let dpr = window.devicePixelRatio || 1;

function resize() {
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    canvas.style.width = window.innerWidth + 'px';
    canvas.style.height = window.innerHeight + 'px';
}

window.addEventListener('resize', resize);
resize();

let score = 0;
let player = { x: canvas.width / 2, y: canvas.height - 50, width: 20, height: 20, speed: 5 };
let platforms = [{ x: 0, y: canvas.height - 20, width: canvas.width, height: 20 }];
let powerUps = [];
let lastPlatformY = platforms[0].y;
let gameLoopId;

function getRandomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function spawnPowerUp() {
    let x = getRandomInt(0, canvas.width - 20);
    let y = getRandomInt(0, canvas.height - 20);
    powerUps.push({ x, y, width: 20, height: 20, collected: false });
}

function update() {
    if (player.y >= canvas.height - player.height) {
        player.y = canvas.height - player.height;
    } else {
        player.y += 2; // Gravity
    }

    platforms.forEach(platform => {
        if (player.x < platform.x + platform.width &&
            player.x + player.width > platform.x &&
            player.y < platform.y + platform.height &&
            player.y + player.height > platform.y) {
            player.y = platform.y - player.height;
        }
    });

    powerUps.forEach(powerUp => {
        if (!powerUp.collected && player.x < powerUp.x + powerUp.width &&
            player.x + player.width > powerUp.x &&
            player.y < powerUp.y + powerUp.height &&
            player.y + player.height > powerUp.y) {
            score++;
            powerUp.collected = true;
        }
    });

    if (player.y < canvas.height / 2) {
        platforms.forEach(platform => platform.y += player.y);
        powerUps.forEach(powerUp => powerUp.y += player.y);
        player.y = canvas.height - player.height;
    }

    if (platforms[platforms.length - 1].y > canvas.height - 100) {
        let newPlatformWidth = getRandomInt(100, canvas.width / 2);
        let newPlatformX = getRandomInt(0, canvas.width - newPlatformWidth);
        lastPlatformY -= getRandomInt(100, 200);
        platforms.push({ x: newPlatformX, y: lastPlatformY, width: newPlatformWidth, height: 20 });
        if (getRandomInt(0, 10) > 7) {
            spawnPowerUp();
        }
    }

    platforms = platforms.filter(platform => platform.y < canvas.height);
    powerUps = powerUps.filter(powerUp => !powerUp.collected);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'green';
    platforms.forEach(platform => ctx.fillRect(platform.x, platform.y, platform.width, platform.height));

    ctx.fillStyle = 'blue';
    powerUps.forEach(powerUp => ctx.fillRect(powerUp.x, powerUp.y, powerUp.width, powerUp.height));

    ctx.fillStyle = 'red';
    ctx.fillRect(player.x, player.y, player.width, player.height);

    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 20);

    gameLoopId = requestAnimationFrame(update);
}

function jump() {
    if (player.y >= canvas.height - player.height) {
        player.y -= player.speed * 15;
    }
}

document.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
        jump();
    }
});

