class Farm {
  constructor() {
    this.crops = [];
  }

  plant(seed) {
    const crop = new Crop(seed);
    this.crops.push(crop);
    return crop;
  }

  harvest() {
    return this.crops.filter(crop => crop.isReady()).map(crop => crop.harvest());
  }
}

class Crop {
  constructor(seed) {
    this.seed = seed;
    this.daysGrown = 0;
  }

  grow() {
    this.daysGrown++;
  }

  isReady() {
    return this.daysGrown >= 3; // A crop is ready after 3 days
  }

  harvest() {
    const harvest = { seed: this.seed, quantity: Math.floor(Math.random() * 5) + 1 };
    this.daysGrown = 0; // Reset for next planting cycle
    return harvest;
  }
}

class Market {
  constructor() {
    this.inventory = {};
  }

  buy(seed, quantity) {
    if (this.inventory[seed] && this.inventory[seed] >= quantity) {
      this.inventory[seed] -= quantity;
      return true;
    }
    return false;
  }

  sell(harvest) {
    if (!this.inventory[harvest.seed]) {
      this.inventory[harvest.seed] = 0;
    }
    this.inventory[harvest.seed] += harvest.quantity;
    console.log(`Sold ${harvest.quantity} ${harvest.seed}(s) at market.`);
  }

  getInventory() {
    return this.inventory;
  }
}

class Coordinator {
  constructor() {
    this.farm = new Farm();
    this.market = new Market();
  }

  plant(seed) {
    return this.farm.plant(seed);
  }

  growCrops() {
    this.farm.crops.forEach(crop => crop.grow());
  }

  harvestAndSell() {
    const harvests = this.farm.harvest();
    harvests.forEach(harvest => this.market.sell(harvest));
  }

  buySeeds(seed, quantity) {
    return this.market.buy(seed, quantity);
  }

  getMarketInventory() {
    return this.market.getInventory();
  }
}

// Runnable demo
const coordinator = new Coordinator();

// Buy seeds from the market
console.log(coordinator.buySeeds('wheat', 5)); // true or false depending on inventory
console.log(coordinator.buySeeds('corn', 3));  // true or false depending on inventory

// Plant seeds on the farm
