  if (newState === 'playing') {
    player = { x: canvas.width / 2, y: canvas.height / 2, angle: 0 };
    enemies = [];
    bullets = [];
    score = 0;
  }
}

function spawnEnemy() {
  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  enemies.push({ x, y, angle: Math.random() * Math.PI * 2 });
}

function update(dt) {
  if (gameState === 'playing') {
    // Player movement
    if (keys['ArrowUp']) player.y -= 5 * dt;
    if (keys['ArrowDown']) player.y += 5 * dt;
    if (keys['ArrowLeft']) player.x -= 5 * dt;
    if (keys['ArrowRight']) player.x += 5 * dt;

    // Bullet movement
    bullets.forEach(bullet => {
      bullet.x += Math.cos(bullet.angle) * 10 * dt;
      bullet.y += Math.sin(bullet.angle) * 10 * dt;
    });

    // Enemy movement
    enemies.forEach(enemy => {
      const dx = player.x - enemy.x;
      const dy = player.y - enemy.y;
      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance < 20) setState('gameover');
      enemy.angle = Math.atan2(dy, dx);
      enemy.x += Math.cos(enemy.angle) * 2 * dt;
      enemy.y += Math.sin(enemy.angle) * 2 * dt;
    });

    // Collision detection
    bullets = bullets.filter(bullet => {
      let hit = false;
      enemies = enemies.filter(enemy => {
        const dx = bullet.x - enemy.x;
        const dy = bullet.y - enemy.y;
        if (dx * dx + dy * dy < 100) {
          hit = true;
          score++;
          return false;
        }
        return true;
      });
      return !hit;
    });

    // Spawn new enemies
    if (Math.random() < dt * 0.01) spawnEnemy();

    // Check for game over
    if (score > highScore) highScore = score;
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (gameState === 'menu') {
    ctx.fillStyle = 'white';
    ctx.textAlign = 'center';
    ctx.font = '48px Arial';
