class EventBus {
  constructor() {
    this.listeners = {};
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(data));
    }
  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }
}

class Crop {
  constructor(name, growthTime) {
    this.name = name;
    this.growthTime = growthTime;
    this.ready = false;
  }

  grow() {
    setTimeout(() => {
      this.ready = true;
      this.eventBus.emit('cropReady', { crop: this });
    }, this.growthTime * 1000);
  }

  setEventBus(eventBus) {
    this.eventBus = eventBus;
  }
}

class Market {
  constructor() {
    this.inventory = [];
  }

  sellCrop(crop) {
    if (crop.ready) {
      console.log(`Market: Selling ${crop.name}`);
      this.inventory.push(crop);
    } else {
      console.log(`Market: ${crop.name} is not ready to be sold.`);
    }
  }

  setEventBus(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('cropReady', ({ crop }) => this.sellCrop(crop));
  }
}

class Farm {
  constructor() {
    this.crops = [];
  }

  plantCrop(name, growthTime) {
    const crop = new Crop(name, growthTime);
    crop.setEventBus(this.eventBus);
    this.crops.push(crop);
    crop.grow();
    console.log(`Farm: Planted ${name} which will be ready in ${growthTime} seconds.`);
  }

  setEventBus(eventBus) {
    this.eventBus = eventBus;
  }
}

// Demo
