const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

class Player {
  constructor() {
    this.x = canvas.width / 2;
    this.y = canvas.height / 2;
    this.radius = 10;
    this.color = 'blue';
    this.speed = 5;
    this.keys = {
      right: false,
      left: false,
      up: false,
      down: false
    };
  }

  update() {
    if (this.keys.right && this.x + this.radius < canvas.width) this.x += this.speed;
    if (this.keys.left && this.x - this.radius > 0) this.x -= this.speed;
    if (this.keys.down && this.y + this.radius < canvas.height) this.y += this.speed;
    if (this.keys.up && this.y - this.radius > 0) this.y -= this.speed;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
    ctx.fillStyle = this.color;
    ctx.fill();
    ctx.closePath();
  }

  handleInput(event) {
    const key = event.key;
    if (key === 'ArrowRight' || key === 'd') this.keys.right = event.type === 'keydown';
    if (key === 'ArrowLeft' || key === 'a') this.keys.left = event.type === 'keydown';
    if (key === 'ArrowUp' || key === 'w') this.keys.up = event.type === 'keydown';
    if (key === 'ArrowDown' || key === 's') this.keys.down = event.type === 'keydown';
  }
}

class Enemy {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.radius = 10;
    this.color = 'red';
    this.speed = 2;
    this.angle = Math.random() * Math.PI * 2;
  }

  update() {
    this.x += this.speed * Math.cos(this.angle);
    this.y += this.speed * Math.sin(this.angle);
    if (this.x + this.radius > canvas.width || this.x - this.radius < 0) this.angle = Math.PI - this.angle;
    if (this.y + this.radius > canvas.height || this.y - this.radius < 0) this.angle = -this.angle;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
    ctx.fillStyle = this.color;
    ctx.fill();
    ctx.closePath();
  }
}

class PowerUp {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.radius = 5;
    this.color = 'green';
    this.speed = 1;
    this.angle = Math.random() * Math.PI * 2;
  }

  update() {
    this.x += this.speed * Math.cos(this.angle);
    this.y += this.speed * Math.sin(this.angle);
    if (this.x + this.radius > canvas.width || this.x - this.radius < 0) this.angle = Math.PI - this.angle;
    if (this.y + this.radius > canvas.height || this.y - this.radius < 0) this.angle = -this.angle;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
    ctx.fillStyle = this.color;
    ctx.fill();
    ctx.closePath();
  }
}

class Game {
  constructor() {
    this.player = new Player();
    this.enemies = [];
    this.powerUps = [];
    this.spawnEnemies();
    this.spawnPowerUps();
  }

  spawnEnemies() {
    for (let i = 0; i < 5; i++) {
      this.enemies.push(new Enemy(Math.random() * canvas.width, Math.random() * canvas.height));
    }
  }

  spawnPowerUps() {
    for (let i = 0; i < 3; i++) {
      this.powerUps.push(new PowerUp(Math.random() * canvas.width, Math.random() * canvas.height));
    }
  }

  update() {
    this.player.update();
    this.enemies.forEach(enemy => enemy.update());
    this.powerUps.forEach(powerUp => powerUp.update());
  }

  draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    this.player.draw();
    this.enemies.forEach(enemy => enemy.draw());
    this.powerUps.forEach(powerUp => powerUp.draw());
  }

  checkCollisions() {
    this.enemies.forEach(enemy => {
      const distance = Math.sqrt((this.player.x - enemy.x) ** 2 + (this.player.y - enemy.y) ** 2);
      if (distance < this.player.radius + enemy.radius) {
        alert('Game Over!');
        document.location.reload();
      }
    });

    this.powerUps.forEach((powerUp, index) => {
      const distance = Math.sqrt((this.player.x - powerUp.x) ** 2 + (this.player.y - powerUp.y) ** 2);
      if (distance < this.player.radius + powerUp.radius) {
        this.powerUps.splice(index, 1);
        alert('Power-up collected!');
      }
    });
  }

  loop() {
    this.update();
    this.checkCollisions();
    this.draw();
    requestAnimationFrame(() => this.loop());
  }
}

const game = new Game();
window.addEventListener('keydown', game.player.handleInput.bind(game.player));
window.addEventListener('keyup', game.player.handleInput.bind(game.player));
game.loop();
