const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const gap = 150;
const pipeWidth = 50;
const pipeGap = 150;
const birdWidth = 20;
const birdHeight = 20;
const birdSpeed = 3;
let score = 0;
let gameOver = false;

const bird = {
  x: 50,
  y: canvas.height / 2,
  velocity: 0,
  flap() {
    this.velocity = -birdSpeed;
  },
  update() {
    this.velocity += gravity;
    this.y += this.velocity;
  },
  draw() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x, this.y, birdWidth, birdHeight);
  }
};

const pipes = [];
function createPipe() {
  const height = Math.random() * (canvas.height - gap);
  pipes.push({ x: canvas.width, y: 0, height });
  pipes.push({ x: canvas.width, y: height + gap, height: canvas.height });
}

function updatePipes() {
  pipes.forEach(pipe => pipe.x -= 2);
  if (pipes[0] && pipes[0].x < -pipeWidth) pipes.shift();
  if (pipes.length < 3) createPipe();
}

function checkCollision() {
  pipes.forEach(pipe => {
    if (bird.x < pipe.x + pipeWidth &&
        bird.x + birdWidth > pipe.x &&
        (bird.y < pipe.y + pipe.height || bird.y + birdHeight > pipe.y + pipe.height + gap)) {
      gameOver = true;
    }
  });
  if (bird.y + birdHeight > canvas.height || bird.y < 0) {
    gameOver = true;
  }
}

function drawPipes() {
  ctx.fillStyle = 'green';
  pipes.forEach(pipe => ctx.fillRect(pipe.x, pipe.y, pipeWidth, pipe.height));
}

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function drawGameOver() {
  ctx.fillStyle = 'red';
  ctx.font = '30px Arial';
  ctx.fillText('Game Over', canvas.width / 2 - 70, canvas.height / 2);
}

function update() {
  if (gameOver) return;
  bird.update();
  updatePipes();
  checkCollision();
  if (pipes[0] && pipes[0].x + pipeWidth < bird.x) {
    score++;
    pipes.shift();
    pipes.shift();
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  bird.draw();
  drawPipes();
  drawScore();
  if (gameOver) drawGameOver();
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', () => {
  if (gameOver) {
    pipes.length = 0;
    bird.y = canvas.height / 2;
    bird.velocity = 0;
    score = 0;
    gameOver = false;
  } else {
    bird.flap();
  }
});

gameLoop();
