    for (let c = 0; c < COLS - 2; c++) {
      if (board[r][c] !== EMPTY && board[r][c] === board[r][c + 1] && board[r][c] === board[r][c + 2]) {
        return true;
      }
    }
  }
  for (let r = 0; r < ROWS - 2; r++) {
