// Match-3 Board with Combo Multiplier on HTML5 Canvas

const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TILE_SIZE = 50;
const BOARD_WIDTH = 8;
const BOARD_HEIGHT = 8;
let board = [];
let comboMultiplier = 1;
let score = 0;
let lastTime = 0;
const fixedTimeStep = 1000 / 60; // 60 FPS

function initBoard() {
    for (let y = 0; y < BOARD_HEIGHT; y++) {
        board[y] = [];
        for (let x = 0; x < BOARD_WIDTH; x++) {
            board[y][x] = Math.floor(Math.random() * 3) + 1;
        }
    }
}

function drawTile(x, y, value) {
    const color = value === 1 ? 'red' : value === 2 ? 'green' : 'blue';
    ctx.fillStyle = color;
    ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    ctx.strokeStyle = 'black';
    ctx.strokeRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < BOARD_HEIGHT; y++) {
        for (let x = 0; x < BOARD_WIDTH; x++) {
            drawTile(x, y, board[y][x]);
        }
    }
}

function checkMatches() {
    let matches = [];

    // Check horizontal matches
    for (let y = 0; y < BOARD_HEIGHT; y++) {
        for (let x = 0; x < BOARD_WIDTH - 2; x++) {
            if (board[y][x] === board[y][x + 1] && board[y][x] === board[y][x + 2]) {
                matches.push([y, x], [y, x + 1], [y, x + 2]);
                x += 2;
            }
        }
    }

    // Check vertical matches
    for (let x = 0; x < BOARD_WIDTH; x++) {
        for (let y = 0; y < BOARD_HEIGHT - 2; y++) {
            if (board[y][x] === board[y + 1][x] && board[y][x] === board[y + 2][x]) {
                matches.push([y, x], [y + 1, x], [y + 2, x]);
                y += 2;
            }
        }
    }

    return matches;
}

function clearMatches(matches) {
    matches.forEach(([y, x]) => {
        board[y][x] = 0;
    });
}

function dropTiles() {
    for (let x = 0; x < BOARD_WIDTH; x++) {
        let emptyCount = 0;
        for (let y = BOARD_HEIGHT - 1; y >= 0; y--) {
            if (board[y][x] === 0) {
                emptyCount++;
            } else if (emptyCount > 0) {
                board[y + emptyCount][x] = board[y][x];
                board[y][x] = 0;
            }
        }
    }
}

function refillBoard() {
    for (let x = 0; x < BOARD_WIDTH; x++) {
        for (let y = 0; y < BOARD_HEIGHT; y++) {
            if (board[y][x] === 0) {
                board[y][x] = Math.floor(Math.random() * 3) + 1;
            }
        }
    }
}

function update() {
    const matches = checkMatches();
    if (matches.length > 0) {
        score += matches.length * 10 * comboMultiplier;
        comboMultiplier++;
        clearMatches(matches);
        dropTiles();
        refillBoard();
    } else {
        comboMultiplier = 1;
    }
}

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    if (deltaTime > fixedTimeStep) {
        lastTime = timestamp - (deltaTime % fixedTimeStep);
        update();
        drawBoard();
    }
    requestAnimationFrame(gameLoop);
}

initBoard();
requestAnimationFrame(gameLoop);
