// 2048-style slide game with enemy spawner and difficulty ramping

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio || 1;
function resize() {
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  canvas.style.width = `${window.innerWidth}px`;
  canvas.style.height = `${window.innerHeight}px`;
  ctx.scale(dpr, dpr);
}
resize();
window.addEventListener('resize', resize);

const grid = 4;
const cellSize = Math.min(window.innerWidth, window.innerHeight) / grid;
const board = Array.from({ length: grid }, () => Array(grid).fill(0));
const enemies = [];

function getRandomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function spawnEnemy() {
  const x = getRandomInt(0, grid - 1);
  const y = getRandomInt(0, grid - 1);
  if (board[x][y] === 0) {
    board[x][y] = 2;
  } else {
    spawnEnemy();
  }
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < grid; i++) {
    for (let j = 0; j < grid; j++) {
      ctx.fillStyle = board[i][j] === 0 ? '#ddd' : `hsl(${board[i][j] * 10}, 100%, 50%)`;
      ctx.fillRect(i * cellSize, j * cellSize, cellSize, cellSize);
      if (board[i][j] > 0) {
        ctx.fillStyle = '#fff';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = `${Math.min(cellSize * 0.8, 50)}px Arial`;
        ctx.fillText(board[i][j], i * cellSize + cellSize / 2, j * cellSize + cellSize / 2);
      }
    }
  }
}

function move(dir) {
  let moved = false;
  for (let i = 0; i < grid; i++) {
    let row = [];
    if (dir === 'up' || dir === 'down') {
      row = board.map(row => row[i]).filter(num => num !== 0);
    } else {
      row = board[i].filter(num => num !== 0);
    }
    for (let j = 1; j < row.length; j++) {
      if (row[j] === row[j - 1]) {
        row[j - 1] *= 2;
        row[j] = 0;
        moved = true;
      }
    }
    row = row.filter(num => num !== 0);
    if (dir === 'up' || dir === 'down') {
      for (let k = 0; k < grid; k++) {
        if (dir === 'up') {
          board[k][i] = row[k] || 0;
        } else {
          board[grid - 1 - k][i] = row[k] || 0;
        }
      }
    } else {
      for (let k = 0; k < grid; k++) {
        if (dir === 'left') {
          board[i][k] = row[k] || 0;
        } else {
          board[i][grid - 1 - k] = row[k] || 0;
        }
      }
    }
  }
  return moved;
}

function gameLoop() {
  drawBoard();
  if (enemies.length > 0) {
    const enemy = enemies[0];
    ctx.fillStyle = 'red';
    ctx.fillRect(enemy.x * cellSize, enemy.y * cellSize, cellSize, cellSize);
    enemy.y += 0.1;
    if (enemy.y >= grid) {
      enemies.shift();
    }
  }
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
  const moved = move(e.key === 'ArrowUp' ? 'up' : e.key === 'ArrowDown' ? 'down' : e.key === 'ArrowLeft' ? 'left' : e.key === 'ArrowRight' ? 'right' : '');
  if (moved) {
    spawnEnemy();
    const spawnInterval = 1000 - enemies.length * 50;
    setTimeout(() => {
      const x = getRandomInt(0, grid - 1);
      const y = 0;
      enemies.push({ x, y });
    }, spawnInterval);
  }
});

gameLoop();
