// Memory Card Flip Game with Level Progression

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const cardWidth = 100;
const cardHeight = 150;
const margin = 10;
const colors = ['#FF5733', '#33FF57', '#3357FF', '#FF33A1', '#33FFF6', '#F633FF'];
let cards = [];
let flippedCards = [];
let matchedPairs = 0;
let level = 1;
let canFlip = true;

function init() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
  startLevel();
}

function startLevel() {
  matchedPairs = 0;
  canFlip = true;
  cards = createCards(level);
  shuffleArray(cards);
}

function createCards(level) {
  const pairs = level * 2;
  const cardColors = colors.slice(0, pairs / 2);
  let allCards = [];
  for (let color of cardColors) {
    allCards.push({ color, flipped: false, matched: false, x: 0, y: 0 });
    allCards.push({ color, flipped: false, matched: false, x: 0, y: 0 });
  }
  return allCards;
}

function shuffleArray(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  cards.forEach(card => drawCard(card));
  requestAnimationFrame(draw);
}

function drawCard(card) {
  ctx.fillStyle = card.flipped ? card.color : '#ccc';
  ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
  if (card.flipped) {
    ctx.fillStyle = '#000';
    ctx.font = '20px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(card.color, card.x + cardWidth / 2, card.y + cardHeight / 2 + 10);
  }
}

function flipCard(card) {
  if (!canFlip || card.flipped || card.matched) return;
  card.flipped = true;
  flippedCards.push(card);
  if (flippedCards.length === 2) {
    checkForMatch();
  }
}

function checkForMatch() {
  canFlip = false;
  if (flippedCards[0].color === flippedCards[1].color) {
    matchedPairs++;
    flippedCards[0].matched = true;
    flippedCards[1].matched = true;
  } else {
    setTimeout(() => {
      flippedCards.forEach(card => card.flipped = false);
    }, 1000);
  }
  flippedCards = [];
  if (matchedPairs === cards.length / 2) {
    level++;
    setTimeout(startLevel, 1500);
  } else {
    canFlip = true;
  }
}

function handleMouseClick(e) {
  const rect = canvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  cards.forEach(card => {
    if (x > card.x && x < card.x + cardWidth && y > card.y && y < card.y + cardHeight) {
      flipCard(card);
    }
  });
}

canvas.addEventListener('click', handleMouseClick);
init();
draw();
