class Hunger {
    constructor(consumeRate) {
        this.hungerLevel = 100;
        this.consumeRate = consumeRate;
    }

    update() {
        this.hungerLevel -= this.consumeRate;
        if (this.hungerLevel < 0) this.hungerLevel = 0;
    }

    eat(amount) {
        this.hungerLevel += amount;
        if (this.hungerLevel > 100) this.hungerLevel = 100;
    }

    getHungerLevel() {
        return this.hungerLevel;
    }
}

class Energy {
    constructor(consumeRate, replenishRate) {
        this.energyLevel = 100;
        this.consumeRate = consumeRate;
        this.replenishRate = replenishRate;
    }

    update() {
        this.energyLevel -= this.consumeRate;
        if (this.energyLevel < 0) this.energyLevel = 0;
    }

    rest() {
        this.energyLevel += this.replenishRate;
        if (this.energyLevel > 100) this.energyLevel = 100;
    }

    getEnergyLevel() {
        return this.energyLevel;
    }
}

class Clock {
    constructor(timeStep, systems) {
        this.timeStep = timeStep;
        this.systems = systems;
    }

    tick() {
        console.log(`Tick: ${this.timeStep}`);
        this.systems.forEach(system => system.update());
        this.timeStep++;
    }

    passTime(seconds) {
        for (let i = 0; i < seconds; i++) {
            this.tick();
        }
    }
}

