      const value = board[y][x];
      if (value !== -1) {
        let horizontal = 1;
        let vertical = 1;
        for (let i = x + 1; i < GRID_SIZE && board[y][i] === value; i++) horizontal++;
        for (let i = y + 1; i < GRID_SIZE && board[i][x] === value; i++) vertical++;
        if (horizontal >= 3) {
          for (let i = 0; i < horizontal; i++) matches.push([y, x + i]);
        }
        if (vertical >= 3) {
          for (let i = 0; i < vertical; i++) matches.push([y + i, x]);
        }
      }
    }
  }
  return matches;
}

function removeMatches(matches) {
  matches.forEach(([y, x]) => board[y][x] = -1);
}

function dropTiles() {
  for (let x = 0; x < GRID_SIZE; x++) {
    let emptyCount = 0;
    for (let y = GRID_SIZE - 1; y >= 0; y--) {
      if (board[y][x] === -1) {
        emptyCount++;
      } else {
        board[y + emptyCount][x] = board[y][x];
        if (emptyCount > 0) {
          board[y][x] = -1;
        }
      }
    }
    for (let y = emptyCount - 1; y >= 0; y--) {
      board[y][x] = Math.floor(Math.random() * 3);
    }
  }
}

function update() {
  switch (state) {
    case 'menu':
      drawMenu();
      break;
    case 'playing':
      drawBoard();
      break;
    case 'paused':
      drawPaused();
      break;
    case 'gameover':
      drawGameOver();
      break;
  }
}

function gameLoop() {
  update();
  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', (event) => {
  switch (state) {
    case 'menu':
      handleMenuClick(event);
      break;
    case 'playing':
      handlePlayingClick(event);
      break;
    case 'gameover':
      handleGameOverClick(event);
      break;
  }
});

