const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio || 1;

function resizeCanvas() {
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);

const blockWidth = 20;
const blockHeight = 20;
const blockSpeed = 1;
const playerSpeed = 5;
const playerWidth = blockWidth;
const playerHeight = blockHeight;
const playerHealth = 3;
const gravity = 0.5;
const jumpPower = -10;

let player = {
  x: canvas.width / 2 - playerWidth / 2,
  y: canvas.height - playerHeight,
  vy: 0,
  health: playerHealth
};

let blocks = [];
let lastBlockTime = 0;
let blockSpawnInterval = 1000;

function spawnBlock() {
  blocks.push({
    x: Math.random() * (canvas.width - blockWidth),
    y: 0,
    width: blockWidth,
    height: blockHeight
  });
}

function updatePlayer() {
  if (keys['ArrowLeft'] && player.x > 0) {
    player.x -= playerSpeed;
  }
  if (keys['ArrowRight'] && player.x < canvas.width - playerWidth) {
    player.x += playerSpeed;
  }
  player.vy += gravity;
  player.y += player.vy;
  if (player.y > canvas.height - playerHeight) {
    player.y = canvas.height - playerHeight;
    player.vy = 0;
  }
}

function checkCollision() {
  blocks.forEach(block => {
    if (player.x < block.x + block.width &&
        player.x + playerWidth > block.x &&
        player.y < block.y + block.height &&
        player.y + playerHeight > block.y) {
      player.health--;
      if (player.health <= 0) {
        respawnPlayer();
      } else {
        blocks = blocks.filter(b => b !== block);
      }
    }
  });
}

function respawnPlayer() {
  player = {
    x: canvas.width / 2 - playerWidth / 2,
    y: canvas.height - playerHeight,
    vy: 0,
    health: playerHealth
  };
}

function drawPlayer() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, playerWidth, playerHeight);
}

function drawBlocks() {
  ctx.fillStyle = 'red';
  blocks.forEach(block => {
    ctx.fillRect(block.x, block.y, block.width, block.height);
  });
}

function drawHealthBar() {
  ctx.fillStyle = 'green';
  ctx.fillRect(10, 10, player.health * 20, 10);
}

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

function gameLoop(timestamp) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (keys['Space'] && player.vy === 0) {
    player.vy = jumpPower;
  }

  if (timestamp - lastBlockTime > blockSpawnInterval) {
    spawnBlock();
    lastBlockTime = timestamp;
  }

  updatePlayer();
  checkCollision();
  drawPlayer();
  drawBlocks();
  drawHealthBar();

  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
