        this.level = Math.min(100, this.level + amount);
        console.log(`Ate ${amount}. Hunger level: ${this.level}`);
    }

    consume(amount = 10) {
        this.level = Math.max(0, this.level - amount);
        console.log(`Consumed ${amount}. Hunger level: ${this.level}`);
    }
}

class Energy {
    constructor() {
        this.level = 100; // Max energy level
    }

    rest(amount = 20) {
        this.level = Math.min(100, this.level + amount);
        console.log(`Rested ${amount}. Energy level: ${this.level}`);
    }

    expend(amount = 10) {
        this.level = Math.max(0, this.level - amount);
        console.log(`Expend ${amount}. Energy level: ${this.level}`);
    }
}

class Clock {
    constructor() {
        this.time = 0; // Time in minutes
    }

    tick(minutes = 1) {
        this.time += minutes;
        console.log(`Time passed: ${minutes} minutes. Total time: ${this.time} minutes`);
    }
}

class Coordinator {
    constructor() {
        this.hunger = new Hunger();
        this.energy = new Energy();
        this.clock = new Clock();
    }

    update() {
        this.clock.tick();

        if (this.clock.time % 60 === 0) { // Every hour
            this.hunger.consume();
            this.energy.expend();
        }

        if (this.hunger.level <= 20) {
            this.hunger.eat();
            this.energy.expend(5); // Additional energy spent due to hunger
        }

        if (this.energy.level <= 20) {
            this.energy.rest();
            this.hunger.consume(5); // Additional hunger due to lack of energy
        }
    }
