// Farming Plot Simulator with Finite State Machine

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let state = 'menu';
let farmPlot = Array.from({ length: 10 }, () => Array(10).fill(0)); // 0: empty, 1: planted
let plantTimer = 0;
let gameOver = false;

function resizeCanvas() {
  const dpr = window.devicePixelRatio || 1;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}

function drawMenu() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'green';
  ctx.font = '48px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('Farming Plot Simulator', canvas.width / 2, canvas.height / 2);
  ctx.font = '24px Arial';
  ctx.fillText('Press [Space] to start', canvas.width / 2, canvas.height / 2 + 50);
}

function drawPlaying() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'lightgreen';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < 10; i++) {
    for (let j = 0; j < 10; j++) {
      if (farmPlot[i][j] === 1) {
        ctx.fillStyle = 'brown';
        ctx.fillRect(i * 50, j * 50, 50, 50);
        ctx.fillStyle = 'green';
        ctx.fillRect(i * 50 + 5, j * 50 + 5, 40, 40);
        if (plantTimer > 0) {
          ctx.fillStyle = 'rgba(255, 255, 255, ' + (plantTimer / 100) + ')';
          ctx.fillRect(i * 50, j * 50, 50, 50);
        }
      }
    }
  }
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'left';
  ctx.fillText(`Plant Timer: ${plantTimer}`, 10, 30);
}

function drawPaused() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '48px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('Paused', canvas.width / 2, canvas.height / 2);
}

function drawGameOver() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'red';
  ctx.font = '48px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  ctx.font = '24px Arial';
  ctx.fillText('Press [R] to restart', canvas.width / 2, canvas.height / 2 + 50);
}

function update() {
  if (state === 'playing') {
    if (plantTimer > 0) {
      plantTimer -= 1;
      if (plantTimer === 0) {
        // Plant grows fully, need to implement logic for harvest or next stage
      }
    }
  }
}

function render() {
  switch (state) {
    case 'menu':
      drawMenu();
      break;
    case 'playing':
      drawPlaying();
      break;
    case 'paused':
      drawPaused();
      break;
    case 'gameover':
      drawGameOver();
      break;
  }
}

function gameLoop() {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

window.addEventListener('resize', resizeCanvas);
window.addEventListener('keydown', (e) => {
  switch (state) {
    case 'menu':
      if (e.key === ' ') {
        state = 'playing';
      }
      break;
    case 'playing':
      if (e.key === 'p') {
        state = 'paused';
      } else if (e.key === '1') { // Plant at cursor position
        const rect = canvas.getBoundingClientRect();
        const x = Math.floor((e.clientX - rect.left) / 50);
        const y = Math.floor((e.clientY - rect.top) / 50);
        if (farmPlot[x][y] === 0) {
          farmPlot[x][y] = 1;
          plantTimer = 100; // 100 frames for growth
        }
      }
      break;
    case 'paused':
      if (e.key === 'p') {
        state = 'playing';
      }
      break;
    case 'gameover':
      if (e.key === 'r') {
        state = 'menu';
        farmPlot = Array.from({ length: 10 }, () => Array(10).fill(0));
        plantTimer = 0;
        gameOver = false;
      }
      break;
  }
});

resizeCanvas();
gameLoop();
