class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Shop {
  constructor(wallet, inventory) {
    this.wallet = wallet;
    this.inventory = inventory;
    this.items = {};
  }

  addItem(itemName, price, quantity) {
    if (price > 0 && quantity > 0) {
      this.items[itemName] = { price, quantity };
    }
  }

  buyItem(itemName) {
    const item = this.items[itemName];
    if (item && item.quantity > 0 && this.wallet.withdraw(item.price)) {
      this.inventory.addItem(itemName);
      item.quantity -= 1;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(itemName) {
    this.items[itemName] = (this.items[itemName] || 0) + 1;
  }

  getItemCount(itemName) {
    return this.items[itemName] || 0;
  }
}

