const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 320;
canvas.height = 480;

const BLOCK_SIZE = 20;
const POWERUP_SIZE = 10;
const GRAVITY = 0.5;
const DROP_SPEED = 100; // ms
const POWERUP_SPAWN_INTERVAL = 3000; // ms

let lastTime = 0;
let blocks = [];
let powerups = [];
let player = { x: canvas.width / 2 - BLOCK_SIZE / 2, y: 0, width: BLOCK_SIZE, height: BLOCK_SIZE, velocityY: 0 };
let score = 0;
let collectingPowerup = false;

function getRandomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function createBlock() {
  blocks.push({
    x: getRandomInt(0, canvas.width - BLOCK_SIZE),
    y: 0,
    width: BLOCK_SIZE,
    height: BLOCK_SIZE,
    velocityY: GRAVITY
  });
}

function createPowerup() {
  powerups.push({
    x: getRandomInt(0, canvas.width - POWERUP_SIZE),
    y: 0,
    width: POWERUP_SIZE,
    height: POWERUP_SIZE,
    velocityY: GRAVITY
  });
}

function update(dt) {
  player.velocityY += GRAVITY * dt;
  player.y += player.velocityY * dt;

  if (player.y + player.height > canvas.height) {
    player.y = canvas.height - player.height;
    player.velocityY = 0;
  }

  blocks.forEach(block => {
    block.y += block.velocityY * dt;
    if (block.y + block.height > canvas.height) {
      block.y = canvas.height - block.height;
      block.velocityY = 0;
    }
  });

  powerups.forEach(powerup => {
    powerup.y += powerup.velocityY * dt;
    if (powerup.y + powerup.height > canvas.height) {
      powerup.y = canvas.height - powerup.height;
      powerup.velocityY = 0;
    }
  });

  // Collision detection
  blocks.forEach(block => {
    if (player.x < block.x + block.width &&
        player.x + player.width > block.x &&
        player.y < block.y + block.height &&
        player.y + player.height > block.y) {
      // Game over
      alert(`Game Over! Score: ${score}`);
      resetGame();
    }
  });

  powerups.forEach(powerup => {
    if (player.x < powerup.x + powerup.width &&
        player.x + player.width > powerup.x &&
        player.y < powerup.y + powerup.height &&
        player.y + player.height > powerup.y) {
      // Collect power-up
      score++;
      collectingPowerup = true;
      setTimeout(() => {
        collectingPowerup = false;
      }, 1000); // Power-up effect duration
      powerups = powerups.filter(p => p !== powerup);
    }
  });
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player
  ctx.fillStyle = collectingPowerup ? 'gold' : 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);

  // Draw blocks
  blocks.forEach(block => {
    ctx.fillStyle = 'gray';
    ctx.fillRect(block.x, block.y, block.width, block.height);
  });

  // Draw power-ups
  powerups.forEach(powerup => {
    ctx.fillStyle = 'green';
    ctx.fillRect(powerup.x, powerup.y, powerup.width, powerup.height);
  });

  // Draw score
  ctx.fillStyle = 'black';
  ctx.font = '16px Arial';
  ctx.fillText(`Score: ${score}`, 10, 20);
}

function resetGame() {
  blocks = [];
  powerups = [];
  player = { x: canvas.width / 2 - BLOCK_SIZE / 2, y: 0, width: BLOCK_SIZE, height: BLOCK_SIZE, velocityY: 0 };
  score = 0;
  collectingPowerup = false;
}

function gameLoop(timestamp) {
  const dt = (timestamp - lastTime) / 1000;
  lastTime = timestamp;

  update(dt);
  draw();

  requestAnimationFrame(gameLoop);
}

function startGame() {
  setInterval(createBlock, DROP_SPEED);
  setInterval(createPowerup, POWERUP_SPAWN_INTERVAL);
  requestAnimationFrame(gameLoop);
