class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Hunger {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.hungerLevel = 100;
    this.eventBus.subscribe('tick', this.decreaseHunger.bind(this));
  }

  decreaseHunger() {
    this.hungerLevel = Math.max(0, this.hungerLevel - 1);
    console.log(`Hunger level: ${this.hungerLevel}`);
    if (this.hungerLevel === 0) {
      console.log('You are too hungry!');
    }
  }

  eat(amount) {
    this.hungerLevel = Math.min(100, this.hungerLevel + amount);
    console.log(`Ate ${amount}, hunger level: ${this.hungerLevel}`);
  }
}

class Energy {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.energyLevel = 100;
    this.eventBus.subscribe('tick', this.decreaseEnergy.bind(this));
  }

  decreaseEnergy() {
    this.energyLevel = Math.max(0, this.energyLevel - 1);
    console.log(`Energy level: ${this.energyLevel}`);
    if (this.energyLevel === 0) {
      console.log('You are too tired!');
    }
  }

  rest(amount) {
    this.energyLevel = Math.min(100, this.energyLevel + amount);
    console.log(`Resting ${amount}, energy level: ${this.energyLevel}`);
  }
}

class Clock {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.time = 0;
    this.interval = setInterval(this.tick.bind(this), 1000);
  }

  tick() {
    this.time++;
    console.log(`Time: ${this.time} seconds`);
    this.eventBus.emit('tick');
  }

  stop() {
    clearInterval(this.interval);
  }
}

