class Loot {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  getRandomItem() {
    if (this.items.length === 0) return null;
    const randomIndex = Math.floor(Math.random() * this.items.length);
    return this.items[randomIndex];
  }
}

class RarityTable {
  constructor() {
    this.table = {
      common: 0.7,
      uncommon: 0.2,
      rare: 0.1
    };
  }

  getRandomRarity() {
    const random = Math.random();
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.table)) {
      cumulativeProbability += probability;
      if (random < cumulativeProbability) {
        return rarity;
      }
    }

    return 'common'; // Fallback to common if something goes wrong
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (!this.items[item.rarity]) {
      this.items[item.rarity] = [];
    }
    this.items[item.rarity].push(item);
  }

  displayInventory() {
    for (const [rarity, items] of Object.entries(this.items)) {
      console.log(`Rarity: ${rarity}`);
      items.forEach(item => console.log(`  - ${item.name}`));
    }
  }
}

