  ctx.fillText(targetText, 50, 200);
  ctx.fillText(inputText, 50, 300);
  if (gameOver) {
    ctx.fillText('Game Over!', 50, 400);
    ctx.fillText(`Time: ${elapsedTime / 1000} seconds`, 50, 500);
  }
}

function renderPaused() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '48px Arial';
  ctx.fillText('Paused', 50, 100);
}

