  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '48px Arial';
  ctx.fillText('Game Over!', 50, 100);
  ctx.fillText(`Time: ${elapsedTime / 1000} seconds`, 50, 200);
}

const renderFunctions = {
  [states.menu]: renderMenu,
  [states.playing]: renderPlaying,
  [states.paused]: renderPaused,
  [states.gameover]: renderGameover
};

function startGame() {
  currentState = states.playing;
  targetText = getRandomText();
  inputText = '';
  startTime = Date.now();
  elapsedTime = 0;
  gameOver = false;
}

function handleKeyPress(event) {
  if (currentState === states.playing && !gameOver) {
    if (event.key === 'Backspace') {
      inputText = inputText.slice(0, -1);
    } else if (event.key.length === 1) {
      inputText += event.key;
    }
  } else if (currentState === states.paused) {
    if (event.key === 'p') {
      currentState = states.playing;
    }
  } else if (currentState === states.gameover) {
    if (event.key === 'r') {
      currentState = states.menu;
      inputText = '';
    }
  }
}

canvas.addEventListener('keydown', handleKeyPress);

function gameLoop(timestamp) {
  const dt = timestamp - lastTime;
  lastTime = timestamp;
  accumulator += dt;

  while (accumulator >= fixedTimeStep) {
    updateFunctions[currentState](fixedTimeStep);
    accumulator -= fixedTimeStep;
  }

  renderFunctions[currentState]();
  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
