// Tower Defense Skirmish Game

const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const FPS = 60;
const TPS = 30;
const TPS_INTERVAL = 1000 / TPS;

let lastRenderTime = 0;
let lastUpdateTime = 0;

const states = {
  menu: {
    update: () => {},
    render: () => {
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.font = '32px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('Tower Defense Skirmish', canvas.width / 2, canvas.height / 2);
      ctx.fillText('Press SPACE to Start', canvas.width / 2, canvas.height / 2 + 50);
    },
    onEnter: () => {},
    onExit: () => {}
  },
  playing: {
    update: () => {
      // Game logic update
    },
    render: () => {
      // Game rendering logic
    },
    onEnter: () => {},
    onExit: () => {}
  },
  paused: {
    update: () => {},
    render: () => {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.font = '32px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('PAUSED', canvas.width / 2, canvas.height / 2);
    },
    onEnter: () => {},
    onExit: () => {}
  },
  gameover: {
    update: () => {},
    render: () => {
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.font = '32px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2);
      ctx.fillText('Press SPACE to Restart', canvas.width / 2, canvas.height / 2 + 50);
    },
    onEnter: () => {},
    onExit: () => {}
  }
};

let currentState = 'menu';

function setState(newState) {
  states[currentState].onExit();
  currentState = newState;
  states[currentState].onEnter();
}

function update(timestamp) {
  const deltaTime = timestamp - lastUpdateTime;
  if (deltaTime >= TPS_INTERVAL) {
    states[currentState].update();
    lastUpdateTime = timestamp - (deltaTime % TPS_INTERVAL);
  }
  requestAnimationFrame(update);
}

function render(timestamp) {
  const deltaTime = timestamp - lastRenderTime;
  if (deltaTime >= 1000 / FPS) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    states[currentState].render();
    lastRenderTime = timestamp - (deltaTime % (1000 / FPS));
  }
  requestAnimationFrame(render);
}

function handleKeyDown(event) {
  switch (event.key) {
    case ' ':
      if (currentState === 'menu') {
        setState('playing');
      } else if (currentState === 'playing') {
        setState('paused');
      } else if (currentState === 'paused') {
        setState('playing');
      } else if (currentState === 'gameover') {
        setState('menu');
      }
      break;
  }
}

document.addEventListener('keydown', handleKeyDown);

setState('menu');
update(0);
render(0);
