// Tile-based roguelike room with player health bar and respawn using HTML5 canvas

// Constants
const TILE_SIZE = 16;
const ROOM_WIDTH = 32;
const ROOM_HEIGHT = 20;
const PLAYER_START_X = ROOM_WIDTH / 2;
const PLAYER_START_Y = ROOM_HEIGHT / 2;
const MAX_HEALTH = 100;
const REGEN_AMOUNT = 5;
const REGEN_INTERVAL = 1000; // 1 second

// Canvas setup
const canvas = document.createElement('canvas');
canvas.width = TILE_SIZE * ROOM_WIDTH;
canvas.height = TILE_SIZE * ROOM_HEIGHT;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game state
let player = {
    x: PLAYER_START_X,
    y: PLAYER_START_Y,
    health: MAX_HEALTH
};
let tiles = Array.from({ length: ROOM_HEIGHT }, () => 
    Array(ROOM_WIDTH).fill(Math.random() < 0.3 ? 1 : 0) // 1 for wall, 0 for floor
);
let lastRegenTime = Date.now();

// Game loop
function gameLoop() {
    update();
    render();
    requestAnimationFrame(gameLoop);
}

function update() {
    // Regenerate health
    if (Date.now() - lastRegenTime > REGEN_INTERVAL) {
        player.health = Math.min(player.health + REGEN_AMOUNT, MAX_HEALTH);
        lastRegenTime = Date.now();
    }

    // Simple movement (WASD)
    const speed = 1;
    if (keys.w && player.y > 0 && tiles[player.y - 1][player.x] === 0) player.y -= speed;
    if (keys.s && player.y < ROOM_HEIGHT - 1 && tiles[player.y + 1][player.x] === 0) player.y += speed;
    if (keys.a && player.x > 0 && tiles[player.y][player.x - 1] === 0) player.x -= speed;
    if (keys.d && player.x < ROOM_WIDTH - 1 && tiles[player.y][player.x + 1] === 0) player.x += speed;

    // Health check and respawn
    if (player.health <= 0) {
        player.x = PLAYER_START_X;
        player.y = PLAYER_START_Y;
        player.health = MAX_HEALTH;
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Render tiles
    for (let y = 0; y < ROOM_HEIGHT; y++) {
        for (let x = 0; x < ROOM_WIDTH; x++) {
            ctx.fillStyle = tiles[y][x] === 1 ? '#444' : '#fff';
            ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
        }
    }

    // Render player
    ctx.fillStyle = '#0f0';
    ctx.fillRect(player.x * TILE_SIZE, player.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);

    // Render health bar
    ctx.fillStyle = '#f00';
    ctx.fillRect(10, 10, player.health * 2, 20);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(10, 10, MAX_HEALTH * 2, 20);
}

// Keyboard input
const keys = { w: false, s: false, a: false, d: false };
document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'w': keys.w = true; break;
        case 's': keys.s = true; break;
        case 'a': keys.a = true; break;
        case 'd': keys.d = true; break;
    }
});
document.addEventListener('keyup', (e) => {
    switch (e.key) {
        case 'w': keys.w = false; break;
        case 's': keys.s = false; break;
        case 'a': keys.a = false; break;
        case 'd': keys.d = false; break;
    }
});

// Start game loop
requestAnimationFrame(gameLoop);
