const canvas = document.createElement('canvas');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

class Vector {
    constructor(x, y) {
        this.x = x;
        this.y = y;
    }

    add(v) {
        return new Vector(this.x + v.x, this.y + v.y);
    }

    subtract(v) {
        return new Vector(this.x - v.x, this.y - v.y);
    }

    scale(s) {
        return new Vector(this.x * s, this.y * s);
    }

    magnitude() {
        return Math.sqrt(this.x * this.x + this.y * this.y);
    }

    normalize() {
        const mag = this.magnitude();
        return new Vector(this.x / mag, this.y / mag);
    }
}

class Particle {
    constructor(pos, vel, size, color) {
        this.pos = pos;
        this.vel = vel;
        this.size = size;
        this.color = color;
        this.lifetime = 1.0;
    }

    update(dt) {
        this.pos = this.pos.add(this.vel.scale(dt));
        this.lifetime -= dt;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.pos.x, this.pos.y, this.size, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
    }
}

class Asteroid {
    constructor(pos, vel, size) {
        this.pos = pos;
        this.vel = vel;
        this.size = size;
        this.vertices = [];
        for (let i = 0; i < 10; i++) {
            const angle = (Math.PI * 2 * i) / 10;
            const offset = new Vector(Math.cos(angle), Math.sin(angle)).scale(this.size * (0.5 + Math.random() * 0.5));
            this.vertices.push(pos.add(offset));
        }
    }

    update(dt) {
        this.pos = this.pos.add(this.vel.scale(dt));
        if (this.pos.x > canvas.width) this.pos.x -= canvas.width;
        if (this.pos.x < 0) this.pos.x += canvas.width;
        if (this.pos.y > canvas.height) this.pos.y -= canvas.height;
        if (this.pos.y < 0) this.pos.y += canvas.height;
    }

    draw() {
        ctx.beginPath();
        ctx.moveTo(this.vertices[0].x, this.vertices[0].y);
        for (let i = 1; i < this.vertices.length; i++) {
            ctx.lineTo(this.vertices[i].x, this.vertices[i].y);
        }
        ctx.closePath();
        ctx.strokeStyle = 'white';
        ctx.stroke();
    }
}

class Ship {
    constructor(pos) {
        this.pos = pos;
        this.vel = new Vector(0, 0);
        this.angle = 0;
        this.size = 10;
        this.thrusting = false;
        this.bullets = [];
    }

    update(dt) {
        if (this.thrusting) {
            const thrust = new Vector(Math.cos(this.angle), Math.sin(this.angle)).scale(0.1);
            this.vel = this.vel.add(thrust);
        }
        this.pos = this.pos.add(this.vel.scale(dt));
        this.vel = this.vel.scale(0.99); // Friction

        for (let i = this.bullets.length - 1; i >= 0; i--) {
            this.bullets[i].update(dt);
            if (this.bullets[i].lifetime <= 0) {
                this.bullets.splice(i, 1);
            }
        }
    }

    draw() {
        ctx.save();
        ctx.translate(this.pos.x, this.pos.y);
        ctx.rotate(this.angle);

        // Draw ship
        ctx.beginPath();
        ctx.moveTo(0, -this.size);
        ctx.lineTo(this.size, this.size);
        ctx.lineTo(-this.size, this.size);
        ctx.closePath();
        ctx.fillStyle = 'red';
        ctx.fill();

        // Draw thrust
        if (this.thrusting) {
            ctx.beginPath();
            ctx.moveTo(0, this.size);
            ctx.lineTo(5, this.size + 10);
            ctx.lineTo(-5, this.size + 10);
            ctx.closePath();
            ctx.fillStyle = 'yellow';
            ctx.fill();
        }

        ctx.restore();

        // Draw bullets
        for (const bullet of this.bullets) {
            bullet.draw();
        }
    }

    shoot() {
        const bulletVel = new Vector(Math.cos(this.angle), Math.sin(this.angle)).scale(5);
        const bulletPos = this.pos.add(new Vector(Math.cos(this.angle), Math.sin(this.angle)).scale(this.size));
        this.bullets.push(new Particle(bulletPos, bulletVel, 2, 'white'));
    }
}

function createParticleBurst(pos, size) {
    for (let i = 0; i < 50; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 5;
        const vel = new Vector(Math.cos(angle) * speed, Math.sin(angle) * speed);
        const color = `rgb(${Math.random() * 255}, ${Math.random() * 255}, ${Math.random() * 255})`;
        particles.push(new Particle(pos, vel, size, color));
    }
}

const ship = new Ship(new Vector(canvas.width / 2, canvas.height / 2));
const asteroids = [];
const particles = [];

for (let i = 0; i < 5; i++) {
    const pos = new Vector(Math.random() * canvas.width, Math.random() * canvas.height);
    const vel = new Vector(Math.random() - 0.5, Math.random() - 0.5);
    const size = Math.random() * 20 + 10;
    asteroids.push(new Asteroid(pos, vel, size));
}

let lastTime = performance.now();

function gameLoop(time) {
    const dt = (time - lastTime) / 1000;
    lastTime = time;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ship.update(dt);
    ship.draw();

    for (const asteroid of asteroids) {
        asteroid.update(dt);
        asteroid.draw();
    }

    for (const particle of particles) {
        particle.update(dt);
        particle.draw();
    }

    // Collision detection
    for (let i = asteroids.length - 1; i >= 0; i--) {
        const asteroid = asteroids[i];
        for (let j = ship.bullets.length - 1; j >= 0; j--) {
            const bullet = ship.bullets[j];
            const dist = bullet.pos.subtract(asteroid.pos).magnitude();
            if (dist < asteroid.size) {
                createParticleBurst(asteroid.pos, asteroid.size);
                asteroids.splice(i, 1);
                ship.bullets.splice(j, 1);
                break;
            }
        }
    }

    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowUp') {
        ship.thrusting = true;
    }
    if (e.key === ' ') {
        ship.shoot();
    }
});

document.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowUp') {
        ship.thrusting = false;
    }
});

document.addEventListener('mousemove', (e) => {
    const mousePos = new Vector(e.clientX, e.clientY);
    const diff = mousePos.subtract(ship.pos);
    ship.angle = Math.atan2(diff.y, diff.x);
});

requestAnimationFrame(gameLoop);
