const PLAYER_SPEED = 5;
const BULLET_SPEED = 10;
const ENEMY_SPEED = 2;
const SHOT_INTERVAL = 500; // milliseconds

// Game state
let player = {
    x: CANVAS_WIDTH / 2,
    y: CANVAS_HEIGHT - 50,
    width: 20,
    height: 20,
    color: 'blue'
};

let bullets = [];
let enemies = [];
let score = 0;
let gameOver = false;
let lastShotTime = 0;

// Canvas setup
