function drawText(text, x, y, color = 'black') {
    ctx.fillStyle = color;
    ctx.font = '20px Arial';
    ctx.fillText(text, x * grid, y * grid + grid / 2);
}

function update() {
    if (state === 'menu') {
        if (keys['ArrowUp'] || keys['ArrowDown']) {
            state = 'playing';
        }
    } else if (state === 'playing') {
        const head = {x: snake[0].x + direction.x, y: snake[0].y + direction.y};
        snake.unshift(head);

        if (head.x === food.x && head.y === food.y) {
            score++;
            placeFood();
        } else {
            snake.pop();
        }

        if (head.x < 0 || head.x >= canvas.width / grid || head.y < 0 || head.y >= canvas.height / grid || snake.some((segment, index) => index !== 0 && segment.x === head.x && segment.y === head.y)) {
            state = 'gameover';
        }
    } else if (state === 'gameover') {
        if (keys['ArrowUp'] || keys['ArrowDown']) {
            state = 'menu';
            snake = [{x: 10, y: 10}];
            direction = {x: 0, y: 0};
            food = {x: 15, y: 15};
            score = 0;
        }
    }
}

function render() {
