    if (state === 'menu') {
        drawText('Press Up/Down to Start', 5, 10);
    } else if (state === 'playing') {
        snake.forEach(segment => drawRect(segment.x, segment.y, 'green'));
        drawRect(food.x, food.y, 'red');
        drawText(`Score: ${score}`, 0, 0);
    } else if (state === 'gameover') {
        drawText('Game Over', 5, 10);
        drawText('Press Up/Down to Restart', 5, 12);
    }
}

function placeFood() {
    food.x = Math.floor(Math.random() * (canvas.width / grid));
    food.y = Math.floor(Math.random() * (canvas.height / grid));
}

const keys = {};
