window.addEventListener('keyup', e => keys[e.key] = false);

function gameLoop() {
    if (state === 'playing') {
        if (keys['ArrowUp'] && direction.y === 0) direction = {x: 0, y: -1};
        if (keys['ArrowDown'] && direction.y === 0) direction = {x: 0, y: 1};
        if (keys['ArrowLeft'] && direction.x === 0) direction = {x: -1, y: 0};
        if (keys['ArrowRight'] && direction.x === 0) direction = {x: 1, y: 0};
    }
    update();
    render();
    requestAnimationFrame(gameLoop);
}

