  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'red';
    ctx.fill();
    ctx.closePath();
  }

  checkHit(x, y) {
    const dx = this.x - x;
    const dy = this.y - y;
    return dx * dx + dy * dy <= this.radius * this.radius;
  }
}

const taps = [];

function spawnTap() {
  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  taps.push(new Tap(x, y));
}

function update() {
  if (performance.now() - lastSpawnTime > spawnInterval) {
    spawnTap();
    lastSpawnTime = performance.now();
    spawnInterval -= 100; // Increase difficulty by reducing spawn interval
    if (spawnInterval < 500) spawnInterval = 500;
  }

  taps.forEach((tap, index) => {
    if (tap.checkHit(canvas.width / 2, canvas.height / 2)) {
      taps.splice(index, 1);
      score++;
    }
  });
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  taps.forEach(tap => tap.draw());

  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Difficulty: ${difficulty}`, 10, 60);
}

function gameLoop() {
  const now = performance.now();
  let delta = now - lastTickTime;

  while (delta >= MS_PER_TICK) {
    update();
    lastTickTime += MS_PER_TICK;
    delta -= MS_PER_TICK;
  }

  render();

  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', (e) => {
  const rect = canvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  taps.forEach((tap, index) => {
    if (tap.checkHit(x, y)) {
      taps.splice(index, 1);
      score++;
    }
  });
});

gameLoop();
