(function() {
    const canvas = document.createElement('canvas');
    document.body.appendChild(canvas);
    const ctx = canvas.getContext('2d');
    let dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);

    const gravity = 0.25;
    const jumpStrength = -4;
    const pipeWidth = 50;
    const pipeGap = 150;
    const pipeSpeed = 2;

    let player = {
        x: 50,
        y: canvas.height / 2,
        vy: 0,
        width: 20,
        height: 20,
        color: 'blue'
    };

    let pipes = [];
    let score = 0;

    function createPipe() {
        let height = Math.random() * (canvas.height - pipeGap - 100) + 50;
        pipes.push({
            x: canvas.width,
            y: height,
            width: pipeWidth,
            height: canvas.height,
            color: 'green'
        });
    }

    function updatePlayer() {
        player.vy += gravity;
        player.y += player.vy;
        if (player.y + player.height > canvas.height || player.y < 0) {
            resetGame();
        }
    }

    function updatePipes() {
        pipes.forEach(pipe => {
            pipe.x -= pipeSpeed;
        });
        pipes = pipes.filter(pipe => pipe.x + pipe.width > 0);

        if (pipes.length === 0 || pipes[pipes.length - 1].x + pipeWidth < canvas.width - 200) {
            createPipe();
        }
    }

    function checkCollision() {
        pipes.forEach(pipe => {
            if (player.x + player.width > pipe.x &&
                player.x < pipe.x + pipe.width &&
                (player.y < pipe.y || player.y + player.height > pipe.y + pipeGap)) {
                resetGame();
            }
        });
    }

    function drawPlayer() {
        ctx.fillStyle = player.color;
        ctx.fillRect(player.x, player.y, player.width, player.height);
    }

    function drawPipes() {
        pipes.forEach(pipe => {
            ctx.fillStyle = pipe.color;
            ctx.fillRect(pipe.x, 0, pipe.width, pipe.y);
            ctx.fillRect(pipe.x, pipe.y + pipeGap, pipe.width, pipe.height);
        });
    }

    function drawScore() {
        ctx.font = '24px Arial';
        ctx.fillStyle = 'black';
        ctx.fillText(`Score: ${score}`, 10, 30);
    }

    function resetGame() {
        pipes = [];
        player.y = canvas.height / 2;
        player.vy = 0;
        score = 0;
    }

    function update() {
        updatePlayer();
        updatePipes();
        checkCollision();
        if (player.x + player.width > pipes[0].x && player.x < pipes[0].x + pipes[0].width) {
            score++;
        }
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        drawPlayer();
        drawPipes();
        drawScore();
    }

    function gameLoop() {
        update();
        draw();
        requestAnimationFrame(gameLoop);
    }

    function jump() {
        player.vy = jumpStrength;
    }

    canvas.addEventListener('click', jump);

    createPipe();
    gameLoop();
})();
