const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const friction = 0.9;
const powerUpChance = 0.05;

let balls = [];
let powerUps = [];

class Ball {
    constructor(x, y, radius, color) {
        this.x = x;
        this.y = y;
        this.radius = radius;
        this.color = color;
        this.velocityX = Math.random() * 5 - 2.5;
        this.velocityY = Math.random() * 5 - 2.5;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.closePath();
    }

    update() {
        this.velocityY += gravity;
        this.x += this.velocityX;
        this.y += this.velocityY;

        if (this.x + this.radius > canvas.width || this.x - this.radius < 0) {
            this.velocityX *= -friction;
        }
        if (this.y + this.radius > canvas.height) {
            this.velocityY *= -friction;
        } else if (this.y - this.radius < 0) {
            this.velocityY *= -friction;
        }
    }

    collectPowerUp(powerUp) {
        if (distance(this, powerUp) < this.radius + powerUp.radius) {
            return true;
        }
        return false;
    }
}

class PowerUp {
    constructor(x, y, radius, color) {
        this.x = x;
        this.y = y;
        this.radius = radius;
        this.color = color;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.closePath();
    }

    update() {
        // Power-ups don't move in this example
    }
}

function distance(obj1, obj2) {
    return Math.sqrt(Math.pow(obj1.x - obj2.x, 2) + Math.pow(obj1.y - obj2.y, 2));
}

function spawnPowerUp() {
    if (Math.random() < powerUpChance) {
        powerUps.push(new PowerUp(Math.random() * canvas.width, Math.random() * canvas.height, 10, 'blue'));
    }
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    balls.forEach((ball, ballIndex) => {
        ball.update();
        ball.draw();

        powerUps.forEach((powerUp, powerUpIndex) => {
            if (ball.collectPowerUp(powerUp)) {
                powerUps.splice(powerUpIndex, 1);
                // Add effects of power-up, e.g., increase ball size
                ball.radius += 2;
            } else {
                powerUp.draw();
                powerUp.update();
            }
        });
    });

    spawnPowerUp();

    requestAnimationFrame(update);
}

// Initialize with one ball
balls.push(new Ball(canvas.width / 2, canvas.height / 2, 20, 'red'));

update();
