class Economy {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  debit(item, amount) {
    if (this.prices[item] >= amount) {
      this.prices[item] -= amount;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, amount) {
    if (this.items[item]) {
      this.items[item] += amount;
    } else {
      this.items[item] = amount;
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item, amount) {
    const price = this.economy.getPrice(item) * amount;
    if (this.economy.debit(item, price)) {
      this.inventory.addItem(item, amount);
      return true;
    }
    return false;
  }
}

class Crafting {
  constructor(recipes, inventory) {
    this.recipes = recipes;
    this.inventory = inventory;
  }

  canCraft(recipeName) {
    const recipe = this.recipes[recipeName];
    if (!recipe) return false;
    for (const [item, amount] of Object.entries(recipe)) {
      if (this.inventory.getItemCount(item) < amount) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName) {
    const recipe = this.recipes[recipeName];
    if (!recipe) return false;
    for (const [item, amount] of Object.entries(recipe)) {
      this.inventory.addItem(item, -amount);
    }
    return true;
  }
}

// Demo
const economy = new Economy({ wood: 100, stone: 50, iron: 200 });
const inventory = new Inventory();
const store = new Store(economy, inventory);
const crafting = new Crafting({
  'wooden sword': { wood: 10, stone: 2 },
  'iron sword': { iron: 20, wood: 5 }
}, inventory);

console.log('Initial Economy:', economy.prices);
console.log('Initial Inventory:', inventory.items);

console.log('Buying 5 wood:', store.purchase('wood', 5));
console.log('Buying 3 stone:', store.purchase('stone', 3));

console.log('Crafting wooden sword:', crafting.craft('wooden sword'));
console.log('Crafting iron sword (should fail):', crafting.craft('iron sword'));

console.log('Final Economy:', economy.prices);
console.log('Final Inventory:', inventory.items);
