const ctx = canvas.getContext('2d');

let tileWidth = 32;
let tileHeight = 32;
let roomWidth = 10;
let roomHeight = 10;
let playerX = roomWidth / 2;
let playerY = roomHeight / 2;
let playerHealth = 100;
let maxHealth = 100;

const dpr = window.devicePixelRatio;
canvas.width = roomWidth * tileWidth * dpr;
canvas.height = roomHeight * tileHeight * dpr;
canvas.style.width = `${roomWidth * tileWidth}px`;
canvas.style.height = `${roomHeight * tileHeight}px`;
ctx.scale(dpr, dpr);

const tiles = [
  { type: 'floor', color: 'gray' },
  { type: 'wall', color: 'brown' },
];

const room = Array.from({ length: roomHeight }, () =>
  Array.from({ length: roomWidth }, () => Math.random() > 0.7 ? tiles[1] : tiles[0])
);

function drawRoom() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let y = 0; y < roomHeight; y++) {
    for (let x = 0; x < roomWidth; x++) {
      ctx.fillStyle = room[y][x].color;
      ctx.fillRect(x * tileWidth, y * tileHeight, tileWidth, tileHeight);
    }
  }
}

function drawPlayer() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(playerX * tileWidth, playerY * tileHeight, tileWidth, tileHeight);
}

function drawHealthBar() {
  ctx.fillStyle = 'red';
  ctx.fillRect(10, roomHeight * tileHeight + 10, (playerHealth / maxHealth) * (roomWidth * tileWidth - 20), 20);
  ctx.strokeStyle = 'black';
  ctx.strokeRect(10, roomHeight * tileHeight + 10, roomWidth * tileWidth - 20, 20);
}

function movePlayer(dx, dy) {
  const newX = playerX + dx;
  const newY = playerY + dy;
  if (newX >= 0 && newX < roomWidth && newY >= 0 && newY < roomHeight && room[newY][newX].type === 'floor') {
    playerX = newX;
    playerY = newY;
  }
}

function handleKeyDown(event) {
  switch (event.key) {
    case 'ArrowUp': movePlayer(0, -1); break;
    case 'ArrowDown': movePlayer(0, 1); break;
    case 'ArrowLeft': movePlayer(-1, 0); break;
    case 'ArrowRight': movePlayer(1, 0); break;
  }
}

function update() {
  drawRoom();
  drawPlayer();
  drawHealthBar();
}

function gameLoop() {
  update();
  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('keydown', handleKeyDown);
canvas.focus();
gameLoop();
