const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const fixedTimestep = 1000 / 60; // 60 frames per second
let lastTime = 0;
let accumulator = 0;

const waveLength = 10; // Number of taps per wave
let waveCount = 0;
let tapsInWave = 0;
let targetTime = 1000; // Time in ms for each tap

const tapRadius = 20;
let tapPositions = [];
let isTapActive = false;

canvas.addEventListener('click', (event) => {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;

  if (isTapActive) {
    for (let i = 0; i < tapPositions.length; i++) {
      const dx = x - tapPositions[i].x;
      const dy = y - tapPositions[i].y;
      if (dx * dx + dy * dy < tapRadius * tapRadius) {
        tapPositions.splice(i, 1);
        tapsInWave++;
        if (tapsInWave >= waveLength) {
          waveCount++;
          tapsInWave = 0;
          targetTime *= 0.95; // Speed up after each wave
        }
        break;
      }
    }
  }
});

function update(dt) {
  if (isTapActive) {
    const now = Date.now();
    if (now - lastTime >= targetTime) {
      lastTime = now;
      const x = Math.random() * canvas.width;
      const y = Math.random() * canvas.height;
      tapPositions.push({ x, y });
    }
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'black';
  ctx.font = '30px Arial';
  ctx.fillText(`Wave: ${waveCount + 1}`, 20, 40);
  ctx.fillText(`Taps: ${tapsInWave}`, 20, 80);

  ctx.fillStyle = 'red';
  for (const tap of tapPositions) {
    ctx.beginPath();
    ctx.arc(tap.x, tap.y, tapRadius, 0, Math.PI * 2);
    ctx.fill();
  }
}

function gameLoop(timestamp) {
  const dt = timestamp - lastTime;
  lastTime = timestamp;

  accumulator += dt;

  while (accumulator >= fixedTimestep) {
    update(fixedTimestep);
    accumulator -= fixedTimestep;
  }

  render();

  requestAnimationFrame(gameLoop);
}

// Start the game
isTapActive = true;
gameLoop(performance.now());
