class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(eventName, callback) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(callback);
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(callback => callback(data));
    }
  }
}

class Order {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('orderReceived', this.placeOrder.bind(this));
  }

  placeOrder(order) {
    console.log(`Order placed: ${order}`);
    this.eventBus.emit('orderPlaced', order);
  }
}

class Kitchen {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('orderPlaced', this.prepareOrder.bind(this));
  }

  prepareOrder(order) {
    console.log(`Preparing order: ${order}`);
    setTimeout(() => {
      this.eventBus.emit('orderReady', order);
    }, 2000); // Simulate order preparation time
  }
}

class Customer {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('orderReady', this.receiveOrder.bind(this));
  }

  receiveOrder(order) {
    console.log(`Order received: ${order}`);
  }
}

