class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // ingredients is an array of { item: 'string', quantity: number }
  }
}

class Inventory {
  constructor(items = {}) {
    this.items = items; // items is an object { item: 'string', quantity: number }
  }

  hasIngredients(recipe) {
    return recipe.ingredients.every(ingr => this.items[ingr.item] >= ingr.quantity);
  }

  consumeIngredients(recipe) {
    recipe.ingredients.forEach(ingr => {
      this.items[ingr.item] -= ingr.quantity;
    });
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }
}

class Crafting {
  constructor(inventory) {
    this.inventory = inventory;
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    return recipe && this.inventory.hasIngredients(recipe);
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe && this.inventory.hasIngredients(recipe)) {
      this.inventory.consumeIngredients(recipe);
      // Assuming crafting a recipe results in a new item with the same name as the recipe
      this.inventory.addItem(recipeName, 1);
      return true;
    }
    return false;
  }
}

