const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const FPS = 60;
const FIXED_TIMESTEP = 1000 / FPS;

let lastTime = performance.now();
let accumulator = 0;

const fish = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    radius: 20,
    speed: 2,
    direction: Math.random() * Math.PI * 2,
    caught: false
};

const hook = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    radius: 5,
    angle: 0,
    speed: 0.1
};

let comboMultiplier = 1;
let comboCounter = 0;

function update(deltaTime) {
    if (!fish.caught) {
        fish.x += fish.speed * Math.cos(fish.direction);
        fish.y += fish.speed * Math.sin(fish.direction);

        if (fish.x < 0 || fish.x > canvas.width || fish.y < 0 || fish.y > canvas.height) {
            fish.direction += Math.PI;
        }

        if (Math.hypot(fish.x - hook.x, fish.y - hook.y) < fish.radius + hook.radius) {
            fish.caught = true;
            comboCounter++;
            comboMultiplier = Math.min(10, comboCounter);
        }
    } else {
        const distance = Math.hypot(fish.x - hook.x, fish.y - hook.y);
        if (distance > 5) {
            const angle = Math.atan2(fish.y - hook.y, fish.x - hook.x);
            fish.x -= Math.cos(angle) * fish.speed;
            fish.y -= Math.sin(angle) * fish.speed;
        } else {
            fish.x = hook.x;
            fish.y = hook.y;
        }
    }

    hook.angle += hook.speed;
    hook.x = canvas.width / 2 + 100 * Math.cos(hook.angle);
    hook.y = canvas.height / 2 + 100 * Math.sin(hook.angle);
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.beginPath();
    ctx.arc(hook.x, hook.y, hook.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'black';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(fish.x, fish.y, fish.radius, 0, Math.PI * 2);
    ctx.fillStyle = fish.caught ? 'blue' : 'orange';
    ctx.fill();

    ctx.font = '24px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText(`Combo: x${comboMultiplier}`, 10, 30);
}

function gameLoop() {
    const now = performance.now();
    const deltaTime = now - lastTime;
    lastTime = now;

    accumulator += deltaTime;

    while (accumulator >= FIXED_TIMESTEP) {
        update(FIXED_TIMESTEP);
        accumulator -= FIXED_TIMESTEP;
    }

    draw();

    requestAnimationFrame(gameLoop);
}

gameLoop();
