const CARD_WIDTH = 100;
const CARD_HEIGHT = 150;
const MARGIN = 10;
const CARD_PAIRS = 8;
const CARDS = [...Array(CARD_PAIRS)].flatMap((_, i) => [i, i]);
let score = 0;
let flippedCards = [];
let gameStarted = false;
let gameOver = false;
let lastTime = 0;
const FPS = 60;
const FIXED_TIMESTEP = 1000 / FPS;

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
}

function drawCard(x, y, value, flipped) {
  ctx.fillStyle = 'white';
  ctx.fillRect(x, y, CARD_WIDTH, CARD_HEIGHT);
  ctx.strokeStyle = 'black';
  ctx.strokeRect(x, y, CARD_WIDTH, CARD_HEIGHT);
  if (flipped) {
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(value, x + 30, y + 70);
  }
}

function checkGameOver() {
  if (flippedCards.length === CARDS.length) {
    gameOver = true;
    ctx.fillStyle = 'black';
    ctx.font = '30px Arial';
    ctx.fillText('Game Over!', 300, 300);
  }
}

function update(deltaTime) {
  if (gameOver) return;
  if (flippedCards.length === 2) {
    if (CARDS[flippedCards[0]] !== CARDS[flippedCards[1]]) {
      setTimeout(() => {
        flippedCards = [];
      }, 1000);
    } else {
      score += 10;
      flippedCards = [];
    }
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 20);
  if (!gameStarted) {
    ctx.fillText('Click to start', 350, 300);
    return;
  }
  for (let i = 0; i < CARD_PAIRS * 2; i++) {
    const row = Math.floor(i / 4);
    const col = i % 4;
    const x = col * (CARD_WIDTH + MARGIN) + 50;
    const y = row * (CARD_HEIGHT + MARGIN) + 50;
    drawCard(x, y, CARDS[i], flippedCards.includes(i));
  }
  checkGameOver();
}

function handleCardClick(event) {
  if (gameOver) return;
  if (!gameStarted) {
    gameStarted = true;
    shuffle(CARDS);
  }
  const x = event.offsetX;
  const y = event.offsetY;
  for (let i = 0; i < CARD_PAIRS * 2; i++) {
    const row = Math.floor(i / 4);
    const col = i % 4;
    const cardX = col * (CARD_WIDTH + MARGIN) + 50;
    const cardY = row * (CARD_HEIGHT + MARGIN) + 50;
    if (x >= cardX && x <= cardX + CARD_WIDTH && y >= cardY && y <= cardY + CARD_HEIGHT) {
      if (!flippedCards.includes(i)) {
        flippedCards.push(i);
      }
    }
  }
}

canvas.addEventListener('click', handleCardClick);

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  lastTime = timestamp;
  update(deltaTime);
  render();
  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
