canvas.width = 800;
canvas.height = 600;

class GameObject {
  constructor(x, y, width, height) {
    this.x = x;
    this.y = y;
    this.width = width;
    this.height = height;
  }

  draw() {
    ctx.fillStyle = 'black';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }

  update() {
    // To be overridden by subclasses
  }
}

class Player extends GameObject {
  constructor(x, y) {
    super(x, y, 20, 20);
    this.speed = 5;
  }

  update(keys) {
    if (keys['ArrowUp'] && this.y > 0) this.y -= this.speed;
    if (keys['ArrowDown'] && this.y < canvas.height - this.height) this.y += this.speed;
    if (keys['ArrowLeft'] && this.x > 0) this.x -= this.speed;
    if (keys['ArrowRight'] && this.x < canvas.width - this.width) this.x += this.speed;
  }

  draw() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

class Enemy extends GameObject {
  constructor(x, y) {
    super(x, y, 15, 15);
    this.speed = 3;
    this.direction = Math.random() * Math.PI * 2;
  }

  update(player) {
    this.x += Math.cos(this.direction) * this.speed;
    this.y += Math.sin(this.direction) * this.speed;

    if (this.x < 0 || this.x > canvas.width - this.width) this.direction = Math.PI - this.direction;
    if (this.y < 0 || this.y > canvas.height - this.height) this.direction = -this.direction;

    const distance = Math.hypot(player.x - this.x, player.y - this.y);
    if (distance < this.width + player.width) {
      this.direction = Math.atan2(player.y - this.y, player.x - this.x);
    }
  }

  draw() {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

class PowerUp extends GameObject {
  constructor(x, y) {
    super(x, y, 10, 10);
  }

  draw() {
    ctx.fillStyle = 'green';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

const player = new Player(canvas.width / 2, canvas.height / 2);
const enemies = [new Enemy(50, 50), new Enemy(200, 300), new Enemy(550, 100)];
const powerUps = [new PowerUp(100, 100), new PowerUp(300, 400), new PowerUp(600, 500)];

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  player.update(keys);
  player.draw();

  enemies.forEach(enemy => {
    enemy.update(player);
    enemy.draw();
  });

  powerUps.forEach(powerUp => {
    powerUp.draw();
  });

  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
