const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const rhythm = [
    { time: 1000, key: 'ArrowUp' },
    { time: 2000, key: 'ArrowRight' },
    { time: 3000, key: 'ArrowDown' },
    { time: 4000, key: 'ArrowLeft' },
    { time: 5000, key: 'Space' }
];

let score = 0;
let startTime = performance.now();

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '30px Arial';
    ctx.fillText(`Score: ${score}`, 10, 50);

    const now = performance.now() - startTime;
    const currentTime = Math.floor(now / 1000) * 1000;
    const currentRhythm = rhythm.find(r => r.time === currentTime);

    if (currentRhythm) {
        ctx.fillText(`Tap ${currentRhythm.key}`, canvas.width / 2, canvas.height / 2);
    }

    requestAnimationFrame(render);
}

function handleInput(event) {
    const now = performance.now() - startTime;
    const currentTime = Math.floor(now / 1000) * 1000;
    const currentRhythm = rhythm.find(r => r.time === currentTime);

    if (currentRhythm && currentRhythm.key === event.key) {
        score += 10;
    }
}

canvas.addEventListener('click', () => {
    handleInput({ key: 'Space' });
});

document.addEventListener('keydown', handleInput);

render();
