const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 400;
const ctx = canvas.getContext('2d');

const gridSize = 20;
const tileCount = canvas.width / gridSize;

let snake = [{ x: 10, y: 10 }];
let direction = { x: 0, y: 0 };
let food = { x: Math.floor(Math.random() * tileCount), y: Math.floor(Math.random() * tileCount) };

function drawRect(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * gridSize, y * gridSize, gridSize, gridSize);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawRect(food.x, food.y, 'red');

  for (let i = 0; i < snake.length; i++) {
    drawRect(snake[i].x, snake[i].y, i === 0 ? 'green' : 'lightgreen');
  }

  const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

  if (head.x < 0 || head.x >= tileCount || head.y < 0 || head.y >= tileCount || snake.some(segment => segment.x === head.x && segment.y === head.y)) {
    resetGame();
    return;
  }

  snake.unshift(head);

  if (head.x === food.x && head.y === food.y) {
    food = { x: Math.floor(Math.random() * tileCount), y: Math.floor(Math.random() * tileCount) };
  } else {
    snake.pop();
  }

  requestAnimationFrame(draw);
}

function resetGame() {
  snake = [{ x: 10, y: 10 }];
  direction = { x: 0, y: 0 };
  food = { x: Math.floor(Math.random() * tileCount), y: Math.floor(Math.random() * tileCount) };
}

document.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowUp':
      if (direction.y === 0) direction = { x: 0, y: -1 };
      break;
    case 'ArrowDown':
      if (direction.y === 0) direction = { x: 0, y: 1 };
      break;
    case 'ArrowLeft':
      if (direction.x === 0) direction = { x: -1, y: 0 };
      break;
    case 'ArrowRight':
      if (direction.x === 0) direction = { x: 1, y: 0 };
      break;
  }
});

let lastMouseX = 0;
let lastMouseY = 0;

function getDirection(x, y) {
  if (Math.abs(x - lastMouseX) > Math.abs(y - lastMouseY)) {
    return { x: x > lastMouseX ? 1 : -1, y: 0 };
  } else {
    return { x: 0, y: y > lastMouseY ? 1 : -1 };
  }
}

canvas.addEventListener('mousemove', (e) => {
  lastMouseX = Math.floor(e.offsetX / gridSize);
  lastMouseY = Math.floor(e.offsetY / gridSize);
});

canvas.addEventListener('click', (e) => {
  const dir = getDirection(lastMouseX, lastMouseY);
  if (dir.x !== -direction.x && dir.y !== -direction.y) {
    direction = dir;
  }
});

draw();
