class Economy {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Store {
  constructor(economy, initialItems = {}) {
    this.economy = economy;
    this.items = initialItems; // { itemName: price }
  }

  getItemPrice(itemName) {
    return this.items[itemName];
  }

  buyItem(itemName) {
    const price = this.getItemPrice(itemName);
    if (price !== undefined && this.economy.withdraw(price)) {
      return true;
    }
    return false;
  }

  addItem(itemName, price) {
    if (price > 0) {
      this.items[itemName] = price;
    }
  }
}

class Inventory {
  constructor(initialItems = {}) {
    this.items = initialItems; // { itemName: quantity }
  }

  getItemCount(itemName) {
    return this.items[itemName] || 0;
  }

  addItem(itemName, quantity) {
    if (quantity > 0) {
      this.items[itemName] = (this.items[itemName] || 0) + quantity;
    }
  }

  removeItem(itemName, quantity) {
    if (quantity > 0 && this.getItemCount(itemName) >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
    }
  }
}

