class Farm {
  constructor() {
    this.crops = [];
  }

  plant(seed) {
    const crop = new Crop(seed);
    this.crops.push(crop);
    return crop;
  }

  harvest() {
    const harvestableCrops = this.crops.filter(crop => crop.isReady());
    this.crops = this.crops.filter(crop => !crop.isReady());
    return harvestableCrops;
  }
}

class Crop {
  constructor(seed) {
    this.seed = seed;
    this.daysGrown = 0;
  }

  grow() {
    this.daysGrown++;
  }

  isReady() {
    return this.daysGrown >= 30; // Assume a crop is ready after 30 days
  }
}

class Market {
  constructor() {
    this.inventory = {};
  }

  sellCrop(crop) {
    if (!this.inventory[crop.seed]) {
      this.inventory[crop.seed] = 0;
    }
    this.inventory[crop.seed]++;
  }

  getInventory() {
    return { ...this.inventory };
  }
}

// Coordinator to wire the systems together
class GameCoordinator {
  constructor() {
    this.farm = new Farm();
    this.market = new Market();
  }

  plantSeed(seed) {
    const crop = this.farm.plant(seed);
    return crop;
  }

  growCrops() {
    this.farm.crops.forEach(crop => crop.grow());
  }

  harvestAndSell() {
    const harvestedCrops = this.farm.harvest();
    harvestedCrops.forEach(crop => this.market.sellCrop(crop));
  }

  getMarketInventory() {
    return this.market.getInventory();
  }
}

// Demo to exercise the interaction
const coordinator = new GameCoordinator();

// Plant some seeds
const wheatCrop = coordinator.plantSeed('Wheat');
const cornCrop = coordinator.plantSeed('Corn');

// Grow crops for 30 days
for (let i = 0; i < 30; i++) {
  coordinator.growCrops();
}

// Harvest and sell crops
coordinator.harvestAndSell();

// Check market inventory
console.log('Market Inventory:', coordinator.getMarketInventory());
// Expected output: Market Inventory: { Wheat: 1, Corn: 1 }
