        this.level -= 5;
        console.log(`Hunger level: ${this.level}`);
        if (this.level <= 0) {
            console.log('You are too hungry!');
            this.eventBus.emit('hungerCritical');
        }
    }

    eat(amount) {
        this.level += amount;
        if (this.level > 100) {
            this.level = 100;
        }
        console.log(`Eaten ${amount}, hunger level: ${this.level}`);
    }
}

class Energy {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.level = 100;
        this.eventBus.subscribe('timePassed', this.decreaseEnergy.bind(this));
        this.eventBus.subscribe('hungerCritical', this.consumedByHunger.bind(this));
    }

    decreaseEnergy() {
        this.level -= 3;
        console.log(`Energy level: ${this.level}`);
        if (this.level <= 0) {
            console.log('You are too tired!');
        }
    }

    consumedByHunger() {
        this.level -= 20;
        console.log(`Energy depleted by hunger, level: ${this.level}`);
    }

    rest(amount) {
        this.level += amount;
        if (this.level > 100) {
            this.level = 100;
        }
        console.log(`Restored ${amount}, energy level: ${this.level}`);
    }
}

