class Demand {
  constructor(initialDemand) {
    this.demand = initialDemand;
  }

  getDemand() {
    return this.demand;
  }

  adjustDemand(change) {
    this.demand += change;
  }
}

// Store System
class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  getProfit() {
    return this.pricing.getPrice() * this.demand.getDemand();
  }

  sellItems(quantity) {
    if (quantity <= this.demand.getDemand()) {
      this.demand.adjustDemand(-quantity);
      return true;
    }
    return false;
  }

  restockItems(quantity) {
    this.demand.adjustDemand(quantity);
  }
}

