class Clock {
  constructor() {
    this.time = 0;
  }

  tick() {
    this.time++;
    return this.time;
  }

  getTime() {
    return this.time;
  }
}

class Hunger {
  constructor(clock) {
    this.clock = clock;
    this.hungerLevel = 50;
  }

  update() {
    if (this.clock.getTime() % 5 === 0) {
      this.hungerLevel -= 10;
      if (this.hungerLevel < 0) this.hungerLevel = 0;
    }
  }

  getHungerLevel() {
    return this.hungerLevel;
  }
}

class Energy {
  constructor(clock) {
    this.clock = clock;
    this.energyLevel = 100;
  }

  update() {
    if (this.clock.getTime() % 3 === 0) {
      this.energyLevel -= 5;
      if (this.energyLevel < 0) this.energyLevel = 0;
    }
  }

  getEnergyLevel() {
    return this.energyLevel;
  }
}

