const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const devicePixelRatio = window.devicePixelRatio || 1;
canvas.width = window.innerWidth * devicePixelRatio;
canvas.height = window.innerHeight * devicePixelRatio;
ctx.scale(devicePixelRatio, devicePixelRatio);

const gravity = 0.5;
const jumpForce = -10;
const birdWidth = 30;
const birdHeight = 30;
const pipeWidth = 60;
const pipeGap = 150;
const pipeSpeed = 2;
const maxPipes = 4;
const playerHealth = 3;

let birdX = birdWidth;
let birdY = canvas.height / 2;
let birdVelocity = 0;
let pipes = [];
let health = playerHealth;
let gameRunning = true;

function Bird(x, y) {
  this.x = x;
  this.y = y;
  this.width = birdWidth;
  this.height = birdHeight;
  this.draw = function() {
    ctx.fillStyle = 'yellow';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  };
  this.update = function() {
    this.y += birdVelocity;
    birdVelocity += gravity;
    if (this.y + this.height > canvas.height) {
      this.y = canvas.height - this.height;
      birdVelocity = 0;
    }
    if (this.y < 0) {
      this.y = 0;
      birdVelocity = 0;
    }
  };
  this.jump = function() {
    birdVelocity = jumpForce;
  };
}

function Pipe(x, gap) {
  this.x = x;
  this.width = pipeWidth;
  this.height = canvas.height;
  this.gap = gap;
  this.draw = function() {
    ctx.fillStyle = 'green';
    ctx.fillRect(this.x, 0, this.width, this.height - this.gap);
    ctx.fillRect(this.x, this.height - this.gap + this.width, this.width, this.gap);
  };
  this.update = function() {
    this.x -= pipeSpeed;
  };
}

function drawHealthBar() {
  ctx.fillStyle = 'red';
  ctx.fillRect(10, 10, health * 20, 10);
}

function checkCollision(bird, pipes) {
  for (let pipe of pipes) {
    if (bird.x < pipe.x + pipe.width &&
        bird.x + bird.width > pipe.x &&
        (bird.y < pipe.height - pipe.gap || bird.y + bird.height > pipe.height - pipe.gap + pipe.width)) {
      return true;
    }
  }
  return false;
}

function resetGame() {
  birdY = canvas.height / 2;
  birdVelocity = 0;
  pipes = [];
  health = playerHealth;
  gameRunning = true;
}

function gameLoop() {
  if (!gameRunning) return;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (Math.random() < 0.05 && pipes.length < maxPipes) {
    pipes.push(new Pipe(canvas.width, Math.random() * (canvas.height - pipeGap)));
  }

  pipes.forEach(pipe => {
    pipe.update();
    pipe.draw();
  });

  pipes = pipes.filter(pipe => pipe.x + pipe.width > 0);

  const bird = new Bird(birdX, birdY);
  bird.update();
  bird.draw();

  drawHealthBar();

  if (checkCollision(bird, pipes)) {
    health--;
    if (health <= 0) {
      gameRunning = false;
      alert('Game Over! Press OK to restart.');
      resetGame();
    }
  }

  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', () => {
  if (gameRunning) {
    bird.jump();
  }
});

resetGame();
gameLoop();
