    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  setPrice(item, price) {
    this.prices[item] = price;
  }
}

class Demand {
  constructor(demand = {}) {
    this.demand = demand;
  }

  getDemand(item) {
    return this.demand[item] || 0;
  }

  setDemand(item, demand) {
    this.demand[item] = demand;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
  }

  purchase(item, quantity) {
    const pricePerItem = this.pricing.getPrice(item);
    const totalCost = pricePerItem * quantity;

    if (this.demand.getDemand(item) >= quantity) {
      console.log(`Purchased ${quantity} of ${item} for ${totalCost}`);
      this.demand.setDemand(item, this.demand.getDemand(item) - quantity);
      this.inventory[item] = (this.inventory[item] || 0) + quantity;
      return true;
    } else {
      console.log(`Not enough demand for ${quantity} of ${item}`);
      return false;
    }
  }

  getInventory() {
    return this.inventory;
  }
}

