// Player
const player = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    radius: 10,
    speed: 5,
    angle: Math.PI / 2,
    update: function() {
        const dx = Math.cos(this.angle) * this.speed;
        const dy = Math.sin(this.angle) * this.speed;
        this.x += dx;
        this.y += dy;
        // Wrap around screen edges
        if (this.x < 0) this.x = canvas.width;
        if (this.x > canvas.width) this.x = 0;
        if (this.y < 0) this.y = canvas.height;
        if (this.y > canvas.height) this.y = 0;
    },
    draw: function() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'white';
        ctx.fill();
    }
};

// Bullet
function Bullet(x, y, angle, speed) {
    this.x = x;
    this.y = y;
    this.radius = 2;
    this.speed = speed;
    this.angle = angle;
    this.update = function() {
        this.x += Math.cos(this.angle) * this.speed;
        this.y += Math.sin(this.angle) * this.speed;
    };
    this.draw = function() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'red';
        ctx.fill();
    };
}

// Asteroid
function Asteroid(x, y, radius, speed) {
    this.x = x;
    this.y = y;
    this.radius = radius;
    this.speed = speed;
    this.angle = Math.random() * Math.PI * 2;
    this.update = function() {
        this.x += Math.cos(this.angle) * this.speed;
        this.y += Math.sin(this.angle) * this.speed;
        // Wrap around screen edges
        if (this.x < 0) this.x = canvas.width;
        if (this.x > canvas.width) this.x = 0;
        if (this.y < 0) this.y = canvas.height;
        if (this.y > canvas.height) this.y = 0;
    };
    this.draw = function() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'gray';
        ctx.fill();
    };
}

// Enemy
function Enemy(x, y, radius, speed) {
    this.x = x;
    this.y = y;
    this.radius = radius;
    this.speed = speed;
    this.angle = Math.random() * Math.PI * 2;
    this.update = function() {
        this.x += Math.cos(this.angle) * this.speed;
        this.y += Math.sin(this.angle) * this.speed;
        // Wrap around screen edges
        if (this.x < 0) this.x = canvas.width;
        if (this.x > canvas.width) this.x = 0;
        if (this.y < 0) this.y = canvas.height;
        if (this.y > canvas.height) this.y = 0;
    };
    this.draw = function() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'red';
        ctx.fill();
    };
}

// Spawning
function spawnAsteroid() {
    const x = Math.random() * canvas.width;
    const y = Math.random() * canvas.height;
    const radius = Math.random() * 20 + 10;
    const speed = Math.random() * 2 + 1;
    asteroids.push(new Asteroid(x, y, radius, speed));
}

function spawnEnemy() {
    const x = Math.random() * canvas.width;
    const y = Math.random() * canvas.height;
    const radius = 10;
    const speed = 2;
    enemies.push(new Enemy(x, y, radius, speed));
}

// Collision detection
function checkCollision(obj1, obj2) {
    const dx = obj1.x - obj2.x;
    const dy = obj1.y - obj2.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    return distance < obj1.radius + obj2.radius;
}

// Game loop
function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Update and draw player
    player.update();
    player.draw();

    // Update and draw bullets
    bullets.forEach((bullet, index) => {
        bullet.update();
        bullet.draw();
        // Remove bullets that move off screen
        if (bullet.x < 0 || bullet.x > canvas.width || bullet.y < 0 || bullet.y > canvas.height) {
            bullets.splice(index, 1);
        }
    });

    // Update and draw asteroids
    asteroids.forEach((asteroid, index) => {
        asteroid.update();
        asteroid.draw();
        // Check for collision with player
        if (checkCollision(asteroid, player)) {
            asteroids.splice(index, 1);
            // Reset game if player collides with asteroid
            asteroids.length = 0;
            bullets.length = 0;
            enemies.length = 0;
            score = 0;
            level = 1;
            spawnInterval = 1500;
            alert('Game Over! Your score: ' + score);
        }
    });

    // Update and draw enemies
    enemies.forEach((enemy, index) => {
        enemy.update();
        enemy.draw();
        // Check for collision with player
        if (checkCollision(enemy, player)) {
            enemies.splice(index, 1);
            // Reset game if player collides with enemy
            asteroids.length = 0;
            bullets.length = 0;
            enemies.length = 0;
            score = 0;
            level = 1;
            spawnInterval = 1500;
            alert('Game Over! Your score: ' + score);
        }
    });

    // Spawn asteroids
    if (Date.now() - lastSpawnTime > spawnInterval) {
        spawnAsteroid();
        lastSpawnTime = Date.now();
        // Increase difficulty
        if (level % 10 === 0) {
            spawnInterval *= 0.9;
            level++;
        }
    }

    // Spawn enemies
    if (Math.random() > 0.99) {
        spawnEnemy();
    }

    // Check for bullet collisions with asteroids and enemies
    bullets.forEach((bullet, bulletIndex) => {
        asteroids.forEach((asteroid, asteroidIndex) => {
            if (checkCollision(bullet, asteroid)) {
                asteroids.splice(asteroidIndex, 1);
                bullets.splice(bulletIndex, 1);
                score += 10;
            }
        });
        enemies.forEach((enemy, enemyIndex) => {
            if (checkCollision(bullet, enemy)) {
                enemies.splice(enemyIndex, 1);
                bullets.splice(bulletIndex, 1);
                score += 20;
            }
        });
    });

    // Display score and level
    ctx.font = '20px Arial';
    ctx.fillStyle = 'white';
    ctx.fillText('Score: ' + score, 10, 30);
    ctx.fillText('Level: ' + level, 10, 60);

    requestAnimationFrame(gameLoop);
}

// Input handling
document.addEventListener('keydown', function(e) {
    if (e.key === 'ArrowLeft') {
        player.angle -= 0.05;
    } else if (e.key === 'ArrowRight') {
