    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            if (board[y][x] === 0) continue;
            let color = board[y][x];
            let line = [];
            for (let dx = x; dx < boardSize && board[y][dx] === color; dx++) {
                line.push([y, dx]);
            }
            if (line.length >= 3) matches.push(line);
            line = [];
            for (let dy = y; dy < boardSize && board[dy][x] === color; dy++) {
                line.push([dy, x]);
            }
            if (line.length >= 3) matches.push(line);
        }
    }
