    if (this.amount >= amount) {
      this.amount -= amount;
      return true;
    }
    return false;
  }

  produce(amount) {
    this.amount += amount;
  }
}

class Economy {
  constructor(building, resource) {
    this.building = building;
    this.resource = resource;
  }

  tradeResource(buildingType, resourceType, amount) {
    if (this.building.getName() === buildingType && this.resource.getType() === resourceType) {
      if (this.resource.consume(amount)) {
        this.building.produceResource(resourceType, amount);
        return true;
      }
    }
    return false;
  }

  checkResourceAmount() {
    return this.resource.getAmount();
  }

  checkBuildingResources() {
    return this.building.getResources();
  }
}

// Demo
const lumberyard = new Building('Lumberyard', { wood: 0 });
const woodResource = new Resource('wood', 100);
const economy = new Economy(lumberyard, woodResource);

console.log('Initial resources in the economy:', economy.checkBuildingResources()); // { wood: 0 }
console.log('Initial wood resource amount:', economy.checkResourceAmount()); // 100

const tradeSuccess = economy.tradeResource('Lumberyard', 'wood', 50);
console.log('Trade success:', tradeSuccess); // true

console.log('Resources in the economy after trade:', economy.checkBuildingResources()); // { wood: 50 }
console.log('Wood resource amount after trade:', economy.checkResourceAmount()); // 50

const tradeFailure = economy.tradeResource('Lumberyard', 'wood', 60);
console.log('Trade failure:', tradeFailure); // false

console.log('Resources in the economy after failed trade:', economy.checkBuildingResources()); // { wood: 50 }
console.log('Wood resource amount after failed trade:', economy.checkResourceAmount()); // 50
