const canvas = document.createElement('canvas');
document.body.appendChild(canvas);

let ctx = canvas.getContext('2d');
let pixelRatio = window.devicePixelRatio || 1;

function resizeCanvas() {
  canvas.width = window.innerWidth * pixelRatio;
  canvas.height = window.innerHeight * pixelRatio;
  ctx.scale(pixelRatio, pixelRatio);
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

let farmingPlot = {
  width: 100,
  height: 100,
  x: 50,
  y: 50,
  growth: 0,
  growRate: 0.1,
  maxGrowth: 100,
  seed: null,
  plant: null,
  timer: null,
  startTime: null,
  duration: 10000 // 10 seconds
};

function plantSeed(seedName) {
  farmingPlot.seed = seedName;
  farmingPlot.plant = null;
  farmingPlot.growth = 0;
  farmingPlot.startTime = Date.now();
  farmingPlot.timer = setInterval(updateGrowth, 100);
}

function updateGrowth() {
  if (farmingPlot.startTime) {
    let elapsed = Date.now() - farmingPlot.startTime;
    if (elapsed >= farmingPlot.duration) {
      clearInterval(farmingPlot.timer);
      farmingPlot.plant = farmingPlot.seed;
      farmingPlot.seed = null;
      farmingPlot.growth = farmingPlot.maxGrowth;
    } else {
      farmingPlot.growth = Math.min(farmingPlot.maxGrowth, (elapsed / farmingPlot.duration) * farmingPlot.maxGrowth);
    }
  }
}

function drawFarmingPlot() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#7A593B';
  ctx.fillRect(farmingPlot.x, farmingPlot.y, farmingPlot.width, farmingPlot.height);

  if (farmingPlot.growth > 0) {
    ctx.fillStyle = farmingPlot.plant ? '#397A39' : '#6B4226';
    ctx.fillRect(farmingPlot.x, farmingPlot.y, farmingPlot.width * (farmingPlot.growth / farmingPlot.maxGrowth), farmingPlot.height);
  }

  ctx.font = '16px Arial';
  ctx.fillStyle = '#FFFFFF';
  ctx.fillText(farmingPlot.seed || farmingPlot.plant || 'Empty', farmingPlot.x + 10, farmingPlot.y + 30);

  if (farmingPlot.startTime) {
    let remaining = farmingPlot.duration - (Date.now() - farmingPlot.startTime);
    ctx.fillText(`Time: ${(remaining / 1000).toFixed(1)}s`, farmingPlot.x + 10, farmingPlot.y + 50);
  }
}

function gameLoop() {
  updateGrowth();
  drawFarmingPlot();
  requestAnimationFrame(gameLoop);
}

// Plant a seed after 2 seconds
setTimeout(() => plantSeed('Wheat'), 2000);

gameLoop();
