class Recipe {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = {
      'wood + stone': 'axe',
      'leather + cloth': 'boots'
    };
    this.eventBus.subscribe('craft', this.handleCraft.bind(this));
  }

  handleCraft(data) {
    const { ingredients } = data;
    const recipeKey = ingredients.sort().join(' + ');
    const result = this.recipes[recipeKey];
    if (result) {
      this.eventBus.emit('craftSuccess', { result });
    } else {
      this.eventBus.emit('craftFailure', { message: 'No recipe found' });
    }
  }
