class Inventory {
  constructor(items = {}) {
    this.items = items; // { itemName: quantity }
  }

  addItem(itemName, quantity) {
    this.items[itemName] = (this.items[itemName] || 0) + quantity;
  }

  removeItem(itemName, quantity) {
    if (this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
      return true;
    }
    return false;
  }

  getItems() {
    return this.items;
  }

  hasIngredients(recipe) {
    const ingredients = recipe.getIngredients();
    for (const [ingredient, needed] of Object.entries(ingredients)) {
      if (!this.items[ingredient] || this.items[ingredient] < needed) {
        return false;
      }
    }
    return true;
  }
}

