function createParticleSystem(x, y, count, color) {
    const particles = [];
    for (let i = 0; i < count; i++) {
        particles.push(createParticle(x, y, color));
    }
    particleSystems.push({ particles, age: 0 });
}

function updateParticles() {
    particleSystems.forEach((system, index) => {
        system.age++;
        if (system.age > 200) {
            particleSystems.splice(index, 1);
            return;
        }
        system.particles.forEach(particle => {
            particle.x += (Math.random() - 0.5) * 2;
            particle.y += (Math.random() - 0.5) * 2;
            particle.lifespan--;
        });
        system.particles = system.particles.filter(particle => particle.lifespan > 0);
    });
}

function drawParticles() {
