    let y = Math.random() * (canvas.height - pipeGap - pipeWidth);
    pipes.push({ x: canvas.width, y: y, width: pipeWidth, height: pipeWidth });
    pipes.push({ x: canvas.width, y: y + pipeWidth + pipeGap, width: pipeWidth, height: canvas.height - y - pipeWidth - pipeGap });
}

function drawBird() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(bird.x, bird.y, bird.width, bird.height);
}

function drawPipes() {
    ctx.fillStyle = 'green';
    pipes.forEach(pipe => {
        ctx.fillRect(pipe.x, pipe.y, pipe.width, pipe.height);
    });
}

function drawScore() {
    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText('Score: ' + score, 10, 30);
}

function drawTimer() {
    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText('Time: ' + timer, 10, 60);
}

