// Event bus implementation
class EventBus {
    constructor() {
        this.listeners = {};
    }

    subscribe(event, listener) {
        if (!this.listeners[event]) {
            this.listeners[event] = [];
        }
        this.listeners[event].push(listener);
    }

    emit(event, data) {
        if (this.listeners[event]) {
            this.listeners[event].forEach(listener => listener(data));
        }
    }
}

// Wallet system
class Wallet {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.balance = 0;
        this.eventBus.subscribe('purchase', this.handlePurchase.bind(this));
    }

    addFunds(amount) {
        this.balance += amount;
        console.log(`Added ${amount} to wallet. New balance: ${this.balance}`);
    }

    handlePurchase(data) {
        if (this.balance >= data.cost) {
            this.balance -= data.cost;
            console.log(`Purchase successful. ${data.cost} deducted. New balance: ${this.balance}`);
            this.eventBus.emit('purchased', data);
        } else {
            console.log('Insufficient funds for purchase.');
        }
    }
}

// Shop system
class Shop {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = [
            { name: 'Sword', cost: 100 },
            { name: 'Shield', cost: 75 }
        ];
        this.eventBus.subscribe('purchased', this.handlePurchase.bind(this));
    }

    listItems() {
        console.log('Items in shop:');
        this.items.forEach(item => console.log(`${item.name}: ${item.cost}`));
    }

    purchaseItem(itemName) {
        const item = this.items.find(i => i.name === itemName);
        if (item) {
            console.log(`Attempting to purchase: ${item.name}`);
            this.eventBus.emit('purchase', item);
        } else {
            console.log('Item not found.');
        }
    }

    handlePurchase(data) {
        console.log(`Item purchased: ${data.name}`);
    }
}

// Inventory system
class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = [];
        this.eventBus.subscribe('purchased', this.addItem.bind(this));
    }

    addItem(data) {
        this.items.push(data);
        console.log(`Added to inventory: ${data.name}`);
    }

    listInventory() {
        console.log('Inventory:');
        this.items.forEach(item => console.log(item.name));
    }
}

