const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio;
let width = window.innerWidth;
let height = window.innerHeight;
canvas.width = width * dpr;
canvas.height = height * dpr;
ctx.scale(dpr, dpr);

const BLOCK_SIZE = 30;
const GRID_WIDTH = Math.floor(width / BLOCK_SIZE);
const GRID_HEIGHT = Math.floor(height / BLOCK_SIZE);
const COLORS = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF'];

class Block {
  constructor(x, y, color) {
    this.x = x;
    this.y = y;
    this.color = color;
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x * BLOCK_SIZE, this.y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
  }
}

class Game {
  constructor() {
    this.state = 'menu';
    this.blocks = [];
    this.timer = null;
    this.score = 0;
    this.level = 1;
    this.init();
  }

  init() {
    canvas.addEventListener('click', () => this.handleClick());
    window.addEventListener('resize', () => this.handleResize());
    this.handleResize();
  }

  handleResize() {
    width = window.innerWidth;
    height = window.innerHeight;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    ctx.scale(dpr, dpr);
    GRID_WIDTH = Math.floor(width / BLOCK_SIZE);
    GRID_HEIGHT = Math.floor(height / BLOCK_SIZE);
  }

  handleClick() {
    switch (this.state) {
      case 'menu':
        this.state = 'playing';
        this.startGame();
        break;
      case 'playing':
        this.state = 'paused';
        this.stopGame();
        break;
      case 'paused':
        this.state = 'playing';
        this.startGame();
        break;
      case 'gameover':
        this.state = 'menu';
        this.blocks = [];
        this.score = 0;
        this.level = 1;
        break;
    }
  }

  startGame() {
    this.timer = setInterval(() => this.update(), 1000 / this.level);
    this.addBlock();
  }

  stopGame() {
    clearInterval(this.timer);
  }

  update() {
    this.moveBlocks();
    this.checkCollision();
    this.draw();
  }

  moveBlocks() {
    this.blocks.forEach(block => block.y++);
    if (this.blocks.some(block => block.y >= GRID_HEIGHT)) {
      this.state = 'gameover';
      this.stopGame();
    }
  }

  checkCollision() {
    const newBlocks = [];
    this.blocks.forEach(block => {
      if (!newBlocks.some(b => b.x === block.x && b.y === block.y - 1)) {
        newBlocks.push(new Block(block.x, block.y - 1, block.color));
      }
    });
    this.blocks = newBlocks;
  }

  addBlock() {
    const x = Math.floor(Math.random() * GRID_WIDTH);
    const color = COLORS[Math.floor(Math.random() * COLORS.length)];
    this.blocks.push(new Block(x, 0, color));
  }

  draw() {
    ctx.clearRect(0, 0, width, height);
    this.blocks.forEach(block => block.draw());
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${this.score}`, 10, 30);
    ctx.fillText(`Level: ${this.level}`, 10, 60);
    if (this.state === 'menu') {
      ctx.fillText('Click to Start', width / 2 - 70, height / 2);
    } else if (this.state === 'paused') {
      ctx.fillText('Paused', width / 2 - 30, height / 2);
    } else if (this.state === 'gameover') {
      ctx.fillText('Game Over', width / 2 - 60, height / 2);
      ctx.fillText('Click to Restart', width / 2 - 80, height / 2 + 30);
    }
  }
}

new Game();
