(function() {
    const canvas = document.createElement('canvas');
    document.body.appendChild(canvas);
    const ctx = canvas.getContext('2d');

    const BLOCK_SIZE = 32;
    const BOARD_WIDTH = 8;
    const BOARD_HEIGHT = 8;
    const HEALTH = 100;

    let health = HEALTH;
    let board = Array.from({ length: BOARD_HEIGHT }, () => 
        Array.from({ length: BOARD_WIDTH }, () => Math.floor(Math.random() * 3))
    );

    function resizeCanvas() {
        const dpr = window.devicePixelRatio;
        const rect = canvas.getBoundingClientRect();
        canvas.width = rect.width * dpr;
        canvas.height = rect.height * dpr;
        ctx.scale(dpr, dpr);
    }

    function drawHealthBar() {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, canvas.width, 20);
        ctx.fillStyle = 'red';
        ctx.fillRect(0, 0, (health / HEALTH) * canvas.width, 20);
    }

    function drawBoard() {
        for (let y = 0; y < BOARD_HEIGHT; y++) {
            for (let x = 0; x < BOARD_WIDTH; x++) {
                ctx.fillStyle = ['blue', 'green', 'purple'][board[y][x]];
                ctx.fillRect(x * BLOCK_SIZE, 20 + y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
            }
        }
    }

    function match3() {
        let matched = false;
        // Check horizontal matches
        for (let y = 0; y < BOARD_HEIGHT; y++) {
            for (let x = 0; x < BOARD_WIDTH - 2; x++) {
                if (board[y][x] === board[y][x + 1] && board[y][x] === board[y][x + 2]) {
                    matched = true;
                    for (let i = 0; i < 3; i++) {
                        board[y][x + i] = -1;
                    }
                }
            }
        }
        // Check vertical matches
        for (let x = 0; x < BOARD_WIDTH; x++) {
            for (let y = 0; y < BOARD_HEIGHT - 2; y++) {
                if (board[y][x] === board[y + 1][x] && board[y][x] === board[y + 2][x]) {
                    matched = true;
                    for (let i = 0; i < 3; i++) {
                        board[y + i][x] = -1;
                    }
                }
            }
        }
        return matched;
    }

    function respawn() {
        for (let y = 0; y < BOARD_HEIGHT; y++) {
            for (let x = 0; x < BOARD_WIDTH; x++) {
                if (board[y][x] === -1) {
                    board[y][x] = Math.floor(Math.random() * 3);
                }
            }
        }
    }

    function update() {
        if (match3()) {
            respawn();
            health -= 10;
            if (health <= 0) {
                alert('Game Over!');
                health = HEALTH;
                board = Array.from({ length: BOARD_HEIGHT }, () => 
                    Array.from({ length: BOARD_WIDTH }, () => Math.floor(Math.random() * 3))
                );
            }
        }
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        drawHealthBar();
        drawBoard();
    }

    function gameLoop() {
        update();
        draw();
        requestAnimationFrame(gameLoop);
    }

    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();
    gameLoop();
})();
