class Loot {
  constructor(name, value) {
    this.name = name;
    this.value = value;
  }
}

class RarityTable {
  constructor() {
    this.table = {
      common: 0.7,
      uncommon: 0.2,
      rare: 0.08,
      epic: 0.02
    };
  }

  roll() {
    const roll = Math.random();
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.table)) {
      cumulativeProbability += probability;
      if (roll <= cumulativeProbability) {
        return rarity;
      }
    }

    return 'common'; // Fallback to common if roll is exactly 1.0
  }
}

class Inventory {
