      renderMenu();
      break;
    case 'playing':
      renderPlaying();
      if (playerHealth <= 0 || enemyHealth <= 0) {
        state = 'gameover';
      }
      break;
    case 'paused':
      renderPaused();
      break;
    case 'gameover':
      renderGameOver();
      break;
