        state = 'menu';
        playerHealth = 100;
        enemyHealth = 100;
        break;
    }
  } else if (event.key === 'p') {
    if (state === 'playing') {
      state = 'paused';
    } else if (state === 'paused') {
      state = 'playing';
    }
  }
