            console.log(`Debited ${amount} from economy. Remaining balance: ${this.balance}.`);
            return true;
        } else {
            console.log(`Insufficient funds. Required: ${amount}, Balance: ${this.balance}.`);
            return false;
        }
    }

    getBalance() {
        return this.balance;
    }
}

class Store {
    constructor(economy, kitchen) {
        this.economy = economy;
        this.kitchen = kitchen;
    }

    processOrder(order) {
        const item = order.getItem();
        const quantity = order.getQuantity();
        const price = this.economy.getPrice(item);
        const totalCost = price * quantity;

        if (this.economy.debit(totalCost)) {
            this.kitchen.addItem(item, quantity);
            console.log(`Processed order for ${quantity} ${item}(s) at ${price} each. Total cost: ${totalCost}.`);
        } else {
            console.log(`Failed to process order for ${quantity} ${item}(s).`);
        }
    }
}

