class Wallet {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    getBalance() {
        return this.balance;
    }

    debit(amount) {
        if (amount > this.balance) {
            throw new Error("Insufficient funds");
        }
        this.balance -= amount;
    }

    credit(amount) {
        this.balance += amount;
    }
}

class Shop {
    constructor(prices) {
        this.prices = prices;
