function updatePlaying(deltaTime) {
  state.score += deltaTime / 1000; // Increment score based on time

  // Randomly place plants
  if (Math.random() < 0.01) {
    state.plants.push({
      x: Math.floor(Math.random() * state.gardenSize),
      y: Math.floor(Math.random() * state.gardenSize),
    });
  }
}

function updatePaused(deltaTime) {}

function updateGameOver(deltaTime) {}

function render() {
  switch (state.currentState) {
    case 'menu':
      renderMenu();
      break;
    case 'playing':
      renderPlaying();
      break;
    case 'paused':
      renderPaused();
      break;
    case 'gameover':
      renderGameOver();
      break;
  }
}

function update(deltaTime) {
  switch (state.currentState) {
    case 'menu':
      updateMenu(deltaTime);
      break;
    case 'playing':
      updatePlaying(deltaTime);
      break;
    case 'paused':
      updatePaused(deltaTime);
      break;
    case 'gameover':
      updateGameOver(deltaTime);
      break;
  }
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - state.lastTime;
  if (deltaTime >= state.timestep) {
    state.lastTime = timestamp;
    update(deltaTime);
    render();
  }
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
