const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 480;
canvas.height = 320;
const ctx = canvas.getContext('2d');

const PADDLE_WIDTH = 100;
const PADDLE_HEIGHT = 10;
const BALL_SIZE = 10;
const BRICK_WIDTH = 75;
const BRICK_HEIGHT = 20;
const BRICK_PADDING = 10;
const BRICK_OFFSET_TOP = 30;
const BRICK_OFFSET_LEFT = 30;
const ROW_COUNT = 5;
const COL_COUNT = 8;
const PADDLE_SPEED = 7;
const BALL_SPEED = 5;

let paddleX = (canvas.width - PADDLE_WIDTH) / 2;
let ballX = canvas.width / 2;
let ballY = canvas.height - 30;
let ballDX = BALL_SPEED;
let ballDY = -BALL_SPEED;
let rightPressed = false;
let leftPressed = false;
let score = 0;
let lives = 3;
let level = 1;
let bricks = [];

function createBricks() {
    bricks = [];
    for (let c = 0; c < COL_COUNT; c++) {
        bricks[c] = [];
        for (let r = 0; r < ROW_COUNT; r++) {
            bricks[c][r] = { x: 0, y: 0, status: 1 };
        }
    }
}

function drawPaddle() {
    ctx.beginPath();
    ctx.rect(paddleX, canvas.height - PADDLE_HEIGHT, PADDLE_WIDTH, PADDLE_HEIGHT);
    ctx.fillStyle = "#0095DD";
    ctx.fill();
    ctx.closePath();
}

function drawBall() {
    ctx.beginPath();
    ctx.arc(ballX, ballY, BALL_SIZE, 0, Math.PI*2);
    ctx.fillStyle = "#0095DD";
    ctx.fill();
    ctx.closePath();
}

function drawBricks() {
    for (let c = 0; c < COL_COUNT; c++) {
        for (let r = 0; r < ROW_COUNT; r++) {
            if (bricks[c][r].status === 1) {
                let brickX = (c * (BRICK_WIDTH + BRICK_PADDING)) + BRICK_OFFSET_LEFT;
                let brickY = (r * (BRICK_HEIGHT + BRICK_PADDING)) + BRICK_OFFSET_TOP;
                bricks[c][r].x = brickX;
                bricks[c][r].y = brickY;
                ctx.beginPath();
                ctx.rect(brickX, brickY, BRICK_WIDTH, BRICK_HEIGHT);
                ctx.fillStyle = "#0095DD";
                ctx.fill();
                ctx.closePath();
            }
        }
    }
}

function collisionDetection() {
    for (let c = 0; c < COL_COUNT; c++) {
        for (let r = 0; r < ROW_COUNT; r++) {
            let b = bricks[c][r];
            if (b.status === 1) {
                if (ballX > b.x && ballX < b.x + BRICK_WIDTH && ballY > b.y && ballY < b.y + BRICK_HEIGHT) {
                    ballDY = -ballDY;
                    b.status = 0;
                    score++;
                    if (score % (COL_COUNT * ROW_COUNT) === 0) {
                        level++;
                        createBricks();
                        ballSpeedUp();
                        ballX = canvas.width / 2;
                        ballY = canvas.height - 30;
                        ballDX = BALL_SPEED;
                        ballDY = -BALL_SPEED;
                        paddleX = (canvas.width - PADDLE_WIDTH) / 2;
                    }
                }
            }
        }
    }
}

function ballSpeedUp() {
    ballDX *= 1.1;
    ballDY *= 1.1;
}

function drawScore() {
    ctx.font = "16px Arial";
    ctx.fillStyle = "#0095DD";
    ctx.fillText("Score: " + score, 8, 20);
}

function drawLives() {
    ctx.font = "16px Arial";
    ctx.fillStyle = "#0095DD";
    ctx.fillText("Lives: " + lives, canvas.width - 65, 20);
}

function drawLevel() {
    ctx.font = "16px Arial";
    ctx.fillStyle = "#0095DD";
    ctx.fillText("Level: " + level, canvas.width / 2 - 20, 20);
}

function keyDownHandler(e) {
    if(e.key === "Right" || e.key === "ArrowRight") {
        rightPressed = true;
    }
    else if(e.key === "Left" || e.key === "ArrowLeft") {
        leftPressed = true;
    }
}

function keyUpHandler(e) {
    if(e.key === "Right" || e.key === "ArrowRight") {
        rightPressed = false;
    }
    else if(e.key === "Left" || e.key === "ArrowLeft") {
        leftPressed = false;
    }
}

document.addEventListener("keydown", keyDownHandler, false);
document.addEventListener("keyup", keyUpHandler, false);

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBricks();
    drawBall();
    drawPaddle();
    drawScore();
    drawLives();
    drawLevel();

    if(rightPressed && paddleX < canvas.width - PADDLE_WIDTH) {
        paddleX += PADDLE_SPEED;
    }
    else if(leftPressed && paddleX > 0) {
        paddleX -= PADDLE_SPEED;
    }

    ballX += ballDX;
    ballY += ballDY;

    if(ballX + ballDX > canvas.width - BALL_SIZE || ballX + ballDX < BALL_SIZE) {
        ballDX = -ballDX;
    }
    if(ballY + ballDY < BALL_SIZE) {
        ballDY = -ballDY;
    }
    else if(ballY + ballDY > canvas.height - BALL_SIZE) {
        if(ballX > paddleX && ballX < paddleX + PADDLE_WIDTH) {
            ballDY = -ballDY;
        }
        else {
            lives--;
            if(!lives) {
                alert("GAME OVER");
                document.location.reload();
            }
            else {
                ballX = canvas.width / 2;
                ballY = canvas.height - 30;
                ballDX = BALL_SPEED;
                ballDY = -BALL_SPEED;
                paddleX = (canvas.width - PADDLE_WIDTH) / 2;
            }
        }
    }

    collisionDetection();

    requestAnimationFrame(draw);
}

createBricks();
draw();
