    if (this.healthPoints.has(entity)) {
      const currentHP = this.healthPoints.get(entity);
      const newHP = Math.max(0, currentHP - damage);
      this.healthPoints.set(entity, newHP);
      console.log(`${entity} takes ${damage} damage. Health remaining: ${newHP}.`);
      if (newHP === 0) {
        console.log(`${entity} has been defeated.`);
