  fish.x += Math.cos(fish.angle) * fish.speed;
  fish.y += Math.sin(fish.angle) * fish.speed;

  if (fish.x < 0 || fish.x > canvas.width || fish.y < 0 || fish.y > canvas.height) {
    fish.x = Math.random() * canvas.width;
    fish.y = Math.random() * canvas.height;
    fish.caught = false;
  }

  const dx = fish.x - line.end.x;
  const dy = fish.y - line.end.y;
  const distance = Math.sqrt(dx * dx + dy * dy);

  if (distance < fish.size && fishing) {
    fish.caught = true;
    score += 10;
    fishingLineLength = line.length;
