const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let width, height;
function resizeCanvas() {
    width = window.innerWidth;
    height = window.innerHeight;
    canvas.width = width * devicePixelRatio;
    canvas.height = height * devicePixelRatio;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

const gravity = 0.5;
const powerUpSpeed = 2;
const powerUpTypes = ['bounce', 'slow', 'speed'];
const powerUpProb = 0.05;

class Ball {
    constructor(x, y, radius) {
        this.x = x;
        this.y = y;
        this.radius = radius;
        this.velocityX = 0;
        this.velocityY = 0;
        this.color = 'blue';
        this.powerUp = null;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.closePath();
    }

    update() {
        this.velocityY += gravity;
        this.x += this.velocityX;
        this.y += this.velocityY;

        if (this.y + this.radius > canvas.height) {
            this.y = canvas.height - this.radius;
            this.velocityY *= -0.5;
            if (this.powerUp === 'bounce') this.velocityY *= -1;
        }
        if (this.x - this.radius < 0 || this.x + this.radius > canvas.width) {
            this.velocityX *= -1;
        }

        if (this.powerUp === 'slow') {
            this.velocityX *= 0.95;
            this.velocityY *= 0.95;
        } else if (this.powerUp === 'speed') {
            this.velocityX *= 1.05;
            this.velocityY *= 1.05;
        }
    }
}

class PowerUp {
    constructor(x, y, type) {
        this.x = x;
        this.y = y;
        this.radius = 10;
        this.type = type;
        this.color = this.getColor(type);
    }

    getColor(type) {
        switch (type) {
            case 'bounce': return 'green';
            case 'slow': return 'purple';
            case 'speed': return 'orange';
            default: return 'gray';
        }
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.closePath();
    }

    update() {
        this.y += powerUpSpeed;
    }
}

let balls = [new Ball(canvas.width / 2, 50, 20)];
let powerUps = [];

function collectPowerUps() {
    balls.forEach(ball => {
        powerUps = powerUps.filter(powerUp => {
            const dx = ball.x - powerUp.x;
            const dy = ball.y - powerUp.y;
            const distance = Math.sqrt(dx * dx + dy * dy);
            if (distance < ball.radius + powerUp.radius) {
                ball.powerUp = powerUp.type;
                return false;
            }
            return true;
        });
    });
}

function spawnPowerUp() {
    if (Math.random() < powerUpProb) {
        const x = Math.random() * canvas.width;
        const y = 0;
        const type = powerUpTypes[Math.floor(Math.random() * powerUpTypes.length)];
        powerUps.push(new PowerUp(x, y, type));
    }
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    balls.forEach(ball => {
        ball.update();
        ball.draw();
    });

    powerUps.forEach(powerUp => {
        powerUp.update();
        powerUp.draw();
    });

    collectPowerUps();
    spawnPowerUp();

    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    if (e.key === ' ') {
        balls.forEach(ball => {
            ball.velocityY = -10;
        });
    }
});

gameLoop();
