class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(data));
    }
  }
}

class Building {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('resourceProduced', this.onResourceProduced.bind(this));
  }

  build(type) {
    console.log(`Building ${type}`);
    this.eventBus.emit('buildingBuilt', { type });
  }

  onResourceProduced(data) {
    console.log(`Resource produced: ${data.type}`);
  }
}

class Resource {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('buildingBuilt', this.onBuildingBuilt.bind(this));
  }

  produce(type) {
    console.log(`Producing resource ${type}`);
    this.eventBus.emit('resourceProduced', { type });
  }

  onBuildingBuilt(data) {
    if (data.type === 'mine') {
      this.produce('ore');
    }
  }
}

class Economy {
