    this.eventBus = eventBus;
    this.eventBus.subscribe('resourceProduced', this.onResourceProduced.bind(this));
  }

  trade(resource, amount) {
    console.log(`Trading ${amount} ${resource}`);
  }

  onResourceProduced(data) {
    if (data.type === 'ore') {
      this.trade('ore', 10);
    }
  }
}

