class Economy {
    constructor(prices) {
        this.prices = prices;
        this.balance = 1000; // Initial balance for demonstration purposes
    }

    getPrice(item) {
        return this.prices[item] || 0;
    }

    debit(amount) {
        if (this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    getInventory() {
        return this.items;
    }
}

class Store {
    constructor(economy, inventory) {
        this.economy = economy;
        this.inventory = inventory;
    }

    purchase(item) {
        const price = this.economy.getPrice(item);
        if (price > 0 && this.economy.debit(price)) {
            this.inventory.addItem(item);
            console.log(`Purchased ${item} for ${price}. Balance: ${this.economy.getBalance()}`);
            return true;
        }
        console.log(`Purchase of ${item} failed. Price: ${price}, Balance: ${this.economy.getBalance()}`);
        return false;
    }
}

