    });
}

function drawParticles() {
    particles.forEach(particle => {
        ctx.fillStyle = particle.color;
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, 2, 0, Math.PI * 2);
        ctx.fill();
    });
}

// Collision detection
function detectCollisions() {
    // Ball with walls
    if (ball.x + ball.dx > CANVAS_WIDTH - ball.radius || ball.x + ball.dx < ball.radius) {
        ball.dx = -ball.dx;
    }
    if (ball.y + ball.dy > CANVAS_HEIGHT - ball.radius) {
        ball.dy = -ball.dy;
    }
    if (ball.y + ball.dy < ball.radius) {
        ball.dy = -ball.dy;
    }

    // Ball with paddle
    if (ball.y + ball.dy > CANVAS_HEIGHT - PADDLE_HEIGHT - ball.radius && 
        ball.x > paddle.x && ball.x < paddle.x + PADDLE_WIDTH) {
        ball.dy = -ball.dy;
    }

    // Ball with bricks
    bricks.forEach(brick => {
        if (brick.alive && ball.x + ball.radius > brick.x && 
            ball.x - ball.radius < brick.x + brick.width && 
            ball.y + ball.radius > brick.y && 
            ball.y - ball.radius < brick.y + brick.height) {
            ball.dy = -ball.dy;
            brick.alive = false;
            for (let i = 0; i < PARTICLE_COUNT; i++) {
                particles.push(createParticle(brick.x + brick.width / 2, brick.y + brick.height / 2));
            }
        }
    });
}

// Game loop
function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;

    let updateSteps = 0;
    while (deltaTime > FIXED_TIME_STEP && updateSteps < MAX_UPDATE_STEPS) {
        updateParticles();
        detectCollisions();
        ball.x += ball.dx;
        ball.y += ball.dy;
        paddle.x += paddle.dx;
        paddle.x = Math.max(0, Math.min(CANVAS_WIDTH - PADDLE_WIDTH, paddle.x));
        updateSteps++;
    }

    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw paddle
    ctx.fillStyle = PADDLE_COLOR;
    ctx.fillRect(paddle.x, paddle.y, PADDLE_WIDTH, PADDLE_HEIGHT);

    // Draw ball
    ctx.fillStyle = BALL_COLOR;
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
    ctx.fill();

    // Draw bricks
    bricks.forEach(brick => {
        if (brick.alive) {
            ctx.fillStyle = BRICK_COLOR;
            ctx.fillRect(brick.x, brick.y, brick.width, brick.height);
        }
    });

    // Draw particles
    drawParticles();

    requestAnimationFrame(gameLoop);
}

// Input handling
document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft') {
        paddle.dx = -5;
    } else if (e.key === 'ArrowRight') {
        paddle.dx = 5;
    }
});

document.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
        paddle.dx = 0;
    }
});

// Start game loop
requestAnimationFrame(gameLoop);
