const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const player = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  radius: 10,
  angle: Math.PI / 2,
  speed: 5,
  rotationSpeed: 0.05
};

const bullets = [];
const enemies = [];
const asteroids = [];

const asteroidSpeeds = [1, 2, 3];
const asteroidRadii = [15, 10, 5];
const asteroidColors = ['#FF5733', '#33FF57', '#3357FF'];

let lastTime = 0;
let spawnTimer = 0;
let spawnInterval = 2000;
let level = 1;

function spawnEnemy() {
  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  const radius = asteroidRadii[Math.floor(Math.random() * asteroidRadii.length)];
  const speed = asteroidSpeeds[Math.floor(Math.random() * asteroidSpeeds.length)];
  const color = asteroidColors[Math.floor(Math.random() * asteroidColors.length)];
  enemies.push({ x, y, radius, speed, color });
}

function update(dt) {
  spawnTimer += dt;
  if (spawnTimer >= spawnInterval) {
    spawnTimer = 0;
    spawnEnemy();
    level++;
    spawnInterval = Math.max(1000, spawnInterval - 100);
  }

  player.angle += player.rotationSpeed;
  player.x += Math.cos(player.angle) * player.speed;
  player.y += Math.sin(player.angle) * player.speed;

  if (player.x < 0) player.x = canvas.width;
  if (player.x > canvas.width) player.x = 0;
  if (player.y < 0) player.y = canvas.height;
  if (player.y > canvas.height) player.y = 0;

  bullets.forEach(bullet => {
    bullet.x += Math.cos(bullet.angle) * 5;
    bullet.y += Math.sin(bullet.angle) * 5;
  });

  enemies.forEach(enemy => {
    enemy.x += Math.cos(Math.atan2(canvas.height / 2 - enemy.y, canvas.width / 2 - enemy.x)) * enemy.speed;
    enemy.y += Math.sin(Math.atan2(canvas.height / 2 - enemy.y, canvas.width / 2 - enemy.x)) * enemy.speed;
  });

  bullets.forEach((bullet, index) => {
    if (bullet.x < 0 || bullet.x > canvas.width || bullet.y < 0 || bullet.y > canvas.height) {
      bullets.splice(index, 1);
    }
  });

  enemies.forEach((enemy, enemyIndex) => {
    const dx = player.x - enemy.x;
    const dy = player.y - enemy.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < player.radius + enemy.radius) {
      enemies.splice(enemyIndex, 1);
      // Game over logic here
    }
  });
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fill();

  bullets.forEach(bullet => {
    ctx.fillStyle = 'yellow';
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, 3, 0, Math.PI * 2);
    ctx.fill();
  });

  enemies.forEach(enemy => {
    ctx.fillStyle = enemy.color;
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
    ctx.fill();
  });
}

function main(timestamp) {
  const dt = timestamp - lastTime;
  lastTime = timestamp;
  update(dt);
  render();
  requestAnimationFrame(main);
}

canvas.addEventListener('keydown', e => {
  if (e.key === 'ArrowLeft') {
    player.rotationSpeed = -0.05;
  } else if (e.key === 'ArrowRight') {
    player.rotationSpeed = 0.05;
  } else if (e.key === 'ArrowUp') {
    bullets.push({ x: player.x, y: player.y, angle: player.angle });
  }
});

canvas.addEventListener('keyup', e => {
  if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
    player.rotationSpeed = 0;
  }
});

main(performance.now());
