class Trade {
  constructor(economy) {
    this.economy = economy;
  }

  buyItem(item, price) {
    if (this.economy.hasEnoughMoney(price)) {
      this.economy.debit(price);
      return true;
    }
    return false;
  }
}

class Reputation {
  constructor() {
    this.score = 0;
  }

  updateScore(transactionSuccessful) {
    if (transactionSuccessful) {
      this.score += 10;
    } else {
      this.score -= 5;
    }
  }

  getScore() {
    return this.score;
  }
}

class Faction {
  constructor() {
    this.membership = 'Neutral';
  }

  updateMembership(reputationScore) {
    if (reputationScore > 50) {
      this.membership = 'Faction A';
    } else if (reputationScore < -50) {
      this.membership = 'Faction B';
    } else {
      this.membership = 'Neutral';
    }
  }

  getMembership() {
    return this.membership;
  }
}

class Economy {
  constructor(initialMoney) {
    this.money = initialMoney;
  }

  hasEnoughMoney(price) {
    return this.money >= price;
  }

  debit(price) {
    this.money -= price;
  }

  getCurrentMoney() {
    return this.money;
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  getItems() {
    return this.items;
  }
}

class Store {
  constructor(trade, inventory) {
    this.trade = trade;
    this.inventory = inventory;
    this.prices = { 'Sword': 50, 'Shield': 30, 'Potion': 10 };
  }

  purchaseItem(item, customer) {
    const price = this.prices[item];
    if (price && this.trade.buyItem(price)) {
      this.inventory.addItem(item);
      customer.reputation.updateScore(true);
      return true;
    }
    customer.reputation.updateScore(false);
    return false;
  }
}

// Demo
const economy = new Economy(100);
const trade = new Trade(economy);
const inventory = new Inventory();
const reputation = new Reputation();
const faction = new Faction();
const customer = { reputation, faction };
const store = new Store(trade, inventory);

console.log('Initial Economy Money:', economy.getCurrentMoney());
console.log('Initial Inventory:', inventory.getItems());
console.log('Initial Reputation Score:', reputation.getScore());
console.log('Initial Faction Membership:', faction.getMembership());

console.log('Purchasing Sword...');
