class Bank {
    constructor() {
        this.balance = 0;
    }

    deposit(amount) {
        this.balance += amount;
        return this.balance;
    }

    withdraw(amount) {
        if (this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor() {
        this.prices = {
            apple: 10,
            banana: 5,
            orange: 8
        };
    }

    getPrices() {
        return { ...this.prices };
    }

    buy(item, quantity) {
        const price = this.prices[item];
        if (price !== undefined) {
            return price * quantity;
        }
        return null;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (this.items[item] !== undefined) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    getItems() {
        return { ...this.items };
    }
}

