class Pricing {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getBasePrice(item) {
    return this.prices[item] || 0;
  }
}

class Demand {
  constructor(demandFactors = {}) {
    this.demandFactors = demandFactors;
  }

  getDemandFactor(item) {
    return this.demandFactors[item] || 1;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  calculatePrice(item, quantity) {
    const basePrice = this.pricing.getBasePrice(item);
    const demandFactor = this.demand.getDemandFactor(item);
    return basePrice * demandFactor * quantity;
  }
}

