const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio || 1;
function resizeCanvas() {
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

const paddle = { x: canvas.width / 2 - 50, y: canvas.height - 20, width: 100, height: 10, speed: 5 };
const ball = { x: canvas.width / 2, y: canvas.height / 2, radius: 10, speedX: 5, speedY: -5 };
const bricks = [];
const rows = 5;
const cols = 10;
const brickWidth = canvas.width / cols - 5;
const brickHeight = 20;
const brickPadding = 10;
const brickOffsetTop = 30;
const brickOffsetLeft = 30;

for (let c = 0; c < cols; c++) {
  bricks[c] = [];
  for (let r = 0; r < rows; r++) {
    bricks[c][r] = { x: 0, y: 0, status: 1 };
  }
}

let score = 0;
let lives = 3;
let state = 'menu';

function drawPaddle() {
  ctx.fillStyle = '#0095DD';
  ctx.fillRect(paddle.x, paddle.y, paddle.width, paddle.height);
}

function drawBall() {
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
  ctx.fillStyle = '#0095DD';
  ctx.fill();
  ctx.closePath();
}

function drawBricks() {
  for (let c = 0; c < cols; c++) {
    for (let r = 0; r < rows; r++) {
      if (bricks[c][r].status === 1) {
        const brickX = (c * (brickWidth + brickPadding)) + brickOffsetLeft;
        const brickY = (r * (brickHeight + brickPadding)) + brickOffsetTop;
        bricks[c][r].x = brickX;
        bricks[c][r].y = brickY;
        ctx.beginPath();
        ctx.rect(brickX, brickY, brickWidth, brickHeight);
        ctx.fillStyle = '#0095DD';
        ctx.fill();
        ctx.closePath();
      }
    }
  }
}

function drawScore() {
  ctx.font = '16px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText(`Score: ${score}`, 8, 20);
}

function drawLives() {
  ctx.font = '16px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText(`Lives: ${lives}`, canvas.width - 65, 20);
}

function collisionDetection() {
  for (let c = 0; c < cols; c++) {
    for (let r = 0; r < rows; r++) {
      const b = bricks[c][r];
      if (b.status === 1) {
        if (ball.x > b.x && ball.x < b.x + brickWidth && ball.y > b.y && ball.y < b.y + brickHeight) {
          ball.speedY = -ball.speedY;
          b.status = 0;
          score++;
          if (score === rows * cols) {
            state = 'gameover';
          }
        }
      }
    }
  }
}

function drawMenu() {
  ctx.font = '24px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText('Press Space to Start', canvas.width / 2 - 100, canvas.height / 2);
}

function drawGameOver() {
  ctx.font = '24px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText('Game Over', canvas.width / 2 - 50, canvas.height / 2);
  ctx.fillText('Press Space to Restart', canvas.width / 2 - 100, canvas.height / 2 + 30);
}

function drawPaused() {
  ctx.font = '24px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText('Paused', canvas.width / 2 - 30, canvas.height / 2);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  if (state === 'menu') {
    drawMenu();
  } else if (state === 'playing') {
    drawPaddle();
    drawBall();
    drawBricks();
    drawScore();
    drawLives();
    collisionDetection();
    ball.x += ball.speedX;
    ball.y += ball.speedY;
    if (ball.x + ball.speedX > canvas.width - ball.radius || ball.x + ball.speedX < ball.radius) {
      ball.speedX = -ball.speedX;
    }
    if (ball.y + ball.speedY < ball.radius) {
      ball.speedY = -ball.speedY;
    } else if (ball.y + ball.speedY > canvas.height - ball.radius) {
      if (ball.x > paddle.x && ball.x < paddle.x + paddle.width) {
        ball.speedY = -ball.speedY;
      } else {
        lives--;
        if (!lives) {
          state = 'gameover';
        } else {
          state = 'menu';
        }
      }
    }
  } else if (state === 'paused') {
    drawPaddle();
    drawBall();
    drawBricks();
    drawScore();
    drawLives();
    drawPaused();
  } else if (state === 'gameover') {
    drawGameOver();
  }
}

function gameLoop() {
  if (state === 'playing') {
    if (leftPressed && paddle.x > 0) {
      paddle.x -= paddle.speed;
    } else if (rightPressed && paddle.x < canvas.width - paddle.width) {
      paddle.x += paddle.speed;
    }
  }
  draw();
  requestAnimationFrame(gameLoop);
}

let leftPressed = false;
let rightPressed = false;

document.addEventListener('keydown', keyDownHandler, false);
document.addEventListener('keyup', keyUpHandler, false);
document.addEventListener('click', clickHandler, false);

function keyDownHandler(e) {
  if (e.key === 'Right' || e.key === 'ArrowRight') {
    rightPressed = true;
  } else if (e.key === 'Left' || e.key === 'ArrowLeft') {
    leftPressed = true;
  } else if (e.key === ' ' && (state === 'menu' || state === 'gameover')) {
    state = 'playing';
    ball.x = canvas.width / 2;
    ball.y = canvas.height / 2;
    score = 0;
    lives = 3;
    for (let c = 0; c < cols; c++) {
      for (let r = 0; r < rows; r++) {
        bricks[c][r].status = 1;
      }
    }
  } else if (e.key === 'p' && state === 'playing') {
