class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, callback) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(callback);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(callback => callback(data));
        }
    }
}

class Combat {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('playerAttacked', this.handlePlayerAttack.bind(this));
    }

    playerAttack(target) {
        this.eventBus.emit('playerAttacked', { target });
    }

    handlePlayerAttack(data) {
        console.log(`Player attacks ${data.target}`);
        // Simulate damage
        const damage = Math.floor(Math.random() * 10) + 1;
        this.eventBus.emit('applyDamage', { target: data.target, damage });
    }
}

class Health {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('applyDamage', this.applyDamage.bind(this));
    }

    applyDamage(data) {
        console.log(`${data.target} takes ${data.damage} damage`);
        // Simulate health reduction
        const newHealth = Math.max(0, data.health - data.damage);
        this.eventBus.emit('healthUpdated', { target: data.target, health: newHealth });
    }
}

class Loot {
