const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const bird = {
  x: 50,
  y: canvas.height / 2,
  vy: 0,
  gravity: 0.5,
  lift: -10,
  radius: 15,
  update: function() {
    this.vy += this.gravity;
    this.y += this.vy;
  },
  draw: function() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'yellow';
    ctx.fill();
  },
  flap: function() {
    this.vy = this.lift;
  }
};

const pipes = [];
const pipeWidth = 50;
const pipeGap = 150;
const pipeSpeed = 2;
const spawnPipe = function() {
  const y = Math.random() * (canvas.height - pipeGap) + pipeGap / 2;
  pipes.push({
    x: canvas.width,
    y: y,
    update: function() {
      this.x -= pipeSpeed;
    },
    draw: function() {
      ctx.fillStyle = 'green';
      ctx.fillRect(this.x, 0, pipeWidth, this.y - pipeGap / 2);
      ctx.fillRect(this.x, this.y + pipeGap / 2, pipeWidth, canvas.height - this.y - pipeGap / 2);
    },
    collidesWith: function(bird) {
      return (bird.x + bird.radius > this.x && bird.x - bird.radius < this.x + pipeWidth) &&
             ((bird.y - bird.radius < this.y - pipeGap / 2) || (bird.y + bird.radius > this.y + pipeGap / 2));
    }
  });
};

let score = 0;
let combo = 1;

const update = function() {
  bird.update();
  pipes.forEach(pipe => pipe.update());
  pipes = pipes.filter(pipe => pipe.x + pipeWidth > 0);

  if (pipes.length === 0 || pipes[pipes.length - 1].x < canvas.width - pipeWidth * 2) {
    spawnPipe();
  }

  if (bird.y + bird.radius > canvas.height || bird.y - bird.radius < 0) {
    resetGame();
  }

  pipes.forEach(pipe => {
    if (pipe.collidesWith(bird)) {
      resetGame();
    }
  });

  if (pipes.length > 0 && bird.x > pipes[0].x + pipeWidth) {
    score += combo;
    combo++;
    pipes.shift();
  }
};

const draw = function() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  bird.draw();
  pipes.forEach(pipe => pipe.draw());
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score} Combo: x${combo}`, 10, 30);
};

const resetGame = function() {
  pipes.length = 0;
  bird.y = canvas.height / 2;
  bird.vy = 0;
  score = 0;
  combo = 1;
};

const fixedTimeStep = 1 / 60; // 60 FPS
let accumulator = 0;
let lastTime = performance.now();

const gameLoop = function() {
  const now = performance.now();
  const deltaTime = (now - lastTime) / 1000;
  lastTime = now;
  accumulator += deltaTime;

  while (accumulator >= fixedTimeStep) {
    update();
    accumulator -= fixedTimeStep;
  }

  draw();
  requestAnimationFrame(gameLoop);
};

canvas.addEventListener('click', bird.flap.bind(bird));
gameLoop();
