class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  credit(amount) {
    this.balance += amount;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  getInventory() {
    return this.items;
  }
}

class Economy {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }
}

class Shop {
  constructor(economy, wallet, inventory) {
    this.economy = economy;
    this.wallet = wallet;
    this.inventory = inventory;
  }

  purchase(item) {
    const price = this.economy.getPrice(item);
    if (this.wallet.debit(price)) {
      this.inventory.addItem(item);
      return true;
    }
    return false;
  }
}

