class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
  }
}

class Crafting {
  constructor() {
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) return false;

    for (const [ingredient, quantity] of Object.entries(recipe.ingredients)) {
      if (inventory.getItemCount(ingredient) < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName, inventory) {
    if (this.canCraft(recipeName, inventory)) {
      const recipe = this.recipes.find(r => r.name === recipeName);
      for (const [ingredient, quantity] of Object.entries(recipe.ingredients)) {
        inventory.removeItem(ingredient, quantity);
      }
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  getItemCount(itemName) {
    return this.items[itemName] || 0;
  }

  addItem(itemName, quantity) {
    if (this.items[itemName]) {
      this.items[itemName] += quantity;
    } else {
      this.items[itemName] = quantity;
    }
  }

  removeItem(itemName, quantity) {
    if (this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
    }
  }
}

class Economy {
  constructor(prices) {
    this.prices = prices; // { itemName: price }
  }

  getPrice(itemName) {
    return this.prices[itemName] || 0;
  }

  debit(itemName, quantity) {
    const price = this.getPrice(itemName);
    const totalCost = price * quantity;
    // Simulate debit operation
    console.log(`Debited ${totalCost} for ${quantity} ${itemName}(s)`);
    return totalCost;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(itemName, quantity) {
    const price = this.economy.getPrice(itemName);
    const totalCost = this.economy.debit(itemName, quantity);
    if (totalCost > 0) {
      this.inventory.addItem(itemName, quantity);
      console.log(`Purchased ${quantity} ${itemName}(s) for ${totalCost}`);
