// EventBus class to handle communication between systems
class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

// Building system
class Building {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('resourceGathered', this.onResourceGathered.bind(this));
  }

  constructBuilding(type) {
