// Snake Game with Enemy Spawner

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.style.width = '100vw';
canvas.style.height = '100vh';
const dpr = window.devicePixelRatio;
canvas.width = canvas.clientWidth * dpr;
canvas.height = canvas.clientHeight * dpr;
const ctx = canvas.getContext('2d');
ctx.scale(dpr, dpr);

const gridSize = 20;
const gridWidth = Math.floor(canvas.width / gridSize);
const gridHeight = Math.floor(canvas.height / gridSize);

let snake = [{ x: 10, y: 10 }];
let direction = { x: 0, y: 0 };
let food = { x: 15, y: 15 };
let enemies = [];
let enemySpawnRate = 1000; // milliseconds
let score = 0;

function getRandomPosition() {
  return {
    x: Math.floor(Math.random() * gridWidth),
    y: Math.floor(Math.random() * gridHeight)
  };
}

function spawnEnemy() {
  const enemy = getRandomPosition();
  if (!snake.some(segment => segment.x === enemy.x && segment.y === enemy.y) && 
      enemy.x !== food.x && enemy.y !== food.y) {
    enemies.push(enemy);
  }
  setTimeout(spawnEnemy, enemySpawnRate);
}

function drawRect(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * gridSize, y * gridSize, gridSize, gridSize);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw snake
  snake.forEach(segment => drawRect(segment.x, segment.y, 'lime'));

  // Draw food
  drawRect(food.x, food.y, 'red');

  // Draw enemies
  enemies.forEach(enemy => drawRect(enemy.x, enemy.y, 'purple'));

  // Draw score
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 20);

  requestAnimationFrame(draw);
}

function update() {
  const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

  // Check for wall collision
  if (head.x < 0 || head.x >= gridWidth || head.y < 0 || head.y >= gridHeight) {
    resetGame();
    return;
  }

  // Check for self collision
  if (snake.some(segment => segment.x === head.x && segment.y === head.y)) {
    resetGame();
    return;
  }

  // Check for enemy collision
  if (enemies.some(enemy => enemy.x === head.x && enemy.y === head.y)) {
    resetGame();
    return;
  }

  // Check for food collision
  if (head.x === food.x && head.y === food.y) {
    score++;
    food = getRandomPosition();
    enemySpawnRate *= 0.95; // Increase difficulty
  } else {
    snake.pop();
  }

  snake.unshift(head);
}

function resetGame() {
  snake = [{ x: 10, y: 10 }];
  direction = { x: 0, y: 0 };
  food = { x: 15, y: 15 };
  enemies = [];
  enemySpawnRate = 1000;
  score = 0;
}

function changeDirection(event) {
  const keyPressed = event.key;
  const goingUp = direction.y === -1;
  const goingDown = direction.y === 1;
  const goingRight = direction.x === 1;
  const goingLeft = direction.x === -1;

  if (keyPressed === 'ArrowUp' && !goingDown) {
    direction = { x: 0, y: -1 };
  }
  if (keyPressed === 'ArrowDown' && !goingUp) {
    direction = { x: 0, y: 1 };
  }
  if (keyPressed === 'ArrowRight' && !goingLeft) {
    direction = { x: 1, y: 0 };
  }
  if (keyPressed === 'ArrowLeft' && !goingRight) {
    direction = { x: -1, y: 0 };
  }
}

document.addEventListener('keydown', changeDirection);
spawnEnemy();
setInterval(update, 100);
draw();
