class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(data));
    }
  }
}

class Spawner {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('enemyKilled', this.onEnemyKilled.bind(this));
  }

  spawnEnemy() {
    console.log('Spawning enemy');
    this.eventBus.emit('enemySpawned', { enemyId: Date.now() });
  }

  onEnemyKilled(data) {
    console.log(`Enemy ${data.enemyId} killed`);
    this.spawnEnemy();
  }
}

class EnemyPool {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('enemySpawned', this.onEnemySpawned.bind(this));
  }

  onEnemySpawned(data) {
    console.log(`Enemy ${data.enemyId} added to pool`);
    // Simulate enemy being killed after some time
    setTimeout(() => {
      this.eventBus.emit('enemyKilled', data);
    }, 2000);
  }
}

class Score {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('enemyKilled', this.onEnemyKilled.bind(this));
    this.score = 0;
  }

  onEnemyKilled(data) {
    this.score += 10;
    console.log(`Enemy ${data.enemyId} killed. Score: ${this.score}`);
  }
}

// Demo
