const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.style.position = 'absolute';
canvas.style.left = '0';
canvas.style.top = '0';
canvas.style.width = '100%';
canvas.style.height = '100%';

const ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio || 1;
function resize() {
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}
window.addEventListener('resize', resize);
resize();

const boardSize = 8;
const tileSpacing = 10;
const tileSize = (canvas.width / boardSize) - (tileSpacing * 2);
const colors = ['#FF5733', '#33FF57', '#3357FF', '#F333FF', '#33FFF7', '#F7F333'];

let board = [];
function initBoard() {
  board = Array.from({ length: boardSize }, () => 
    Array.from({ length: boardSize }, () => 
      Math.floor(Math.random() * colors.length)
    )
  );
}
initBoard();

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let y = 0; y < boardSize; y++) {
    for (let x = 0; x < boardSize; x++) {
      ctx.fillStyle = colors[board[y][x]];
      ctx.fillRect(x * (tileSize + tileSpacing * 2) + tileSpacing, 
                   y * (tileSize + tileSpacing * 2) + tileSpacing, 
                   tileSize, tileSize);
    }
  }
}

function matchCheck() {
  let matches = [];
  for (let y = 0; y < boardSize; y++) {
    for (let x = 0; x < boardSize - 2; x++) {
      if (board[y][x] === board[y][x + 1] && board[y][x] === board[y][x + 2]) {
        matches.push(...[...Array(3)].map((_, i) => ({ x: x + i, y })));
      }
    }
  }
  for (let x = 0; x < boardSize; x++) {
    for (let y = 0; y < boardSize - 2; y++) {
      if (board[y][x] === board[y + 1][x] && board[y][x] === board[y + 2][x]) {
        matches.push(...[...Array(3)].map((_, i) => ({ x, y: y + i })));
      }
    }
  }
  return matches;
}

function clearMatches(matches) {
  matches.forEach(({ x, y }) => board[y][x] = null);
}

function dropTiles() {
  for (let x = 0; x < boardSize; x++) {
    let emptySlots = 0;
    for (let y = boardSize - 1; y >= 0; y--) {
      if (board[y][x] === null) {
        emptySlots++;
      } else if (emptySlots > 0) {
        board[y + emptySlots][x] = board[y][x];
        board[y][x] = null;
      }
    }
  }
}

function fillEmpty() {
  for (let x = 0; x < boardSize; x++) {
    for (let y = 0; y < boardSize; y++) {
      if (board[y][x] === null) {
        board[y][x] = Math.floor(Math.random() * colors.length);
      }
    }
  }
}

function gameLoop() {
  const matches = matchCheck();
  if (matches.length > 0) {
    clearMatches(matches);
    dropTiles();
    fillEmpty();
  }
  drawBoard();
  requestAnimationFrame(gameLoop);
}

let selected = null;
canvas.addEventListener('click', (e) => {
  const rect = canvas.getBoundingClientRect();
  const x = Math.floor((e.clientX - rect.left) / (tileSize + tileSpacing * 2));
  const y = Math.floor((e.clientY - rect.top) / (tileSize + tileSpacing * 2));
  if (selected) {
    swapTiles(selected, { x, y });
    selected = null;
  } else {
    selected = { x, y };
  }
});

function swapTiles(pos1, pos2) {
  [board[pos1.y][pos1.x], board[pos2.y][pos2.x]] = [board[pos2.y][pos2.x], board[pos1.y][pos1.x]];
}

document.addEventListener('keydown', (e) => {
  if (selected) {
    const { x, y } = selected;
    switch (e.key) {
      case 'ArrowUp': swapTiles(selected, { x, y: y - 1 }); break;
      case 'ArrowDown': swapTiles(selected, { x, y: y + 1 }); break;
      case 'ArrowLeft': swapTiles(selected, { x: x - 1, y }); break;
      case 'ArrowRight': swapTiles(selected, { x: x + 1, y }); break;
    }
    selected = null;
  }
});

gameLoop();
