// Building System
class Building {
    constructor() {
        this.buildings = {};
    }

    build(type, amount = 1) {
        if (this.buildings[type]) {
            this.buildings[type] += amount;
        } else {
            this.buildings[type] = amount;
        }
        console.log(`Built ${amount} ${type}(s).`);
    }

    getBuildingCount(type) {
        return this.buildings[type] || 0;
    }
}

// Resource System
class Resource {
    constructor() {
        this.resources = { food: 0, wood: 0, gold: 0 };
    }

    gather(resourceType, amount = 1) {
        if (this.resources[resourceType]) {
            this.resources[resourceType] += amount;
        } else {
            this.resources[resourceType] = amount;
        }
        console.log(`Gathered ${amount} ${resourceType}.`);
    }

    getResourceAmount(resourceType) {
        return this.resources[resourceType] || 0;
    }
}

// Economy System
class Economy {
    constructor(resourceSystem) {
        this.resourceSystem = resourceSystem;
        this.prices = { food: 10, wood: 15, gold: 20 };
    }

    sell(resourceType, amount = 1) {
        const price = this.prices[resourceType];
        if (this.resourceSystem.getResourceAmount(resourceType) >= amount) {
            const revenue = price * amount;
            this.resourceSystem.gather('gold', revenue);
            this.resourceSystem.gather(resourceType, -amount);
            console.log(`Sold ${amount} ${resourceType} for ${revenue} gold.`);
        } else {
            console.log(`Not enough ${resourceType} to sell.`);
        }
    }
}

// Coordinator to wire the systems together
class Coordinator {
    constructor() {
        this.buildingSystem = new Building();
        this.resourceSystem = new Resource();
        this.economySystem = new Economy(this.resourceSystem);
    }

    buildBuilding(type, amount) {
        this.buildingSystem.build(type, amount);
    }

    gatherResource(resourceType, amount) {
        this.resourceSystem.gather(resourceType, amount);
    }

    sellResource(resourceType, amount) {
        this.economySystem.sell(resourceType, amount);
    }
}

// Demo
const coordinator = new Coordinator();

// Build some buildings
coordinator.buildBuilding('farm', 5);
coordinator.buildBuilding('mill', 3);

// Gather resources
coordinator.gatherResource('food', 100);
coordinator.gatherResource('wood', 50);

// Sell resources
coordinator.sellResource('food', 20);
coordinator.sellResource('wood', 10);

// Check resource amounts
