// Event Bus Implementation
class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(data));
    }
  }
}

// Dialogue System
class Dialogue {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('startDialogue', this.startDialogue.bind(this));
  }

  startDialogue(data) {
    console.log(`Dialogue: ${data.text}`);
    if (data.nextEvent) {
      this.eventBus.emit(data.nextEvent, data);
    }
  }
}

// Flags System
class Flags {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('setFlag', this.setFlag.bind(this));
    this.flags = {};
  }

  setFlag(data) {
    this.flags[data.name] = data.value;
    console.log(`Flag set: ${data.name} = ${data.value}`);
    if (data.nextEvent) {
      this.eventBus.emit(data.nextEvent, data);
    }
  }
}

// Quest System
class Quest {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('completeQuest', this.completeQuest.bind(this));
    this.completedQuests = [];
  }

  completeQuest(data) {
    this.completedQuests.push(data.name);
    console.log(`Quest completed: ${data.name}`);
    if (data.nextEvent) {
      this.eventBus.emit(data.nextEvent, data);
    }
  }
}

// Demo
