class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      if (this.items[item]) {
        this.items[item] += quantity;
      } else {
        this.items[item] = quantity;
      }
      return true;
    }
    return false;
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Shop {
  constructor(wallet, inventory, prices = {}) {
    this.wallet = wallet;
    this.inventory = inventory;
    this.prices = prices;
  }

  buyItem(item) {
    const price = this.prices[item];
    if (price && this.wallet.withdraw(price)) {
      this.inventory.addItem(item);
      return true;
    }
    return false;
  }

  sellItem(item) {
    const price = this.prices[item];
    if (price && this.inventory.removeItem(item)) {
      this.wallet.deposit(price);
      return true;
    }
    return false;
  }

  getItemPrice(item) {
    return this.prices[item] || 0;
  }
}

// Demo
const wallet = new Wallet(100);
const inventory = new Inventory();
const prices = { sword: 50, shield: 30 };
const shop = new Shop(wallet, inventory, prices);

console.log("Initial Wallet Balance:", wallet.getBalance());
console.log("Initial Inventory:", inventory.items);

shop.buyItem("sword");
console.log("After buying sword:", "Wallet Balance:", wallet.getBalance(), "Inventory:", inventory.items);

shop.buyItem("shield");
console.log("After buying shield:", "Wallet Balance:", wallet.getBalance(), "Inventory:", inventory.items);

shop.sellItem("sword");
console.log("After selling sword:", "Wallet Balance:", wallet.getBalance(), "Inventory:", inventory.items);
