const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const player = {
  health: 100,
  maxHealth: 100,
  position: { x: 400, y: 300 },
  velocity: { x: 0, y: 0 },
  speed: 5,
  respawnDelay: 3000,
  lastRespawn: 0
};

const enemy = {
  health: 50,
  position: { x: 200, y: 300 },
  velocity: { x: 2, y: 0 },
  speed: 3
};

const bullet = {
  position: { x: 0, y: 0 },
  velocity: { x: 0, y: 0 },
  speed: 10,
  active: false
};

const bulletSize = 5;
const playerSize = 20;
const enemySize = 15;

const fixedTimestep = 16; // approximately 60 FPS
let lastTime = performance.now();

function update(deltaTime) {
  // Player movement
  if (keys['ArrowRight']) player.velocity.x = player.speed;
  else if (keys['ArrowLeft']) player.velocity.x = -player.speed;
  else player.velocity.x = 0;

  if (keys['ArrowDown']) player.velocity.y = player.speed;
  else if (keys['ArrowUp']) player.velocity.y = -player.speed;
  else player.velocity.y = 0;

  player.position.x += player.velocity.x * deltaTime;
  player.position.y += player.velocity.y * deltaTime;

  // Enemy movement
  enemy.position.x += enemy.velocity.x * deltaTime;
  if (enemy.position.x < 0 || enemy.position.x > canvas.width - enemySize) {
    enemy.velocity.x *= -1;
  }

  // Bullet movement
  if (bullet.active) {
    bullet.position.x += bullet.velocity.x * deltaTime;
    bullet.position.y += bullet.velocity.y * deltaTime;
    if (bullet.position.x < 0 || bullet.position.x > canvas.width || bullet.position.y < 0 || bullet.position.y > canvas.height) {
      bullet.active = false;
    }
  }

  // Collision detection
  if (isColliding(player, enemy)) {
    player.health -= 10;
    if (player.health <= 0) {
      player.lastRespawn = performance.now();
      player.health = player.maxHealth;
    }
  }

  if (bullet.active && isColliding(bullet, enemy)) {
    enemy.health -= 10;
    if (enemy.health <= 0) {
      resetEnemy();
    }
    bullet.active = false;
  }

  // Respawn player
  if (performance.now() - player.lastRespawn > player.respawnDelay) {
    player.position = { x: 400, y: 300 };
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.position.x, player.position.y, playerSize, playerSize);

  // Draw enemy
  ctx.fillStyle = 'red';
  ctx.fillRect(enemy.position.x, enemy.position.y, enemySize, enemySize);

  // Draw bullet
  if (bullet.active) {
    ctx.fillStyle = 'black';
    ctx.fillRect(bullet.position.x, bullet.position.y, bulletSize, bulletSize);
  }

  // Draw health bar
  ctx.fillStyle = 'green';
  ctx.fillRect(10, 10, (player.health / player.maxHealth) * 100, 20);
}

function isColliding(obj1, obj2) {
  return obj1.position.x < obj2.position.x + obj2.size &&
         obj1.position.x + obj1.size > obj2.position.x &&
         obj1.position.y < obj2.position.y + obj2.size &&
         obj1.position.y + obj1.size > obj2.position.y;
}

function resetEnemy() {
  enemy.health = 50;
  enemy.position = { x: 200, y: Math.random() * (canvas.height - enemySize) };
}

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

function shoot() {
  if (!bullet.active) {
    bullet.active = true;
    bullet.position = { x: player.position.x + playerSize / 2, y: player.position.y + playerSize / 2 };
    bullet.velocity = { x: (enemy.position.x - player.position.x) / Math.sqrt((enemy.position.x - player.position.x) ** 2 + (enemy.position.y - player.position.y) ** 2) * bullet.speed,
                       y: (enemy.position.y - player.position.y) / Math.sqrt((enemy.position.x - player.position.x) ** 2 + (enemy.position.y - player.position.y) ** 2) * bullet.speed };
  }
}

window.addEventListener('keypress', e => {
  if (e.key === ' ') {
    shoot();
  }
});

function gameLoop() {
  const now = performance.now();
  const deltaTime = (now - lastTime) / 1000;
  lastTime = now;

  update(deltaTime);
  render();

  requestAnimationFrame(gameLoop);
}

gameLoop();
