```js
const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;

const player = {
  x: 50,
  y: 50,
  width: 20,
  height: 20,
  speed: 5,
  color: 'blue'
};

const powerUps = [];
for (let i = 0; i < 10; i++) {
  powerUps.push({
    x: Math.random() * (canvas.width - 20),
    y: Math.random() * (canvas.height - 20),
    width: 10,
    height: 10,
    color: 'red'
  });
}

const walls = [
  { x: 0, y: 0, width: canvas.width, height: 10 },
  { x: 0, y: canvas.height - 10, width: canvas.width, height: 10 },
  { x: 0, y: 0, width: 10, height: canvas.height },
  { x: canvas.width - 10, y: 0, width: 10, height: canvas.height }
];

let lastTime = 0;
const fixedTimeStep = 1000 / 60;
let accumulator = 0;

function update(deltaTime) {
  const speed = player.speed * deltaTime / 1000;

  if (keys['ArrowUp'] && !checkCollision(player, walls, 0, -speed)) player.y -= speed;
  if (keys['ArrowDown'] && !checkCollision(player, walls, 0, speed)) player.y += speed;
  if (keys['ArrowLeft'] && !checkCollision(player, walls, -speed, 0)) player.x -= speed;
  if (keys['ArrowRight'] && !checkCollision(player, walls, speed, 0)) player.x += speed;

  for (let i = powerUps.length - 1; i >= 0; i--) {
    if (checkCollision(player, [powerUps[i]], 0, 0)) {
      powerUps.splice(i, 1);
    }
  }
}

function checkCollision(rect1, rects, dx, dy) {
  for (const rect2 of rects) {
    if (
      rect1.x + dx < rect2.x + rect2.width &&
      rect1.x + dx + rect1.width > rect2.x &&
      rect1.y + dy < rect2.y + rect2.height &&
      rect1.y + dy + rect1.height > rect2.y
    ) {
      return true;
    }
  }
  return false;
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = player.color;
  ctx.fillRect(player.x, player.y, player.width, player.height);

  ctx.fillStyle = 'red';
  for (const powerUp of powerUps) {
    ctx.fillRect(powerUp.x, powerUp.y, powerUp.width, powerUp.height);
  }

  ctx.fillStyle = 'black';
  for (const wall of walls) {
    ctx.fillRect(wall.x, wall.y, wall.width, wall.height);
  }
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  lastTime = timestamp;
  accumulator += deltaTime;

  while (accumulator >= fixedTimeStep) {
    update(fixedTimeStep);
    accumulator -= fixedTimeStep;
  }

  render();
  requestAnimationFrame(gameLoop);
}

const keys = {};
window.addEventListener('keydown', (e) => { keys[e.key] = true; });
window.addEventListener('keyup', (e) => { keys[e.key] = false; });

gameLoop(performance.now());
