(function() {
    const canvas = document.createElement('canvas');
    document.body.appendChild(canvas);
    const ctx = canvas.getContext('2d');
    let scale = window.devicePixelRatio;
    let boardSize = 4;
    let board = Array(boardSize).fill().map(() => Array(boardSize).fill(0));
    let score = 0;
    let highScore = localStorage.getItem('2048HighScore') || 0;

    function resizeCanvas() {
        canvas.width = window.innerWidth * scale;
        canvas.height = window.innerHeight * scale;
        ctx.scale(scale, scale);
    }

    function drawBoard() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#bbada0';
        ctx.fillRect(0, 0, boardSize * 100, boardSize * 100);
        for (let y = 0; y < boardSize; y++) {
            for (let x = 0; x < boardSize; x++) {
                let tile = board[y][x];
                if (tile !== 0) {
                    ctx.fillStyle = `rgb(${255 - (tile * 255 / 2048)}, ${255 - (tile * 255 / 2048)}, ${255 - (tile * 255 / 2048)})`;
                    ctx.fillRect(x * 100, y * 100, 100, 100);
                    ctx.fillStyle = '#f9f6f2';
                    ctx.font = '50px Arial';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    ctx.fillText(tile, x * 100 + 50, y * 100 + 50);
                }
            }
        }
        ctx.fillStyle = '#eee4da';
        ctx.fillRect(boardSize * 100, 0, 200, 100);
        ctx.fillStyle = '#776e65';
        ctx.font = '30px Arial';
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillText(`Score: ${score}`, boardSize * 100 + 190, 50);
        ctx.fillText(`High Score: ${highScore}`, boardSize * 100 + 190, 150);
    }

    function newTile() {
        let emptyCells = [];
        for (let y = 0; y < boardSize; y++) {
            for (let x = 0; x < boardSize; x++) {
                if (board[y][x] === 0) {
                    emptyCells.push({ x, y });
                }
            }
        }
        if (emptyCells.length > 0) {
            let { x, y } = emptyCells[Math.floor(Math.random() * emptyCells.length)];
            board[y][x] = Math.random() < 0.9 ? 2 : 4;
        }
    }

    function move(dir) {
        let moved = false;
        if (dir === 'ArrowUp' || dir === 'KeyW') {
            for (let x = 0; x < boardSize; x++) {
                let newRow = [];
                for (let y = 0; y < boardSize; y++) {
                    if (board[y][x] !== 0) {
                        newRow.push(board[y][x]);
                    }
                }
                for (let i = 0; i < newRow.length - 1; i++) {
                    if (newRow[i] === newRow[i + 1]) {
                        newRow[i] *= 2;
                        newRow[i + 1] = 0;
                        score += newRow[i];
                    }
                }
                newRow = newRow.filter(tile => tile !== 0);
                while (newRow.length < boardSize) {
                    newRow.push(0);
                }
                for (let y = 0; y < boardSize; y++) {
                    if (board[y][x] !== newRow[y]) {
                        board[y][x] = newRow[y];
                        moved = true;
                    }
                }
            }
        } else if (dir === 'ArrowDown' || dir === 'KeyS') {
            for (let x = 0; x < boardSize; x++) {
