class RarityTable {
    constructor() {
        this.rarityWeights = {
            "common": 0.6,
            "uncommon": 0.3,
            "rare": 0.1
        };
    }

    getRandomRarity() {
        const rand = Math.random();
        let cumulative = 0;
        for (const rarity in this.rarityWeights) {
            cumulative += this.rarityWeights[rarity];
            if (rand < cumulative) {
                return rarity;
            }
        }
        return "common"; // Default to common if no match
    }
}

class Loot {
    constructor() {
        this.items = {
            "common": ["potion", "coin", "scroll"],
            "uncommon": ["sword", "shield", "amulet"],
            "rare": ["legendary weapon", "magic staff", "ancient artifact"]
        };
    }

    getRandomItem(rarity) {
        const items = this.items[rarity] || this.items.common;
        return items[Math.floor(Math.random() * items.length)];
    }
