// Farming Plot Simulator with Particle Burst Effect

const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Constants
const PARTICLE_COUNT = 100;
const PARTICLE_LIFESPAN = 100;
const FIXED_TIMESTEP = 1000 / 60; // 60 FPS
const GRAVITY = 0.05;
const BURST_RADIUS = 100;

// Particle class
class Particle {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.vx = Math.random() * 4 - 2;
    this.vy = Math.random() * -2 - 1;
    this.alpha = 1;
    this.lifespan = PARTICLE_LIFESPAN;
  }

  update() {
    this.vy += GRAVITY;
    this.x += this.vx;
    this.y += this.vy;
    this.lifespan -= 1;
    this.alpha = this.lifespan / PARTICLE_LIFESPAN;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, 1, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(255, 255, 255, ${this.alpha})`;
    ctx.fill();
  }
}

// Farming Plot Simulator class
class FarmingPlot {
  constructor() {
    this.particles = [];
    this.plant = { x: canvas.width / 2, y: canvas.height - 50, growth: 0 };
    this.isGrowing = false;
  }

  update(deltaTime) {
    if (this.isGrowing) {
      this.plant.growth += deltaTime * 0.01;
      if (this.plant.growth >= 1) {
        this.isGrowing = false;
        this.plant.growth = 1;
        this.explode();
      }
    }

    this.particles = this.particles.filter(particle => particle.lifespan > 0);
    this.particles.forEach(particle => particle.update());
  }

  draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw plant
    ctx.fillStyle = 'green';
    ctx.fillRect(this.plant.x - 10, this.plant.y - this.plant.growth * 100, 20, this.plant.growth * 100);

    // Draw particles
    this.particles.forEach(particle => particle.draw());
  }

  startGrowing() {
    this.isGrowing = true;
  }

  explode() {
    for (let i = 0; i < PARTICLE_COUNT; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 2;
      const particle = new Particle(
        this.plant.x + Math.cos(angle) * BURST_RADIUS,
        this.plant.y + Math.sin(angle) * BURST_RADIUS
      );
      particle.vx = Math.cos(angle) * speed;
      particle.vy = Math.sin(angle) * speed;
      this.particles.push(particle);
    }
  }
}

const farmingPlot = new FarmingPlot();

// Main loop
let lastTime = performance.now();
function gameLoop(currentTime) {
  const deltaTime = currentTime - lastTime;
  lastTime = currentTime;

  farmingPlot.update(deltaTime);
  farmingPlot.draw();

  requestAnimationFrame(gameLoop);
}

// Start game loop
requestAnimationFrame(gameLoop);

// Event listener for planting
canvas.addEventListener('click', () => {
  if (!farmingPlot.isGrowing) {
    farmingPlot.startGrowing();
  }
});
