// Constants
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const FPS = 60;
const TIME_STEP = 1000 / FPS;

// Canvas setup
const canvas = document.createElement('canvas');
canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game state
let lastTime = 0;
let gameTime = 0;
let enemies = [];
let towers = [];
let powerUps = [];
let selectedTower = null;

// Tower class
class Tower {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.range = 100;
        this.damage = 10;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, 10, 0, Math.PI * 2);
        ctx.fillStyle = 'green';
        ctx.fill();
    }

    attack(enemies) {
        let target = enemies.find(e => this.distanceTo(e) <= this.range);
        if (target) {
            target.health -= this.damage;
            if (target.health <= 0) {
                enemies.splice(enemies.indexOf(target), 1);
            }
        }
    }

    distanceTo(other) {
        return Math.sqrt((this.x - other.x) ** 2 + (this.y - other.y) ** 2);
    }
}

// Enemy class
class Enemy {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.health = 100;
        this.speed = 2;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, 10, 0, Math.PI * 2);
        ctx.fillStyle = 'red';
        ctx.fill();
    }

    update() {
        this.x += this.speed;
    }
}

// PowerUp class
class PowerUp {
    constructor(x, y, type) {
        this.x = x;
        this.y = y;
        this.type = type;
        this.radius = 10;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.type === 'range' ? 'blue' : 'yellow';
        ctx.fill();
    }

    collect(tower) {
        if (this.type === 'range') {
            tower.range += 20;
        } else if (this.type === 'damage') {
            tower.damage += 5;
        }
        powerUps.splice(powerUps.indexOf(this), 1);
    }
}

// Main loop
function gameLoop(timestamp) {
    let deltaTime = timestamp - lastTime;
    lastTime = timestamp;

    // Accumulate game time
    gameTime += deltaTime;

    // Fixed time step update
    while (gameTime >= TIME_STEP) {
        update();
        gameTime -= TIME_STEP;
    }

    draw();

    requestAnimationFrame(gameLoop);
}

// Update game state
function update() {
    // Spawn enemies
    if (Math.random() < 0.05) {
        enemies.push(new Enemy(-10, Math.random() * CANVAS_HEIGHT));
    }

    // Move enemies
    enemies.forEach(enemy => enemy.update());

    // Towers attack
    towers.forEach(tower => tower.attack(enemies));

    // Collect power-ups
    towers.forEach(tower => {
        powerUps.forEach(powerUp => {
            if (tower.distanceTo(powerUp) <= powerUp.radius) {
                powerUp.collect(tower);
            }
        });
    });

    // Spawn power-ups
    if (Math.random() < 0.02) {
        powerUps.push(new PowerUp(Math.random() * CANVAS_WIDTH, Math.random() * CANVAS_HEIGHT, Math.random() > 0.5 ? 'range' : 'damage'));
    }
}

// Draw game state
function draw() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw enemies
    enemies.forEach(enemy => enemy.draw());

    // Draw towers
    towers.forEach(tower => tower.draw());

    // Draw power-ups
    powerUps.forEach(powerUp => powerUp.draw());
}

// Event listeners
canvas.addEventListener('click', (event) => {
    if (selectedTower) {
        let rect = canvas.getBoundingClientRect();
        let x = event.clientX - rect.left;
        let y = event.clientY - rect.top;
        towers.push(new Tower(x, y));
    }
});

canvas.addEventListener('dblclick', (event) => {
    let rect = canvas.getBoundingClientRect();
    let x = event.clientX - rect.left;
    let y = event.clientY - rect.top;
    selectedTower = towers.find(tower => tower.distanceTo({ x, y }) <= 10);
});

// Start the game loop
requestAnimationFrame(gameLoop);
