  if (fish.x + fish.width > canvas.width || fish.x < 0) {
    fish.direction *= -1;
  }
}

function updateReel() {
  if (reel.grabbed) {
    reel.x = fish.x + fish.width;
    reel.y = fish.y;
  } else {
    reel.x -= reel.speed;
    if (reel.x < 0) {
      reel.x = canvas.width;
    }
  }
}

function checkCollision() {
  if (reel.grabbed && fish.x < reel.x + reel.width &&
      fish.x + fish.width > reel.x &&
      fish.y < reel.y + reel.height &&
      fish.y + fish.height > reel.y) {
    combo++;
    score += 10 * combo;
    reel.grabbed = false;
    fish.x = 100;
    fish.y = 300;
    fish.direction = 1;
  }
}

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Combo: ${combo}`, 10, 60);
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  updateFish();
  updateReel();
  checkCollision();
  drawFish();
  drawReel();
  drawScore();
  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', () => {
  reel.grabbed = true;
});

canvas.addEventListener('mouseup', () => {
  reel.grabbed = false;
});

gameLoop();
