class EventBus {
    constructor() {
        this.listeners = {};
    }

    subscribe(event, callback) {
        if (!this.listeners[event]) {
            this.listeners[event] = [];
        }
        this.listeners[event].push(callback);
    }

    emit(event, data) {
        if (this.listeners[event]) {
            this.listeners[event].forEach(callback => callback(data));
        }
    }
}

class Bank {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.balance = 0;

        this.eventBus.subscribe('deposit', this.deposit.bind(this));
        this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
    }

    deposit(amount) {
        this.balance += amount;
        this.eventBus.emit('balanceChanged', { balance: this.balance });
        console.log(`Deposited ${amount}, new balance is ${this.balance}`);
    }

    withdraw(amount) {
        if (this.balance >= amount) {
            this.balance -= amount;
            this.eventBus.emit('balanceChanged', { balance: this.balance });
            console.log(`Withdrew ${amount}, new balance is ${this.balance}`);
        } else {
            console.log('Insufficient funds');
        }
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.prices = { apple: 1, banana: 2, carrot: 1.5 };

        this.eventBus.subscribe('sell', this.sell.bind(this));
        this.eventBus.subscribe('buy', this.buy.bind(this));
    }

    sell(item, quantity) {
        const price = this.prices[item] * quantity;
        this.eventBus.emit('sellRequest', { item, quantity, price });
    }

    buy(item, quantity, price) {
        if (this.prices[item] * quantity === price) {
            console.log(`Bought ${quantity} ${item}s for ${price}`);
            this.eventBus.emit('itemBought', { item, quantity });
        } else {
            console.log('Transaction failed due to price mismatch');
        }
    }

    getItemPrice(item) {
        return this.prices[item];
    }
}

class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = {};

        this.eventBus.subscribe('itemBought', this.addItem.bind(this));
        this.eventBus.subscribe('sellRequest', this.handleSellRequest.bind(this));
    }

    addItem(itemData) {
        const { item, quantity } = itemData;
        if (!this.items[item]) {
            this.items[item] = 0;
        }
        this.items[item] += quantity;
        console.log(`Added ${quantity} ${item}s to inventory`);
    }

    handleSellRequest(sellRequest) {
        const { item, quantity, price } = sellRequest;
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            this.eventBus.emit('sellConfirmed', { item, quantity, price });
            console.log(`Sold ${quantity} ${item}s for ${price}`);
        } else {
            console.log(`Could not sell ${quantity} ${item}s, insufficient stock`);
        }
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }
}

// Demo
