    return this.prices.get(resource) || 0;
  }

  addResourceToInventory(resource, quantity) {
    if (this.inventory.has(resource)) {
      this.inventory.set(resource, this.inventory.get(resource) + quantity);
    } else {
      this.inventory.set(resource, quantity);
    }
  }

  removeResourceFromInventory(resource, quantity) {
    if (this.inventory.has(resource)) {
      const currentQuantity = this.inventory.get(resource);
      if (currentQuantity >= quantity) {
        this.inventory.set(resource, currentQuantity - quantity);
      } else {
        throw new Error("Insufficient resources in inventory");
      }
    } else {
      throw new Error("Resource not found in inventory");
    }
  }

  getInventoryQuantity(resource) {
    return this.inventory.get(resource) || 0;
  }
}

