const player = { x: 400, y: 300, size: 10, speed: 5 };
const enemies = [];
const spawner = { interval: 2000, nextSpawn: 0 };
const difficultyMultiplier = 1.05;

function drawPlayer() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x - player.size / 2, player.y - player.size / 2, player.size, player.size);
}

function drawEnemies() {
    ctx.fillStyle = 'red';
    enemies.forEach(enemy => {
        ctx.fillRect(enemy.x - enemy.size / 2, enemy.y - enemy.size / 2, enemy.size, enemy.size);
    });
}

function updatePlayer(dt) {
    if (keys['ArrowLeft']) player.x -= player.speed * dt;
    if (keys['ArrowRight']) player.x += player.speed * dt;
    if (keys['ArrowUp']) player.y -= player.speed * dt;
    if (keys['ArrowDown']) player.y += player.speed * dt;
    player.x = Math.max(player.size / 2, Math.min(canvas.width - player.size / 2, player.x));
    player.y = Math.max(player.size / 2, Math.min(canvas.height - player.size / 2, player.y));
}

function spawnEnemy() {
    const x = Math.random() * canvas.width;
    const y = Math.random() * canvas.height;
    const size = Math.random() * 10 + 5;
    const speed = Math.random() * 2 + 1;
    enemies.push({ x, y, size, speed });
    spawner.nextSpawn = Date.now() + spawner.interval;
}

function updateEnemies(dt) {
    enemies.forEach(enemy => {
        enemy.x += (player.x - enemy.x) * enemy.speed * dt;
        enemy.y += (player.y - enemy.y) * enemy.speed * dt;
    });
}

function checkCollisions() {
    enemies.forEach(enemy => {
        if (Math.abs(player.x - enemy.x) < (player.size + enemy.size) / 2 &&
            Math.abs(player.y - enemy.y) < (player.size + enemy.size) / 2) {
            alert('Game Over!');
            resetGame();
        }
    });
}

function resetGame() {
    enemies.length = 0;
    player.x = canvas.width / 2;
    player.y = canvas.height / 2;
    spawner.interval = 2000;
    spawner.nextSpawn = Date.now() + spawner.interval;
}

let lastTime = 0;
function gameLoop(timestamp) {
    const dt = Math.min((timestamp - lastTime) / 1000, 1 / 30); // Fixed timestep cap
    lastTime = timestamp;

    updatePlayer(dt);
    if (Date.now() > spawner.nextSpawn) {
        spawnEnemy();
        spawner.interval *= difficultyMultiplier;
    }
    updateEnemies(dt);
    checkCollisions();

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawPlayer();
    drawEnemies();

    requestAnimationFrame(gameLoop);
}

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

resetGame();
requestAnimationFrame(gameLoop);
