let startTime = null;
let score = 0;
let pointerDown = false;
let pointerPosition = { x: 0, y: 0 };

canvas.addEventListener('keydown', (e) => {
    if (startTime === null) startTime = performance.now();
    if (e.key === text[textIndex]) {
        textIndex++;
        score++;
    }
});

canvas.addEventListener('pointerdown', (e) => {
    pointerDown = true;
    pointerPosition = { x: e.clientX - canvas.offsetLeft, y: e.clientY - canvas.offsetTop };
});

canvas.addEventListener('pointermove', (e) => {
    if (pointerDown) {
        pointerPosition = { x: e.clientX - canvas.offsetLeft, y: e.clientY - canvas.offsetTop };
    }
});

canvas.addEventListener('pointerup', () => {
    pointerDown = false;
});

function mainLoop(timestamp) {
    if (!startTime) startTime = timestamp;
    const elapsed = timestamp - startTime;
    const minutesElapsed = elapsed / (1000 * 60);
    const expectedCharsTyped = minutesElapsed * targetSpeed;
    const accuracy = (score / expectedCharsTyped) || 0;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '24px Arial';
    ctx.fillText(text.substring(0, textIndex), 10, 50);
    ctx.fillText(`Score: ${score}`, 10, 80);
    ctx.fillText(`Accuracy: ${(accuracy * 100).toFixed(2)}%`, 10, 110);

    if (pointerDown) {
        const charIndex = Math.floor(pointerPosition.x / 25); // Assuming each char is 25px wide
        if (text[charIndex] === text[textIndex]) {
            textIndex++;
            score++;
        }
    }

    requestAnimationFrame(mainLoop);
}

