const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio || 1;
let canvasWidth = window.innerWidth;
let canvasHeight = window.innerHeight;
canvas.width = canvasWidth * dpr;
canvas.height = canvasHeight * dpr;
ctx.scale(dpr, dpr);

const cardWidth = 80;
const cardHeight = 120;
const margin = 10;
const columns = Math.floor(canvasWidth / (cardWidth + margin));
const rows = Math.floor(canvasHeight / (cardHeight + margin));
const totalCards = columns * rows;
const cardPairs = totalCards / 2;

let state = 'menu';
let cards = [];
let firstCard = null;
let secondCard = null;
let flipsLeft = cardPairs;
let score = 0;

function resetGame() {
    state = 'playing';
    firstCard = null;
    secondCard = null;
    flipsLeft = cardPairs;
    score = 0;
    cards = [];
    for (let i = 0; i < cardPairs; i++) {
        cards.push({ value: i, flipped: false, matched: false });
        cards.push({ value: i, flipped: false, matched: false });
    }
    shuffle(cards);
}

function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
}

function drawCard(x, y, card, faceUp) {
    ctx.fillStyle = '#fff';
    ctx.fillRect(x, y, cardWidth, cardHeight);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(x, y, cardWidth, cardHeight);
    if (faceUp) {
        ctx.fillStyle = '#000';
        ctx.font = '20px Arial';
        ctx.fillText(card.value, x + cardWidth / 2 - 10, y + cardHeight / 2 + 5);
    }
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < cards.length; i++) {
        const x = (i % columns) * (cardWidth + margin);
        const y = Math.floor(i / columns) * (cardHeight + margin);
        drawCard(x, y, cards[i], cards[i].flipped || cards[i].matched);
    }
}

function drawMenu() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#000';
    ctx.font = '30px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Memory Game', canvasWidth / 2, canvasHeight / 3);
    ctx.font = '20px Arial';
    ctx.fillText('Click to Start', canvasWidth / 2, canvasHeight / 3 + 50);
}

function drawPaused() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#000';
    ctx.font = '30px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Game Paused', canvasWidth / 2, canvasHeight / 3);
    ctx.font = '20px Arial';
    ctx.fillText('Click to Resume', canvasWidth / 2, canvasHeight / 3 + 50);
}

function drawGameOver() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#000';
    ctx.font = '30px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvasWidth / 2, canvasHeight / 3);
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, canvasWidth / 2, canvasHeight / 3 + 50);
    ctx.fillText('Click to Restart', canvasWidth / 2, canvasHeight / 3 + 100);
}

function update() {
    if (state === 'playing') {
        if (firstCard && secondCard) {
            if (firstCard.value === secondCard.value) {
                firstCard.matched = true;
                secondCard.matched = true;
                score++;
            } else {
                firstCard.flipped = false;
                secondCard.flipped = false;
            }
            firstCard = null;
            secondCard = null;
            if (score === cardPairs) {
                state = 'gameover';
            }
        }
    }
}

function handleMouseDown(event) {
    if (state === 'menu') {
        state = 'playing';
        resetGame();
    } else if (state === 'playing') {
        const rect = canvas.getBoundingClientRect();
        const x = event.clientX - rect.left;
        const y = event.clientY - rect.top;
        for (let i = 0; i < cards.length; i++) {
            const cardX = (i % columns) * (cardWidth + margin);
            const cardY = Math.floor(i / columns) * (cardHeight + margin);
            if (x >= cardX && x <= cardX + cardWidth && y >= cardY && y <= cardY + cardHeight) {
                if (!cards[i].flipped && !cards[i].matched) {
                    cards[i].flipped = true;
                    if (!firstCard) {
                        firstCard = cards[i];
                    } else {
                        secondCard = cards[i];
                        setTimeout(update, 500);
                    }
                }
                break;
            }
        }
    } else if (state === 'paused') {
        state = 'playing';
    } else if (state === 'gameover') {
        resetGame();
    }
}

function handleKeyDown(event) {
    if (event.key === 'p' && state === 'playing') {
        state = 'paused';
    } else if (event.key === 'p' && state === 'paused') {
        state = 'playing';
    }
}

canvas.addEventListener('mousedown', handleMouseDown);
window.addEventListener('keydown', handleKeyDown);

function loop() {
    if (state === 'menu') {
        drawMenu();
    } else if (state === 'paused') {
        drawPaused();
    } else if (state === 'gameover') {
        drawGameOver();
    } else {
        drawBoard();
    }
    requestAnimationFrame(loop);
}

loop();
