// Top-down arena shooter with combo multiplier
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let width, height, pixelRatio;
function resizeCanvas() {
    width = window.innerWidth;
    height = window.innerHeight;
    pixelRatio = window.devicePixelRatio || 1;
    canvas.width = width * pixelRatio;
    canvas.height = height * pixelRatio;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
    ctx.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);

// Game state
const player = {
    x: width / 2,
    y: height / 2,
    size: 10,
    speed: 2,
    angle: 0,
    combo: 0
};

const enemies = [];
const enemyCount = 5;
const enemySize = 5;
const enemySpeed = 1;

for (let i = 0; i < enemyCount; i++) {
    enemies.push({
        x: Math.random() * width,
        y: Math.random() * height,
        size: enemySize,
        speed: enemySpeed
    });
}

let gameOver = false;

// Game loop
function gameLoop() {
    if (gameOver) return;

    ctx.clearRect(0, 0, width, height);

    // Player movement
    const speed = player.speed;
    if (keys.ArrowUp || keys.W) player.y -= speed;
    if (keys.ArrowDown || keys.S) player.y += speed;
    if (keys.ArrowLeft || keys.A) player.x -= speed;
    if (keys.ArrowRight || keys.D) player.x += speed;

    // Boundary check
    player.x = Math.max(player.size, Math.min(width - player.size, player.x));
    player.y = Math.max(player.size, Math.min(height - player.size, player.y));

    // Player aim and shoot
    if (keys.Space) {
        const bullet = {
            x: player.x + Math.cos(player.angle) * player.size,
            y: player.y + Math.sin(player.angle) * player.size,
            size: 2,
            speed: 5,
            angle: player.angle
        };
        bullets.push(bullet);
    }

    // Update bullets
    bullets.forEach((bullet, index) => {
        bullet.x += Math.cos(bullet.angle) * bullet.speed;
        bullet.y += Math.sin(bullet.angle) * bullet.speed;

        // Remove off-screen bullets
        if (bullet.x < 0 || bullet.x > width || bullet.y < 0 || bullet.y > height) {
            bullets.splice(index, 1);
        }
    });

    // Update enemies
    enemies.forEach((enemy, index) => {
        const dx = player.x - enemy.x;
        const dy = player.y - enemy.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance > 0) {
            enemy.x += (dx / distance) * enemy.speed;
            enemy.y += (dy / distance) * enemy.speed;
        }

        // Check for collisions with bullets
        bullets.forEach((bullet, bulletIndex) => {
            const dx = bullet.x - enemy.x;
            const dy = bullet.y - enemy.y;
            const distance = Math.sqrt(dx * dx + dy * dy);
            if (distance < enemy.size + bullet.size) {
                enemies.splice(index, 1);
                bullets.splice(bulletIndex, 1);
                player.combo++;
                if (enemies.length === 0) {
                    gameOver = true;
                    alert(`Game Over! Combo: ${player.combo}`);
                }
                return;
            }
        });
    });

    // Draw player
    ctx.fillStyle = 'blue';
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.size, 0, Math.PI * 2);
    ctx.fill();

    // Draw enemies
    ctx.fillStyle = 'red';
    enemies.forEach(enemy => {
        ctx.beginPath();
        ctx.arc(enemy.x, enemy.y, enemy.size, 0, Math.PI * 2);
        ctx.fill();
    });

    // Draw bullets
    ctx.fillStyle = 'white';
    bullets.forEach(bullet => {
        ctx.beginPath();
        ctx.arc(bullet.x, bullet.y, bullet.size, 0, Math.PI * 2);
        ctx.fill();
    });

    requestAnimationFrame(gameLoop);
}

// Input handling
const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

// Start game loop
let bullets = [];
gameLoop();
