  return {
    x: Math.random() * canvas.width,
    y: 0,
    r: 10,
    vy: 0
  };
}

function resetLevel() {
  balls = [];
  wave = 0;
  waveBalls = 0;
  level++;
}

function updateBalls() {
  balls.forEach((ball, index) => {
    ball.vy += gravity;
    ball.y += ball.vy;
    if (ball.y + ball.r > canvas.height) {
      balls.splice(index, 1);
    }
  });
}

function drawBalls() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  balls.forEach(ball => {
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
    ctx.fillStyle = 'blue';
    ctx.fill();
  });
  ctx.font = '24px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText(`Level: ${level}`, 10, 30);
  ctx.fillText(`Wave: ${wave + 1}`, 10, 60);
}

function spawnBalls() {
  if (balls.length < maxBalls && waveBalls < level) {
    balls.push(createBall());
    waveBalls++;
  }
}

function checkWaveCompletion() {
  if (waveBalls === level && balls.length === 0) {
    wave++;
    waveBalls = 0;
    if (wave % 5 === 0) {
      resetLevel();
    }
  }
}

function gameLoop() {
  updateBalls();
  spawnBalls();
  checkWaveCompletion();
  drawBalls();
  requestAnimationFrame(gameLoop);
}

