// Economy System
class Economy {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

// Store System
class Store {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getPrices() {
    return this.prices;
  }

  getPrice(item) {
    return this.prices[item] || null;
  }

  setPrice(item, price) {
    if (price >= 0) {
      this.prices[item] = price;
      return true;
    }
    return false;
  }
}

// Inventory System
class Inventory {
  constructor(items = {}) {
    this.items = items;
  }

  getInventory() {
    return this.items;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }

  addItem(item, count = 1) {
    if (count > 0) {
      this.items[item] = (this.items[item] || 0) + count;
      return true;
    }
    return false;
  }

  removeItem(item, count = 1) {
    if (count > 0 && this.items[item] >= count) {
      this.items[item] -= count;
      return true;
    }
    return false;
  }
}

