        this.balance = initialBalance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Shop {
    constructor(items = {}) {
        this.items = items; // { itemName: { price, stock } }
    }

    buyItem(itemName, wallet) {
        const item = this.items[itemName];
        if (item && item.stock > 0 && wallet.withdraw(item.price)) {
            item.stock -= 1;
            return true;
        }
        return false;
    }

    getItems() {
        return { ...this.items };
    }
}

class Inventory {
    constructor() {
        this.items = {}; // { itemName: quantity }
    }

    addItem(itemName) {
        if (this.items[itemName]) {
            this.items[itemName] += 1;
        } else {
            this.items[itemName] = 1;
        }
    }

    getItemCount(itemName) {
        return this.items[itemName] || 0;
    }

    getInventory() {
        return { ...this.items };
    }
}

class Coordinator {
    constructor(wallet, shop, inventory) {
        this.wallet = wallet;
        this.shop = shop;
        this.inventory = inventory;
    }

    buyAndStoreItem(itemName) {
        if (this.shop.buyItem(itemName, this.wallet)) {
            this.inventory.addItem(itemName);
            return true;
        }
        return false;
    }

    getWalletBalance() {
        return this.wallet.getBalance();
    }

    getShopItems() {
        return this.shop.getItems();
    }

    getInventory() {
        return this.inventory.getInventory();
    }
}

