class Spawner {
  constructor() {
    this.spawnRate = 2000; // milliseconds
    this.intervalId = null;
  }

  start(onSpawn) {
    if (!this.intervalId) {
      this.intervalId = setInterval(() => {
        onSpawn();
      }, this.spawnRate);
    }
  }

  stop() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }
}

class EnemyPool {
  constructor() {
    this.enemies = [];
  }

  addEnemy(enemy) {
    this.enemies.push(enemy);
  }

  removeEnemy(enemy) {
    this.enemies = this.enemies.filter(e => e !== enemy);
  }

  getEnemies() {
    return this.enemies;
  }
}

class Score {
  constructor() {
    this.score = 0;
  }

  increment() {
    this.score += 10;
  }

  getScore() {
    return this.score;
  }
}

class GameCoordinator {
  constructor(spawner, enemyPool, score) {
    this.spawner = spawner;
    this.enemyPool = enemyPool;
    this.score = score;
  }

  startGame() {
    this.spawner.start(() => {
      const newEnemy = { id: Date.now(), health: 100 };
      this.enemyPool.addEnemy(newEnemy);
      console.log(`Enemy spawned: ${newEnemy.id}`);
    });

    // Simulate enemy death
    setInterval(() => {
      const enemies = this.enemyPool.getEnemies();
      if (enemies.length > 0) {
        const enemy = enemies[0];
        this.enemyPool.removeEnemy(enemy);
        this.score.increment();
        console.log(`Enemy ${enemy.id} defeated. Score: ${this.score.getScore()}`);
      }
    }, 3000);
  }

  stopGame() {
    this.spawner.stop();
  }
}

// Demo
const spawner = new Spawner();
const enemyPool = new EnemyPool();
const score = new Score();
const coordinator = new GameCoordinator(spawner, enemyPool, score);

coordinator.startGame();

// Stop the game after 20 seconds for demonstration purposes
setTimeout(() => {
  coordinator.stopGame();
  console.log("Game stopped.");
}, 20000);
