class Building {
  constructor(name, cost) {
    this.name = name;
    this.cost = cost;
  }

  getName() {
    return this.name;
  }

  getCost() {
    return this.cost;
  }
}

class Resource {
  constructor(name, quantity) {
    this.name = name;
    this.quantity = quantity;
  }

  getName() {
    return this.name;
  }

  getQuantity() {
    return this.quantity;
  }

  addQuantity(amount) {
    this.quantity += amount;
  }

  subtractQuantity(amount) {
    if (amount > this.quantity) {
      throw new Error("Insufficient resources");
    }
    this.quantity -= amount;
  }
}

class Economy {
  constructor(resources) {
    this.resources = resources;
  }

  canAfford(building) {
    const resource = this.resources.find(r => r.getName() === building.getName());
    if (!resource) {
      throw new Error("Resource not found");
    }
    return resource.getQuantity() >= building.getCost();
  }

  spend(building) {
    const resource = this.resources.find(r => r.getName() === building.getName());
    if (!resource) {
      throw new Error("Resource not found");
    }
    if (resource.getQuantity() < building.getCost()) {
      throw new Error("Insufficient resources");
    }
    resource.subtractQuantity(building.getCost());
    console.log(`Spent ${building.getCost()} ${building.getName()} to build ${building.getName()}`);
  }

  receiveIncome(building) {
    const resource = this.resources.find(r => r.getName() === building.getName());
    if (!resource) {
      throw new Error("Resource not found");
    }
    resource.addQuantity(building.getCost());
    console.log(`Received ${building.getCost()} ${building.getName()} income from ${building.getName()}`);
  }
}

// Demo
const lumber = new Resource("Lumber", 100);
const stone = new Resource("Stone", 50);
const resources = [lumber, stone];

const economy = new Economy(resources);

const sawmill = new Building("Sawmill", 20);
const quarry = new Building("Quarry", 10);

console.log(`Can afford Sawmill: ${economy.canAfford(sawmill)}`); // true
economy.spend(sawmill);
console.log(`Can afford Quarry: ${economy.canAfford(quarry)}`); // true
economy.spend(quarry);

economy.receiveIncome(sawmill);
economy.receiveIncome(quarry);

console.log(`Lumber quantity: ${lumber.getQuantity()}`); // 90
console.log(`Stone quantity: ${stone.getQuantity()}`); // 60
