// 2048-style game with countdown timer

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let boardSize = 4;
let tilePadding = 10;
let tileSize = 50;
let board = [];
let score = 0;
let gameOver = false;
let timer = 60; // countdown timer in seconds
let intervalId;

function resizeCanvas() {
  const scale = window.devicePixelRatio;
  canvas.width = window.innerWidth * scale;
  canvas.height = window.innerHeight * scale;
  ctx.scale(scale, scale);
  tileSize = Math.min(canvas.width, canvas.height) / (boardSize + 2);
  tilePadding = tileSize / 10;
  drawBoard();
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

function initBoard() {
  board = Array.from({ length: boardSize }, () => Array(boardSize).fill(null));
  addRandomTile();
  addRandomTile();
}

function addRandomTile() {
  let emptyCells = [];
  for (let row = 0; row < boardSize; row++) {
    for (let col = 0; col < boardSize; col++) {
      if (board[row][col] === null) {
        emptyCells.push({ row, col });
      }
    }
  }
  if (emptyCells.length > 0) {
    const { row, col } = emptyCells[Math.floor(Math.random() * emptyCells.length)];
    board[row][col] = Math.random() > 0.9 ? 4 : 2;
  }
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#bbada0';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  for (let row = 0; row < boardSize; row++) {
    for (let col = 0; col < boardSize; col++) {
      const tileValue = board[row][col];
      if (tileValue) {
        ctx.fillStyle = getTileColor(tileValue);
        ctx.fillRect(
          col * (tileSize + tilePadding) + tilePadding,
          row * (tileSize + tilePadding) + tilePadding,
          tileSize,
          tileSize
        );
        ctx.fillStyle = '#f9f6f2';
        ctx.font = `${Math.min(20, tileSize / 3)}px Arial`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(
          tileValue.toString(),
          col * (tileSize + tilePadding) + tileSize / 2 + tilePadding,
          row * (tileSize + tilePadding) + tileSize / 2 + tilePadding
        );
      }
    }
  }
}

function getTileColor(value) {
  const colors = [
    '#eee4da', '#ede0c8', '#f2b179', '#f59563', '#f67c5f', '#f65e3b', '#edcf72', '#edcc61', '#edc850', '#edc53f', '#edc22e'
  ];
  const log2Value = Math.log2(value);
  return colors[log2Value - 1] || '#3c3a32';
}

function handleKeyPress(event) {
  if (gameOver) return;
  let moved = false;
  switch (event.key) {
    case 'ArrowUp':
      moved = moveUp();
      break;
    case 'ArrowDown':
      moved = moveDown();
      break;
    case 'ArrowLeft':
      moved = moveLeft();
      break;
    case 'ArrowRight':
      moved = moveRight();
      break;
  }
  if (moved) {
    addRandomTile();
    checkGameOver();
  }
  drawBoard();
}

document.addEventListener('keydown', handleKeyPress);

function moveUp() {
  let moved = false;
  for (let col = 0; col < boardSize; col++) {
    let newRow = 0;
    for (let row = 1; row < boardSize; row++) {
      if (board[row][col] !== null) {
        if (board[newRow][col] === null || board[newRow][col] !== board[row][col]) {
          board[newRow][col] = board[row][col];
          if (newRow !== row) {
            board[row][col] = null;
            moved = true;
          }
          newRow++;
        } else if (board[newRow][col] === board[row][col]) {
          board[newRow][col] *= 2;
          board[row][col] = null;
          score += board[newRow][col];
          newRow++;
          moved = true;
        }
      }
    }
  }
  return moved;
}

function moveDown() {
  let moved = false;
  for (let col = 0; col < boardSize; col++) {
    let newRow = boardSize - 1;
    for (let row = boardSize - 2; row >= 0; row--) {
      if (board[row][col] !== null) {
        if (board[newRow][col] === null || board[newRow][col] !== board[row][col]) {
          board[newRow][col] = board[row][col];
          if (newRow !== row) {
            board[row][col] = null;
            moved = true;
          }
          newRow--;
        } else if (board[newRow][col] === board[row][col]) {
          board[newRow][col] *= 2;
          board[row][col] = null;
          score += board[newRow][col];
          newRow--;
          moved = true;
        }
      }
    }
  }
  return moved;
}

function moveLeft() {
  let moved = false;
  for (let row = 0; row < boardSize; row++) {
    let newCol = 0;
    for (let col = 1; col < boardSize; col++) {
      if (board[row][col] !== null) {
        if (board[row][newCol] === null || board[row][newCol] !== board[row][col]) {
          board[row][newCol] = board[row][col];
          if (newCol !== col) {
            board[row][col] = null;
            moved = true;
          }
          newCol++;
        } else if (board[row][newCol] === board[row][col]) {
          board[row][newCol] *= 2;
          board[row][col] = null;
          score += board[row][newCol];
          newCol++;
          moved = true;
        }
      }
    }
  }
  return moved;
}

function moveRight() {
  let moved = false;
  for (let row = 0; row < boardSize; row++) {
    let newCol = boardSize - 1;
    for (let col = boardSize - 2; col >= 0; col--) {
      if (board[row][col] !== null) {
        if (board[row][newCol] === null || board[row][newCol] !== board[row][col]) {
          board[row][newCol] = board[row][col];
          if (newCol !== col) {
            board[row][col] = null;
            moved = true;
          }
          newCol--;
        } else if (board[row][newCol] === board[row][col]) {
          board[row][newCol] *= 2;
          board[row][col] = null;
          score += board[row][newCol];
          newCol--;
          moved = true;
        }
      }
    }
  }
  return moved;
}

function checkGameOver() {
  for (let row = 0; row < boardSize; row++) {
    for (let col = 0; col < boardSize; col++) {
      if (board[row][col] === null) return;
      if (row > 0 && board[row][col] === board[row - 1][col]) return;
      if (row < boardSize - 1 && board[row][col] === board[row + 1][col]) return;
      if (col > 0 && board[row][col] === board[row][col - 1]) return;
      if (col < boardSize - 1 && board[row][col] === board[row][col + 1]) return;
    }
  }
  gameOver = true;
  clearInterval(intervalId);
  alert(`Game Over! Your score: ${score}`);
}

function startTimer() {
  intervalId = setInterval(() => {
    timer--;
    if (timer < 0) {
      clearInterval(intervalId);
      gameOver = true;
      alert(`Time's up! Your score: ${score}`);
    }
  }, 1000);
}

initBoard();
startTimer();
