class Building {
    constructor() {
        this.buildings = [];
    }

    build(type) {
        this.buildings.push(type);
        return `Built a ${type}`;
    }

    list() {
        return this.buildings.join(', ');
    }
}

class Resource {
    constructor() {
        this.resources = { food: 0, wood: 0, stone: 0 };
    }

    gather(type, amount) {
        if (this.resources[type] !== undefined) {
            this.resources[type] += amount;
            return `Gathered ${amount} ${type}`;
        } else {
            return `Invalid resource type: ${type}`;
        }
    }

    status() {
        return Object.entries(this.resources)
            .map(([resource, amount]) => `${resource}: ${amount}`)
            .join(', ');
    }
}

class Economy {
    constructor(buildingSystem, resourceSystem) {
        this.buildingSystem = buildingSystem;
        this.resourceSystem = resourceSystem;
    }

    upgrade(type, cost) {
        const sufficientResources = Object.entries(cost).every(([resource, amount]) => {
            return this.resourceSystem.resources[resource] >= amount;
        });

        if (sufficientResources) {
            Object.entries(cost).forEach(([resource, amount]) => {
                this.resourceSystem.resources[resource] -= amount;
            });
            return `Upgraded ${type}`;
        } else {
            return `Insufficient resources for ${type}`;
        }
    }
}

// Demo
