  constructor(eventBus, initialLevel = 100) {
    this.eventBus = eventBus;
    this.level = initialLevel;

    this.eventBus.subscribe('tick', this.decreaseHunger.bind(this));
    this.eventBus.subscribe('eat', this.increaseHunger.bind(this));
  }

  decreaseHunger() {
    if (this.level > 0) {
      this.level -= 1;
      console.log(`Hunger decreased to ${this.level}`);
    }
  }

  increaseHunger(amount = 10) {
    if (this.level + amount <= 100) {
      this.level += amount;
      console.log(`Hunger increased to ${this.level}`);
    }
  }
}

