    this.eventBus = eventBus;
    this.level = initialLevel;

    this.eventBus.subscribe('tick', this.decreaseEnergy.bind(this));
    this.eventBus.subscribe('rest', this.increaseEnergy.bind(this));
  }

  decreaseEnergy() {
    if (this.level > 0) {
      this.level -= 1;
      console.log(`Energy decreased to ${this.level}`);
    }
  }

  increaseEnergy(amount = 10) {
    if (this.level + amount <= 100) {
      this.level += amount;
