const canvas = document.createElement('canvas');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const damping = 0.7;
const particleCount = 20;
const fixedTimestep = 1000 / 60;
let lastTime = 0;

class Ball {
    constructor(x, y, radius) {
        this.x = x;
        this.y = y;
        this.radius = radius;
        this.velocityY = 0;
    }

    update(deltaTime) {
        this.velocityY += gravity * deltaTime;
        this.y += this.velocityY * deltaTime;
        if (this.y + this.radius >= canvas.height) {
            this.y = canvas.height - this.radius;
            this.velocityY *= -damping;
        }
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'blue';
        ctx.fill();
        ctx.closePath();
    }

    burstParticles() {
        for (let i = 0; i < particleCount; i++) {
            particles.push(new Particle(this.x, this.y, this.radius));
        }
    }
}

class Particle {
    constructor(x, y, size) {
        this.x = x;
        this.y = y;
        this.size = size;
        this.life = 100;
        this.alpha = 1;
        this.velocityX = (Math.random() - 0.5) * 5;
        this.velocityY = (Math.random() - 0.5) * 5;
    }

    update() {
        this.x += this.velocityX;
        this.y += this.velocityY;
        this.alpha -= 0.01;
        this.life--;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(0, 0, 255, ${this.alpha})`;
        ctx.fill();
        ctx.closePath();
    }
}

const ball = new Ball(canvas.width / 2, 50, 20);
const particles = [];

function update(timestamp) {
    const deltaTime = timestamp - lastTime;
    if (deltaTime >= fixedTimestep) {
        lastTime = timestamp;

        ctx.clearRect(0, 0, canvas.width, canvas.height);

        ball.update(deltaTime);
        ball.draw();

        if (ball.velocityY === 0) {
            ball.burstParticles();
        }

        particles.forEach((particle, index) => {
            if (particle.life > 0) {
                particle.update();
                particle.draw();
            } else {
                particles.splice(index, 1);
            }
        });

        requestAnimationFrame(update);
    }
}

requestAnimationFrame(update);
