    return this.balance;
  }

  deposit(amount) {
    this.balance += amount;
  }

  withdraw(amount) {
    if (amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Store {
  constructor(prices) {
    this.prices = prices;
  }

  getPrices() {
    return { ...this.prices };
  }

  getItemPrice(item) {
    return this.prices[item];
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  getItems() {
    return { ...this.items };
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }
}

class GameCoordinator {
