    const price = this.store.getItemPrice(item);
    if (price !== undefined && this.economy.withdraw(price)) {
      this.inventory.addItem(item);
      console.log(`Bought ${item}. Remaining balance: ${this.economy.getBalance()}`);
      return true;
    }
    console.log(`Failed to buy ${item}. Insufficient funds or item not available.`);
    return false;
  }

  sellItem(item) {
    const price = this.store.getItemPrice(item);
    if (price !== undefined && this.inventory.removeItem(item)) {
      this.economy.deposit(price);
      console.log(`Sold ${item}. New balance: ${this.economy.getBalance()}`);
      return true;
    }
    console.log(`Failed to sell ${item}. Item not in inventory.`);
    return false;
  }

  displayStatus() {
    console.log('Economy Balance:', this.economy.getBalance());
    console.log('Store Prices:', this.store.getPrices());
    console.log('Inventory Items:', this.inventory.getItems());
  }
}

