let direction = { x: 0, y: 0 };
let food = { x: Math.floor(Math.random() * gridCount), y: Math.floor(Math.random() * gridCount) };
let score = 0;
let particles = [];

const colors = ['#FF5733', '#33FFCE', '#335BFF', '#F333FF', '#FFD733'];
