function getRandomColor() {
  return colors[Math.floor(Math.random() * colors.length)];
}

function createParticle(x, y) {
  particles.push({ x, y, color: getRandomColor(), alpha: 1 });
}

function update() {
  const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

  if (head.x < 0 || head.x >= gridCount || head.y < 0 || head.y >= gridCount || snake.some(segment => segment.x === head.x && segment.y === head.y)) {
    resetGame();
    return;
  }

  snake.unshift(head);

  if (head.x === food.x && head.y === food.y) {
    score++;
    food = { x: Math.floor(Math.random() * gridCount), y: Math.floor(Math.random() * gridCount) };
    createParticle(head.x, head.y);
  } else {
    snake.pop();
  }

  particles = particles.filter(particle => particle.alpha > 0);

  particles.forEach(particle => particle.alpha -= 0.05);

  requestAnimationFrame(update);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'black';
  snake.forEach(segment => {
    ctx.fillRect(segment.x * gridSize, segment.y * gridSize, gridSize, gridSize);
  });

  ctx.fillStyle = 'red';
  ctx.fillRect(food.x * gridSize, food.y * gridSize, gridSize, gridSize);

  ctx.fillStyle = 'white';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);

