    ctx.fillStyle = `${particle.color} ${particle.alpha}`;
    ctx.fillRect(particle.x * gridSize, particle.y * gridSize, gridSize, gridSize);
  });

  requestAnimationFrame(draw);
}

function resetGame() {
  snake = [{ x: gridCount / 2, y: gridCount / 2 }];
  direction = { x: 0, y: 0 };
