```js
// Constants
const TILE_SIZE = 32;
const ROOM_WIDTH = 10;
const ROOM_HEIGHT = 10;
const WALL_CHAR = '#';
const FLOOR_CHAR = '.';
const PLAYER_CHAR = '@';
const ENEMY_CHAR = 'E';
const SCORE_INCREMENT = 10;
const GAME_OVER_TEXT = 'Game Over!';

// Game state
let canvas, ctx;
let room = [];
let playerPos = { x: 1, y: 1 };
let enemies = [];
let score = 0;
let gameOver = false;

// Initialize the game
function init() {
  canvas = document.createElement('canvas');
  document.body.appendChild(canvas);
  ctx = canvas.getContext('2d');

  // Handle devicePixelRatio for high-DPI screens
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  ctx.scale(dpr, dpr);

  // Set canvas size to fill the window
  canvas.width = ROOM_WIDTH * TILE_SIZE;
  canvas.height = ROOM_HEIGHT * TILE_SIZE;

  // Create the room layout
  for (let y = 0; y < ROOM_HEIGHT; y++) {
    let row = [];
    for (let x = 0; x < ROOM_WIDTH; x++) {
      if (x === 0 || x === ROOM_WIDTH - 1 || y === 0 || y === ROOM_HEIGHT - 1) {
        row.push(WALL_CHAR);
      } else {
        row.push(FLOOR_CHAR);
      }
    }
    room.push(row);
  }

  // Place enemies
  enemies.push({ x: 5, y: 5 });

  // Start the game loop
  requestAnimationFrame(gameLoop);
}

// Game loop
function gameLoop() {
  update();
  render();
  if (!gameOver) {
    requestAnimationFrame(gameLoop);
  }
}

// Update game state
function update() {
  // Player movement
  if (keys['ArrowUp'] && canMove(playerPos.x, playerPos.y - 1)) {
    playerPos.y--;
  } else if (keys['ArrowDown'] && canMove(playerPos.x, playerPos.y + 1)) {
    playerPos.y++;
  } else if (keys['ArrowLeft'] && canMove(playerPos.x - 1, playerPos.y)) {
    playerPos.x--;
  } else if (keys['ArrowRight'] && canMove(playerPos.x + 1, playerPos.y)) {
    playerPos.x++;
  }

  // Enemy movement
  enemies.forEach(enemy => {
    const dx = playerPos.x - enemy.x;
    const dy = playerPos.y - enemy.y;
    if (dx === 0 && dy === 0) {
      gameOver = true;
    } else if (Math.abs(dx) > Math.abs(dy)) {
      if (canMove(enemy.x + (dx > 0 ? 1 : -1), enemy.y)) {
        enemy.x += (dx > 0 ? 1 : -1);
      }
    } else {
      if (canMove(enemy.x, enemy.y + (dy > 0 ? 1 : -1))) {
        enemy.y += (dy > 0 ? 1 : -1);
      }
    }
  });

  // Check for enemy collisions
  enemies.forEach(enemy => {
    if (playerPos.x === enemy.x && playerPos.y === enemy.y) {
      gameOver = true;
    }
  });

  // Increment score for movement
  if (keys['ArrowUp'] || keys['ArrowDown'] || keys['ArrowLeft'] || keys['ArrowRight']) {
    score += SCORE_INCREMENT;
  }
}

// Render the game
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw the room
  room.forEach((row, y) => {
    row.forEach((tile, x) => {
      ctx.fillStyle = tile === WALL_CHAR ? '#000' : '#fff';
      ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    });
  });

  // Draw the player
  ctx.fillStyle = '#0f0';
  ctx.fillRect(playerPos.x * TILE_SIZE, playerPos.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);

  // Draw the enemies
  enemies.forEach(enemy => {
    ctx.fillStyle = '#f00';
    ctx.fillRect(enemy.x * TILE_SIZE, enemy.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
  });

  // Draw the score
  ctx.fillStyle = '#000';
  ctx.fillText(`Score: ${score}`, 10, 20);

  // Draw game over text if applicable
  if (gameOver) {
    ctx.font = '48px Arial';
    ctx.fillStyle = '#f00';
    ctx.textAlign = 'center';
    ctx.fillText(GAME_OVER_TEXT, canvas.width / 2, canvas.height / 2);
  }
}

// Check if a move is valid
function canMove(x, y) {
  return x >= 0 && x < ROOM_WIDTH && y >= 0 && y < ROOM_HEIGHT && room[y][x] !== WALL_CHAR;
}

// Key state tracking
const keys = {};
window.addEventListener('keydown', e => {
  keys[e.key] = true;
});
window.addEventListener('keyup', e => {
  keys[e.key] = false;
});

// Start the game
init();
