class Loot {
  constructor(name, value) {
    this.name = name;
    this.value = value;
  }
}

class RarityTable {
  constructor() {
    this.table = {
      common: 70,
      uncommon: 25,
      rare: 4,
      epic: 1
    };
  }

  getRandomLoot() {
    const roll = Math.random() * 100;
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.table)) {
      cumulativeProbability += probability;
      if (roll <= cumulativeProbability) {
        return new Loot(`Loot-${rarity}`, this.getLootValue(rarity));
      }
    }

    return new Loot("Loot-common", this.getLootValue("common"));
  }

  getLootValue(rarity) {
    const values = {
      common: 1,
      uncommon: 3,
      rare: 10,
      epic: 30
    };
    return values[rarity] || 1;
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  getItems() {
    return this.items;
  }
}

class Economy {
  constructor() {
    this.balance = 1000;
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Store {
  constructor(economy) {
    this.economy = economy;
    this.rarityTable = new RarityTable();
    this.inventory = new Inventory();
  }

  purchaseItem() {
    const item = this.rarityTable.getRandomLoot();
    const price = item.value;

    if (this.economy.debit(price)) {
      this.inventory.addItem(item);
      console.log(`Purchased ${item.name} for ${price}. Balance: ${this.economy.getBalance()}`);
    } else {
      console.log("Insufficient funds for purchase.");
    }
  }

  getInventory() {
    return this.inventory.getItems();
  }
}

// Demo
const economy = new Economy();
const store = new Store(economy);

store.purchaseItem();
store.purchaseItem();
store.purchaseItem();

console.log("Inventory:", store.getInventory());
