class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Economy {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('sellItem', ({ itemId, price }) => {
      this.balance += price;
      console.log(`Sold item ${itemId} for ${price}. New balance: ${this.balance}`);
    });
  }

  getBalance() {
    return this.balance;
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = [
      { id: '001', name: 'Sword', price: 50 },
      { id: '002', name: 'Shield', price: 30 },
      { id: '003', name: 'Potion', price: 10 }
    ];
    this.eventBus.subscribe('buyItem', itemId => {
      const item = this.items.find(i => i.id === itemId);
      if (item) {
        this.eventBus.emit('sellItem', { itemId, price: item.price });
        console.log(`Bought item ${itemId}: ${item.name} for ${item.price}`);
      } else {
        console.log(`Item ${itemId} not found.`);
      }
    });
  }

  listItems() {
    return this.items.map(item => `${item.id}: ${item.name} - ${item.price}`);
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = [];
    this.eventBus.subscribe('sellItem', ({ itemId, price }) => {
      const itemIndex = this.items.findIndex(i => i.id === itemId);
      if (itemIndex !== -1) {
        this.items.splice(itemIndex, 1);
        console.log(`Removed item ${itemId} from inventory.`);
      }
    });
  }

  addItem(item) {
    this.items.push(item);
    console.log(`Added item ${item.id}: ${item.name} to inventory.`);
  }

  getItems() {
    return this.items.map(item => `${item.id}: ${item.name}`);
  }
}

// Demo
