let score = 0;
let gameOver = false;
const fish = { x: 100, y: 100, width: 50, height: 50, speed: 2 };
const line = { x: 100, y: 100, length: 150, angle: 0 };

function resizeCanvas() {
  const dpr = window.devicePixelRatio || 1;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

function drawFish() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(fish.x, fish.y, fish.width, fish.height);
}

function drawLine() {
  ctx.beginPath();
  ctx.moveTo(line.x, line.y);
  ctx.lineTo(line.x + Math.cos(line.angle) * line.length, line.y + Math.sin(line.angle) * line.length);
  ctx.strokeStyle = 'brown';
  ctx.lineWidth = 3;
  ctx.stroke();
}

function drawScore() {
  ctx.font = '24px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 25);
}

function update() {
  if (gameOver) return;

  fish.x += fish.speed;
  if (fish.x > canvas.width + fish.width) {
    fish.x = -fish.width;
  }

  if (Math.abs(fish.x - line.x) < fish.width && Math.abs(fish.y - line.y) < fish.height) {
    score++;
    fish.x = -fish.width;
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawFish();
  drawLine();
  drawScore();
}

function gameLoop() {
  update();
  requestAnimationFrame(gameLoop);
}

function startGame() {
  gameOver = false;
  score = 0;
  gameLoop();
}

function endGame() {
  gameOver = true;
  ctx.font = '48px Arial';
  ctx.fillStyle = 'red';
  ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
}

