// Constants
const GROUND_HEIGHT = 50;
const BIRD_WIDTH = 30;
const BIRD_HEIGHT = 30;
const GAP_SIZE = 100;
const PIPE_WIDTH = 50;
const GRAVITY = 0.5;
const FLAP_STRENGTH = -10;
const PIPE_SPEED = 2;

// Variables
let bird;
let pipes = [];
let score = 0;
let highScore = localStorage.getItem('highScore') || 0;
let isGameOver = false;

// Canvas setup
const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
document.body.appendChild(canvas);
resizeCanvas();

function resizeCanvas() {
    const dpr = window.devicePixelRatio;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);
}

window.addEventListener('resize', resizeCanvas);
window.addEventListener('orientationchange', resizeCanvas);

// Bird class
class Bird {
    constructor() {
        this.x = 50;
        this.y = canvas.height / 2;
        this.velocity = 0;
    }

    update() {
        this.velocity += GRAVITY;
        this.y += this.velocity;
        if (this.y > canvas.height - GROUND_HEIGHT - BIRD_HEIGHT) {
            this.y = canvas.height - GROUND_HEIGHT - BIRD_HEIGHT;
            this.velocity = 0;
            if (!isGameOver) {
                checkCollision();
            }
        }
    }

    flap() {
        this.velocity = FLAP_STRENGTH;
    }

    draw() {
        ctx.fillStyle = 'yellow';
        ctx.fillRect(this.x, this.y, BIRD_WIDTH, BIRD_HEIGHT);
    }
}

// Pipe class
class Pipe {
    constructor(x) {
        this.x = x;
        this.height = Math.random() * (canvas.height - GAP_SIZE - GROUND_HEIGHT) + GROUND_HEIGHT;
    }

    update() {
        this.x -= PIPE_SPEED;
        if (this.x + PIPE_WIDTH < 0) {
            pipes.shift();
            score++;
            if (score > highScore) {
                highScore = score;
                localStorage.setItem('highScore', highScore);
            }
        }
    }

    draw() {
        ctx.fillStyle = 'green';
        ctx.fillRect(this.x, 0, PIPE_WIDTH, this.height);
        ctx.fillRect(this.x, this.height + GAP_SIZE, PIPE_WIDTH, canvas.height - this.height - GAP_SIZE);
    }
}

// Game initialization
function init() {
    bird = new Bird();
    pipes = [];
    score = 0;
    isGameOver = false;
}

// Collision detection
function checkCollision() {
    for (let pipe of pipes) {
        if (bird.x < pipe.x + PIPE_WIDTH &&
            bird.x + BIRD_WIDTH > pipe.x &&
            (bird.y < pipe.height || bird.y + BIRD_HEIGHT > pipe.height + GAP_SIZE)) {
            gameOver();
        }
    }
}

// Game over logic
function gameOver() {
    isGameOver = true;
    alert(`Game Over! Your score: ${score}. High score: ${highScore}`);
}

// Game loop
function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!isGameOver) {
        bird.update();
        bird.draw();

        if (pipes.length === 0 || pipes[pipes.length - 1].x < canvas.width - 200) {
            pipes.push(new Pipe(canvas.width));
        }

        for (let pipe of pipes) {
            pipe.update();
            pipe.draw();
        }
    }

    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`High Score: ${highScore}`, 10, 60);

    requestAnimationFrame(gameLoop);
}

// Start game
init();
gameLoop();

// Handle user input
window.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
        bird.flap();
    }
    if (e.code === 'Enter' && isGameOver) {
        init();
        gameLoop();
    }
});
