class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemCrafted', this.addItem.bind(this));
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
    console.log(`Inventory updated: Added ${item}. Total: ${this.items[item]}`);
  }

  hasItem(item, amount = 1) {
    return this.items[item] >= amount;
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
  }

  addRecipe(result, ingredients) {
    this.recipes[result] = ingredients;
  }

  canCraft(result) {
    const ingredients = this.recipes[result];
    if (!ingredients) return false;
    return Object.keys(ingredients).every(item => {
      return ingredients[item] <= this.eventBus.inventory.hasItem(item, ingredients[item]);
    });
  }

  craft(result) {
    if (this.canCraft(result)) {
      const ingredients = this.recipes[result];
      Object.keys(ingredients).forEach(item => {
        this.eventBus.inventory.addItem(item, -ingredients[item]);
      });
      this.eventBus.emit('itemCrafted', result);
      console.log(`Crafted ${result}`);
    } else {
      console.log(`Cannot craft ${result}`);
    }
  }
}

