class Entity {
  constructor(x, y, width, height, color) {
    this.x = x;
    this.y = y;
    this.width = width;
    this.height = height;
    this.color = color;
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

class Player extends Entity {
  constructor(x, y) {
    super(x, y, 32, 32, 'blue');
    this.velocityX = 0;
    this.velocityY = 0;
    this.jumpPower = -10;
    this.gravity = 0.5;
    this.onGround = false;
    this.controls = { left: false, right: false, jump: false };
  }

  update() {
    if (this.controls.left) this.velocityX = -5;
    else if (this.controls.right) this.velocityX = 5;
    else this.velocityX = 0;

    if (this.controls.jump && this.onGround) {
      this.velocityY = this.jumpPower;
      this.onGround = false;
    }

    this.velocityY += this.gravity;
    this.x += this.velocityX;
    this.y += this.velocityY;

    // Collision with ground
    if (this.y + this.height > canvas.height) {
      this.y = canvas.height - this.height;
      this.velocityY = 0;
      this.onGround = true;
    }
  }
}

class Platform extends Entity {
  constructor(x, y, width, height) {
    super(x, y, width, height, 'green');
  }
}

class PowerUp extends Entity {
