const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

const player = {
  x: 400,
  y: 300,
  width: 20,
  height: 20,
  speed: 5
};

const enemies = [];
const bullets = [];
const walls = [];

const tileSize = 40;
const mazeSize = 10;
const maze = generateMaze(mazeSize);

function generateMaze(size) {
  const maze = Array(size).fill().map(() => Array(size).fill(0));
  for (let i = 0; i < size; i++) {
    for (let j = 0; j < size; j++) {
      if (i === 0 || i === size - 1 || j === 0 || j === size - 1) {
        maze[i][j] = 1;
      } else if (Math.random() < 0.3) {
        maze[i][j] = 1;
      }
    }
  }
  return maze;
}

function spawnEnemies() {
  for (let i = 0; i < enemies.length; i++) {
    enemies[i].dead = true;
  }
  const count = Math.min(10, level * 2);
  for (let i = 0; i < count; i++) {
    const x = Math.random() * canvas.width;
    const y = Math.random() * canvas.height;
    enemies.push({ x, y, width: 15, height: 15, speed: 2 + level * 0.5, dead: false });
  }
}

let level = 1;
spawnEnemies();

function update() {
  if (player.dead) {
    ctx.fillStyle = 'red';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'black';
    ctx.font = '48px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    return;
  }

  const keys = {};
  document.addEventListener('keydown', (e) => keys[e.key] = true);
  document.addEventListener('keyup', (e) => keys[e.key] = false);

  let dx = 0, dy = 0;
  if (keys['ArrowUp'] || keys['w']) dy = -player.speed;
  if (keys['ArrowDown'] || keys['s']) dy = player.speed;
  if (keys['ArrowLeft'] || keys['a']) dx = -player.speed;
  if (keys['ArrowRight'] || keys['d']) dx = player.speed;

  if (dx !== 0 || dy !== 0) {
    const playerRect = { x: player.x + dx, y: player.y + dy, width: player.width, height: player.height };
    if (!collidesWithWalls(playerRect)) {
      player.x += dx;
      player.y += dy;
    }
  }

  if (keys[' ']) {
    bullets.push({ x: player.x + player.width / 2, y: player.y, width: 5, height: 5, speed: 10 });
  }

  enemies.forEach((enemy) => {
    if (enemy.dead) return;
    const enemyRect = { x: enemy.x, y: enemy.y, width: enemy.width, height: enemy.height };
    if (collidesWithWalls(enemyRect)) {
      enemy.speed *= -1;
    }
    enemy.x += enemy.speed;
    enemy.y += Math.sin(enemy.x / 10) * 3;
    if (collidesWithRects(enemyRect, bullets)) {
      enemy.dead = true;
    }
    if (collidesWithRects(enemyRect, [player])) {
      player.dead = true;
    }
  });

  bullets.forEach((bullet, index) => {
    bullet.y -= bullet.speed;
    if (bullet.y < 0) {
      bullets.splice(index, 1);
    }
  });

  if (enemies.every((enemy) => enemy.dead)) {
    level++;
    spawnEnemies();
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'gray';
  maze.forEach((row, i) => {
    row.forEach((cell, j) => {
      if (cell === 1) {
        ctx.fillRect(j * tileSize, i * tileSize, tileSize, tileSize);
      }
    });
  });

  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);

  ctx.fillStyle = 'red';
  enemies.forEach((enemy) => {
    if (!enemy.dead) {
      ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
    }
  });

  ctx.fillStyle = 'green';
  bullets.forEach((bullet) => {
    ctx.fillRect(bullet.x, bullet.y, bullet.width, bullet.height);
  });
}

function collidesWithWalls(rect) {
  for (let i = 0; i < maze.length; i++) {
    for (let j = 0; j < maze[i].length; j++) {
      if (maze[i][j] === 1) {
        const wallRect = { x: j * tileSize, y: i * tileSize, width: tileSize, height: tileSize };
        if (collidesWithRects(rect, [wallRect])) {
          return true;
        }
      }
    }
  }
  return false;
}

function collidesWithRects(rect1, rects) {
  return rects.some((rect2) => (
    rect1.x < rect2.x + rect2.width &&
    rect1.x + rect1.width > rect2.x &&
    rect1.y < rect2.y + rect2.height &&
    rect1.y + rect1.height > rect2.y
  ));
}

function mainLoop() {
  const now = Date.now();
  const dt = now - lastTime;
  lastTime = now;

  update();
  render();

  setTimeout(mainLoop, 16);
}

let lastTime = Date.now();
mainLoop();
