class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Wallet {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('purchaseMade', this.onPurchaseMade.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}. Current balance: ${this.balance}`);
  }

  withdraw(amount) {
    if (amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. Current balance: ${this.balance}`);
      return true;
    } else {
      console.log(`Insufficient funds. Current balance: ${this.balance}`);
      return false;
    }
  }

  onPurchaseMade(data) {
    if (this.withdraw(data.amount)) {
      this.eventBus.emit('purchaseCompleted', { item: data.item });
    }
  }
