// Building System
class Building {
    constructor(name, resourceCosts = {}, economy) {
        this.name = name;
        this.resourceCosts = resourceCosts;
        this.economy = economy;
    }

    build() {
        if (this.economy.canAfford(this.resourceCosts)) {
            this.economy.deductResources(this.resourceCosts);
            console.log(`Built ${this.name}`);
            return true;
        } else {
            console.log(`Cannot build ${this.name}: Insufficient resources`);
            return false;
        }
    }
}

// Resource System
class Resource {
    constructor(name, amount = 0) {
        this.name = name;
        this.amount = amount;
    }

    add(amount) {
        this.amount += amount;
        console.log(`Added ${amount} ${this.name}`);
    }

    deduct(amount) {
        if (this.amount >= amount) {
            this.amount -= amount;
            console.log(`Deducted ${amount} ${this.name}`);
            return true;
        } else {
            console.log(`Cannot deduct ${amount} ${this.name}: Insufficient resources`);
            return false;
        }
    }

    getAmount() {
        return this.amount;
    }
}

// Economy System
class Economy {
    constructor(resources = {}) {
        this.resources = Object.keys(resources).reduce((acc, key) => {
            acc[key] = new Resource(key, resources[key]);
            return acc;
        }, {});
    }

    addResource(name, amount) {
        if (this.resources[name]) {
            this.resources[name].add(amount);
        } else {
            this.resources[name] = new Resource(name, amount);
            console.log(`Added new resource ${name} with amount ${amount}`);
        }
    }

    deductResources(costs) {
        for (const [resourceName, amount] of Object.entries(costs)) {
            if (!this.resources[resourceName] || !this.resources[resourceName].deduct(amount)) {
                console.log(`Failed to deduct ${amount} of ${resourceName}`);
                return false;
            }
        }
        console.log(`Deducted resources for construction`);
        return true;
    }

    canAfford(costs) {
        for (const [resourceName, amount] of Object.entries(costs)) {
            if (!this.resources[resourceName] || this.resources[resourceName].getAmount() < amount) {
                return false;
            }
        }
        return true;
    }
}

