let snake = [{ x: 10, y: 10 }];
let direction = { x: 0, y: 0 };
let food = { x: 15, y: 15 };
let score = 0;
let state = 'menu';

function getRandomFoodPosition() {
    return {
        x: Math.floor(Math.random() * grid),
        y: Math.floor(Math.random() * grid)
    };
}

function drawRect(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x * tile, y * tile, tile, tile);
}

function drawSnake() {
    snake.forEach(segment => drawRect(segment.x, segment.y, 'lime'));
}

function drawFood() {
    drawRect(food.x, food.y, 'red');
}

function drawScore() {
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 20);
}

function updateSnake() {
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };
    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
        score++;
        food = getRandomFoodPosition();
    } else {
        snake.pop();
    }

    if (head.x < 0 || head.x >= grid || head.y < 0 || head.y >= grid || snake.some(segment => segment.x === head.x && segment.y === head.y)) {
        state = 'gameover';
    }
}

function handleInput(event) {
    const keyPressed = event.key;
    const goingUp = direction.y === -1;
    const goingDown = direction.y === 1;
    const goingRight = direction.x === 1;
    const goingLeft = direction.x === -1;

    if (keyPressed === 'ArrowUp' && !goingDown) {
        direction = { x: 0, y: -1 };
    }
    if (keyPressed === 'ArrowDown' && !goingUp) {
        direction = { x: 0, y: 1 };
    }
    if (keyPressed === 'ArrowRight' && !goingLeft) {
        direction = { x: 1, y: 0 };
    }
    if (keyPressed === 'ArrowLeft' && !goingRight) {
        direction = { x: -1, y: 0 };
    }
    if (keyPressed === 'Enter' && state === 'menu') {
        state = 'playing';
    }
    if (keyPressed === 'Enter' && state === 'gameover') {
        state = 'menu';
        snake = [{ x: 10, y: 10 }];
        direction = { x: 0, y: 0 };
        food = { x: 15, y: 15 };
        score = 0;
    }
}

function renderMenu() {
    ctx.fillStyle = 'black';
    ctx.font = '30px Arial';
    ctx.fillText('Snake Game', 80, 200);
    ctx.font = '20px Arial';
    ctx.fillText('Press Enter to Start', 100, 250);
}

function renderGameOver() {
    ctx.fillStyle = 'black';
    ctx.font = '30px Arial';
    ctx.fillText('Game Over', 100, 200);
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 130, 250);
    ctx.fillText('Press Enter to Restart', 80, 300);
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (state === 'playing') {
        drawSnake();
        drawFood();
        drawScore();
    } else if (state === 'menu') {
        renderMenu();
    } else if (state === 'gameover') {
        renderGameOver();
    }
}

function update() {
    if (state === 'playing') {
        updateSnake();
    }
}

const fixedTimestep = 1000 / 10; // 10 frames per second
let lastTime = 0;

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    if (deltaTime >= fixedTimestep) {
        lastTime = timestamp - (deltaTime % fixedTimestep);
        update();
        render();
    }
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', handleInput);
gameLoop();
