```js
// Breakout Game with Finite State Machine

// Constants
const CANVAS_WIDTH = 480;
const CANVAS_HEIGHT = 320;
const BALL_SIZE = 10;
const PADDLE_WIDTH = 60;
const PADDLE_HEIGHT = 10;
const BRICK_WIDTH = 40;
const BRICK_HEIGHT = 20;
const BRICK_ROWS = 5;
const BRICK_COLS = 12;
const PADDLE_SPEED = 4;
const BALL_SPEED = 3;
const FIXED_TIMESTEP = 1000 / 60; // 60 FPS

// State
let gameState = 'menu';
let lastTime = 0;
let paddle = { x: CANVAS_WIDTH / 2 - PADDLE_WIDTH / 2, y: CANVAS_HEIGHT - PADDLE_HEIGHT - 10, dx: 0 };
let ball = { x: CANVAS_WIDTH / 2, y: CANVAS_HEIGHT / 2, dx: BALL_SPEED, dy: -BALL_SPEED };
let bricks = [];
let score = 0;
let highScore = 0;

// Initialize bricks
function initBricks() {
    bricks = [];
    for (let row = 0; row < BRICK_ROWS; row++) {
        for (let col = 0; col < BRICK_COLS; col++) {
            bricks.push({
                x: col * BRICK_WIDTH,
                y: row * BRICK_HEIGHT,
                width: BRICK_WIDTH,
                height: BRICK_HEIGHT,
                alive: true
            });
        }
    }
}

// Canvas setup
const canvas = document.createElement('canvas');
canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Input
document.addEventListener('keydown', (e) => {
    if (gameState === 'playing') {
        if (e.key === 'ArrowLeft') paddle.dx = -PADDLE_SPEED;
        if (e.key === 'ArrowRight') paddle.dx = PADDLE_SPEED;
    }
    if (e.key === 'Enter') {
        if (gameState === 'menu' || gameState === 'gameover') {
            gameState = 'playing';
            initBricks();
            score = 0;
            ball.x = CANVAS_WIDTH / 2;
            ball.y = CANVAS_HEIGHT / 2;
            ball.dx = BALL_SPEED;
            ball.dy = -BALL_SPEED;
        } else if (gameState === 'paused') {
            gameState = 'playing';
        }
    }
    if (e.key === 'Escape') {
        if (gameState === 'playing') gameState = 'paused';
    }
});
document.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') paddle.dx = 0;
});

// Game logic
function update(dt) {
    if (gameState === 'playing') {
        // Update paddle
        paddle.x += paddle.dx * dt;
        if (paddle.x < 0) paddle.x = 0;
        if (paddle.x > CANVAS_WIDTH - PADDLE_WIDTH) paddle.x = CANVAS_WIDTH - PADDLE_WIDTH;

        // Update ball
        ball.x += ball.dx * dt;
        ball.y += ball.dy * dt;

        // Ball collision with walls
        if (ball.x < 0 || ball.x > CANVAS_WIDTH - BALL_SIZE) ball.dx = -ball.dx;
        if (ball.y < 0) ball.dy = -ball.dy;

        // Ball collision with paddle
        if (ball.y + BALL_SIZE > paddle.y && ball.x > paddle.x && ball.x < paddle.x + PADDLE_WIDTH) {
            ball.dy = -ball.dy;
            ball.y = paddle.y - BALL_SIZE;
        }

        // Ball collision with bricks
        for (let i = 0; i < bricks.length; i++) {
            const brick = bricks[i];
            if (brick.alive && ball.x + BALL_SIZE > brick.x && ball.x < brick.x + brick.width &&
                ball.y + BALL_SIZE > brick.y && ball.y < brick.y + brick.height) {
                brick.alive = false;
                ball.dy = -ball.dy;
                score++;
                highScore = Math.max(highScore, score);
            }
        }

        // Ball collision with bottom wall (game over)
        if (ball.y > CANVAS_HEIGHT) {
            gameState = 'gameover';
        }
    }
}

// Render
function render() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Render paddle
    ctx.fillStyle = 'blue';
    ctx.fillRect(paddle.x, paddle.y, PADDLE_WIDTH, PADDLE_HEIGHT);

    // Render ball
    ctx.fillStyle = 'red';
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, BALL_SIZE, 0, Math.PI * 2);
    ctx.fill();

    // Render bricks
    ctx.fillStyle = 'green';
    for (let i = 0; i < bricks.length; i++) {
        const brick = bricks[i];
        if (brick.alive) {
            ctx.fillRect(brick.x, brick.y, brick.width, brick.height);
        }
    }

    // Render text
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    if (gameState === 'menu') {
        ctx.fillText('Press Enter to Start', CANVAS_WIDTH / 2 - 100, CANVAS_HEIGHT / 2);
    } else if (gameState === 'playing') {
        ctx.fillText(`Score: ${score}`, 10, 20);
    } else if (gameState === 'paused') {
        ctx.fillText('Paused', CANVAS_WIDTH / 2 - 30, CANVAS_HEIGHT / 2);
        ctx.fillText('Press Enter to Resume', CANVAS_WIDTH / 2 - 100, CANVAS_HEIGHT / 2 + 30);
    } else if (gameState === 'gameover') {
        ctx.fillText('Game Over', CANVAS_WIDTH / 2 - 50, CANVAS_HEIGHT / 2);
        ctx.fillText(`Score: ${score}`, CANVAS_WIDTH / 2 - 30, CANVAS_HEIGHT / 2 + 30);
        ctx.fillText(`High Score: ${highScore}`, CANVAS_WIDTH / 2 - 50, CANVAS_HEIGHT / 2 + 60);
        ctx.fillText('Press Enter to Restart', CANVAS_WIDTH / 2 - 100, CANVAS_HEIGHT / 2 + 90);
    }
}

// Main loop
function gameLoop(timestamp) {
    const dt = timestamp - lastTime;
    if (dt >= FIXED_TIMESTEP) {
        lastTime = timestamp;
        update(FIXED_TIMESTEP);
        render();
    }
    requestAnimationFrame(gameLoop);
}

// Start the game loop
requestAnimationFrame(gameLoop);
