class Loot {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('generateLoot', this.generate.bind(this));
  }

  generate() {
    const lootItem = this.createLootItem();
    console.log(`Generated Loot: ${lootItem.name} (Rarity: ${lootItem.rarity})`);
    this.eventBus.emit('lootGenerated', lootItem);
  }

  createLootItem() {
    return {
      name: `Item${Math.floor(Math.random() * 100)}`,
      rarity: this.getRarity()
    };
  }

