        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (quantity > 0) {
            this.items[item] = (this.items[item] || 0) + quantity;
            return true;
        }
        return false;
    }

    getInventory() {
        return this.items;
    }
}

