// Event Bus Implementation
class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

// Hunger System
class Hunger {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.hungerLevel = 50;
    this.eventBus.subscribe('eat', () => this.decreaseHunger());
  }

  decreaseHunger(amount = 10) {
    this.hungerLevel = Math.max(0, this.hungerLevel - amount);
    this.eventBus.emit('hungerLevelChanged', this.hungerLevel);
  }

  getHungerLevel() {
    return this.hungerLevel;
  }
}

// Energy System
class Energy {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.energyLevel = 50;
    this.eventBus.subscribe('rest', () => this.increaseEnergy());
    this.eventBus.subscribe('hungerLevelChanged', (hungerLevel) => {
      if (hungerLevel > 70) {
        this.increaseEnergy();
      }
    });
  }

  increaseEnergy(amount = 10) {
    this.energyLevel = Math.min(100, this.energyLevel + amount);
    this.eventBus.emit('energyLevelChanged', this.energyLevel);
  }

  getEnergyLevel() {
    return this.energyLevel;
  }
}

// Clock System
class Clock {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.time = 0;
    setInterval(() => this.tick(), 1000);
  }

  tick() {
    this.time++;
    this.eventBus.emit('timePassed', this.time);
    if (this.time % 10 === 0) {
      this.eventBus.emit('eat');
    }
    if (this.time % 15 === 0) {
      this.eventBus.emit('rest');
    }
  }

  getTime() {
    return this.time;
  }
}

