// Maze Chase Game with Basic AI Opponent

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.style.position = 'absolute';
canvas.style.top = '0';
canvas.style.left = '0';
canvas.style.width = '100%';
canvas.style.height = '100%';
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio || 1;
let windowWidth = window.innerWidth;
let windowHeight = window.innerHeight;
canvas.width = windowWidth * dpr;
canvas.height = windowHeight * dpr;
ctx.scale(dpr, dpr);

const mazeWidth = 20;
const mazeHeight = 20;
const cellSize = Math.min(windowWidth, windowHeight) / 20;

const player = { x: 0, y: 0, dx: 0, dy: 0, speed: 2 };
const ai = { x: mazeWidth - 1, y: mazeHeight - 1, speed: 1 };
let walls = [];

function createMaze() {
    for (let y = 0; y < mazeHeight; y++) {
        for (let x = 0; x < mazeWidth; x++) {
            if (x === 0 || y === 0 || x === mazeWidth - 1 || y === mazeHeight - 1 ||
                (x % 2 === 0 && y % 2 === 0)) {
                walls.push({ x, y });
            }
        }
    }
}

function drawMaze() {
    ctx.fillStyle = 'black';
    walls.forEach(wall => {
        ctx.fillRect(wall.x * cellSize, wall.y * cellSize, cellSize, cellSize);
    });
}

function drawPlayer() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x * cellSize, player.y * cellSize, cellSize, cellSize);
}

function drawAI() {
    ctx.fillStyle = 'red';
    ctx.fillRect(ai.x * cellSize, ai.y * cellSize, cellSize, cellSize);
}

function checkCollision(obj, walls) {
    return walls.some(wall => wall.x === obj.x && wall.y === obj.y);
}

function movePlayer() {
    let newX = player.x + player.dx;
    let newY = player.y + player.dy;
    if (!checkCollision({ x: newX, y: newY }, walls)) {
        player.x = newX;
        player.y = newY;
    }
    player.dx = 0;
    player.dy = 0;
}

function moveAI() {
    let direction = Math.floor(Math.random() * 4);
    switch (direction) {
        case 0: ai.dy = ai.y > 0 && !checkCollision({ x: ai.x, y: ai.y - 1 }, walls) ? -1 : 0; break;
        case 1: ai.dx = ai.x < mazeWidth - 1 && !checkCollision({ x: ai.x + 1, y: ai.y }, walls) ? 1 : 0; break;
        case 2: ai.dy = ai.y < mazeHeight - 1 && !checkCollision({ x: ai.x, y: ai.y + 1 }, walls) ? 1 : 0; break;
        case 3: ai.dx = ai.x > 0 && !checkCollision({ x: ai.x - 1, y: ai.y }, walls) ? -1 : 0; break;
    }
    ai.x += ai.dx;
    ai.y += ai.dy;
}

function update() {
    movePlayer();
    moveAI();
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawMaze();
    drawPlayer();
    drawAI();
    if (player.x === ai.x && player.y === ai.y) {
        alert('Game Over!');
        document.location.reload();
    }
    requestAnimationFrame(update);
}

function handleKeyDown(event) {
    switch (event.key) {
        case 'ArrowUp': player.dy = -1; break;
        case 'ArrowDown': player.dy = 1; break;
        case 'ArrowLeft': player.dx = -1; break;
        case 'ArrowRight': player.dx = 1; break;
    }
}

createMaze();
document.addEventListener('keydown', handleKeyDown);
update();
