class Recipe {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.recipes = {};
    }

    addRecipe(item, ingredients) {
        this.recipes[item] = ingredients;
    }

    canCraft(item, inventory) {
        const ingredients = this.recipes[item];
        if (!ingredients) return false;
        for (const [ingredient, amount] of Object.entries(ingredients)) {
            if (inventory[ingredient] < amount) return false;
        }
        return true;
    }

    craft(item) {
        if (this.canCraft(item, this.eventBus.emit('getInventory'))) {
            const ingredients = this.recipes[item];
            const inventory = { ...this.eventBus.emit('getInventory') };
            for (const [ingredient, amount] of Object.entries(ingredients)) {
                inventory[ingredient] -= amount;
            }
            this.eventBus.emit('setInventory', inventory);
            this.eventBus.emit('addItem', item);
            return true;
        }
        return false;
    }
}

