    addFunds(amount) {
        this.balance += amount;
        this.eventBus.emit('balanceChanged', { balance: this.balance });
    }

    handlePurchase(data) {
        if (this.balance >= data.price) {
            this.balance -= data.price;
            this.eventBus.emit('purchaseSuccess', { item: data.item });
            this.eventBus.emit('balanceChanged', { balance: this.balance });
        } else {
            this.eventBus.emit('purchaseFailure', { item: data.item, reason: 'Insufficient funds' });
        }
    }
}

