// Constants
const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;

const GRAVITY = 980;
const JUMP_STRENGTH = -400;
const PLAYER_WIDTH = 50;
const PLAYER_HEIGHT = 50;
const PLATFORM_WIDTH = 200;
const PLATFORM_HEIGHT = 20;
const FIXED_TIMESTEP = 1 / 60; // 60 FPS
const MAX_FRAMESKIP = 5;

let lastTime = performance.now();
let accumulator = 0;
let score = 0;

// Player
let player = {
    x: 50,
    y: canvas.height - PLAYER_HEIGHT - 10,
    width: PLAYER_WIDTH,
    height: PLAYER_HEIGHT,
    velocityX: 0,
    velocityY: 0,
    onGround: false
};

// Platforms
let platforms = [
    { x: 200, y: 500, width: PLATFORM_WIDTH, height: PLATFORM_HEIGHT },
    { x: 600, y: 400, width: PLATFORM_WIDTH, height: PLATFORM_HEIGHT },
    { x: 1000, y: 300, width: PLATFORM_WIDTH, height: PLATFORM_HEIGHT }
];

// Game state
let gameRunning = true;

// Input
let rightPressed = false;
let leftPressed = false;
let upPressed = false;

document.addEventListener('keydown', keyDownHandler, false);
document.addEventListener('keyup', keyUpHandler, false);

function keyDownHandler(e) {
    if (e.key === 'Right' || e.key === 'ArrowRight') {
        rightPressed = true;
    } else if (e.key === 'Left' || e.key === 'ArrowLeft') {
        leftPressed = true;
    } else if (e.key === 'Up' || e.key === 'ArrowUp') {
        upPressed = true;
    }
}

function keyUpHandler(e) {
    if (e.key === 'Right' || e.key === 'ArrowRight') {
        rightPressed = false;
    } else if (e.key === 'Left' || e.key === 'ArrowLeft') {
        leftPressed = false;
    } else if (e.key === 'Up' || e.key === 'ArrowUp') {
        upPressed = false;
    }
}

// Physics and game logic
function update(deltaTime) {
    if (!gameRunning) return;

    // Player movement
    if (rightPressed) {
        player.velocityX = 200;
    } else if (leftPressed) {
        player.velocityX = -200;
    } else {
        player.velocityX = 0;
    }

    // Jump
    if (upPressed && player.onGround) {
        player.velocityY = JUMP_STRENGTH;
        player.onGround = false;
    }

    // Apply gravity
    player.velocityY += GRAVITY * deltaTime;
    player.x += player.velocityX * deltaTime;
    player.y += player.velocityY * deltaTime;

    // Collision detection with platforms
    player.onGround = false;
    platforms.forEach(platform => {
        if (player.x < platform.x + platform.width &&
            player.x + player.width > platform.x &&
            player.y < platform.y + platform.height &&
            player.y + player.height > platform.y) {
            player.onGround = true;
            player.velocityY = 0;
            player.y = platform.y - player.height;
        }
    });

    // Scoring
    score += deltaTime * 10; // Simple scoring system

    // Game over
    if (player.y > canvas.height) {
        gameRunning = false;
    }
}

// Rendering
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw player
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Draw platforms
    ctx.fillStyle = 'green';
    platforms.forEach(platform => {
        ctx.fillRect(platform.x, platform.y, platform.width, platform.height);
    });

    // Draw score
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText('Score: ' + Math.floor(score), 10, 30);

    // Game over message
    if (!gameRunning) {
        ctx.fillStyle = 'red';
        ctx.font = '40px Arial';
        ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
    }
}

// Main loop
function gameLoop(currentTime) {
    let deltaTime = (currentTime - lastTime) / 1000;
    lastTime = currentTime;

    accumulator += deltaTime;

    let framesSkipped = 0;
    while (accumulator >= FIXED_TIMESTEP && framesSkipped < MAX_FRAMESKIP) {
        update(FIXED_TIMESTEP);
        accumulator -= FIXED_TIMESTEP;
        framesSkipped++;
    }

    draw();

    if (gameRunning) {
        requestAnimationFrame(gameLoop);
    }
}

// Start the game
requestAnimationFrame(gameLoop);
