class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }

  emit(event, payload) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(payload));
    }
  }
}

class Quest {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('questCompleted', this.onQuestCompleted.bind(this));
  }

  startQuest(questId) {
    console.log(`Quest ${questId} started.`);
    // Simulate quest completion after a delay
    setTimeout(() => {
      this.eventBus.emit('questCompleted', { questId });
    }, 1000);
  }

  onQuestCompleted({ questId }) {
    console.log(`Quest ${questId} completed!`);
  }
}

class Reward {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('questCompleted', this.onQuestCompleted.bind(this));
  }

  onQuestCompleted({ questId }) {
    console.log(`Rewarding player for completing quest ${questId}.`);
    // Simulate granting a reward
    const reward = `Treasure of ${questId}`;
    this.eventBus.emit('rewardGranted', { reward });
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('rewardGranted', this.onRewardGranted.bind(this));
    this.items = [];
  }

  onRewardGranted({ reward }) {
    console.log(`Adding ${reward} to inventory.`);
    this.items.push(reward);
    console.log(`Inventory now contains: ${this.items.join(', ')}`);
  }
}

