                const angle = Math.atan2(mouseY - player.y, mouseX - player.x);
                bullet.dx = Math.cos(angle) * bullet.speed;
                bullet.dy = Math.sin(angle) * bullet.speed;
            }
            break;
    }
});

canvas.addEventListener('keyup', (e) => {
