class Wallet {
  constructor(initialAmount = 0) {
    this.balance = initialAmount;
  }

  addMoney(amount) {
    this.balance += amount;
  }

  removeMoney(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Shop {
  constructor(items = {}) {
    this.items = items; // { itemName: price }
  }

  getPrice(itemName) {
    return this.items[itemName];
  }

  hasItem(itemName) {
    return itemName in this.items;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(itemName, quantity = 1) {
    if (itemName in this.items) {
      this.items[itemName] += quantity;
    } else {
      this.items[itemName] = quantity;
    }
  }

  removeItem(itemName, quantity = 1) {
    if (itemName in this.items && this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
      return true;
    }
    return false;
  }

  getItemCount(itemName) {
    return this.items[itemName] || 0;
  }
}

class GameCoordinator {
  constructor(wallet, shop, inventory) {
    this.wallet = wallet;
    this.shop = shop;
    this.inventory = inventory;
  }

  buyItem(itemName) {
    const price = this.shop.getPrice(itemName);
    if (this.shop.hasItem(itemName) && this.wallet.removeMoney(price)) {
      this.inventory.addItem(itemName);
      console.log(`Bought ${itemName}. Wallet balance: ${this.wallet.getBalance()}, Inventory:`, this.inventory.items);
      return true;
    }
    console.log(`Could not buy ${itemName}.`);
    return false;
  }

  sellItem(itemName) {
    const price = this.shop.getPrice(itemName);
    if (this.inventory.removeItem(itemName) && price > 0) {
      this.wallet.addMoney(price);
      console.log(`Sold ${itemName}. Wallet balance: ${this.wallet.getBalance()}, Inventory:`, this.inventory.items);
      return true;
    }
    console.log(`Could not sell ${itemName}.`);
    return false;
  }
}

