// Ball Drop Game with Health Bar and Respawn

const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);

const ctx = canvas.getContext('2d');

const gravity = 0.5;
const maxFallSpeed = 10;
const initialHealth = 100;
const healthBarWidth = 200;
const healthBarHeight = 20;
const ballSize = 20;
const player = {
  x: canvas.width / 2 - ballSize / 2,
  y: 100,
  vy: 0,
  health: initialHealth
};

function drawHealthBar() {
  ctx.fillStyle = 'red';
  ctx.fillRect(10, 10, healthBarWidth, healthBarHeight);
  ctx.fillStyle = 'green';
  ctx.fillRect(10, 10, (player.health / initialHealth) * healthBarWidth, healthBarHeight);
}

function drawBall() {
  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(player.x + ballSize / 2, player.y + ballSize / 2, ballSize / 2, 0, Math.PI * 2);
  ctx.fill();
}

function update() {
  player.vy += gravity;
  player.vy = Math.min(player.vy, maxFallSpeed);
  player.y += player.vy;

  if (player.y + ballSize > canvas.height) {
    player.y = canvas.height - ballSize;
    player.vy = -player.vy * 0.8; // Bounce with some energy loss
    player.health -= 10; // Reduce health on impact
  }

  if (player.health <= 0) {
    respawn();
  }
}

function respawn() {
  player.health = initialHealth;
  player.y = 100;
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawHealthBar();
  drawBall();
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

gameLoop();
