  { x: 100, y: 500, width: blockWidth, height: blockHeight },
  { x: 300, y: 400, width: blockWidth, height: blockHeight },
  { x: 500, y: 300, width: blockWidth, height: blockHeight },
  { x: 700, y: 200, width: blockWidth, height: blockHeight }
];

let keys = {
  right: false,
  left: false,
  space: false
};

function drawPlayer() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);
}

function drawBlocks() {
  ctx.fillStyle = 'red';
  blocks.forEach(block => {
    ctx.fillRect(block.x, block.y, block.width, block.height);
  });
}

function drawHealthBar() {
  ctx.fillStyle = 'green';
  ctx.fillRect(10, 10, player.health * 50, 20);
}

function movePlayer() {
  if (keys.right) player.x += playerSpeed;
  if (keys.left) player.x -= playerSpeed;
  player.velocityY += gravity;
  player.y += player.velocityY;

  if (player.y + player.height > canvas.height) {
    player.y = canvas.height - player.height;
    player.velocityY = 0;
  }
}

function checkCollision() {
  blocks.forEach(block => {
    if (
      player.x < block.x + block.width &&
      player.x + player.width > block.x &&
      player.y < block.y + block.height &&
      player.y + player.height > block.y
    ) {
      player.y = block.y - player.height;
      player.velocityY = 0;
    }
  });
}

function respawnPlayer() {
  player = {
    x: canvas.width / 2,
    y: canvas.height - playerHeight,
    width: playerWidth,
    height: playerHeight,
    velocityY: 0,
    health: player.health - 1
  };
