const TILE_SIZE = 32;
const ROOM_WIDTH = 8;
const ROOM_HEIGHT = 8;

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);

const ctx = canvas.getContext('2d');

let lastTime = 0;
let playerX = ROOM_WIDTH / 2;
let playerY = ROOM_HEIGHT / 2;
let movement = { x: 0, y: 0 };

const keys = {
  ArrowUp: false,
  ArrowDown: false,
  ArrowLeft: false,
  ArrowRight: false
};

document.addEventListener('keydown', (e) => {
  keys[e.key] = true;
});

document.addEventListener('keyup', (e) => {
  keys[e.key] = false;
});

document.addEventListener('mousemove', (e) => {
  const rect = canvas.getBoundingClientRect();
  const scaleX = canvas.width / rect.width;
  const scaleY = canvas.height / rect.height;
  playerX = (e.clientX - rect.left) * scaleX / TILE_SIZE;
  playerY = (e.clientY - rect.top) * scaleY / TILE_SIZE;
});

document.addEventListener('click', (e) => {
  const rect = canvas.getBoundingClientRect();
  const scaleX = canvas.width / rect.width;
  const scaleY = canvas.height / rect.height;
  playerX = Math.floor((e.clientX - rect.left) * scaleX / TILE_SIZE);
  playerY = Math.floor((e.clientY - rect.top) * scaleY / TILE_SIZE);
});

function update(dt) {
  movement.x = 0;
  movement.y = 0;

  if (keys.ArrowUp) movement.y = -1;
  if (keys.ArrowDown) movement.y = 1;
  if (keys.ArrowLeft) movement.x = -1;
  if (keys.ArrowRight) movement.x = 1;

  playerX += movement.x * dt * 2;
  playerY += movement.y * dt * 2;

  playerX = Math.max(0, Math.min(ROOM_WIDTH - 1, playerX));
  playerY = Math.max(0, Math.min(ROOM_HEIGHT - 1, playerY));
}

function render() {
  const dpr = window.devicePixelRatio || 1;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  for (let y = 0; y < ROOM_HEIGHT; y++) {
    for (let x = 0; x < ROOM_WIDTH; x++) {
      ctx.fillStyle = '#444';
      ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);

      ctx.strokeStyle = '#fff';
      ctx.strokeRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    }
  }

  ctx.fillStyle = '#0f0';
  ctx.fillRect(Math.floor(playerX) * TILE_SIZE, Math.floor(playerY) * TILE_SIZE, TILE_SIZE, TILE_SIZE);
}

function gameLoop(timestamp) {
  const dt = (timestamp - lastTime) / 1000;
  lastTime = timestamp;

  update(dt);
  render();

  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
