    this.time = 0;
  }

  tick() {
    this.time++;
    console.log(`Current time: ${this.time}`);
  }
}

class Hunger {
  constructor() {
    this.level = 100;
  }

  eat(amount) {
    this.level = Math.min(100, this.level + amount);
    console.log(`Hunger level: ${this.level}`);
  }

  consume(amount) {
    this.level = Math.max(0, this.level - amount);
    console.log(`Hunger level: ${this.level}`);
  }
}

class Energy {
  constructor() {
    this.level = 100;
  }

  rest(amount) {
    this.level = Math.min(100, this.level + amount);
    console.log(`Energy level: ${this.level}`);
  }

  use(amount) {
    this.level = Math.max(0, this.level - amount);
    console.log(`Energy level: ${this.level}`);
  }
}

class Economy {
  constructor() {
    this.balance = 1000;
    this.prices = {
      food: 10,
      rest: 5
    };
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Debited ${amount}, new balance: ${this.balance}`);
      return true;
    } else {
      console.log(`Insufficient funds, current balance: ${this.balance}`);
      return false;
    }
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }
}

class Inventory {
  constructor() {
    this.items = {
      food: 0,
      rest: 0
    };
  }

  addItem(item, amount) {
    this.items[item] = (this.items[item] || 0) + amount;
    console.log(`Added ${amount} ${item}(s), total: ${this.items[item]}`);
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item) {
    const price = this.economy.getPrice(item);
    if (this.economy.debit(price)) {
      this.inventory.addItem(item, 1);
      return true;
    }
    return false;
  }
}

