class EventBus {
  constructor() {
    this.events = {};
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }

  subscribe(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }
}

class Hunger {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.hungerLevel = 100; // Max hunger is 100

    this.eventBus.subscribe('tick', this.tick.bind(this));
    this.eventBus.subscribe('eat', this.eat.bind(this));
  }

  tick() {
    if (this.hungerLevel > 0) {
      this.hungerLevel -= 1;
      console.log(`Hunger decreased to ${this.hungerLevel}`);
      if (this.hungerLevel <= 0) {
        console.log('You are hungry!');
      }
    }
  }

  eat(amount = 20) {
    this.hungerLevel = Math.min(this.hungerLevel + amount, 100);
    console.log(`Ate ${amount}, hunger is now ${this.hungerLevel}`);
  }
}

class Energy {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.energyLevel = 100; // Max energy is 100

    this.eventBus.subscribe('tick', this.tick.bind(this));
    this.eventBus.subscribe('rest', this.rest.bind(this));
  }

  tick() {
    if (this.energyLevel > 0) {
      this.energyLevel -= 1;
      console.log(`Energy decreased to ${this.energyLevel}`);
      if (this.energyLevel <= 0) {
        console.log('You are tired!');
      }
    }
  }

  rest(amount = 30) {
    this.energyLevel = Math.min(this.energyLevel + amount, 100);
    console.log(`Resting ${amount}, energy is now ${this.energyLevel}`);
  }
}

class Clock {
