    this.eventBus = eventBus;
    this.interval = interval;
    this.timer = null;
  }

  start() {
    this.timer = setInterval(() => {
      this.eventBus.emit('tick');
    }, this.interval);
  }

  stop() {
    clearInterval(this.timer);
  }
}

