    this.total = total;
  }

  add(points) {
    this.total += points;
    console.log(`Added ${points} experience points. Total: ${this.total}`);
  }

  levelUpThreshold(level) {
    return 100 * Math.pow(level, 2);
  }

  canLevelUp(level) {
    return this.total >= this.levelUpThreshold(level);
  }
}

class LevelUp {
  constructor(experience, inventory, economy) {
    this.experience = experience;
    this.inventory = inventory;
    this.economy = economy;
  }

  attemptLevelUp(skill) {
    if (this.experience.canLevelUp(skill.level)) {
      const cost = this.experience.levelUpThreshold(skill.level);
      if (this.economy.debit(cost)) {
        skill.upgrade();
        this.experience.add(-cost);
        console.log(`Level up successful! Debited ${cost} from economy.`);
      } else {
        console.log(`Insufficient funds to level up.`);
      }
    } else {
      console.log(`Not enough experience to level up.`);
    }
  }
}

