      this.balance -= amount;
      console.log(`Debited ${amount} from economy. Remaining balance: ${this.balance}`);
      return true;
    } else {
      console.log(`Insufficient balance for debit of ${amount}. Current balance: ${this.balance}`);
      return false;
    }
  }

  credit(amount) {
    this.balance += amount;
    console.log(`Credited ${amount} to economy. New balance: ${this.balance}`);
  }

  getBalance() {
    return this.balance;
  }
}

