  x: canvas.width - 100,
  y: canvas.height - 100,
  width: 50,
  height: 50,
  speed: 3,
  direction: { x: 0, y: 0 }
};

let lastKey = '';

function drawRect(rect, color) {
  ctx.fillStyle = color;
  ctx.fillRect(rect.x, rect.y, rect.width, rect.height);
}

function update() {
  if (player.direction.x !== 0 || player.direction.y !== 0) {
    player.x += player.direction.x * player.speed;
    player.y += player.direction.y * player.speed;
  }

  if (enemy.direction.x !== 0 || enemy.direction.y !== 0) {
    enemy.x += enemy.direction.x * enemy.speed;
    enemy.y += enemy.direction.y * enemy.speed;
  }

  if (lastKey === 'ArrowLeft') {
    enemy.direction.x = -1;
  } else if (lastKey === 'ArrowRight') {
    enemy.direction.x = 1;
  } else if (lastKey === 'ArrowUp') {
    enemy.direction.y = -1;
  } else if (lastKey === 'ArrowDown') {
    enemy.direction.y = 1;
  } else {
    enemy.direction = { x: 0, y: 0 };
  }

  if (player.x < 0) player.x = 0;
  if (player.x + player.width > canvas.width) player.x = canvas.width - player.width;
  if (player.y < 0) player.y = 0;
  if (player.y + player.height > canvas.height) player.y = canvas.height - player.height;

  if (enemy.x < 0) enemy.x = 0;
  if (enemy.x + enemy.width > canvas.width) enemy.x = canvas.width - enemy.width;
  if (enemy.y < 0) enemy.y = 0;
  if (enemy.y + enemy.height > canvas.height) enemy.y = canvas.height - enemy.height;
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawRect(player, 'blue');
  drawRect(enemy, 'red');
}

function gameLoop() {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

