class Economy {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
    this.prices = {
      "sword": 10,
      "shield": 5,
      "potion": 2
    };
  }

  buyItem(item, quantity) {
    const price = this.prices[item] * quantity;
    if (price && this.economy.withdraw(price) && this.inventory.addItem(item, quantity)) {
      console.log(`Bought ${quantity} ${item}(s) for ${price} gold.`);
      return true;
    }
    console.log(`Failed to buy ${quantity} ${item}(s).`);
    return false;
  }

  sellItem(item, quantity) {
    const price = this.prices[item] * quantity;
    if (price && this.economy.deposit(price) && this.inventory.removeItem(item, quantity)) {
      console.log(`Sold ${quantity} ${item}(s) for ${price} gold.`);
      return true;
    }
    console.log(`Failed to sell ${quantity} ${item}(s).`);
    return false;
  }
}

