const blockWidth = 30;
const blockHeight = 30;
const gravity = 0.5;
const fallSpeed = 100; // milliseconds per block fall

let blocks = [];
let fallTimer = 0;
let score = 0;
let timeLeft = 60; // seconds

function getRandomBlock() {
  return {
    x: Math.floor(Math.random() * (canvas.width / blockWidth)) * blockWidth,
    y: -blockHeight,
    color: `hsl(${Math.random() * 360}, 100%, 50%)`
  };
}

function updateBlocks(deltaTime) {
  fallTimer += deltaTime;
  if (fallTimer >= fallSpeed) {
    blocks.forEach(block => block.y += gravity);
    fallTimer = 0;
  }

  if (blocks.length === 0 || blocks[blocks.length - 1].y >= canvas.height - blockHeight) {
    blocks.push(getRandomBlock());
  }

  blocks = blocks.filter(block => block.y < canvas.height);
}

function drawBlocks() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Time: ${timeLeft}`, canvas.width - 80, 30);

  blocks.forEach(block => {
    ctx.fillStyle = block.color;
    ctx.fillRect(block.x, block.y, blockWidth, blockHeight);
  });
}

function checkCollision() {
  blocks.forEach(block => {
    if (block.y + blockHeight >= canvas.height) {
      score += 10;
      block.y = -blockHeight;
    }
  });
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTimestamp;
  lastTimestamp = timestamp;

  if (timeLeft <= 0) {
    alert(`Game Over! Your score: ${score}`);
    document.location.reload();
    return;
  }

  updateBlocks(deltaTime);
  checkCollision();
  drawBlocks();

  timeLeft = Math.max(0, timeLeft - deltaTime / 1000);
  requestAnimationFrame(gameLoop);
}

let lastTimestamp = performance.now();
requestAnimationFrame(gameLoop);
