```js
// Constants
const UPDATE_INTERVAL = 16; // Roughly 60 FPS
const JUMP_STRENGTH = -600;
const GRAVITY = 500;
const OBSTACLE_SPEED = 200;
const OBSTACLE_WIDTH = 50;
const OBSTACLE_HEIGHT = 50;
const PLAYER_WIDTH = 50;
const PLAYER_HEIGHT = 50;
const PLAYER_COLOR = 'blue';
const OBSTACLE_COLOR = 'red';

// Canvas setup
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.style.width = '100%';
canvas.style.height = '100%';
const ctx = canvas.getContext('2d');

function resizeCanvas() {
    canvas.width = window.innerWidth * devicePixelRatio;
    canvas.height = window.innerHeight * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

// Game state
let player = {
    x: 50,
    y: canvas.height - 100,
    vy: 0,
    grounded: false
};

let obstacles = [];
let score = 0;
let wave = 1;

// Input
let isJumping = false;
window.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
        isJumping = true;
    }
});

window.addEventListener('keyup', (e) => {
    if (e.code === 'Space') {
        isJumping = false;
    }
});

// Game loop
function update() {
    const dt = UPDATE_INTERVAL / 1000;

    // Player physics
    if (isJumping && player.grounded) {
        player.vy = JUMP_STRENGTH;
        player.grounded = false;
    }

    player.vy += GRAVITY * dt;
    player.y += player.vy * dt;

    if (player.y > canvas.height - PLAYER_HEIGHT) {
        player.y = canvas.height - PLAYER_HEIGHT;
        player.grounded = true;
        player.vy = 0;
    }

    // Obstacle physics
    obstacles.forEach(obstacle => {
        obstacle.x -= OBSTACLE_SPEED * dt;
        if (obstacle.x + OBSTACLE_WIDTH < 0) {
            obstacles.shift();
        }
    });

    // Collision detection
    obstacles.forEach(obstacle => {
        if (player.x < obstacle.x + OBSTACLE_WIDTH &&
            player.x + PLAYER_WIDTH > obstacle.x &&
            player.y < obstacle.y + OBSTACLE_HEIGHT &&
            player.y + PLAYER_HEIGHT > obstacle.y) {
            // Game over
            alert(`Game Over! Your score: ${score}`);
            obstacles = [];
            score = 0;
            wave = 1;
            player.y = canvas.height - 100;
        }
    });

    // Spawn obstacles
    if (Math.random() < 0.01 * wave) {
        obstacles.push({
            x: canvas.width,
            y: canvas.height - OBSTACLE_HEIGHT
        });
    }

    // Score
    score += dt * 10;
    wave = Math.floor(score / 100) + 1;

    requestAnimationFrame(update);
}

// Rendering
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw player
    ctx.fillStyle = PLAYER_COLOR;
    ctx.fillRect(player.x, player.y, PLAYER_WIDTH, PLAYER_HEIGHT);

    // Draw obstacles
    ctx.fillStyle = OBSTACLE_COLOR;
    obstacles.forEach(obstacle => {
        ctx.fillRect(obstacle.x, obstacle.y, OBSTACLE_WIDTH, OBSTACLE_HEIGHT);
    });

    requestAnimationFrame(draw);
}

// Start game
update();
draw();
