// Event Bus
class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(listener);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(data));
        }
    }
}

// Building System
class Building {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.buildings = [];
        this.eventBus.subscribe('resource:produced', this.onResourceProduced.bind(this));
    }

    build(type) {
        this.buildings.push(type);
        console.log(`Building ${type} constructed.`);
        this.eventBus.emit('building:constructed', { type });
    }

    onResourceProduced(data) {
        console.log(`Building system received resource: ${data.resource} x ${data.amount}`);
    }
}

// Resource System
class Resource {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.resources = {};
        this.eventBus.subscribe('building:constructed', this.onBuildingConstructed.bind(this));
    }

    produce(resource, amount) {
        if (!this.resources[resource]) {
            this.resources[resource] = 0;
        }
        this.resources[resource] += amount;
        console.log(`Produced ${resource} x ${amount}. Total: ${this.resources[resource]}`);
        this.eventBus.emit('resource:produced', { resource, amount });
    }

    onBuildingConstructed(data) {
        console.log(`Resource system detected new building: ${data.type}`);
        if (data.type === 'Farm') {
            this.produce('Food', 10);
        } else if (data.type === 'Mine') {
            this.produce('Metal', 5);
        }
    }
}

// Economy System
class Economy {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('resource:produced', this.onResourceProduced.bind(this));
    }

    trade(resource, amount, price) {
        console.log(`Trading ${resource} x ${amount} for ${price} gold.`);
        this.eventBus.emit('economy:trade', { resource, amount, price });
    }

    onResourceProduced(data) {
        console.log(`Economy system received resource: ${data.resource} x ${data.amount}`);
    }
}

// Demo
