const buildingSystem = new Building(eventBus);
const resourceSystem = new Resource(eventBus);
const economySystem = new Economy(eventBus);

buildingSystem.build('Farm');
buildingSystem.build('Mine');
resourceSystem.produce('Wood', 20);
economySystem.trade('Metal', 5, 50);
