class Loot {
  constructor() {
    this.lootPool = [];
  }

  addLoot(item, rarity) {
    this.lootPool.push({ item, rarity });
  }

  getRandomLoot() {
    if (this.lootPool.length === 0) return null;
    const randomIndex = Math.floor(Math.random() * this.lootPool.length);
    return this.lootPool[randomIndex];
  }
}

class RarityTable {
  constructor() {
    this.rarityWeights = {
      common: 0.6,
      uncommon: 0.3,
      rare: 0.1
    };
  }

  getWeightedRarity() {
    const randomValue = Math.random();
    let cumulativeWeight = 0;

    for (const rarity in this.rarityWeights) {
      cumulativeWeight += this.rarityWeights[rarity];
      if (randomValue < cumulativeWeight) {
        return rarity;
      }
    }

    return 'common'; // Default to common if something goes wrong
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  listItems() {
    return this.items;
  }
}

