class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // ingredients is an array of { item: 'name', quantity: number }
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return this.ingredients;
  }
}

class Inventory {
  constructor() {
    this.items = new Map(); // Map of item names to quantities
  }

  addItem(item, quantity) {
    if (this.items.has(item)) {
      this.items.set(item, this.items.get(item) + quantity);
    } else {
      this.items.set(item, quantity);
    }
  }

  removeItem(item, quantity) {
    if (this.items.has(item) && this.items.get(item) >= quantity) {
      this.items.set(item, this.items.get(item) - quantity);
      if (this.items.get(item) === 0) {
        this.items.delete(item);
      }
      return true;
    }
    return false;
  }

  hasIngredients(recipe) {
    const ingredients = recipe.getIngredients();
    for (const { item, quantity } of ingredients) {
      if (!this.items.has(item) || this.items.get(item) < quantity) {
        return false;
      }
    }
    return true;
  }

  getItems() {
    return this.items;
  }
}

class Crafting {
  constructor(inventory) {
    this.inventory = inventory;
    this.recipes = new Map(); // Map of recipe names to Recipe objects
  }

  addRecipe(recipe) {
    this.recipes.set(recipe.getName(), recipe);
  }

  craft(recipeName) {
    const recipe = this.recipes.get(recipeName);
    if (!recipe) {
      console.log(`Recipe "${recipeName}" not found.`);
      return false;
    }

    if (!this.inventory.hasIngredients(recipe)) {
      console.log(`Missing ingredients for "${recipeName}".`);
      return false;
    }

    for (const { item, quantity } of recipe.getIngredients()) {
      this.inventory.removeItem(item, quantity);
    }

    console.log(`Crafted "${recipeName}".`);
    return true;
  }
}

