class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item) {
    const price = this.economy.getPrice(item);
    if (price > 0 && this.economy.debit(price)) {
      this.inventory.addItem(item);
      return true;
    }
    return false;
  }
}

// Combat System
class Combat {
  constructor(health) {
    this.health = health;
  }

  takeDamage(amount) {
    this.health -= amount;
    if (this.health < 0) {
      this.health = 0;
    }
  }

  getHealth() {
    return this.health;
  }
}

// Health System
class Health {
  constructor(initialHealth = 100) {
    this.currentHealth = initialHealth;
  }

  takeDamage(amount) {
    this.currentHealth -= amount;
    if (this.currentHealth < 0) {
      this.currentHealth = 0;
    }
  }

  heal(amount) {
    this.currentHealth += amount;
    if (this.currentHealth > 100) {
      this.currentHealth = 100;
    }
  }

  getHealth() {
    return this.currentHealth;
  }
}

// Loot System
class Loot {
  constructor() {
    this.lootTable = {
      sword: 0.3,
      shield: 0.3,
      potion: 0.4
    };
  }

  rollLoot() {
    const roll = Math.random();
    let cumulativeProbability = 0;

    for (const item in this.lootTable) {
      cumulativeProbability += this.lootTable[item];
      if (roll <= cumulativeProbability) {
        return item;
      }
    }

    return null; // Should never reach here due to cumulative probability
  }
}

