class Wallet {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    getBalance() {
        return this.balance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }
}

class Shop {
    constructor() {
        this.items = {
            'sword': 50,
            'potion': 20,
            'shield': 75
        };
    }

    listItems() {
        return Object.keys(this.items).map(item => ({ name: item, price: this.items[item] }));
    }

    getItemPrice(item) {
        return this.items[item] || null;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (quantity > 0) {
            if (this.items[item]) {
                this.items[item] += quantity;
            } else {
                this.items[item] = quantity;
            }
            return true;
        }
        return false;
    }

    removeItem(item, quantity = 1) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    getInventory() {
        return this.items;
    }
}

class GameCoordinator {
    constructor(wallet, shop, inventory) {
        this.wallet = wallet;
        this.shop = shop;
        this.inventory = inventory;
    }

    buyItem(item) {
        const price = this.shop.getItemPrice(item);
        if (price !== null && this.wallet.withdraw(price)) {
            this.inventory.addItem(item);
            return true;
        }
        return false;
    }

    sellItem(item) {
        const price = this.shop.getItemPrice(item);
        if (price !== null && this.inventory.removeItem(item)) {
            this.wallet.deposit(price);
            return true;
        }
        return false;
    }

    displayStatus() {
        console.log(`Wallet Balance: ${this.wallet.getBalance()}`);
        console.log('Inventory:');
        console.log(JSON.stringify(this.inventory.getInventory(), null, 2));
    }
}

