class Health {
  constructor(maxHealth = 100) {
    this.currentHealth = maxHealth;
    this.maxHealth = maxHealth;
  }

  takeDamage(amount) {
    this.currentHealth -= amount;
    if (this.currentHealth < 0) this.currentHealth = 0;
    console.log(`Health: Took ${amount} damage, current health is ${this.currentHealth}.`);
  }

  heal(amount) {
    this.currentHealth += amount;
    if (this.currentHealth > this.maxHealth) this.currentHealth = this.maxHealth;
    console.log(`Health: Healed by ${amount}, current health is ${this.currentHealth}.`);
  }
}

class Loot {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
    console.log(`Loot: Added item ${item} to inventory.`);
  }

  getItems() {
    return this.items;
  }
}

class Economy {
  constructor() {
    this.balance = 1000;
    this.prices = {
      potion: 50,
      weapon: 200
    };
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Economy: Debited ${amount}, new balance is ${this.balance}.`);
      return true;
    } else {
      console.log(`Economy: Insufficient funds. Current balance is ${this.balance}.`);
      return false;
    }
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item) {
    const price = this.economy.getPrice(item);
    if (price > 0 && this.economy.debit(price)) {
      this.inventory.addItem(item);
      console.log(`Store: Purchased ${item} for ${price}.`);
    } else {
      console.log(`Store: Failed to purchase ${item}.`);
    }
  }
}

