const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let windowWidth = window.innerWidth;
let windowHeight = window.innerHeight;
let dpr = window.devicePixelRatio;
canvas.width = windowWidth * dpr;
canvas.height = windowHeight * dpr;
canvas.style.width = `${windowWidth}px`;
canvas.style.height = `${windowHeight}px`;

let player = {
    x: 50,
    y: 100,
    width: 50,
    height: 50,
    velocityX: 0,
    velocityY: 0,
    gravity: 0.5,
    onGround: false
};

let platforms = [];
let waves = [];
let currentWave = 0;

function createWave(waveNumber) {
    let wave = {
        platforms: [],
        width: 0
    };

    let startX = 0;
    for (let i = 0; i < 10; i++) {
        let platform = {
            x: startX,
            y: Math.random() * (windowHeight - 100) + 50,
            width: 100,
            height: 20
        };
        wave.platforms.push(platform);
        startX += platform.width + Math.random() * 100 + 50;
    }
    wave.width = startX;
    waves.push(wave);
}

function update() {
    player.velocityY += player.gravity;
    player.y += player.velocityY;

    if (player.y + player.height > windowHeight) {
        player.y = windowHeight - player.height;
        player.velocityY = 0;
        player.onGround = true;
    } else {
        player.onGround = false;
    }

    if (player.x > windowWidth) {
        player.x = 0;
        currentWave++;
        createWave(currentWave);
    }

    for (let platform of waves[currentWave].platforms) {
        if (player.x + player.width > platform.x &&
            player.x < platform.x + platform.width &&
            player.y + player.height > platform.y &&
            player.y < platform.y + platform.height) {
            player.y = platform.y - player.height;
            player.velocityY = 0;
            player.onGround = true;
        }
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'green';
    for (let platform of waves[currentWave].platforms) {
        ctx.fillRect(platform.x * dpr, platform.y * dpr, platform.width * dpr, platform.height * dpr);
    }

    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x * dpr, player.y * dpr, player.width * dpr, player.height * dpr);
}

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

window.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight') {
        player.velocityX = 5;
    }
    if (e.key === 'ArrowLeft') {
        player.velocityX = -5;
    }
    if (e.key === 'ArrowUp' && player.onGround) {
        player.velocityY = -10;
    }
});

window.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
        player.velocityX = 0;
    }
});

window.addEventListener('resize', () => {
    windowWidth = window.innerWidth;
    windowHeight = window.innerHeight;
    dpr = window.devicePixelRatio;
    canvas.width = windowWidth * dpr;
    canvas.height = windowHeight * dpr;
    canvas.style.width = `${windowWidth}px`;
    canvas.style.height = `${windowHeight}px`;
});

createWave(0);
gameLoop();
