const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 400;
const ctx = canvas.getContext('2d');

const TILE_SIZE = 100;
const GRID_SIZE = 4;
const TARGET_SCORE = 2048;

let score = 0;
let currentLevel = 1;
let grid = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(0));
let nextTileValue = 2;
let lastTime = 0;
const fixedTimeStep = 1000 / 30;

function getRandomInt(max) {
    return Math.floor(Math.random() * max);
}

function addRandomTile() {
    const emptyCells = [];
    for (let y = 0; y < GRID_SIZE; y++) {
        for (let x = 0; x < GRID_SIZE; x++) {
            if (grid[y][x] === 0) {
                emptyCells.push({ x, y });
            }
        }
    }
    if (emptyCells.length > 0) {
        const { x, y } = emptyCells[getRandomInt(emptyCells.length)];
        grid[y][x] = nextTileValue;
        nextTileValue = nextTileValue === 2 ? 4 : 2;
    }
}

function mergeTiles(row) {
    let newRow = row.filter(value => value !== 0);
    for (let i = 0; i < newRow.length - 1; i++) {
        if (newRow[i] === newRow[i + 1]) {
            newRow[i] *= 2;
            score += newRow[i];
            newRow[i + 1] = 0;
        }
    }
    newRow = newRow.filter(value => value !== 0);
    while (newRow.length < GRID_SIZE) {
        newRow.push(0);
    }
    return newRow;
}

function transposeGrid(grid) {
    return grid[0].map((_, colIndex) => grid.map(row => row[colIndex]));
}

function moveLeft(grid) {
    return grid.map(row => mergeTiles(row));
}

function moveRight(grid) {
    return grid.map(row => mergeTiles(row.slice().reverse())).map(row => row.reverse());
}

function moveUp(grid) {
    return transposeGrid(moveLeft(transposeGrid(grid)));
}

function moveDown(grid) {
    return transposeGrid(moveRight(transposeGrid(grid)));
}

function handleInput(e) {
