    switch (e.key) {
        case 'ArrowLeft':
            grid = moveLeft(grid);
            break;
        case 'ArrowRight':
            grid = moveRight(grid);
            break;
        case 'ArrowUp':
            grid = moveUp(grid);
            break;
        case 'ArrowDown':
            grid = moveDown(grid);
            break;
    }
    if (JSON.stringify(grid) !== JSON.stringify(oldGrid)) {
        addRandomTile();
        if (grid.flat().every(value => value !== 0)) {
            // Game over logic
        }
    }
}

document.addEventListener('keydown', handleInput);

function drawTile(x, y, value) {
    ctx.fillStyle = '#ccc';
    ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    ctx.fillStyle = '#000';
    ctx.font = '48px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(value.toString(), x * TILE_SIZE + TILE_SIZE / 2, y * TILE_SIZE + TILE_SIZE / 2);
