```js
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let tileCount = 4;
let tiles = [];
let score = 0;
let level = 1;
let wave = 1;
let tileWidth, tileHeight;
let padding = 5;

function init() {
  resizeCanvas();
  tiles = Array(tileCount * tileCount).fill(0);
  addRandomTile();
  requestAnimationFrame(gameLoop);
}

function resizeCanvas() {
  const dpr = window.devicePixelRatio || 1;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
  tileWidth = (canvas.width - padding * 2) / tileCount;
  tileHeight = (canvas.height - padding * 2) / tileCount;
}

window.addEventListener('resize', resizeCanvas);

function addRandomTile() {
  const emptyTiles = tiles.flatMap((v, i) => v === 0 ? i : []);
  if (emptyTiles.length > 0) {
    const index = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
    tiles[index] = Math.random() > 0.9 ? 4 : 2;
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < tileCount; i++) {
    for (let j = 0; j < tileCount; j++) {
      const value = tiles[i * tileCount + j];
      ctx.fillStyle = getTileColor(value);
      ctx.fillRect(padding + j * tileWidth, padding + i * tileHeight, tileWidth - padding, tileHeight - padding);
      if (value !== 0) {
        ctx.font = 'bold 30px Arial';
        ctx.fillStyle = '#fff';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(value.toString(), j * tileWidth + tileWidth / 2, i * tileHeight + tileHeight / 2);
      }
    }
  }
  ctx.font = '20px Arial';
  ctx.fillStyle = '#000';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Level: ${level}`, 10, 60);
  ctx.fillText(`Wave: ${wave}`, 10, 90);
}

function getTileColor(value) {
  const colors = ['#ccc', '#eee', '#ddd', '#bbb', '#aaa', '#999', '#888', '#777', '#666', '#555', '#444', '#333'];
  const logValue = Math.log2(value);
  return colors[Math.min(logValue - 1, colors.length - 1)];
}

function slideTiles(direction) {
  const moves = [];
  let didMove = false;

  for (let i = 0; i < tileCount; i++) {
    const row = [];
    for (let j = 0; j < tileCount; j++) {
      const index = direction === 'up' || direction === 'left' ? i * tileCount + j : j * tileCount + i;
      row.push({ index, value: tiles[index] });
    }

    const merged = merge(row);
    for (let j = 0; j < tileCount; j++) {
      const index = direction === 'up' || direction === 'left' ? i * tileCount + j : j * tileCount + i;
      if (tiles[index] !== merged[j].value) {
        didMove = true;
        tiles[index] = merged[j].value;
        moves.push({ from: index, to: merged[j].index });
      }
    }
  }

  return didMove;
}

function merge(row) {
  row.sort((a, b) => direction === 'right' || direction === 'down' ? a.value - b.value : b.value - a.value);

  for (let i = 0; i < row.length - 1; i++) {
    if (row[i].value !== 0 && row[i].value === row[i + 1].value) {
      row[i].value *= 2;
      row[i + 1].value = 0;
      score += row[i].value;
    }
  }

  return row.filter(tile => tile.value !== 0);
}

function gameLoop() {
  draw();
  if (wave % 10 === 0 && wave !== 0) {
    level++;
    tileCount++;
    tiles = Array(tileCount * tileCount).fill(0);
    resizeCanvas();
  }
  if (wave % 2 === 0 && wave !== 0) {
    addRandomTile();
  }
  wave++;
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
  let didMove = false;
  switch (e.key) {
    case 'ArrowUp':
      didMove = slideTiles('up');
      break;
    case 'ArrowDown':
      didMove = slideTiles('down');
      break;
    case 'ArrowLeft':
      didMove = slideTiles('left');
      break;
    case 'ArrowRight':
      didMove = slideTiles('right');
      break;
  }
  if (didMove) {
    addRandomTile();
  }
});

init();
```

