const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let width = window.innerWidth;
let height = window.innerHeight;
let dpr = window.devicePixelRatio;

canvas.width = width * dpr;
canvas.height = height * dpr;
ctx.scale(dpr, dpr);

const BLOCK_SIZE = 30;
const COLUMN_COUNT = Math.floor(width / BLOCK_SIZE);
const ROW_COUNT = Math.floor(height / BLOCK_SIZE);

let board = Array.from({ length: ROW_COUNT }, () => Array(COLUMN_COUNT).fill(0));
let currentPiece = { shape: getRandomShape(), row: 0, col: Math.floor(COLUMN_COUNT / 2) - 1 };
let comboMultiplier = 1;
let score = 0;
let dropInterval = 500;
let lastDropTime = Date.now();

const SHAPES = [
    { shape: [[1, 1, 1, 1]], color: 'cyan' }, // I
    { shape: [[1, 1], [1, 1]], color: 'orange' }, // O
    { shape: [[1, 1, 1], [0, 1, 0]], color: 'yellow' }, // T
    { shape: [[1, 1, 1], [1, 0, 0]], color: 'green' }, // L
    { shape: [[1, 1, 1], [0, 0, 1]], color: 'blue' }, // J
    { shape: [[0, 1, 1], [1, 1, 0]], color: 'purple' }, // S
    { shape: [[1, 1, 0], [0, 1, 1]], color: 'red' } // Z
];

function getRandomShape() {
    return SHAPES[Math.floor(Math.random() * SHAPES.length)];
}

function drawBlock(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
    ctx.strokeStyle = 'black';
    ctx.strokeRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
}

function drawBoard() {
    for (let row = 0; row < ROW_COUNT; row++) {
        for (let col = 0; col < COLUMN_COUNT; col++) {
            if (board[row][col]) {
                drawBlock(col, row, board[row][col]);
            }
        }
    }
}

function drawPiece(piece) {
    piece.shape.forEach((row, rowIndex) => {
        row.forEach((cell, colIndex) => {
            if (cell) {
                drawBlock(piece.col + colIndex, piece.row + rowIndex, piece.color);
            }
        });
    });
}

function canMove(piece, drow, dcol) {
    for (let row = 0; row < piece.shape.length; row++) {
        for (let col = 0; col < piece.shape[row].length; col++) {
            if (piece.shape[row][col]) {
                let newRow = piece.row + row + drow;
                let newCol = piece.col + col + dcol;
                if (newRow >= ROW_COUNT || newRow < 0 || newCol >= COLUMN_COUNT || newCol < 0 || board[newRow][newCol]) {
                    return false;
                }
            }
        }
    }
    return true;
}

function mergePieceIntoBoard(piece) {
    piece.shape.forEach((row, rowIndex) => {
        row.forEach((cell, colIndex) => {
            if (cell) {
                board[piece.row + rowIndex][piece.col + colIndex] = piece.color;
            }
        });
    });
}

function clearLines() {
    let linesCleared = 0;
    for (let row = ROW_COUNT - 1; row >= 0; row--) {
        if (board[row].every(cell => cell)) {
            board.splice(row, 1);
            board.unshift(Array(COLUMN_COUNT).fill(0));
            linesCleared++;
        }
    }
    if (linesCleared > 0) {
        score += linesCleared * linesCleared * comboMultiplier;
        comboMultiplier++;
    }
}

function update() {
    let now = Date.now();
    if (now - lastDropTime > dropInterval) {
        if (canMove(currentPiece, 1, 0)) {
            currentPiece.row++;
        } else {
            mergePieceIntoBoard(currentPiece);
            clearLines();
            currentPiece = { shape: getRandomShape(), row: 0, col: Math.floor(COLUMN_COUNT / 2) - 1 };
            if (!canMove(currentPiece, 0, 0)) {
                alert(`Game Over! Score: ${score}`);
                document.location.reload();
            }
            comboMultiplier = 1;
        }
        lastDropTime = now;
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBoard();
    drawPiece(currentPiece);
}

function handleKeyDown(event) {
    switch (event.key) {
        case 'ArrowLeft':
            if (canMove(currentPiece, 0, -1)) {
                currentPiece.col--;
            }
            break;
        case 'ArrowRight':
            if (canMove(currentPiece, 0, 1)) {
                currentPiece.col++;
            }
            break;
        case 'ArrowDown':
            if (canMove(currentPiece, 1, 0)) {
                currentPiece.row++;
                lastDropTime = Date.now();
            }
            break;
        case 'ArrowUp':
            let rotatedShape = rotateShape(currentPiece.shape);
            if (canMove({ ...currentPiece, shape: rotatedShape }, 0, 0)) {
                currentPiece.shape = rotatedShape;
            }
            break;
    }
}

function rotateShape(shape) {
    let N = shape.length;
    let rotated = Array.from({ length: N }, () => Array(N).fill(0));
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            rotated[j][N - 1 - i] = shape[i][j];
        }
    }
    return rotated;
}

document.addEventListener('keydown', handleKeyDown);
setInterval(update, 30);
setInterval(render, 30);
