// Farming Plot Simulator with Combo Multiplier
// Rendered on an HTML5 canvas using requestAnimationFrame

const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Constants
const plotSize = 50;
const colors = ['#7CFC00', '#228B22', '#32CD32', '#556B2F'];
const comboMultiplier = 1.5;

// Game state
let plots = [];
let combo = 0;
let score = 0;

// Initialize plots
function initPlots() {
    for (let x = 0; x < canvas.width; x += plotSize) {
        for (let y = 0; y < canvas.height; y += plotSize) {
            plots.push({ x, y, color: colors[Math.floor(Math.random() * colors.length)], harvested: false });
        }
    }
}

// Draw plots
function drawPlots() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    plots.forEach(plot => {
        ctx.fillStyle = plot.color;
        ctx.fillRect(plot.x, plot.y, plotSize, plotSize);
        if (plot.harvested) {
            ctx.strokeStyle = 'black';
            ctx.strokeRect(plot.x, plot.y, plotSize, plotSize);
        }
    });
}

// Check for harvest
function checkHarvest() {
    plots.forEach(plot => {
        if (plot.harvested) {
            score += 10 * Math.pow(comboMultiplier, combo);
            combo++;
        } else {
            combo = 0;
        }
        plot.harvested = false;
    });
}

// Handle click
canvas.addEventListener('click', (event) => {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((event.clientX - rect.left) / plotSize) * plotSize;
    const y = Math.floor((event.clientY - rect.top) / plotSize) * plotSize;
    plots.forEach(plot => {
        if (plot.x === x && plot.y === y) {
            plot.harvested = true;
        }
    });
});

// Game loop
function gameLoop() {
    checkHarvest();
    drawPlots();
    requestAnimationFrame(gameLoop);
}

// Start game
initPlots();
gameLoop();
