// Fishing Mini-Game with Finite State Machine
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let state = 'menu';
let fish = [];
let score = 0;
let timer = 0;
let pausedTime = 0;
const fishSpeed = 0.5;
const fishSize = 20;
const hookSize = 5;
let hookPos = { x: canvas.width / 2, y: canvas.height };
let hookVel = 0;
const hookSpeed = 5;
const maxHookVel = 10;
const maxScore = 10;

function resize() {
  canvas.width = window.innerWidth * devicePixelRatio;
  canvas.height = window.innerHeight * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
}

window.addEventListener('resize', resize);
resize();

function drawMenu() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.fillText('Press SPACE to Start', canvas.width / 2, canvas.height / 2);
}

function drawPlaying() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '20px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'left';
  ctx.fillText(`Score: ${score}`, 10, 20);

  fish.forEach(f => {
    ctx.fillStyle = 'blue';
    ctx.fillRect(f.x - fishSize / 2, f.y - fishSize / 2, fishSize, fishSize);
  });

  ctx.fillStyle = 'red';
  ctx.fillRect(hookPos.x - hookSize / 2, hookPos.y - hookSize / 2, hookSize, hookSize);
}

function drawPaused() {
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.fillText('PAUSED', canvas.width / 2, canvas.height / 2);
}

function drawGameOver() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  ctx.fillText(`Final Score: ${score}`, canvas.width / 2, canvas.height / 2 + 40);
}

function updateMenu(dt) {
  if (keys.Space) {
    state = 'playing';
    keys.Space = false;
  }
}

function updatePlaying(dt) {
  timer += dt;
  if (timer > 1) {
    timer = 0;
    fish.push({ x: Math.random() * canvas.width, y: 0 });
  }

  fish.forEach(f => {
    f.y += fishSpeed;
    if (f.y > canvas.height) {
      fish.shift();
    }
  });

  hookPos.y -= hookVel * dt;
  hookVel = Math.max(hookVel - 0.1 * dt, 0);

  fish.forEach((f, i) => {
    if (Math.abs(f.x - hookPos.x) < hookSize / 2 + fishSize / 2 && Math.abs(f.y - hookPos.y) < hookSize / 2 + fishSize / 2) {
      score++;
      fish.splice(i, 1);
    }
  });

  if (score >= maxScore) {
    state = 'gameover';
  }
}

function updatePaused(dt) {
  if (keys.Space) {
    state = 'playing';
    keys.Space = false;
    hookPos.y = canvas.height;
    hookVel = 0;
    pausedTime = Date.now();
  }
}

function updateGameOver(dt) {
  if (keys.Space) {
    location.reload();
    keys.Space = false;
  }
}

function update(dt) {
  switch (state) {
    case 'menu': updateMenu(dt); break;
    case 'playing': updatePlaying(dt); break;
    case 'paused': updatePaused(dt); break;
    case 'gameover': updateGameOver(dt); break;
  }
}

function draw() {
  switch (state) {
    case 'menu': drawMenu(); break;
    case 'playing': drawPlaying(); break;
    case 'paused': drawPaused(); break;
    case 'gameover': drawGameOver(); break;
  }
}

function gameLoop() {
  const now = Date.now();
  const dt = (now - lastTime) / 1000;
  lastTime = now;

  update(dt);
  draw();

  requestAnimationFrame(gameLoop);
}

const keys = {};
window.addEventListener('keydown', e => {
  keys[e.code] = true;
  if (state === 'playing' && e.code === 'Space') {
    hookVel = Math.min(hookVel + 1, maxHookVel);
  }
});
window.addEventListener('keyup', e => {
  keys[e.code] = false;
});

let lastTime = Date.now();
gameLoop();
