class Wallet {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      if (this.items[item]) {
        this.items[item] += quantity;
      } else {
        this.items[item] = quantity;
      }
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }

  getItems() {
    return { ...this.items };
  }
}

class Shop {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item, quantity) {
    const price = this.economy.getPrice(item);
    if (price === null || quantity <= 0) {
      return false;
    }

    const totalCost = price * quantity;
    if (this.economy.withdraw(totalCost)) {
      this.inventory.addItem(item, quantity);
      return true;
    }
    return false;
  }
}

class Economy {
  constructor() {
    this.wallet = new Wallet();
    this.prices = {
      sword: 10,
      shield: 5,
      potion: 3
    };
  }

  deposit(amount) {
    return this.wallet.deposit(amount);
  }

  withdraw(amount) {
    return this.wallet.withdraw(amount);
  }

  getBalance() {
    return this.wallet.getBalance();
  }

  getPrice(item) {
    return this.prices[item] || null;
  }
}

