const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const fishSpeed = 2;
const powerUpSpeed = 2;
const fishSize = 50;
const powerUpSize = 30;
const powerUpTypes = ['doublePoints', 'slowDown', 'speedUp'];
const powerUpColors = ['#FFD700', '#87CEEB', '#FF69B4'];

let fishX = canvas.width / 2;
let fishY = canvas.height - fishSize - 10;
let score = 0;
let time = 0;
let powerUps = [];

function getRandomPowerUp() {
  const type = powerUpTypes[Math.floor(Math.random() * powerUpTypes.length)];
  const color = powerUpColors[powerUpTypes.indexOf(type)];
  return {
    x: Math.random() * (canvas.width - powerUpSize),
    y: -powerUpSize,
    size: powerUpSize,
    color: color,
    type: type,
    speed: powerUpSpeed
  };
}

function update() {
  time += 1 / 60; // Fixed timestep

  // Move fish
  if (keys.right && fishX < canvas.width - fishSize) fishX += fishSpeed;
  if (keys.left && fishX > 0) fishX -= fishSpeed;

  // Move power-ups
  powerUps.forEach((powerUp, index) => {
    powerUp.y += powerUp.speed;
    if (powerUp.y > canvas.height) {
      powerUps.splice(index, 1);
    }
  });

  // Check for collisions
  powerUps.forEach((powerUp, index) => {
    if (
      fishX < powerUp.x + powerUp.size &&
      fishX + fishSize > powerUp.x &&
      fishY < powerUp.y + powerUp.size &&
      fishY + fishSize > powerUp.y
    ) {
      handlePowerUp(powerUp);
      powerUps.splice(index, 1);
    }
  });

  // Spawn new power-up occasionally
  if (Math.random() < 0.02) {
    powerUps.push(getRandomPowerUp());
  }
}

function handlePowerUp(powerUp) {
  switch (powerUp.type) {
    case 'doublePoints':
      score += 2;
      break;
    case 'slowDown':
      fishSpeed = Math.max(1, fishSpeed - 0.5);
      break;
    case 'speedUp':
      fishSpeed += 0.5;
      break;
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw fish
  ctx.fillStyle = 'blue';
  ctx.fillRect(fishX, fishY, fishSize, fishSize);

  // Draw power-ups
  powerUps.forEach(powerUp => {
    ctx.fillStyle = powerUp.color;
    ctx.fillRect(powerUp.x, powerUp.y, powerUp.size, powerUp.size);
  });

  // Draw score
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function gameLoop() {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

const keys = { right: false, left: false };

document.addEventListener('keydown', e => {
  if (e.key === 'ArrowRight') keys.right = true;
  if (e.key === 'ArrowLeft') keys.left = true;
});

document.addEventListener('keyup', e => {
  if (e.key === 'ArrowRight') keys.right = false;
  if (e.key === 'ArrowLeft') keys.left = false;
});

gameLoop();
