const snake = [{ x: 10, y: 10 }];
let dx = 0;
let dy = 0;
let food = { x: Math.floor(Math.random() * 20), y: Math.floor(Math.random() * 20) };
let level = 1;
let score = 0;
const grid = 20;

function drawRect(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * grid, y * grid, grid, grid);
}

function drawSnake() {
  snake.forEach(segment => drawRect(segment.x, segment.y, 'green'));
}

function drawFood() {
  drawRect(food.x, food.y, 'red');
}

function drawLevelAndScore() {
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Level: ${level}`, 10, 30);
  ctx.fillText(`Score: ${score}`, 10, 50);
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  const head = { x: snake[0].x + dx, y: snake[0].y + dy };

  if (head.x === food.x && head.y === food.y) {
    score++;
    level = Math.floor(score / 5) + 1;
    food = { x: Math.floor(Math.random() * 20), y: Math.floor(Math.random() * 20) };
  } else {
    snake.pop();
  }

  snake.unshift(head);

  if (head.x < 0 || head.x >= 20 || head.y < 0 || head.y >= 20 || snake.some(segment => segment.x === head.x && segment.y === head.y)) {
    alert(`Game Over! Score: ${score}`);
    document.location.reload();
  }

  drawSnake();
  drawFood();
  drawLevelAndScore();

  setTimeout(gameLoop, 1000 / level);
}

