class Crop {
    constructor(name) {
        this.name = name;
        this.growthStage = 0;
    }

    grow() {
        this.growthStage++;
        return this.growthStage;
    }

    isReadyToHarvest() {
        // Arbitrary growth stages for demonstration
        const readyStages = { wheat: 3, corn: 4, potato: 2 };
        return this.growthStage >= readyStages[this.name];
    }

    harvest() {
        if (this.isReadyToHarvest()) {
            return this.name;
        }
        return null;
    }
}

// Farm.js
class Farm {
    constructor() {
        this.crops = [];
    }

    plantCrop(name) {
        this.crops.push(new Crop(name));
    }

    tendCrops() {
        this.crops.forEach(crop => crop.grow());
    }

    harvestCrops() {
        const harvested = this.crops.filter(crop => crop.isReadyToHarvest()).map(crop => crop.harvest());
        this.crops = this.crops.filter(crop => !crop.isReadyToHarvest());
        return harvested;
    }
}

// Market.js
class Market {
    constructor(economy) {
        this.economy = economy;
        this.inventory = {};
    }

    buyItem(item, quantity) {
        const pricePerItem = this.economy.getPrice(item);
        const totalCost = pricePerItem * quantity;

        if (this.economy.debit(totalCost)) {
            this.addItemToInventory(item, quantity);
            console.log(`Bought ${quantity} ${item}(s) for ${totalCost}. New balance: ${this.economy.getBalance()}`);
        } else {
            console.log(`Insufficient funds to buy ${quantity} ${item}(s). Current balance: ${this.economy.getBalance()}`);
        }
    }

    addItemToInventory(item, quantity) {
        if (this.inventory[item]) {
            this.inventory[item] += quantity;
        } else {
            this.inventory[item] = quantity;
        }
    }

    getInventory() {
        return this.inventory;
    }
}

