const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 600;

const gravity = 0.5;
const flapStrength = -10;
const gapHeight = 100;
const gapWidth = 50;
const powerupRadius = 10;
const powerupSpeed = 1.5;
const fixedTimeStep = 1000 / 60;
let lastTime = 0;

const bird = {
    x: 50,
    y: canvas.height / 2,
    vy: 0
};

const pipes = [];
const powerups = [];

function createPipe() {
    const y = Math.random() * (canvas.height - gapHeight);
    pipes.push({ x: canvas.width, y, width: gapWidth, height: y });
    pipes.push({ x: canvas.width, y: y + gapHeight, width: gapWidth, height: canvas.height - y - gapHeight });
}

function createPowerup() {
    const y = Math.random() * (canvas.height - powerupRadius * 2) + powerupRadius;
    powerups.push({ x: canvas.width, y, radius: powerupRadius });
}

function update() {
    const now = Date.now();
    const dt = now - lastTime;
    lastTime = now;

    if (dt > fixedTimeStep) {
        bird.vy += gravity;
        bird.y += bird.vy;

        if (bird.y + 10 > canvas.height || bird.y < 0) {
            resetGame();
        }

        pipes.forEach(pipe => {
            pipe.x -= 2;
            if (pipe.x + pipe.width < 0) {
                pipes.shift();
                pipes.shift();
            }
        });

        powerups.forEach(powerup => {
            powerup.x -= powerupSpeed;
            if (powerup.x + powerup.radius < 0) {
                powerups.shift();
            }
        });

        if (Math.random() < 0.02) {
            createPipe();
        }

        if (Math.random() < 0.01) {
            createPowerup();
        }

        checkCollisions();
    }
}

function checkCollisions() {
    pipes.forEach(pipe => {
        if (bird.x + 10 > pipe.x && bird.x < pipe.x + pipe.width &&
            bird.y < pipe.y + pipe.height || bird.y + 10 > pipe.y) {
            resetGame();
        }
    });

    powerups.forEach((powerup, index) => {
        if (Math.sqrt((bird.x - powerup.x) ** 2 + (bird.y - powerup.y) ** 2) < bird.radius + powerup.radius) {
            powerups.splice(index, 1);
            // Apply power-up effect
        }
    });
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'green';
    pipes.forEach(pipe => {
        ctx.fillRect(pipe.x, 0, pipe.width, pipe.y);
        ctx.fillRect(pipe.x, pipe.y + pipe.height, pipe.width, canvas.height);
    });

    ctx.fillStyle = 'blue';
    powerups.forEach(powerup => {
        ctx.beginPath();
        ctx.arc(powerup.x, powerup.y, powerup.radius, 0, Math.PI * 2);
        ctx.fill();
    });

    ctx.fillStyle = 'red';
    ctx.fillRect(bird.x, bird.y, 10, 10);
}

function resetGame() {
    bird.y = canvas.height / 2;
    bird.vy = 0;
    pipes.length = 0;
    powerups.length = 0;
}

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', e => {
    if (e.code === 'Space') {
        bird.vy = flapStrength;
    }
});

gameLoop();
