function random(min, max) {
  return Math.random() * (max - min) + min;
}

function createNote() {
  const x = random(0, w);
  notes.push({ x, y: -noteSize, size: noteSize, hit: false });
}

function updateNotes(delta) {
  notes.forEach(note => {
    note.y += noteSpeed * delta;
    if (note.y > h) {
      note.hit = true; // missed note
    }
  });
}

function drawNotes() {
  ctx.fillStyle = 'red';
  notes.forEach(note => {
    ctx.beginPath();
    ctx.arc(note.x, note.y, note.size, 0, Math.PI * 2);
    ctx.fill();
  });
}

function checkTaps(event) {
  const { clientX, clientY } = event;
  const localX = clientX * devicePixelRatio;
  const localY = clientY * devicePixelRatio;

  notes.forEach(note => {
    if (!note.hit && Math.hypot(localX - note.x, localY - note.y) < tapRadius) {
      note.hit = true;
      score++;
    }
  });
}

function clearMissedNotes() {
  notes = notes.filter(note => !note.hit);
}

function updateLevel() {
  if (notes.length === 0 && Date.now() - lastNoteTime > 2000) {
    level++;
    noteInterval = Math.max(500, noteInterval - 100);
  }
}

