function updateShip() {
    if (keys[37]) ship.angle -= ship.rotationSpeed; // Left
    if (keys[39]) ship.angle += ship.rotationSpeed; // Right
    if (keys[38]) ship.speed = Math.min(ship.speed + 0.1, ship.maxSpeed); // Up
    if (keys[40]) ship.speed = Math.max(ship.speed - 0.1, 0); // Down
    ship.x += Math.cos(ship.angle) * ship.speed;
    ship.y += Math.sin(ship.angle) * ship.speed;
    ship.x = (ship.x + canvas.width) % canvas.width;
    ship.y = (ship.y + canvas.height) % canvas.height;
    if (keys[32] && ship.bullets.length < 10) { // Space
        ship.bullets.push({
