class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(listener);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(data));
        }
    }
}

class Crafting {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('recipeFulfilled', this.onRecipeFulfilled.bind(this));
    }

    craft(recipeName) {
        this.eventBus.emit('craftRequest', { recipeName });
    }

    onRecipeFulfilled(recipe) {
        console.log(`Crafted: ${recipe.name}`);
    }
}

class Recipe {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.recipes = {
            'Sword': { ingredients: { 'Wood': 2, 'Stone': 1 } },
            'Shield': { ingredients: { 'Wood': 1, 'Leather': 1 } }
        };
        this.eventBus.subscribe('craftRequest', this.onCraftRequest.bind(this));
    }

    onCraftRequest(request) {
        const recipe = this.recipes[request.recipeName];
        if (recipe) {
            this.eventBus.emit('checkInventory', { ingredients: recipe.ingredients });
        } else {
            console.log(`Recipe not found: ${request.recipeName}`);
        }
    }

    fulfillRecipe(recipeName) {
        this.eventBus.emit('recipeFulfilled', this.recipes[recipeName]);
    }
}

class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = { 'Wood': 10, 'Stone': 5, 'Leather': 3 };
        this.eventBus.subscribe('checkInventory', this.onCheckInventory.bind(this));
    }

    onCheckInventory(request) {
        let canCraft = true;
        for (const [item, quantity] of Object.entries(request.ingredients)) {
            if (!this.items[item] || this.items[item] < quantity) {
                canCraft = false;
                console.log(`Not enough ${item} to craft.`);
                break;
            }
        }
        if (canCraft) {
            this.deductIngredients(request.ingredients);
            this.eventBus.emit('recipeFulfilled', request.recipeName);
        }
    }

    deductIngredients(ingredients) {
        for (const [item, quantity] of Object.entries(ingredients)) {
            this.items[item] -= quantity;
        }
    }
}

// Demo
const eventBus = new EventBus();
const crafting = new Crafting(eventBus);
const recipe = new Recipe(eventBus);
const inventory = new Inventory(eventBus);

crafting.craft('Sword'); // Should output: Not enough Stone to craft.
crafting.craft('Shield'); // Should output: Crafted: Shield
