// Maze Chase Game with High-Score

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
let ctx = canvas.getContext('2d');

let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore')) : 0;

const devicePixelRatio = window.devicePixelRatio || 1;
canvas.width = window.innerWidth * devicePixelRatio;
canvas.height = window.innerHeight * devicePixelRatio;
ctx.scale(devicePixelRatio, devicePixelRatio);

const mazeSize = 20;
const cellSize = Math.min(canvas.width, canvas.height) / mazeSize;
const player = { x: mazeSize / 2, y: mazeSize / 2, size: cellSize / 2, speed: 2 };
const goal = { x: mazeSize - 1, y: 0, size: cellSize / 2 };
let score = 0;
let gameOver = false;

function generateMaze() {
    const maze = Array.from({ length: mazeSize }, () => Array(mazeSize).fill(1));
    const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    function carve(x, y) {
        maze[y][x] = 0;
        directions.sort(() => Math.random() - 0.5);
        directions.forEach(([dx, dy]) => {
            const nx = x + dx * 2, ny = y + dy * 2;
            if (nx > 0 && nx < mazeSize - 1 && ny > 0 && ny < mazeSize - 1 && maze[ny][nx] === 1) {
                maze[y + dy][x + dx] = 0;
                carve(nx, ny);
            }
        });
    }
    carve(1, 1);
    return maze;
}

const maze = generateMaze();

function drawMaze() {
    ctx.fillStyle = 'black';
    for (let y = 0; y < mazeSize; y++) {
        for (let x = 0; x < mazeSize; x++) {
            if (maze[y][x]) {
                ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            }
        }
    }
}

function drawPlayer() {
    ctx.fillStyle = 'green';
    ctx.fillRect(player.x * cellSize + cellSize / 4, player.y * cellSize + cellSize / 4, player.size, player.size);
}

function drawGoal() {
    ctx.fillStyle = 'red';
    ctx.fillRect(goal.x * cellSize + cellSize / 4, goal.y * cellSize + cellSize / 4, goal.size, goal.size);
}

function drawScore() {
    ctx.fillStyle = 'white';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

function checkCollision() {
    if (player.x === goal.x && player.y === goal.y) {
        score++;
        if (score > highScore) {
            highScore = score;
            localStorage.setItem('highScore', highScore);
        }
        goal.x = Math.floor(Math.random() * mazeSize);
        goal.y = Math.floor(Math.random() * mazeSize);
        while (maze[goal.y][goal.x] === 1) {
            goal.x = Math.floor(Math.random() * mazeSize);
            goal.y = Math.floor(Math.random() * mazeSize);
        }
    }
}

function update() {
    if (gameOver) return;
    let dx = 0, dy = 0;
    if (keys['ArrowUp']) dy = -1;
    if (keys['ArrowDown']) dy = 1;
    if (keys['ArrowLeft']) dx = -1;
    if (keys['ArrowRight']) dx = 1;
    const nx = player.x + dx, ny = player.y + dy;
    if (nx >= 0 && nx < mazeSize && ny >= 0 && ny < mazeSize && maze[ny][nx] === 0) {
        player.x = nx;
        player.y = ny;
    }
    checkCollision();
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawMaze();
    drawPlayer();
    drawGoal();
    drawScore();
}

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

function gameLoop() {
    update();
    render();
    if (!gameOver) requestAnimationFrame(gameLoop);
}

gameLoop();
