const canvas = document.createElement('canvas');
canvas.width = 600;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const GRID_SIZE = 8;
const BLOCK_SIZE = canvas.width / GRID_SIZE;
const COLORS = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF'];

let board = Array.from({ length: GRID_SIZE }, () =>
  Array.from({ length: GRID_SIZE }, () =>
    Math.floor(Math.random() * COLORS.length)
  )
);

let selected = null;
let toSwap = null;
let score = 0;
let frame = 0;
const fixedTimestep = 1000 / 60;

function update() {
  if (toSwap) {
    const [x1, y1] = selected;
    const [x2, y2] = toSwap;
    [board[x1][y1], board[x2][y2]] = [board[x2][y2], board[x1][y1]];
    selected = null;
    toSwap = null;
    if (!matches()) {
      [board[x1][y1], board[x2][y2]] = [board[x2][y2], board[x1][y1]];
    }
  }
  removeMatches();
  dropBlocks();
  if (matches()) {
    update();
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let y = 0; y < GRID_SIZE; y++) {
    for (let x = 0; x < GRID_SIZE; x++) {
      ctx.fillStyle = COLORS[board[x][y]];
      ctx.fillRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
      ctx.strokeStyle = '#000';
      ctx.strokeRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
    }
  }
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function matches() {
  let found = false;
  for (let y = 0; y < GRID_SIZE; y++) {
    for (let x = 0; x < GRID_SIZE; x++) {
      if (x < GRID_SIZE - 2 && board[x][y] === board[x + 1][y] && board[x][y] === board[x + 2][y]) {
        found = true;
      }
      if (y < GRID_SIZE - 2 && board[x][y] === board[x][y + 1] && board[x][y] === board[x][y + 2]) {
        found = true;
      }
    }
  }
  return found;
}

function removeMatches() {
  for (let y = 0; y < GRID_SIZE; y++) {
    for (let x = 0; x < GRID_SIZE; x++) {
      if (x < GRID_SIZE - 2 && board[x][y] === board[x + 1][y] && board[x][y] === board[x + 2][y]) {
        score += 3;
        board[x][y] = board[x + 1][y] = board[x + 2][y] = -1;
      }
      if (y < GRID_SIZE - 2 && board[x][y] === board[x][y + 1] && board[x][y] === board[x][y + 2]) {
        score += 3;
        board[x][y] = board[x][y + 1] = board[x][y + 2] = -1;
      }
    }
  }
}

function dropBlocks() {
  for (let x = 0; x < GRID_SIZE; x++) {
    let empty = 0;
    for (let y = GRID_SIZE - 1; y >= 0; y--) {
      if (board[x][y] === -1) {
        empty++;
      } else if (empty > 0) {
        board[x][y + empty] = board[x][y];
        board[x][y] = -1;
      }
    }
  }
}

function select(x, y) {
  if (selected) {
    toSwap = [x, y];
  } else {
    selected = [x, y];
  }
}

canvas.addEventListener('click', (e) => {
  const rect = canvas.getBoundingClientRect();
  const x = Math.floor((e.clientX - rect.left) / BLOCK_SIZE);
  const y = Math.floor((e.clientY - rect.top) / BLOCK_SIZE);
  select(x, y);
});

let keys = {};
window.addEventListener('keydown', (e) => {
  keys[e.key] = true;
});
window.addEventListener('keyup', (e) => {
  keys[e.key] = false;
});

function handleInput() {
  if (selected) {
    let [x, y] = selected;
    if (keys['ArrowUp'] && y > 0) {
      toSwap = [x, y - 1];
    } else if (keys['ArrowDown'] && y < GRID_SIZE - 1) {
      toSwap = [x, y + 1];
    } else if (keys['ArrowLeft'] && x > 0) {
      toSwap = [x - 1, y];
    } else if (keys['ArrowRight'] && x < GRID_SIZE - 1) {
      toSwap = [x + 1, y];
    }
  }
}

function gameLoop(timestamp) {
  handleInput();
  update();
  draw();
  frame += fixedTimestep;
  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
