// Recipe System
class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients;
    this.result = result;
  }

  canCraft(inventory) {
    for (const [item, count] of Object.entries(this.ingredients)) {
      if (!inventory.hasItem(item, count)) {
        return false;
      }
    }
    return true;
  }

  craft(inventory) {
    for (const [item, count] of Object.entries(this.ingredients)) {
      inventory.removeItem(item, count);
    }
    inventory.addItem(this.result, 1);
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  hasItem(item, count) {
    return (this.items[item] || 0) >= count;
  }

  addItem(item, count) {
    this.items[item] = (this.items[item] || 0) + count;
  }

  removeItem(item, count) {
    if (this.hasItem(item, count)) {
      this.items[item] -= count;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

// Crafting System
class Crafting {
  constructor() {
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) return false;
    return recipe.canCraft(inventory);
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe && recipe.canCraft(inventory)) {
      recipe.craft(inventory);
    }
  }
}

// Top-level coordinator
class GameCoordinator {
  constructor() {
    this.inventory = new Inventory();
    this.crafting = new Crafting();
  }

  addRecipe(name, ingredients, result) {
    const recipe = new Recipe(name, ingredients, result);
    this.crafting.addRecipe(recipe);
  }

  addItemToInventory(item, count) {
    this.inventory.addItem(item, count);
  }

  canCraft(recipeName) {
    return this.crafting.canCraft(recipeName, this.inventory);
  }

  craft(recipeName) {
    this.crafting.craft(recipeName, this.inventory);
  }

  getInventoryItem(item) {
    return this.inventory.getItemCount(item);
  }
}

// Demo
const game = new GameCoordinator();

// Add recipes
game.addRecipe('Wood Sword', { 'Wood': 2, 'Stone': 1 }, 'Wood Sword');
game.addRecipe('Stone Axe', { 'Stone': 3, 'Wood': 1 }, 'Stone Axe');

// Add items to inventory
game.addItemToInventory('Wood', 10);
game.addItemToInventory('Stone', 5);

// Craft an item
console.log('Crafting Wood Sword:', game.canCraft('Wood Sword')); // true
game.craft('Wood Sword');
console.log('Wood count after crafting:', game.getInventoryItem('Wood')); // 8
console.log('Wood Sword count after crafting:', game.getInventoryItem('Wood Sword')); // 1

// Try crafting an item with insufficient materials
console.log('Crafting Stone Axe:', game.canCraft('Stone Axe')); // true
game.craft('Stone Axe');
console.log('Stone count after crafting:', game.getInventoryItem('Stone')); // 2
console.log('Stone Axe count after crafting:', game.getInventoryItem('Stone Axe')); // 1

// Attempt to craft another Stone Axe with insufficient materials
console.log('Crafting another Stone Axe:', game.canCraft('Stone Axe')); // false
