const blockWidth = 30;
const blockHeight = 30;
const maxSpeed = 5;
const enemySpawnRate = 1000; // milliseconds
const difficultyIncreaseRate = 5000; // milliseconds
const maxEnemies = 5;
let speed = 1;
let lastDifficultyIncrease = Date.now();
let enemies = [];

class Block {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.width = blockWidth;
    this.height = blockHeight;
  }

  update() {
    this.y += speed;
  }

  draw() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }

  collidesWith(enemy) {
    return (this.x < enemy.x + enemy.width &&
            this.x + this.width > enemy.x &&
            this.y < enemy.y + enemy.height &&
            this.y + this.height > enemy.y);
  }
}

class Enemy {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.width = blockWidth;
    this.height = blockHeight;
  }

  update() {
    this.y += speed;
  }

  draw() {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

function spawnEnemy() {
  if (enemies.length < maxEnemies) {
    const x = Math.random() * (w - blockWidth);
    const y = -blockHeight;
    enemies.push(new Enemy(x, y));
  }
}

function update() {
  const now = Date.now();
  if (now - lastDifficultyIncrease > difficultyIncreaseRate) {
    speed = Math.min(speed + 0.5, maxSpeed);
    lastDifficultyIncrease = now;
  }

  for (let i = blocks.length - 1; i >= 0; i--) {
    blocks[i].update();
    if (blocks[i].y > h) {
      blocks.splice(i, 1);
    }
  }

  for (let i = enemies.length - 1; i >= 0; i--) {
    enemies[i].update();
    if (enemies[i].y > h) {
      enemies.splice(i, 1);
    }
  }

  for (let block of blocks) {
    for (let enemy of enemies) {
      if (block.collidesWith(enemy)) {
        blocks.splice(blocks.indexOf(block), 1);
        enemies.splice(enemies.indexOf(enemy), 1);
      }
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, w, h);
  for (let block of blocks) {
    block.draw();
  }
  for (let enemy of enemies) {
    enemy.draw();
  }
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

