const words = ["hello", "world", "javascript", "typing", "game", "speed", "pointer", "keyboard"];
let currentWordIndex = 0;
let input = '';
let startTime = null;
let endTime = null;
let isGameRunning = false;
let score = 0;
let pointerInput = false;

function startGame() {
    isGameRunning = true;
    currentWordIndex = 0;
    input = '';
    score = 0;
    startTime = performance.now();
    pointerInput = false;
}

function endGame() {
    isGameRunning = false;
    endTime = performance.now();
    alert(`Game Over! Your score: ${score} Time taken: ${(endTime - startTime) / 1000} seconds`);
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '32px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText(words[currentWordIndex], 50, 50);

    ctx.fillText(input, 50, 100);

    if (!isGameRunning) {
        ctx.fillText('Click or Tap to Start', 50, 150);
    }
}

function checkWord() {
    if (input === words[currentWordIndex]) {
        score++;
        input = '';
        currentWordIndex++;
        if (currentWordIndex >= words.length) {
            endGame();
        }
    }
}

canvas.addEventListener('click', () => {
    if (!isGameRunning) {
        startGame();
    }
});

canvas.addEventListener('touchstart', (e) => {
    e.preventDefault();
    if (!isGameRunning) {
        startGame();
    }
    pointerInput = true;
});

canvas.addEventListener('touchmove', (e) => {
    e.preventDefault();
    if (pointerInput) {
        const rect = canvas.getBoundingClientRect();
        const x = (e.touches[0].clientX - rect.left) * windowRatio;
        const y = (e.touches[0].clientY - rect.top) * windowRatio;
        input = '';
        currentWordIndex = Math.floor((y - 50) / 50);
        if (currentWordIndex >= 0 && currentWordIndex < words.length) {
            input = words[currentWordIndex];
            checkWord();
        }
    }
});

canvas.addEventListener('touchend', () => {
    pointerInput = false;
});

window.addEventListener('keydown', (e) => {
    if (isGameRunning) {
        if (e.key === 'Backspace') {
            input = input.slice(0, -1);
        } else if (e.key === 'Enter') {
            checkWord();
        } else {
            input += e.key;
        }
    }
});

function gameLoop() {
    draw();
    requestAnimationFrame(gameLoop);
}

gameLoop();
