  ctx.closePath();
  ctx.fillStyle = 'gray';
  ctx.fill();
  ctx.restore();
}

function drawBullet(bullet) {
  ctx.beginPath();
  ctx.arc(bullet.x, bullet.y, bulletSize, 0, Math.PI * 2);
  ctx.fillStyle = 'white';
  ctx.fill();
}

function drawShip() {
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.angle);
  ctx.beginPath();
  ctx.moveTo(0, -shipSize);
  ctx.lineTo(shipSize, shipSize);
  ctx.lineTo(-shipSize, shipSize);
  ctx.closePath();
  ctx.fillStyle = 'green';
  ctx.fill();
  ctx.restore();
}

function drawText(text, x, y, size = 40, color = 'white') {
  ctx.font = `${size}px Arial`;
  ctx.fillStyle = color;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, x, y);
}

function updateAsteroids() {
  asteroids.forEach(asteroid => {
    asteroid.x += Math.cos(asteroid.angle) * asteroid.speed;
    asteroid.y += Math.sin(asteroid.angle) * asteroid.speed;
    if (asteroid.x < 0) asteroid.x += width;
    if (asteroid.x > width) asteroid.x -= width;
    if (asteroid.y < 0) asteroid.y += height;
    if (asteroid.y > height) asteroid.y -= height;
  });
}

function updateBullets() {
  bullets.forEach(bullet => {
    bullet.x += Math.cos(bullet.angle) * bulletSpeed;
    bullet.y += Math.sin(bullet.angle) * bulletSpeed;
  });
  bullets = bullets.filter(bullet => bullet.x > 0 && bullet.x < width && bullet.y > 0 && bullet.y < height);
}

function updateShip() {
  ship.angle += ship.turning;
  if (ship.accelerating) {
    ship.speed = Math.min(5, ship.speed + 0.1);
  } else {
    ship.speed = Math.max(0, ship.speed - 0.05);
  }
  ship.x += Math.cos(ship.angle) * ship.speed;
  ship.y += Math.sin(ship.angle) * ship.speed;
  if (ship.x < 0) ship.x += width;
  if (ship.x > width) ship.x -= width;
  if (ship.y < 0) ship.y += height;
  if (ship.y > height) ship.y -= height;
}

function checkCollisions() {
  asteroids.forEach(asteroid => {
    if (Math.hypot(asteroid.x - ship.x, asteroid.y - ship.y) < asteroid.size / 2 + shipSize / 2) {
      lives--;
      resetShip();
    }
  });

  bullets.forEach(bullet => {
    asteroids = asteroids.filter(asteroid => {
      if (Math.hypot(asteroid.x - bullet.x, asteroid.y - bullet.y) < asteroid.size / 2 + bulletSize / 2) {
        score += 10;
        return false;
      }
      return true;
    });
  });
}

function resetShip() {
  ship.x = width / 2;
  ship.y = height / 2;
  ship.angle = Math.PI / 2;
  ship.speed = 0;
}

function draw() {
  ctx.clearRect(0, 0, width, height);

  switch (currentState) {
    case states.menu:
      drawText('Asteroids', width / 2, height / 2 - 40, 60);
      drawText('Press Space to Start', width / 2, height / 2 + 40);
      break;
    case states.playing:
      updateShip();
      updateAsteroids();
      updateBullets();
      checkCollisions();
      if (lives <= 0) {
        currentState = states.gameover;
      }
      ctx.fillText(`Score: ${score}`, 10, 20);
      ctx.fillText(`Lives: ${lives}`, 10, 40);
      drawShip();
      asteroids.forEach(drawAsteroid);
      bullets.forEach(drawBullet);
      break;
    case states.paused:
      drawText('Paused', width / 2, height / 2, 60);
      break;
    case states.gameover:
      drawText('Game Over', width / 2, height / 2 - 40, 60);
      drawText(`Score: ${score}`, width / 2, height / 2 + 20, 40);
      drawText('Press Space to Restart', width / 2, height / 2 + 60);
      break;
  }
}

function update() {
  draw();
  requestAnimationFrame(update);
}

function handleKeyDown(e) {
  switch (currentState) {
    case states.menu:
      if (e.key === ' ') {
        currentState = states.playing;
      }
      break;
    case states.playing:
      if (e.key === 'ArrowLeft') {
        ship.turning = -0.1;
      } else if (e.key === 'ArrowRight') {
        ship.turning = 0.1;
      } else if (e.key === 'ArrowUp') {
        ship.accelerating = true;
      } else if (e.key === ' ') {
        bullets.push({
          x: ship.x + Math.cos(ship.angle) * shipSize,
          y: ship.y + Math.sin(ship.angle) * shipSize,
          angle: ship.angle
        });
      } else if (e.key === 'Escape') {
        currentState = states.paused;
      }
      break;
    case states.paused:
      if (e.key === 'Escape') {
        currentState = states.playing;
      }
      break;
    case states.gameover:
      if (e.key === ' ') {
        currentState = states.menu;
        resetGame();
      }
      break;
  }
}

function handleKeyUp(e) {
  if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
    ship.turning = 0;
  } else if (e.key === 'ArrowUp') {
    ship.accelerating = false;
  }
}

document.addEventListener('keydown', handleKeyDown);
document.addEventListener('keyup', handleKeyUp);

window.addEventListener('resize', () => {
  width = window.innerWidth;
  height = window.innerHeight;
  canvas.width = width * devicePixelRatio;
  canvas.height = height * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
});

resetGame();
update();
