class Wallet {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    getBalance() {
        return this.balance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }
}

class Shop {
    constructor() {
        this.items = {
            sword: { price: 50, quantity: 10 },
            shield: { price: 30, quantity: 15 },
            potion: { price: 20, quantity: 20 }
        };
    }

    getItemPrice(itemName) {
        return this.items[itemName]?.price || 0;
    }

    getItemQuantity(itemName) {
        return this.items[itemName]?.quantity || 0;
    }

    purchaseItem(itemName, quantity) {
        const item = this.items[itemName];
        if (item && quantity > 0 && item.quantity >= quantity) {
            item.quantity -= quantity;
            return true;
        }
        return false;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(itemName, quantity) {
        if (quantity > 0) {
            if (this.items[itemName]) {
                this.items[itemName] += quantity;
            } else {
                this.items[itemName] = quantity;
            }
            return true;
        }
        return false;
    }

    getItemCount(itemName) {
        return this.items[itemName] || 0;
    }
}

class Coordinator {
    constructor(wallet, shop, inventory) {
        this.wallet = wallet;
        this.shop = shop;
        this.inventory = inventory;
    }

