    console.log(`${characterName} joined faction ${factionName}.`);
    this.reputationSystem.changeReputation(characterName, 10); // +10 rep for joining a faction
  }

  leaveFaction(characterName, factionName) {
    console.log(`${characterName} left faction ${factionName}.`);
    this.reputationSystem.changeReputation(characterName, -10); // -10 rep for leaving a faction
  }
}

