// Turn-based tactics duel with a scoring system and a game-over state.
// Render on an HTML5 canvas with a fixed timestep main loop.

// Canvas setup
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game state
const gameState = {
  turn: 1,
  playerHealth: 100,
  enemyHealth: 100,
  gameOver: false
};

// Constants
const TPS = 30; // Ticks Per Second
const FIXED_TIME_STEP = 1000 / TPS;
let lastTimestamp = 0;
let accumulator = 0;

// Player and enemy actions
function playerAttack() {
  gameState.enemyHealth -= 10;
}

function enemyAttack() {
  gameState.playerHealth -= 15;
}

// Game loop
function gameLoop(timestamp) {
  const frameTime = timestamp - lastTimestamp;
  lastTimestamp = timestamp;
  accumulator += frameTime;

  while (accumulator >= FIXED_TIME_STEP) {
    update();
    accumulator -= FIXED_TIME_STEP;
  }

  render();
  if (!gameState.gameOver) {
    requestAnimationFrame(gameLoop);
  }
}

// Update game state
function update() {
  if (gameState.turn % 2 !== 0) {
    playerAttack();
  } else {
    enemyAttack();
  }

  gameState.turn++;
  if (gameState.playerHealth <= 0 || gameState.enemyHealth <= 0) {
    gameState.gameOver = true;
  }
}

// Render game state
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player health bar
  ctx.fillStyle = 'green';
  ctx.fillRect(50, 50, gameState.playerHealth * 4, 30);
  ctx.strokeRect(50, 50, 400, 30);

  // Draw enemy health bar
  ctx.fillStyle = 'red';
  ctx.fillRect(50, 100, gameState.enemyHealth * 4, 30);
  ctx.strokeRect(50, 100, 400, 30);

  // Game over message
  if (gameState.gameOver) {
    ctx.font = '48px Arial';
    ctx.fillStyle = 'black';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over!', canvas.width / 2, canvas.height / 2);
  }
}

// Start the game loop
requestAnimationFrame(gameLoop);
