class Recipe {
    constructor(name, ingredients, result) {
        this.name = name;
        this.ingredients = ingredients; // { item: quantity }
        this.result = result; // { item: quantity }
    }
}

class Crafting {
    constructor(recipes) {
        this.recipes = recipes;
    }

    canCraft(recipeName, inventory) {
        const recipe = this.recipes.find(r => r.name === recipeName);
        if (!recipe) return false;

        for (const [item, quantity] of Object.entries(recipe.ingredients)) {
            if ((inventory[item] || 0) < quantity) return false;
        }
        return true;
    }

    craft(recipeName, inventory) {
        const recipe = this.recipes.find(r => r.name === recipeName);
        if (!recipe) return null;

        for (const [item, quantity] of Object.entries(recipe.ingredients)) {
            inventory[item] = (inventory[item] || 0) - quantity;
        }
        return recipe.result;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        this.items[item] = (this.items[item] || 0) + quantity;
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }
}

class Economy {
    constructor(prices) {
        this.prices = prices;
    }

    getPrice(item) {
        return this.prices[item] || 0;
    }

    debit(item, quantity) {
        const price = this.getPrice(item);
        if (price * quantity > this.prices[item]) {
            return false; // Not enough funds
        }
        this.prices[item] -= price * quantity;
        return true;
    }
}

class Store {
    constructor(economy, inventory) {
        this.economy = economy;
        this.inventory = inventory;
    }

    purchase(item, quantity) {
        const price = this.economy.getPrice(item);
        if (price * quantity > this.economy.getPrice(item)) {
            console.log(`Insufficient funds for ${item}`);
            return false;
        }

        if (!this.economy.debit(item, quantity)) {
            console.log(`Failed to debit ${item} from economy`);
            return false;
        }

        this.inventory.addItem(item, quantity);
        console.log(`Purchased ${quantity} ${item}(s), added to inventory`);
        return true;
    }
}

