// Card-Flip Memory Game with Basic AI Opponent
// Rendered on an HTML5 Canvas
// Deterministic main loop with fixed timestep

const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;

const cardWidth = 100;
const cardHeight = 150;
const padding = 10;
const gridCols = 4;
const gridRows = 3;
const totalCards = gridCols * gridRows;
const cardImages = [];
let cards = [];
let flippedCards = [];
let playerScore = 0;
let aiScore = 0;
let aiTurn = false;
let lastFlipTime = performance.now();
const fixedTimestep = 16.666; // Approximately 60 FPS

// Load card images
for (let i = 0; i < totalCards / 2; i++) {
    cardImages.push(new Image());
    cardImages[i].src = `https://picsum.photos/id/${i + 1}/100/150`;
}

// Initialize cards
function initCards() {
    let indices = [];
    for (let i = 0; i < totalCards; i++) {
        indices.push(i);
    }
    indices.sort(() => Math.random() - 0.5);

    cards = indices.map((index) => ({
        image: cardImages[Math.floor(index / 2)],
        flipped: false,
        matched: false,
        x: (index % gridCols) * (cardWidth + padding),
        y: Math.floor(index / gridCols) * (cardHeight + padding)
    }));
}

// Flip a card
function flipCard(index) {
    if (flippedCards.length >= 2 || cards[index].flipped || cards[index].matched || aiTurn) return;
    cards[index].flipped = true;
    flippedCards.push(index);

    if (flippedCards.length === 2) {
        checkMatch();
    }
}

// Check if two flipped cards match
function checkMatch() {
    const [index1, index2] = flippedCards;
    if (cards[index1].image === cards[index2].image) {
        cards[index1].matched = true;
        cards[index2].matched = true;
        playerScore++;
    } else {
        aiTurn = true;
    }
    setTimeout(() => {
        cards[index1].flipped = false;
        cards[index2].flipped = false;
        flippedCards = [];
        if (aiTurn) {
            aiTurn = false;
            aiFlip();
        }
    }, 1000);
}

// AI flip a card
function aiFlip() {
    const availableCards = cards.filter(card => !card.flipped && !card.matched);
    if (availableCards.length > 0) {
        const randomIndex = Math.floor(Math.random() * availableCards.length);
        flipCard(cards.indexOf(availableCards[randomIndex]));
    }
}

// Draw the game
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    cards.forEach(card => {
        if (card.flipped || card.matched) {
            ctx.drawImage(card.image, card.x, card.y, cardWidth, cardHeight);
        } else {
            ctx.fillStyle = '#ccc';
            ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
            ctx.strokeRect(card.x, card.y, cardWidth, cardHeight);
        }
    });
    ctx.fillStyle = '#000';
    ctx.font = '24px Arial';
    ctx.fillText(`Player Score: ${playerScore}`, 10, 30);
    ctx.fillText(`AI Score: ${aiScore}`, 10, 60);
}

// Game loop with fixed timestep
function gameLoop() {
    const now = performance.now();
    const deltaTime = now - lastFlipTime;

    if (deltaTime >= fixedTimestep) {
        lastFlipTime = now - (deltaTime % fixedTimestep);
        draw();
    }

    requestAnimationFrame(gameLoop);
}

// Start the game
initCards();
gameLoop();

// Event listener for card clicks
canvas.addEventListener('click', (event) => {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    for (let i = 0; i < cards.length; i++) {
        if (x > cards[i].x && x < cards[i].x + cardWidth &&
            y > cards[i].y && y < cards[i].y + cardHeight) {
            flipCard(i);
            break;
        }
    }
});
