class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices) {
    this.prices = prices;
  }

  buy(item, bank) {
    const price = this.prices[item];
    if (price && bank.withdraw(price)) {
      return { success: true, item, price };
    }
    return { success: false };
  }

  sell(item, bank) {
    const price = this.prices[item];
    if (price && bank.deposit(price)) {
      return { success: true, item, price };
    }
    return { success: false };
  }

  getPrice(item) {
    return this.prices[item];
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

class GameCoordinator {
  constructor() {
    this.bank = new Bank();
    this.market = new Market({ apple: 5, banana: 3, orange: 4 });
    this.inventory = new Inventory();
  }

