    const result = this.market.buy(item, this.bank);
    if (result.success) {
      this.inventory.addItem(item);
      console.log(`Bought ${item} for ${result.price}. Balance: ${this.bank.getBalance()}`);
    } else {
      console.log(`Failed to buy ${item}. Not enough money or item not available.`);
    }
  }

  sellItem(item) {
    const result = this.market.sell(item, this.bank);
    if (result.success) {
      this.inventory.removeItem(item);
      console.log(`Sold ${item} for ${result.price}. Balance: ${this.bank.getBalance()}`);
    } else {
      console.log(`Failed to sell ${item}. Item not in inventory.`);
    }
  }

  checkInventory() {
    console.log('Current Inventory:', this.inventory.getInventory());
  }

  checkBalance() {
    console.log('Current Balance:', this.bank.getBalance());
  }
}

// Demo
