    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            if (board[y][x] === 0) {
                emptyCells.push({ y, x });
            }
        }
    }
    if (emptyCells.length > 0) {
        const { y, x } = emptyCells[getRandomInt(emptyCells.length)];
        powerUps.push({ y, x, type: getRandomInt(2) === 0 ? 'double' : 'clear' });
