}

function moveBoard(dir) {
    let moved = false;
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            if (board[y][x] !== 0) {
                let targetX = x, targetY = y;
                while (true) {
                    switch (dir) {
                        case 'ArrowLeft':
                            if (targetX > 0 && board[targetY][targetX - 1] === 0) {
                                targetX--;
                                moved = true;
                            } else if (targetX > 0 && board[targetY][targetX - 1] === board[targetY][targetX]) {
                                board[targetY][targetX - 1] *= 2;
                                score += board[targetY][targetX - 1];
                                board[targetY][targetX] = 0;
                                moved = true;
                            }
                            break;
                        case 'ArrowRight':
                            if (targetX < boardSize - 1 && board[targetY][targetX + 1] === 0) {
                                targetX++;
                                moved = true;
                            } else if (targetX < boardSize - 1 && board[targetY][targetX + 1] === board[targetY][targetX]) {
                                board[targetY][targetX + 1] *= 2;
                                score += board[targetY][targetX + 1];
                                board[targetY][targetX] = 0;
                                moved = true;
                            }
                            break;
                        case 'ArrowUp':
                            if (targetY > 0 && board[targetY - 1][targetX] === 0) {
                                targetY--;
                                moved = true;
                            } else if (targetY > 0 && board[targetY - 1][targetX] === board[targetY][targetX]) {
                                board[targetY - 1][targetX] *= 2;
                                score += board[targetY - 1][targetX];
                                board[targetY][targetX] = 0;
                                moved = true;
                            }
                            break;
                        case 'ArrowDown':
                            if (targetY < boardSize - 1 && board[targetY + 1][targetX] === 0) {
                                targetY++;
                                moved = true;
                            } else if (targetY < boardSize - 1 && board[targetY + 1][targetX] === board[targetY][targetX]) {
                                board[targetY + 1][targetX] *= 2;
                                score += board[targetY + 1][targetX];
                                board[targetY][targetX] = 0;
                                moved = true;
                            }
                            break;
                    }
                    if (board[targetY][targetX] === 0 || !moved) {
                        break;
                    }
                }
                board[targetY][targetX] = board[y][x];
                if (targetX !== x || targetY !== y) {
                    board[y][x] = 0;
                }
            }
        }
    }
    return moved;
}

function handlePowerUps() {
    powerUps.forEach((powerUp, index) => {
        if (powerUp.type === 'double') {
            board[powerUp.y][powerUp.x] *= 2;
            score += board[powerUp.y][powerUp.x];
        } else if (powerUp.type === 'clear') {
            board[powerUp.y][powerUp.x] = 0;
        }
        powerUps.splice(index, 1);
    });
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            ctx.fillStyle = board[y][x] === 0 ? '#ccc' : `hsl(${Math.log2(board[y][x]) * 30}, 100%, 50%)`;
            ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
            ctx.fillStyle = '#000';
            ctx.font = 'bold 24px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            if (board[y][x] !== 0) {
                ctx.fillText(board[y][x], x * tileSize + tileSize / 2, y * tileSize + tileSize / 2);
            }
        }
    }
    powerUps.forEach(powerUp => {
        ctx.fillStyle = powerUp.type === 'double' ? 'blue' : 'green';
        ctx.fillRect(powerUp.x * tileSize + 20, powerUp.y * tileSize + 20, 60, 60);
    });
    ctx.fillStyle = '#000';
    ctx.font = 'bold 24px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 30);
}

function gameLoop() {
    drawBoard();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    if (moveBoard(e.key)) {
        spawnTile();
        spawnPowerUp();
    }
    handlePowerUps();
});

spawnTile();
spawnTile();
spawnPowerUp();

gameLoop();
