canvas.width = 400;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const bird = {
  x: 50,
  y: canvas.height / 2,
  width: 20,
  height: 20,
  velocity: 0,
  gravity: 0.5,
  flapPower: -10,
  jump() {
    this.velocity = this.flapPower;
  }
};

const pipes = [];
const pipeWidth = 50;
const pipeGap = 150;
let level = 1;
let score = 0;

function generatePipe() {
  const height = Math.random() * (canvas.height - pipeGap);
  pipes.push({
    x: canvas.width,
    y: height,
    width: pipeWidth,
    height: height,
    pass() {
      score++;
      level++;
    }
  });
}

function updatePipes() {
  pipes.forEach(pipe => {
    pipe.x -= 2 + level * 0.1;
    if (pipe.x < -pipeWidth) {
      pipes.shift();
    }
  });
}

function drawPipes() {
  pipes.forEach(pipe => {
    ctx.fillStyle = 'green';
    ctx.fillRect(pipe.x, 0, pipe.width, pipe.y);
    ctx.fillRect(pipe.x, pipe.y + pipeGap, pipe.width, canvas.height);
  });
}

function checkCollision() {
  if (bird.y + bird.height > canvas.height || bird.y < 0) {
    return true;
  }
  for (const pipe of pipes) {
    if (bird.x < pipe.x + pipe.width &&
        bird.x + bird.width > pipe.x &&
        (bird.y < pipe.y || bird.y + bird.height > pipe.y + pipeGap)) {
      return true;
    }
  }
  return false;
}

function drawBird() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(bird.x, bird.y, bird.width, bird.height);
}

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function drawLevel() {
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Level: ${level}`, 10, 60);
}

let lastTime = 0;
const fixedTimeStep = 1000 / 60;

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  lastTime = timestamp;

  bird.velocity += bird.gravity;
  bird.y += bird.velocity;

  if (pipes.length === 0 || pipes[pipes.length - 1].x < canvas.width - 200) {
    generatePipe();
  }

  updatePipes();
  pipes.forEach(pipe => {
    if (bird.x > pipe.x + pipe.width && !pipe.passed) {
      pipe.pass();
      pipe.passed = true;
    }
  });

  if (checkCollision()) {
    alert(`Game Over! Your score: ${score}`);
    document.location.reload();
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawPipes();
  drawBird();
  drawScore();
  drawLevel();

  if (deltaTime >= fixedTimeStep) {
    window.requestAnimationFrame(gameLoop);
  }
}

window.addEventListener('keydown', e => {
  if (e.code === 'Space') {
    bird.jump();
  }
});

window.requestAnimationFrame(gameLoop);
