  x: canvas.width / 2,
  y: canvas.height / 2,
  width: 10,
  height: 10,
  speedX: 2,
  speedY: 2,
  caught: false
};

function drawRect(x, y, width, height, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x, y, width, height);
}

function drawFish() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(fish.x, fish.y, fish.width, fish.height);
}

function updatePlayer(keys) {
  if (keys.ArrowUp && player.y > 0) player.y -= player.speed;
  if (keys.ArrowDown && player.y < canvas.height - player.height) player.y += player.speed;
}

function updateAI() {
  if (ai.y > fish.y && ai.y > 0) ai.y -= ai.speed;
  if (ai.y < fish.y && ai.y < canvas.height - ai.height) ai.y += ai.speed;
}

function updateFish() {
  fish.x += fish.speedX;
  fish.y += fish.speedY;

  if (fish.x <= 0 || fish.x >= canvas.width - fish.width) fish.speedX *= -1;
  if (fish.y <= 0 || fish.y >= canvas.height - fish.height) fish.speedY *= -1;
}

function checkCatch(player, fish) {
  if (player.catchCooldown > 0) {
    player.catchCooldown--;
    return;
  }

  if (player.x < fish.x + fish.width &&
      player.x + player.width > fish.x &&
      player.y < fish.y + fish.height &&
      player.y + player.height > fish.y) {
    fish.caught = true;
    player.catchCooldown = 60; // Cooldown time
  }
}

function checkAICatch(ai, fish) {
  if (ai.catchCooldown > 0) {
    ai.catchCooldown--;
    return;
  }

  if (ai.x < fish.x + fish.width &&
      ai.x + ai.width > fish.x &&
      ai.y < fish.y + fish.height &&
      ai.y + ai.height > fish.y) {
    fish.caught = true;
    ai.catchCooldown = 60; // Cooldown time
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawRect(player.x, player.y, player.width, player.height, 'green');
  drawRect(ai.x, ai.y, ai.width, ai.height, 'red');
  drawFish();

  requestAnimationFrame(draw);
}

function gameLoop(keys) {
  updatePlayer(keys);
  updateAI();
  updateFish();
  checkCatch(player, fish);
  checkAICatch(ai, fish);

  draw();
}

