    console.log(`Eaten. Hunger level: ${this.level}`);
  }

  consume(amount = 10) {
    this.level = Math.max(this.level - amount, 0);
    console.log(`Consumed. Hunger level: ${this.level}`);
  }

  getLevel() {
    return this.level;
  }
}

class Energy {
  constructor() {
    this.level = 100; // Max energy level
  }

  rest(amount = 20) {
    this.level = Math.min(this.level + amount, 100);
    console.log(`Rested. Energy level: ${this.level}`);
  }

  spend(amount = 10) {
    this.level = Math.max(this.level - amount, 0);
    console.log(`Spent. Energy level: ${this.level}`);
  }

  getLevel() {
    return this.level;
  }
}

class Clock {
