class Building {
  constructor(name, constructionTime) {
    this.name = name;
    this.constructionTime = constructionTime;
    this.progress = 0;
  }

  updateProgress(time) {
    this.progress += time;
    return this.progress >= this.constructionTime;
  }

  getName() {
    return this.name;
  }
}

class Resource {
  constructor(name, amount) {
    this.name = name;
    this.amount = amount;
  }

  addResource(amount) {
    this.amount += amount;
  }

  removeResource(amount) {
    if (this.amount >= amount) {
      this.amount -= amount;
      return true;
    }
    return false;
  }

  getResourceAmount() {
    return this.amount;
  }
}

class Economy {
  constructor() {
    this.resources = {
      wood: new Resource('Wood', 100),
      gold: new Resource('Gold', 50)
    };
  }

  gatherResource(resourceName, amount) {
    if (this.resources[resourceName]) {
      this.resources[resourceName].addResource(amount);
      return true;
    }
    return false;
  }

  spendResource(resourceName, amount) {
    if (this.resources[resourceName]) {
      return this.resources[resourceName].removeResource(amount);
    }
    return false;
  }

  getResourceAmount(resourceName) {
    if (this.resources[resourceName]) {
      return this.resources[resourceName].getResourceAmount();
    }
    return 0;
  }
}

class Coordinator {
  constructor() {
    this.buildings = [];
    this.economy = new Economy();
  }

  addBuilding(building) {
    this.buildings.push(building);
  }

  update(time) {
    this.buildings.forEach(building => {
      if (building.updateProgress(time)) {
        console.log(`Building ${building.getName()} completed!`);
        // Assuming building completion adds resources
        if (building.name === 'Wood Mill') {
          this.economy.gatherResource('wood', 10);
        } else if (building.name === 'Gold Mine') {
          this.economy.gatherResource('gold', 5);
        }
      }
    });
  }

  reportResources() {
    console.log(`Wood: ${this.economy.getResourceAmount('wood')}`);
    console.log(`Gold: ${this.economy.getResourceAmount('gold')}`);
  }
}

