class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemAdded', this.onItemAdded.bind(this));
    this.eventBus.subscribe('itemUsed', this.onItemUsed.bind(this));
  }

  addItem(item, quantity) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item] += quantity;
    this.eventBus.emit('itemAdded', { item, quantity });
  }

  removeItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      this.eventBus.emit('itemUsed', { item, quantity });
    } else {
      console.log(`Not enough ${item} in inventory.`);
    }
  }

  onItemAdded(data) {
    console.log(`Added ${data.quantity} ${data.item} to inventory.`);
  }

  onItemUsed(data) {
    console.log(`Used ${data.quantity} ${data.item} from inventory.`);
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('craftItem', this.onCraftItem.bind(this));
  }

  addRecipe(result, ingredients) {
    this.recipes[result] = ingredients;
  }

  craftItem(result) {
    const ingredients = this.recipes[result];
    if (ingredients) {
      const hasIngredients = Object.keys(ingredients).every(item => {
        return this.eventBus.emit('checkInventory', { item, quantity: ingredients[item] });
      });
      if (hasIngredients) {
        Object.keys(ingredients).forEach(item => {
          this.eventBus.emit('removeItem', { item, quantity: ingredients[item] });
        });
        this.eventBus.emit('addItem', { item: result, quantity: 1 });
        console.log(`Crafted ${result}.`);
      } else {
        console.log(`Missing ingredients to craft ${result}.`);
      }
    } else {
      console.log(`No recipe found for ${result}.`);
    }
  }

  onCraftItem(data) {
    this.craftItem(data.item);
  }
}

class Crafting {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('addItem', this.onAddItem.bind(this));
    this.eventBus.subscribe('removeItem', this.onRemoveItem.bind(this));
    this.eventBus.subscribe('checkInventory', this.onCheckInventory.bind(this));
  }

  onAddItem(data) {
    this.eventBus.emit('addItem', data);
  }

  onRemoveItem(data) {
    this.eventBus.emit('removeItem', data);
  }

  onCheckInventory(data) {
    return this.eventBus.emit('checkInventory', data);
  }
}

// Demo
const eventBus = new EventBus();
const inventory = new Inventory(eventBus);
const recipe = new Recipe(eventBus);
const crafting = new Crafting(eventBus);

recipe.addRecipe('sword', { iron: 2, wood: 1 });

inventory.addItem('iron', 5);
inventory.addItem('wood', 3);

crafting.onAddItem = inventory.addItem.bind(inventory);
crafting.onRemoveItem = inventory.removeItem.bind(inventory);
crafting.onCheckInventory = (data) => inventory.items[data.item] >= data.quantity;

crafting.onCraftItem({ item: 'sword' });

console.log('Final Inventory:', inventory.items);
