class LevelUp {
  constructor(experienceSystem, skillSystem) {
    this.experienceSystem = experienceSystem;
    this.skillSystem = skillSystem;
    this.experienceThresholds = [10, 20, 30, 40, 50]; // Example thresholds for each level
  }

  checkForLevelUp() {
    const currentExperience = this.experienceSystem.getTotalExperience();
    const currentLevel = this.skillSystem.getLevel();

    if (currentExperience >= this.experienceThresholds[currentLevel - 1]) {
      this.skillSystem.levelUp();
      console.log(`Level up! New level: ${this.skillSystem.getLevel()}`);
    }
  }
}

