    this.experienceSystem.notifyExperienceGained = (amount) => {
      this.experienceSystem.addExperience(amount);
      this.levelUpSystem.checkForLevelUp();
    };
  }

  // Public API to add experience
  addExperience(amount) {
    this.experienceSystem.notifyExperienceGained(amount);
  }

