const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const tileWidth = 32;
const tileHeight = 32;
const mapWidth = canvas.width / tileWidth;
const mapHeight = canvas.height / tileHeight;

const states = {
  MENU: 'menu',
  PLAYING: 'playing',
  PAUSED: 'paused',
  GAMEOVER: 'gameover'
};

let currentState = states.MENU;

const map = Array.from({ length: mapHeight }, () =>
  Array.from({ length: mapWidth }, () => Math.random() > 0.7 ? 1 : 0)
);

const player = {
  x: mapWidth / 2,
  y: mapHeight / 2
};

const fps = 30;
const frameDuration = 1000 / fps;

let lastFrameTime = performance.now();

function drawMap() {
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  for (let y = 0; y < mapHeight; y++) {
    for (let x = 0; x < mapWidth; x++) {
      if (map[y][x] === 1) {
        ctx.fillStyle = '#333';
        ctx.fillRect(x * tileWidth, y * tileHeight, tileWidth, tileHeight);
      }
    }
  }

  ctx.fillStyle = '#fff';
  ctx.fillRect(player.x * tileWidth, player.y * tileHeight, tileWidth, tileHeight);
}

function updatePlayer() {
  if (keys['ArrowLeft']) player.x = Math.max(0, player.x - 1);
  if (keys['ArrowRight']) player.x = Math.min(mapWidth - 1, player.x + 1);
  if (keys['ArrowUp']) player.y = Math.max(0, player.y - 1);
  if (keys['ArrowDown']) player.y = Math.min(mapHeight - 1, player.y + 1);
}

const keys = {};

document.addEventListener('keydown', (e) => {
  keys[e.key] = true;
});

document.addEventListener('keyup', (e) => {
  keys[e.key] = false;
});

function mainLoop(currentTime) {
  const deltaTime = currentTime - lastFrameTime;

  if (deltaTime >= frameDuration) {
    lastFrameTime = currentTime - (deltaTime % frameDuration);

    switch (currentState) {
      case states.PLAYING:
        updatePlayer();
        break;
      case states.PAUSED:
        // Handle pause state updates if needed
        break;
      case states.GAMEOVER:
        // Handle gameover state updates if needed
        break;
      case states.MENU:
        // Handle menu state updates if needed
        break;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawMap();
  }

  requestAnimationFrame(mainLoop);
}

