        this.experiencePoints += points;
        this.calculateBonuses();
    }

    getBonusForSkill(skillName) {
        return this.skillBonuses[skillName] || 0;
    }

    calculateBonuses() {
        // Example bonus calculation: every 100 points gives 1 bonus per skill
        this.skillBonuses = {
            'Combat': Math.floor(this.experiencePoints / 100),
            'Magic': Math.floor(this.experiencePoints / 150),
            'Stealth': Math.floor(this.experiencePoints / 200)
        };
    }
}

