        return this.balance;
    }

    addMoney(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    subtractMoney(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }
}

class Shop {
