const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 600;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const grid = 20;
const tileSize = canvas.width / grid;
const snake = [{ x: grid / 2, y: grid / 2 }];
let direction = { x: 0, y: 0 };
let food = { x: Math.floor(Math.random() * grid), y: Math.floor(Math.random() * grid) };
let score = 0;
let lastTime = 0;
const targetFPS = 10;

function update(time) {
  const delta = time - lastTime;
  if (delta >= 1000 / targetFPS) {
    lastTime = time;

    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };
    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score++;
      food = { x: Math.floor(Math.random() * grid), y: Math.floor(Math.random() * grid) };
    } else {
      snake.pop();
    }

    if (head.x < 0 || head.x >= grid || head.y < 0 || head.y >= grid || snake.some((segment, index) => index !== 0 && segment.x === head.x && segment.y === head.y)) {
      resetGame();
    }
  }

  requestAnimationFrame(update);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  snake.forEach(segment => {
    ctx.fillStyle = 'green';
    ctx.fillRect(segment.x * tileSize, segment.y * tileSize, tileSize, tileSize);
  });

  ctx.fillStyle = 'red';
  ctx.fillRect(food.x * tileSize, food.y * tileSize, tileSize, tileSize);

  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 20);

  requestAnimationFrame(draw);
}

function resetGame() {
  snake.length = 1;
  snake[0] = { x: grid / 2, y: grid / 2 };
  direction = { x: 0, y: 0 };
  score = 0;
  food = { x: Math.floor(Math.random() * grid), y: Math.floor(Math.random() * grid) };
}

document.addEventListener('keydown', event => {
  switch (event.key) {
    case 'ArrowUp':
      if (direction.y === 0) direction = { x: 0, y: -1 };
      break;
    case 'ArrowDown':
      if (direction.y === 0) direction = { x: 0, y: 1 };
      break;
    case 'ArrowLeft':
      if (direction.x === 0) direction = { x: -1, y: 0 };
      break;
    case 'ArrowRight':
      if (direction.x === 0) direction = { x: 1, y: 0 };
      break;
  }
});

canvas.addEventListener('click', event => {
  const rect = canvas.getBoundingClientRect();
  const x = Math.floor((event.clientX - rect.left) / tileSize);
  const y = Math.floor((event.clientY - rect.top) / tileSize);

  const head = { x: snake[0].x, y: snake[0].y };
  if (x === head.x && y === head.y) return;

  const dx = x - head.x;
  const dy = y - head.y;

  if (Math.abs(dx) > Math.abs(dy)) {
    direction = { x: dx > 0 ? 1 : -1, y: 0 };
  } else {
    direction = { x: 0, y: dy > 0 ? 1 : -1 };
  }
});

update();
draw();
