// Turn-based Tactics Duel Game

// Constants
const CANVAS_ID = 'gameCanvas';
const CELL_SIZE = 32;
const GRID_WIDTH = 10;
const GRID_HEIGHT = 10;
const HIGH_SCORE_KEY = 'highScore';

// Game state
let canvas, ctx;
let playerHealth = 100;
let enemyHealth = 100;
let playerTurn = true;
let gameOver = false;
let highScore = localStorage.getItem(HIGH_SCORE_KEY) || 0;

// Initialize game
function init() {
    canvas = document.getElementById(CANVAS_ID);
    ctx = canvas.getContext('2d');
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);
    window.addEventListener('click', handlePlayerAction);
    draw();
}

// Resize canvas to window size with devicePixelRatio
function resizeCanvas() {
    const dpr = window.devicePixelRatio || 1;
    const width = window.innerWidth;
    const height = window.innerHeight;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    ctx.scale(dpr, dpr);
    canvas.style.width = width + 'px';
    canvas.style.height = height + 'px';
}

// Handle player action
function handlePlayerAction(event) {
    if (!playerTurn || gameOver) return;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    const cellX = Math.floor(x / CELL_SIZE);
    const cellY = Math.floor(y / CELL_SIZE);

    // Simple combat logic
    if (cellX >= GRID_WIDTH / 2) {
        enemyHealth -= 10;
        playerTurn = false;
        updateHighScore();
    }
    draw();
}

// Update high score
function updateHighScore() {
    if (enemyHealth <= 0) {
        const currentScore = 100 + playerHealth;
        if (currentScore > highScore) {
            highScore = currentScore;
            localStorage.setItem(HIGH_SCORE_KEY, highScore);
        }
    }
}

// Draw game state
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw grid
    for (let x = 0; x < GRID_WIDTH; x++) {
        for (let y = 0; y < GRID_HEIGHT; y++) {
            ctx.fillStyle = (x + y) % 2 === 0 ? '#ddd' : '#aaa';
            ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
        }
    }

    // Draw health bars
    ctx.fillStyle = 'green';
    ctx.fillRect(10, 10, playerHealth, 20);
    ctx.fillStyle = 'red';
    ctx.fillRect(canvas.width - 110, 10, enemyHealth, 20);

    // Draw turn indicator
    ctx.fillStyle = 'black';
    ctx.font = '16px Arial';
    ctx.fillText(playerTurn ? 'Player Turn' : 'Enemy Turn', 10, 50);

    // Check for game over
    if (playerHealth <= 0 || enemyHealth <= 0) {
        ctx.fillStyle = 'black';
        ctx.font = '24px Arial';
        ctx.fillText(playerHealth <= 0 ? 'Enemy Wins!' : 'Player Wins!', canvas.width / 2 - 100, canvas.height / 2);
        gameOver = true;
    }

    // Draw high score
    ctx.fillStyle = 'black';
    ctx.fillText(`High Score: ${highScore}`, 10, 80);
}

// Start game
init();
