const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');

class Ship {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.size = 30;
        this.angle = 0;
        this.vx = 0;
        this.vy = 0;
        this.rotationSpeed = 0.04;
        this.thrust = 0.04;
        this.maxSpeed = 2;
    }

    draw() {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(this.angle);
        ctx.beginPath();
        ctx.moveTo(0, -this.size);
        ctx.lineTo(this.size, this.size);
        ctx.lineTo(-this.size, this.size);
        ctx.closePath();
        ctx.fillStyle = 'white';
        ctx.fill();
        ctx.restore();
    }

    update() {
        if (keys['ArrowUp']) {
            this.vx += Math.cos(this.angle) * this.thrust;
            this.vy -= Math.sin(this.angle) * this.thrust;
        }
        this.vx = Math.min(Math.max(this.vx, -this.maxSpeed), this.maxSpeed);
        this.vy = Math.min(Math.max(this.vy, -this.maxSpeed), this.maxSpeed);
        this.x += this.vx;
        this.y += this.vy;
        if (keys['ArrowLeft']) this.angle -= this.rotationSpeed;
        if (keys['ArrowRight']) this.angle += this.rotationSpeed;
        if (this.x < 0) this.x = canvas.width;
        if (this.x > canvas.width) this.x = 0;
        if (this.y < 0) this.y = canvas.height;
        if (this.y > canvas.height) this.y = 0;
    }
}

class Asteroid {
    constructor(x, y, size, angle) {
        this.x = x;
        this.y = y;
        this.size = size;
        this.angle = angle;
        this.vx = Math.random() * 2 - 1;
        this.vy = Math.random() * 2 - 1;
        this.rotationSpeed = (Math.random() - 0.5) * 0.02;
    }

    draw() {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(this.angle);
        ctx.beginPath();
        ctx.arc(0, 0, this.size, 0, Math.PI * 2);
        ctx.fillStyle = 'red';
        ctx.fill();
        ctx.restore();
    }

    update() {
        this.x += this.vx;
        this.y += this.vy;
        this.angle += this.rotationSpeed;
        if (this.x < 0) this.x = canvas.width;
        if (this.x > canvas.width) this.x = 0;
        if (this.y < 0) this.y = canvas.height;
        if (this.y > canvas.height) this.y = 0;
    }
}

function createAsteroids(count) {
    const asteroids = [];
    for (let i = 0; i < count; i++) {
        const x = Math.random() * canvas.width;
        const y = Math.random() * canvas.height;
        const size = Math.random() * 20 + 10;
        const angle = Math.random() * Math.PI * 2;
        asteroids.push(new Asteroid(x, y, size, angle));
    }
    return asteroids;
}

const ship = new Ship(canvas.width / 2, canvas.height / 2);
const asteroids = createAsteroids(5);
let countdown = 3;
let startTime = null;
let isCountdown = true;

const keys = {
    'ArrowUp': false,
    'ArrowLeft': false,
    'ArrowRight': false
};

document.addEventListener('keydown', (e) => {
    keys[e.key] = true;
});

document.addEventListener('keyup', (e) => {
    keys[e.key] = false;
});

function gameLoop(timestamp) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (isCountdown) {
        if (!startTime) startTime = timestamp;
        const elapsedTime = timestamp - startTime;
        if (elapsedTime >= 1000) {
            countdown--;
            startTime = timestamp;
        }
        if (countdown <= 0) {
            isCountdown = false;
        }
        ctx.font = '48px Arial';
        ctx.fillStyle = 'white';
        ctx.textAlign = 'center';
        ctx.fillText(countdown.toString(), canvas.width / 2, canvas.height / 2);
    } else {
        ship.update();
        ship.draw();
        asteroids.forEach(asteroid => {
            asteroid.update();
            asteroid.draw();
        });
    }

    requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
