// 2048-style slide game with particle burst effect

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 400;
const ctx = canvas.getContext('2d');

const grid = Array.from({length: 4}, () => Array(4).fill(0));
let particles = [];
let score = 0;

function spawn() {
    let emptyCells = [];
    for (let i = 0; i < 4; i++) {
        for (let j = 0; j < 4; j++) {
            if (grid[i][j] === 0) {
                emptyCells.push([i, j]);
            }
        }
    }
    if (emptyCells.length > 0) {
        const [x, y] = emptyCells[Math.floor(Math.random() * emptyCells.length)];
        grid[x][y] = Math.random() > 0.9 ? 4 : 2;
        particles.push({x, y, dx: 0, dy: 0, size: 8, opacity: 1});
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#f4e3c2';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    for (let i = 0; i < 4; i++) {
        for (let j = 0; j < 4; j++) {
            if (grid[i][j] !== 0) {
                ctx.fillStyle = `rgb(${255 - 20 * grid[i][j]}, ${200 - 10 * grid[i][j]}, ${180 - 8 * grid[i][j]})`;
                ctx.fillRect(j * 100 + 10, i * 100 + 10, 80, 80);
                ctx.fillStyle = '#6a5b4f';
                ctx.font = 'bold 36px Arial';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(grid[i][j], j * 100 + 50, i * 100 + 50);
            }
        }
    }

    ctx.fillStyle = '#ffeb3b';
    for (let p of particles) {
        ctx.globalAlpha = p.opacity;
        ctx.beginPath();
        ctx.arc(p.x * 100 + 50 + p.dx * 10, p.y * 100 + 50 + p.dy * 10, p.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
        p.size *= 0.95;
        p.opacity *= 0.95;
    }
    particles = particles.filter(p => p.opacity > 0.1);

    ctx.fillStyle = '#6a5b4f';
    ctx.font = 'bold 24px Arial';
    ctx.textAlign = 'left';
    ctx.fillText(`Score: ${score}`, 10, 30);
}

function move(dir) {
    let moved = false;
    if (dir === 'left') {
        for (let i = 0; i < 4; i++) {
            let row = grid[i].filter(n => n);
            for (let j = 0; j < row.length - 1; j++) {
                if (row[j] === row[j + 1]) {
                    row[j] *= 2;
                    score += row[j];
                    row[j + 1] = 0;
                }
            }
            grid[i] = row.filter(n => n).concat(Array(4 - row.filter(n => n).length).fill(0));
        }
    } else if (dir === 'right') {
        for (let i = 0; i < 4; i++) {
            let row = grid[i].filter(n => n);
            for (let j = row.length - 1; j > 0; j--) {
                if (row[j] === row[j - 1]) {
                    row[j] *= 2;
                    score += row[j];
                    row[j - 1] = 0;
                }
            }
            grid[i] = Array(4 - row.filter(n => n).length).fill(0).concat(row.filter(n => n));
        }
    } else if (dir === 'up') {
        for (let j = 0; j < 4; j++) {
            let col = [];
            for (let i = 0; i < 4; i++) {
                if (grid[i][j]) col.push(grid[i][j]);
            }
            for (let i = 0; i < col.length - 1; i++) {
                if (col[i] === col[i + 1]) {
                    col[i] *= 2;
                    score += col[i];
                    col[i + 1] = 0;
                }
            }
            col = col.filter(n => n).concat(Array(4 - col.filter(n => n).length).fill(0));
            for (let i = 0; i < 4; i++) {
                grid[i][j] = col[i];
            }
        }
    } else if (dir === 'down') {
        for (let j = 0; j < 4; j++) {
            let col = [];
            for (let i = 0; i < 4; i++) {
                if (grid[i][j]) col.push(grid[i][j]);
            }
            for (let i = col.length - 1; i > 0; i--) {
                if (col[i] === col[i - 1]) {
                    col[i] *= 2;
                    score += col[i];
                    col[i - 1] = 0;
                }
            }
            col = Array(4 - col.filter(n => n).length).fill(0).concat(col.filter(n => n));
            for (let i = 0; i < 4; i++) {
                grid[i][j] = col[i];
            }
        }
    }

    if (moved) {
        spawn();
        particles = particles.map(p => ({...p, dx: Math.random() * 4 - 2, dy: Math.random() * 4 - 2}));
    }
}

document.addEventListener('keydown', e => {
    switch (e.key) {
        case 'ArrowLeft':
            move('left');
            break;
        case 'ArrowRight':
            move('right');
            break;
        case 'ArrowUp':
            move('up');
            break;
        case 'ArrowDown':
            move('down');
            break;
    }
});

spawn();
spawn();

function gameLoop() {
    draw();
    requestAnimationFrame(gameLoop);
}

gameLoop();
