const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio || 1;
canvas.width = window.innerWidth * dpr;
canvas.height = window.innerHeight * dpr;
ctx.scale(dpr, dpr);

const player = { x: canvas.width / 2, y: canvas.height / 2, r: 10, a: 0, speed: 5, thrust: 0.1 };
const asteroids = [];
const bullets = [];
let score = 0;
let gameOver = false;

class Asteroid {
  constructor(x, y, r) {
    this.x = x;
    this.y = y;
    this.r = r;
    this.a = Math.random() * Math.PI * 2;
    this.speed = Math.random() * 2 + 1;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);
    ctx.stroke();
  }

  move() {
    this.x += Math.cos(this.a) * this.speed;
    this.y += Math.sin(this.a) * this.speed;
    if (this.x < 0 || this.x > canvas.width) this.x = (this.x + canvas.width) % canvas.width;
    if (this.y < 0 || this.y > canvas.height) this.y = (this.y + canvas.height) % canvas.height;
  }
}

class Bullet {
  constructor(x, y, a) {
    this.x = x;
    this.y = y;
    this.a = a;
    this.speed = 10;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, 2, 0, Math.PI * 2);
    ctx.fill();
  }

  move() {
    this.x += Math.cos(this.a) * this.speed;
    this.y += Math.sin(this.a) * this.speed;
  }
}

function createAsteroids(num) {
  for (let i = 0; i < num; i++) {
    const x = Math.random() * canvas.width;
    const y = Math.random() * canvas.height;
    const r = Math.random() * 20 + 10;
    asteroids.push(new Asteroid(x, y, r));
  }
}

function drawPlayer() {
  ctx.save();
  ctx.translate(player.x, player.y);
  ctx.rotate(player.a);
  ctx.beginPath();
  ctx.moveTo(10, 0);
  ctx.lineTo(-10, -5);
  ctx.lineTo(-10, 5);
  ctx.closePath();
  ctx.stroke();
  ctx.restore();
}

function drawBullets() {
  bullets.forEach(bullet => {
    bullet.draw();
    bullet.move();
  });
}

function drawAsteroids() {
  asteroids.forEach(asteroid => {
    asteroid.draw();
    asteroid.move();
  });
}

function checkCollisions() {
  asteroids.forEach((asteroid, ai) => {
    bullets.forEach((bullet, bi) => {
      const dx = asteroid.x - bullet.x;
      const dy = asteroid.y - bullet.y;
      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance < asteroid.r) {
        bullets.splice(bi, 1);
        asteroids.splice(ai, 1);
        score += Math.round(100 / asteroid.r);
        if (Math.random() < 0.5) {
          asteroids.push(new Asteroid(asteroid.x, asteroid.y, asteroid.r / 2));
          asteroids.push(new Asteroid(asteroid.x, asteroid.y, asteroid.r / 2));
        }
      }
    });

    const dx = asteroid.x - player.x;
    const dy = asteroid.y - player.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < player.r + asteroid.r) {
      gameOver = true;
    }
  });
}

function drawScore() {
  ctx.fillStyle = 'white';
  ctx.fillText(`Score: ${score}`, 10, 20);
}

function update() {
  if (gameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '30px Arial';
    ctx.fillText('Game Over', canvas.width / 2 - 80, canvas.height / 2);
    return;
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (Math.random() < 0.01) {
    asteroids.push(new Asteroid(Math.random() * canvas.width, Math.random() * canvas.height, 20));
  }

  if (player.thrust) {
    player.a += player.thrust;
  }

  player.x += Math.cos(player.a) * player.speed;
  player.y += Math.sin(player.a) * player.speed;

  if (player.x < 0) player.x = canvas.width;
  if (player.x > canvas.width) player.x = 0;
  if (player.y < 0) player.y = canvas.height;
  if (player.y > canvas.height) player.y = 0;

  drawPlayer();
  drawBullets();
  drawAsteroids();
  drawScore();
  checkCollisions();
}

window.addEventListener('keydown', e => {
  if (e.key === 'ArrowLeft') player.thrust = -0.1;
  if (e.key === 'ArrowRight') player.thrust = 0.1;
  if (e.key === 'ArrowUp') bullets.push(new Bullet(player.x, player.y, player.a));
});

window.addEventListener('keyup', e => {
  if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') player.thrust = 0;
});

window.addEventListener('resize', () => {
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
});

createAsteroids(5);
setInterval(update, 16);
