  x: canvas.width - 20,
  y: canvas.height / 2 - 50,
  width: 10,
  height: 100,
  dy: 2
};

const playerPaddle = {
  x: 10,
  y: canvas.height / 2 - 50,
  width: 10,
  height: 100,
  dy: 2,
  controls: {
    up: false,
    down: false
  }
};

document.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowUp') playerPaddle.controls.up = true;
  if (e.key === 'ArrowDown') playerPaddle.controls.down = true;
});

document.addEventListener('keyup', (e) => {
  if (e.key === 'ArrowUp') playerPaddle.controls.up = false;
  if (e.key === 'ArrowDown') playerPaddle.controls.down = false;
});

function movePlayerPaddle() {
  if (playerPaddle.controls.up && playerPaddle.y > 0) {
    playerPaddle.y -= playerPaddle.dy;
  }
  if (playerPaddle.controls.down && playerPaddle.y < canvas.height - playerPaddle.height) {
    playerPaddle.y += playerPaddle.dy;
  }
}

function moveAIPaddle() {
  const center = aiPaddle.y + aiPaddle.height / 2;
  if (center < ball.y && aiPaddle.y < canvas.height - aiPaddle.height) {
    aiPaddle.y += aiPaddle.dy;
  } else if (center > ball.y && aiPaddle.y > 0) {
    aiPaddle.y -= aiPaddle.dy;
  }
}

function moveBall() {
  ball.y += ball.dy;
  if (ball.y + ball.radius > canvas.height || ball.y - ball.radius < 0) {
    ball.dy = -ball.dy;
  }
  if (ball.x + ball.radius > canvas.width - aiPaddle.width && ball.y > aiPaddle.y && ball.y < aiPaddle.y + aiPaddle.height) {
    ball.dx = -ball.dx;
  } else if (ball.x - ball.radius < playerPaddle.width && ball.y > playerPaddle.y && ball.y < playerPaddle.y + playerPaddle.height) {
    ball.dx = -ball.dx;
  }
  if (ball.x + ball.radius > canvas.width || ball.x - ball.radius < 0) {
    ball.x = canvas.width / 2;
    ball.y = 50;
    ball.dx = ball.dx > 0 ? -2 : 2;
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = ball.color;
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = 'black';
  ctx.fillRect(playerPaddle.x, playerPaddle.y, playerPaddle.width, playerPaddle.height);
  ctx.fillRect(aiPaddle.x, aiPaddle.y, aiPaddle.width, aiPaddle.height);
}

function gameLoop() {
  movePlayerPaddle();
  moveAIPaddle();
  moveBall();
  draw();
  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
