let score = 0;
let powerUps = [];
let tapPosition = { x: 0, y: 0 };
let isTapping = false;
let tapStartTime = 0;
let tapEndTime = 0;

const powerUpTypes = [
  { color: 'blue', effect: 'multiplyScore' },
  { color: 'green', effect: 'addTime' },
  { color: 'red', effect: 'subtractScore' }
];

function generatePowerUp() {
  const type = powerUpTypes[Math.floor(Math.random() * powerUpTypes.length)];
  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  powerUps.push({ x, y, type });
}

function applyPowerUp(powerUp) {
  switch (powerUp.type.effect) {
    case 'multiplyScore':
      score *= 2;
      break;
    case 'addTime':
      tapEndTime += 5000;
      break;
    case 'subtractScore':
      score = Math.max(score - 10, 0);
      break;
  }
}

function checkCollision() {
  powerUps.forEach((powerUp, index) => {
    if (Math.abs(powerUp.x - tapPosition.x) < 20 && Math.abs(powerUp.y - tapPosition.y) < 20) {
      applyPowerUp(powerUp);
      powerUps.splice(index, 1);
    }
  });
}

function update() {
  if (isTapping && Date.now() - tapStartTime > 100) {
    checkCollision();
    isTapping = false;
  }
  if (Date.now() - tapEndTime > 1000) {
    generatePowerUp();
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  powerUps.forEach(powerUp => {
    ctx.fillStyle = powerUp.type.color;
    ctx.beginPath();
    ctx.arc(powerUp.x, powerUp.y, 20, 0, Math.PI * 2);
    ctx.fill();
  });
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('mousedown', (e) => {
  isTapping = true;
  tapStartTime = Date.now();
  tapPosition = { x: e.clientX - canvas.offsetLeft, y: e.clientY - canvas.offsetTop };
});

canvas.addEventListener('mouseup', () => {
  tapEndTime = Date.now();
});

gameLoop();
