const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const states = {
  menu: 0,
  playing: 1,
  paused: 2,
  gameover: 3
};

let currentState = states.menu;
let score = 0;
let player = { x: 100, y: 300, width: 20, height: 20, speed: 5 };
let platforms = [{ x: 0, y: 580, width: 800, height: 20 }];
let gravity = 0.5;
let jumpStrength = -10;
let isJumping = false;

function drawMenu() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '30px Arial';
  ctx.fillText('Press Space to Start', 250, 300);
}

function drawGame() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'green';
  platforms.forEach(platform => {
    ctx.fillRect(platform.x, platform.y, platform.width, platform.height);
  });
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);
  ctx.fillStyle = 'white';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function drawPaused() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '30px Arial';
  ctx.fillText('Game Paused', 300, 300);
  ctx.fillText('Press Space to Resume', 250, 350);
}

function drawGameOver() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '30px Arial';
  ctx.fillText('Game Over', 300, 300);
  ctx.fillText(`Score: ${score}`, 300, 350);
  ctx.fillText('Press Space to Restart', 250, 400);
}

function updateMenu() {
  if (keys.Space) {
    currentState = states.playing;
  }
}

function updateGame() {
  if (keys.Space && !isJumping) {
    player.y += jumpStrength;
    isJumping = true;
  }

  player.y += gravity;
  if (player.y + player.height > platforms[platforms.length - 1].y) {
    player.y = platforms[platforms.length - 1].y - player.height;
    isJumping = false;
  }

  platforms.forEach(platform => {
    if (player.x < platform.x + platform.width &&
        player.x + player.width > platform.x &&
        player.y < platform.y + platform.height &&
        player.y + player.height > platform.y) {
      isJumping = false;
    }
  });

  score += 1;
  if (Math.random() < 0.01) {
    platforms.push({ x: Math.random() * (canvas.width - 100), y: platforms[platforms.length - 1].y - 100, width: 100, height: 20 });
  }
  platforms = platforms.filter(platform => platform.y > -20);
}

function updatePaused() {
  if (keys.Space) {
    currentState = states.playing;
  }
}

function updateGameOver() {
  if (keys.Space) {
    currentState = states.menu;
    score = 0;
    player.y = 300;
    platforms = [{ x: 0, y: 580, width: 800, height: 20 }];
  }
}

function update() {
  switch (currentState) {
    case states.menu:
      updateMenu();
      break;
    case states.playing:
      updateGame();
      break;
    case states.paused:
      updatePaused();
      break;
    case states.gameover:
      updateGameOver();
      break;
  }
}

function draw() {
  switch (currentState) {
    case states.menu:
      drawMenu();
      break;
    case states.playing:
      drawGame();
      break;
    case states.paused:
      drawPaused();
      break;
    case states.gameover:
      drawGameOver();
      break;
  }
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

const keys = {};
window.addEventListener('keydown', e => {
  keys[e.key] = true;
  if (e.key === ' ') {
    if (currentState === states.paused) {
      currentState = states.playing;
    } else if (currentState === states.gameover) {
      currentState = states.menu;
      score = 0;
      player.y = 300;
      platforms = [{ x: 0, y: 580, width: 800, height: 20 }];
    }
  }
});
window.addEventListener('keyup', e => {
  keys[e.key] = false;
});

gameLoop();
