const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 300;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const BLOCK_SIZE = 20;
const BOARD_WIDTH = canvas.width / BLOCK_SIZE;
const BOARD_HEIGHT = canvas.height / BLOCK_SIZE;

let board = Array.from({ length: BOARD_HEIGHT }, () => Array(BOARD_WIDTH).fill(0));
let currentShape = null;
let currentX = 0;
let currentY = 0;
let score = 0;
let gameInterval;

const SHAPES = [
    [[1, 1, 1, 1]], // I
    [[1, 1], [1, 1]], // O
    [[1, 1, 1], [0, 1, 0]], // T
    [[1, 1, 0], [0, 1, 1]], // S
    [[0, 1, 1], [1, 1, 0]], // Z
    [[1, 1, 1], [1, 0, 0]], // L
    [[1, 1, 1], [0, 0, 1]]  // J
];

function getRandomShape() {
    const randomIndex = Math.floor(Math.random() * SHAPES.length);
    return SHAPES[randomIndex].map(row => [...row]);
}

function canMove(shape, x, y) {
    for (let row = 0; row < shape.length; row++) {
        for (let col = 0; col < shape[row].length; col++) {
            if (shape[row][col]) {
                const newX = x + col;
                const newY = y + row;
                if (newX < 0 || newX >= BOARD_WIDTH || newY >= BOARD_HEIGHT || board[newY][newX]) {
                    return false;
                }
            }
        }
    }
    return true;
}

function mergeShape(shape, x, y) {
    for (let row = 0; row < shape.length; row++) {
        for (let col = 0; col < shape[row].length; col++) {
            if (shape[row][col]) {
                board[y + row][x + col] = shape[row][col];
            }
        }
    }
}

function clearLines() {
    let linesCleared = 0;
    for (let row = BOARD_HEIGHT - 1; row >= 0; row--) {
        if (board[row].every(cell => cell !== 0)) {
            board.splice(row, 1);
            board.unshift(Array(BOARD_WIDTH).fill(0));
            linesCleared++;
        }
    }
    score += linesCleared * 10;
}

function drawBlock(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(x * BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let row = 0; row < BOARD_HEIGHT; row++) {
        for (let col = 0; col < BOARD_WIDTH; col++) {
            if (board[row][col]) {
                drawBlock(col, row, 'blue');
            }
        }
    }
    if (currentShape) {
        currentShape.forEach((row, dy) => {
            row.forEach((cell, dx) => {
                if (cell) {
                    drawBlock(currentX + dx, currentY + dy, 'red');
                }
            });
        });
    }
    ctx.fillStyle = '#000';
    ctx.fillText(`Score: ${score}`, 10, 20);
}

function newGame() {
    currentShape = getRandomShape();
    currentX = Math.floor((BOARD_WIDTH - currentShape[0].length) / 2);
    currentY = 0;
    if (!canMove(currentShape, currentX, currentY)) {
        clearInterval(gameInterval);
        alert(`Game Over! Your score is ${score}`);
    }
}

function drop() {
    if (canMove(currentShape, currentX, currentY + 1)) {
        currentY++;
    } else {
        mergeShape(currentShape, currentX, currentY);
        clearLines();
        newGame();
    }
}

function rotateShape(shape) {
    const newShape = shape[0].map((_, index) => shape.map(row => row[index]).reverse());
    return newShape;
}

function rotate() {
    const newShape = rotateShape(currentShape);
    if (canMove(newShape, currentX, currentY)) {
        currentShape = newShape;
    }
}

function moveLeft() {
    if (canMove(currentShape, currentX - 1, currentY)) {
        currentX--;
    }
}

function moveRight() {
    if (canMove(currentShape, currentX + 1, currentY)) {
        currentX++;
    }
}

function update() {
    drop();
    drawBoard();
}

document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowLeft':
            moveLeft();
            break;
        case 'ArrowRight':
            moveRight();
            break;
        case 'ArrowDown':
            drop();
            break;
        case 'ArrowUp':
            rotate();
            break;
    }
    drawBoard();
});

canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / BLOCK_SIZE);
    const y = Math.floor((e.clientY - rect.top) / BLOCK_SIZE);
    if (x >= 0 && x < BOARD_WIDTH && y >= 0 && y < BOARD_HEIGHT) {
        if (canMove(currentShape, x, y)) {
            currentX = x;
            currentY = y;
        }
    }
    drawBoard();
});

newGame();
gameInterval = setInterval(update, 500);
```

