class Order {
  constructor() {
    this.orders = [];
  }

  createOrder(items) {
    const order = { id: Date.now(), items, status: 'pending' };
    this.orders.push(order);
    return order.id;
  }

  getOrderStatus(orderId) {
    const order = this.orders.find(o => o.id === orderId);
    return order ? order.status : null;
  }

  updateOrderStatus(orderId, newStatus) {
    const order = this.orders.find(o => o.id === orderId);
    if (order) {
