// Event Bus implementation
class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

// Bank System
class Bank {
  constructor(eventBus) {
    this.balance = 0;
    this.eventBus = eventBus;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    this.eventBus.emit('balanceUpdated', { balance: this.balance });
  }

  withdraw(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      this.eventBus.emit('balanceUpdated', { balance: this.balance });
      this.eventBus.emit('itemBought', { amount });
    } else {
      console.log('Insufficient funds');
    }
  }

  getBalance() {
    return this.balance;
  }
}

// Market System
class Market {
  constructor(eventBus) {
    this.prices = { apple: 2, banana: 1, orange: 3 };
    this.eventBus = eventBus;
    this.eventBus.subscribe('buyItem', this.buyItem.bind(this));
  }

  buyItem(item) {
    if (this.prices[item]) {
      this.eventBus.emit('withdraw', this.prices[item]);
    } else {
      console.log('Item not available');
    }
  }

  getItemPrice(item) {
    return this.prices[item];
  }
}

// Inventory System
class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemBought', this.addItem.bind(this));
  }

  addItem(data) {
    if (!this.items[data.amount]) {
      this.items[data.amount] = 0;
    }
    this.items[data.amount]++;
  }

  getInventory() {
    return this.items;
  }
}

// Demo
const eventBus = new EventBus();
const bank = new Bank(eventBus);
const market = new Market(eventBus);
const inventory = new Inventory(eventBus);

// Initial deposit
console.log('Depositing 100 into the bank');
bank.deposit(100);
console.log('Current balance:', bank.getBalance());

