console.log('Buying an apple');
market.buyItem('apple');
console.log('Current balance:', bank.getBalance());

// Buying a banana
console.log('Buying a banana');
market.buyItem('banana');
console.log('Current balance:', bank.getBalance());

// Checking inventory
console.log('Current inventory:', inventory.getInventory());
