class Quest {
  constructor() {
    this.currentQuest = null;
  }

  startQuest(quest) {
    this.currentQuest = quest;
    console.log(`Quest started: ${quest}`);
  }

  completeQuest() {
    if (this.currentQuest) {
      console.log(`Quest completed: ${this.currentQuest}`);
      this.currentQuest = null;
      return true;
    } else {
      console.log("No active quest to complete.");
      return false;
    }
  }

  getCurrentQuest() {
    return this.currentQuest;
  }
}

class Reward {
  constructor() {
    this.availableRewards = {};
  }

  addReward(quest, reward) {
    this.availableRewards[quest] = reward;
    console.log(`Reward added for ${quest}: ${reward}`);
  }

  claimReward(quest) {
    if (this.availableRewards[quest]) {
      const reward = this.availableRewards[quest];
      console.log(`Reward claimed for ${quest}: ${reward}`);
      delete this.availableRewards[quest];
      return reward;
    } else {
      console.log(`No reward available for ${quest}.`);
      return null;
    }
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
    console.log(`Item added to inventory: ${item}`);
  }

  getInventory() {
    return this.items;
  }
}

class GameCoordinator {
  constructor() {
    this.questSystem = new Quest();
    this.rewardSystem = new Reward();
    this.inventorySystem = new Inventory();
  }

  startAndCompleteQuest(quest, reward) {
    this.questSystem.startQuest(quest);
    this.rewardSystem.addReward(quest, reward);
    if (this.questSystem.completeQuest()) {
      const rewardItem = this.rewardSystem.claimReward(quest);
      if (rewardItem) {
        this.inventorySystem.addItem(rewardItem);
      }
    }
  }

  showInventory() {
    console.log("Current Inventory:", this.inventorySystem.getInventory());
  }
}

// Demo
