        this.level = 50; // Initial energy level out of 100
    }

    rest(amount) {
        if (this.level + amount > 100) {
            this.level = 100;
        } else {
            this.level += amount;
        }
        console.log(`Rested ${amount}, energy is now at ${this.level}`);
    }

    getEnergyLevel() {
        return this.level;
    }
}

