        this.time++;
        console.log(`Time is now ${this.time} hours`);
    }

    getCurrentTime() {
        return this.time;
    }
}

class Economy {
    constructor(prices) {
        this.prices = prices; // Map of item to price
        this.balance = 1000; // Initial balance
    }

    getBalance() {
        return this.balance;
    }

    getPrices() {
        return this.prices;
    }

    debit(amount) {
        if (this.balance >= amount) {
            this.balance -= amount;
            console.log(`Debited ${amount}, balance is now ${this.balance}`);
            return true;
        } else {
            console.log(`Insufficient funds to debit ${amount}`);
            return false;
        }
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, amount) {
        if (this.items[item]) {
            this.items[item] += amount;
        } else {
            this.items[item] = amount;
        }
        console.log(`Added ${amount} of ${item}, inventory is now:`, this.items);
    }

    getInventory() {
        return this.items;
    }
}

class Store {
    constructor(economy, inventory) {
        this.economy = economy;
        this.inventory = inventory;
    }

    purchase(item, amount) {
        const prices = this.economy.getPrices();
        const pricePerUnit = prices[item];
        if (pricePerUnit === undefined) {
            console.log(`Item ${item} not available for purchase`);
            return;
        }

        const totalCost = pricePerUnit * amount;
        if (this.economy.debit(totalCost)) {
            this.inventory.addItem(item, amount);
            console.log(`Purchased ${amount} of ${item} for ${totalCost}`);
        }
    }
}

