// Match-3 Game with Particle Burst Effect

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const particleCount = 50;
const particles = [];
const grid = Array.from({ length: 8 }, () => Array(8).fill(0));
const colors = ['red', 'green', 'blue', 'yellow', 'purple', 'orange'];
const cellSize = canvas.width / 8;
const fixedTimestep = 1000 / 60; // 60 FPS
let lastTime = 0;
let score = 0;
let animating = true;

function initGrid() {
    for (let i = 0; i < 8; i++) {
        for (let j = 0; j < 8; j++) {
            grid[i][j] = Math.floor(Math.random() * colors.length);
        }
    }
}

function drawGrid() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < 8; i++) {
        for (let j = 0; j < 8; j++) {
            ctx.fillStyle = colors[grid[i][j]];
            ctx.fillRect(i * cellSize, j * cellSize, cellSize, cellSize);
        }
    }
}

function detectMatches() {
    const matches = [];
    for (let i = 0; i < 8; i++) {
        for (let j = 0; j < 6; j++) {
            if (grid[i][j] === grid[i][j + 1] && grid[i][j] === grid[i][j + 2]) {
                matches.push([[i, j], [i, j + 1], [i, j + 2]]);
            }
        }
        for (let j = 0; j < 5; j++) {
            if (grid[j][i] === grid[j + 1][i] && grid[j][i] === grid[j + 2][i]) {
                matches.push([[j, i], [j + 1, i], [j + 2, i]]);
            }
        }
    }
    return matches;
}

function clearMatches(matches) {
    matches.forEach(match => {
        match.forEach(([i, j]) => {
            grid[i][j] = 0;
            burstParticles(i, j);
        });
    });
}

function burstParticles(x, y) {
    for (let i = 0; i < particleCount; i++) {
        particles.push({
            x: x * cellSize + cellSize / 2,
            y: y * cellSize + cellSize / 2,
            dx: (Math.random() - 0.5) * 2,
            dy: (Math.random() - 0.5) * 2,
            ttl: Math.random() * 100 + 50
        });
    }
}

function updateParticles() {
    particles.forEach((p, i) => {
        p.x += p.dx;
        p.y += p.dy;
        p.ttl--;
        if (p.ttl <= 0) {
            particles.splice(i, 1);
        }
    });
}

function drawParticles() {
    ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
    particles.forEach(p => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
        ctx.fill();
    });
}

function updateGrid() {
    for (let i = 0; i < 8; i++) {
        for (let j = 7; j >= 0; j--) {
            if (grid[i][j] === 0) {
                for (let k = j; k > 0; k--) {
                    grid[i][k] = grid[i][k - 1];
                }
                grid[i][0] = Math.floor(Math.random() * colors.length);
            }
        }
    }
}

function mainLoop(timestamp) {
    if (!animating) return;
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;

    const steps = Math.floor(deltaTime / fixedTimestep);
    for (let i = 0; i < steps; i++) {
        const matches = detectMatches();
        if (matches.length > 0) {
            clearMatches(matches);
            updateGrid();
        }
    }

    drawGrid();
    updateParticles();
    drawParticles();

    requestAnimationFrame(mainLoop);
}

initGrid();
requestAnimationFrame(mainLoop);
