// One-button endless runner with combo multiplier on an HTML5 canvas

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

let score = 0;
let combo = 1;
let comboMultiplier = 1.5;
let lastTime = 0;
const fixedTimeStep = 1000 / 60; // 60 FPS
let accumulator = 0;

const player = {
  x: 50,
  y: canvas.height / 2,
  width: 20,
  height: 20,
  speed: 5
};

const obstacles = [];
let obstacleSpeed = 2;

function update(deltaTime) {
  player.x += player.speed * deltaTime;

  // Spawn obstacles
  if (Math.random() < 0.01) {
    obstacles.push({
      x: canvas.width,
      y: Math.random() * (canvas.height - 50) + 25,
      width: 30,
      height: 30
    });
  }

  // Move obstacles
  obstacles.forEach(obstacle => {
    obstacle.x -= obstacleSpeed * deltaTime;
  });

  // Remove off-screen obstacles
  while (obstacles.length > 0 && obstacles[0].x + obstacles[0].width < 0) {
    obstacles.shift();
  }

  // Collision detection
  obstacles.forEach(obstacle => {
    if (player.x < obstacle.x + obstacle.width &&
        player.x + player.width > obstacle.x &&
        player.y < obstacle.y + obstacle.height &&
        player.y + player.height > obstacle.y) {
      resetCombo();
    }
  });

  // Increase combo
  if (player.x > canvas.width) {
    combo++;
    score += combo * comboMultiplier;
    resetPlayer();
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);

  // Draw obstacles
  ctx.fillStyle = 'red';
  obstacles.forEach(obstacle => {
    ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
  });

  // Draw score and combo
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${Math.floor(score)}`, 10, 30);
  ctx.fillText(`Combo: ${combo}x`, 10, 60);
}

function resetCombo() {
  combo = 1;
}

function resetPlayer() {
  player.x = 50;
  player.y = canvas.height / 2;
}

function gameLoop(timestamp) {
  const currentTime = timestamp;
  const deltaTime = currentTime - lastTime;
  lastTime = currentTime;

  accumulator += deltaTime;

  while (accumulator >= fixedTimeStep) {
    update(fixedTimeStep);
    accumulator -= fixedTimeStep;
  }

  render();

  requestAnimationFrame(gameLoop);
}

// Button control
let isButtonPressed = false;

document.addEventListener('keydown', (e) => {
  if (e.key === ' ') {
    isButtonPressed = true;
  }
});

document.addEventListener('keyup', (e) => {
  if (e.key === ' ') {
    isButtonPressed = false;
  }
});

function controlPlayer() {
  if (isButtonPressed) {
    player.y -= 5; // Jump
  } else {
    player.y += 2; // Gravity
  }

  // Prevent player from going off screen
  player.y = Math.max(0, Math.min(canvas.height - player.height, player.y));
}

// Main loop
function mainLoop(timestamp) {
  controlPlayer();
  gameLoop(timestamp);
  requestAnimationFrame(mainLoop);
}

requestAnimationFrame(mainLoop);
