class Bank {
  constructor(balance = 0) {
    this.balance = balance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Market {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  setPrice(item, price) {
    if (price >= 0) {
      this.prices[item] = price;
    }
  }
}

class Inventory {
  constructor(items = {}) {
    this.items = items;
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

