        this.clock.tick(minutes);
        if (this.clock.getTime() % 30 === 0) {
            this.hunger.eat();
        }
        if (this.clock.getTime() % 60 === 0) {
            this.energy.rest();
        }
    }

    reportStatus() {
        console.log(`Status at ${this.clock.getTime()} minutes: Hunger - ${this.hunger.getHungerLevel()}, Energy - ${this.energy.getEnergyLevel()}`);
    }
}

// Demo
const coordinator = new Coordinator();
for (let i = 0; i < 180; i += 10) {
