class Wallet {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    getBalance() {
        return this.balance;
    }

    addMoney(amount) {
        if (amount > 0) {
            this.balance += amount;
        }
    }

    subtractMoney(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }
}

class Shop {
    constructor(prices = {}) {
        this.prices = prices;
    }

    getPrice(item) {
        return this.prices[item] || null;
    }

    purchase(wallet, item) {
        const price = this.getPrice(item);
        if (price !== null && wallet.subtractMoney(price)) {
            return true;
        }
        return false;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item) {
        if (this.items[item]) {
            this.items[item]++;
        } else {
            this.items[item] = 1;
        }
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }

    removeItem(item) {
        if (this.items[item] && this.items[item] > 0) {
            this.items[item]--;
        }
    }
}

