class Loot {
  constructor() {
    this.lootItems = [];
  }

  addLoot(item) {
    this.lootItems.push(item);
  }

  getAllLoot() {
    return this.lootItems;
  }
}

class RarityTable {
  constructor() {
    this.rarityLevels = {
      COMMON: 0.6,
      UNCOMMON: 0.3,
      RARE: 0.09,
      LEGENDARY: 0.01
    };
  }

  getRandomRarity() {
    const random = Math.random();
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.rarityLevels)) {
      cumulativeProbability += probability;
      if (random <= cumulativeProbability) {
        return rarity;
      }
    }

    return 'COMMON'; // Default to common if something goes wrong
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, rarity) {
    if (!this.items[rarity]) {
      this.items[rarity] = [];
    }
    this.items[rarity].push(item);
  }

  getInventory() {
    return this.items;
  }
}

// Coordinator class to wire the systems together
class GameCoordinator {
  constructor() {
    this.lootSystem = new Loot();
    this.raritySystem = new RarityTable();
    this.inventorySystem = new Inventory();
  }

  addLootItem(item) {
    this.lootSystem.addLoot(item);
  }

  distributeLoot() {
    const lootItems = this.lootSystem.getAllLoot();
    lootItems.forEach(item => {
      const rarity = this.raritySystem.getRandomRarity();
      this.inventorySystem.addItem(item, rarity);
    });
  }

  getInventory() {
    return this.inventorySystem.getInventory();
  }
}

// Runnable demo
const coordinator = new GameCoordinator();

// Add some loot items
coordinator.addLootItem('Sword');
coordinator.addLootItem('Potion');
coordinator.addLootItem('Shield');
coordinator.addLootItem('Ring');
coordinator.addLootItem('Amulet');

// Distribute loot into inventory
coordinator.distributeLoot();

// Log the inventory
console.log('Inventory:', coordinator.getInventory());
