const states = {
    menu: { name: 'menu', enter: () => { ctx.fillText('Tap to Start', 350, 300); }, update: () => {} },
    playing: { name: 'playing', enter: () => {}, update: () => {} },
    paused: { name: 'paused', enter: () => { ctx.fillText('Game Paused', 350, 300); }, update: () => {} },
    gameover: { name: 'gameover', enter: () => { ctx.fillText('Game Over', 350, 300); }, update: () => {} }
};

let currentState = states.menu;
let tapCount = 0;
let lastTapTime = 0;

function changeState(newState) {
    if (currentState !== newState) {
        currentState = newState;
        currentState.enter();
    }
}

function handleTap() {
    if (currentState === states.playing) {
        tapCount++;
        lastTapTime = performance.now();
    } else if (currentState === states.menu) {
        changeState(states.playing);
    } else if (currentState === states.paused) {
        changeState(states.playing);
    } else if (currentState === states.gameover) {
        tapCount = 0;
        changeState(states.menu);
    }
}

function update() {
    if (currentState === states.playing) {
        const currentTime = performance.now();
        if (currentTime - lastTapTime > 2000) {
            changeState(states.gameover);
        }
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '30px Arial';
    ctx.fillText(`Taps: ${tapCount}`, 10, 30);
    currentState.update();
}

function gameLoop() {
    update();
    render();
    requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', handleTap);

changeState(states.menu);
gameLoop();
