// Typing Speed Game

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
let ctx = canvas.getContext('2d');

let health = 100;
const maxHealth = 100;
let score = 0;
let lastRespawn = Date.now();
const respawnTime = 5000; // 5 seconds
let typingSpeed = 0;
let targetText = '';
let targetIndex = 0;

function resizeCanvas() {
  canvas.width = window.innerWidth * devicePixelRatio;
  canvas.height = window.innerHeight * devicePixelRatio;
  ctx = canvas.getContext('2d');
  ctx.scale(devicePixelRatio, devicePixelRatio);
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

function randomWord() {
  const words = ['javascript', 'canvas', 'game', 'typing', 'speed'];
  return words[Math.floor(Math.random() * words.length)];
}

function drawHealthBar() {
  ctx.fillStyle = 'red';
  ctx.fillRect(10, 10, (health / maxHealth) * 100, 20);
  ctx.fillStyle = 'black';
  ctx.strokeRect(10, 10, 100, 20);
}

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 35);
}

function drawTargetText() {
  ctx.fillStyle = 'black';
  ctx.fillText(targetText, canvas.width / 2 - targetText.length * 5, canvas.height / 2);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawHealthBar();
  drawScore();
  drawTargetText();
}

function update() {
  const now = Date.now();
  if (now - lastRespawn > respawnTime) {
    lastRespawn = now;
    targetText = randomWord();
    targetIndex = 0;
  }

  if (health <= 0) {
    health = maxHealth;
    score = 0;
    lastRespawn = now;
  }

  requestAnimationFrame(update);
}

function handleInput(event) {
  if (event.key === targetText[targetIndex]) {
    targetIndex++;
    if (targetIndex >= targetText.length) {
      score += targetText.length;
      targetText = randomWord();
      targetIndex = 0;
    }
  } else {
    health -= 10;
    if (health < 0) health = 0;
  }
}

document.addEventListener('keydown', handleInput);

update();
draw();
