class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Farm {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('cropHarvested', this.onCropHarvested.bind(this));
  }

  plantCrop(cropType) {
    console.log(`Planting ${cropType}`);
    this.eventBus.emit('cropPlanted', { cropType });
  }

  onCropHarvested(data) {
    console.log(`Harvested ${data.cropType}`);
  }
}

class Crop {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('cropPlanted', this.onCropPlanted.bind(this));
    this.growTime = 5000; // 5 seconds
  }

  onCropPlanted(data) {
    console.log(`Crop ${data.cropType} planted, will be ready in ${this.growTime / 1000} seconds.`);
    setTimeout(() => {
      console.log(`Crop ${data.cropType} is ready for harvest.`);
      this.eventBus.emit('cropHarvested', data);
    }, this.growTime);
  }
}

class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('cropHarvested', this.onCropHarvested.bind(this));
    this.prices = { wheat: 10, corn: 15 };
  }

  onCropHarvested(data) {
    const price = this.prices[data.cropType] || 0;
    console.log(`Market bought ${data.cropType} for $${price}`);
  }
}

