// Economy System
class Economy {
  constructor(initialBalance = 1000) {
    this.balance = initialBalance;
    this.prices = {
      'Potion': 50,
      'Sword': 200,
      'Shield': 150
    };
  }

  getBalance() {
    return this.balance;
  }

  getItemPrice(item) {
    return this.prices[item] || 0;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  credit(amount) {
    this.balance += amount;
  }
}

// Store System
class Store {
  constructor(economy) {
    this.economy = economy;
  }

  purchaseItem(item) {
    const price = this.economy.getItemPrice(item);
    if (price > 0 && this.economy.debit(price)) {
      console.log(`Purchased ${item} for ${price}`);
      return true;
    } else {
      console.log(`Failed to purchase ${item}`);
      return false;
    }
  }
}

// Inventory System
