  constructor() {
    this.health = 100;
  }

  takeDamage(amount) {
    this.health -= amount;
    console.log(`Took ${amount} damage. Health: ${this.health}`);
  }

  heal(amount) {
    this.health += amount;
    console.log(`Healed ${amount}. Health: ${this.health}`);
  }
}

// Loot System
