const powerUpImage = 'https://via.placeholder.com/50x50?text=Power+Up';

class Card {
    constructor(x, y, image, index) {
        this.x = x;
        this.y = y;
        this.image = image;
        this.index = index;
        this.flipped = false;
    }

    draw() {
        if (!this.flipped) {
            ctx.fillStyle = '#ccc';
            ctx.fillRect(this.x, this.y, cardWidth, cardHeight);
        } else {
            ctx.drawImage(this.image, this.x, this.y);
        }
    }

    isClicked(x, y) {
        return x > this.x && x < this.x + cardWidth && y > this.y && y < this.y + cardHeight;
    }
}

class PowerUp {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.active = false;
    }

    draw() {
        if (this.active) {
            ctx.drawImage(powerUpImage, this.x, this.y);
        }
    }

    isClicked(x, y) {
        return x > this.x && x < this.x + 50 && y > this.y && y < this.y + 50;
    }
}

function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
}

function createCards() {
    const images = [...cardImages];
    shuffle(images);
    let index = 0;
    for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
            const x = col * (cardWidth + gap);
            const y = row * (cardHeight + gap);
            cards.push(new Card(x, y, new Image(), index));
            cards[index].image.src = images[index];
            index++;
        }
    }
}

function createPowerUps() {
    const x = Math.random() * (canvas.width - 50);
    const y = Math.random() * (canvas.height - 50);
    powerUps.push(new PowerUp(x, y));
}

function checkForMatch() {
    if (selectedCards.length === 2) {
        const [card1, card2] = selectedCards;
        if (card1.image.src === card2.image.src) {
            score += 10;
            if (powerUpActive) {
                score += 5;
            }
        } else {
            setTimeout(() => {
                card1.flipped = false;
                card2.flipped = false;
            }, 1000);
        }
        selectedCards = [];
    }
}

function handlePowerUp() {
    powerUpActive = true;
    powerUpTimer = powerUpDuration;
}

function updatePowerUp() {
    if (powerUpActive) {
        powerUpTimer -= 1 / 60;
        if (powerUpTimer <= 0) {
            powerUpActive = false;
        }
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    cards.forEach(card => card.draw());
    powerUps.forEach(powerUp => powerUp.draw());
    ctx.fillStyle = '#000';
    ctx.fillText(`Score: ${score}`, 10, 20);
    if (powerUpActive) {
        ctx.fillText(`Power-Up Active: ${Math.floor(powerUpTimer)}s`, 10, 40);
    }
}

function gameLoop() {
    updatePowerUp();
    draw();
    requestAnimationFrame(gameLoop);
}

function handleClick(event) {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    cards.forEach(card => {
        if (!card.flipped && card.isClicked(x, y)) {
            card.flipped = true;
            selectedCards.push(card);
            checkForMatch();
        }
    });

    powerUps.forEach(powerUp => {
        if (powerUp.isClicked(x, y)) {
            powerUp.active = true;
            handlePowerUp();
        }
    });
}

canvas.addEventListener('click', handleClick);

createCards();
createPowerUps();
gameLoop();
