// JavaScript code
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

const plantType = {
    CARROT: { color: 'orange', growTime: 5000 },
    TOMATO: { color: 'red', growTime: 7000 },
    LETTUCE: { color: 'green', growTime: 3000 },
};

const enemies = [];
const plants = [];
const enemiesPerWave = 3;
let waveInterval = 5000;
let lastWaveTime = 0;
let lastUpdateTime = 0;
let score = 0;

class Plant {
    constructor(x, y, type) {
        this.x = x;
        this.y = y;
        this.type = type;
        this.growthTime = type.growTime;
        this.growStartTime = Date.now();
    }

    update() {
        const currentTime = Date.now();
        if (currentTime - this.growStartTime >= this.growthTime) {
            this.harvest();
        }
    }

    render() {
        ctx.fillStyle = this.type.color;
        ctx.fillRect(this.x, this.y, 20, 20);
    }

    harvest() {
        score += 10;
        const index = plants.indexOf(this);
        if (index !== -1) {
            plants.splice(index, 1);
        }
    }
}

class Enemy {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.speed = 0.5;
    }

    update() {
        this.y += this.speed;
    }

    render() {
        ctx.fillStyle = 'red';
        ctx.fillRect(this.x, this.y, 10, 10);
    }

    checkCollision(plant) {
        return (
            this.x < plant.x + 20 &&
            this.x + 10 > plant.x &&
            this.y < plant.y + 20 &&
            this.y + 10 > plant.y
        );
    }
}

function spawnEnemies() {
    for (let i = 0; i < enemiesPerWave; i++) {
        const x = Math.random() * canvas.width;
        const y = -10;
        enemies.push(new Enemy(x, y));
    }
}

function update() {
    const now = Date.now();
    const dt = now - lastUpdateTime;
    lastUpdateTime = now;

    if (now - lastWaveTime >= waveInterval) {
        spawnEnemies();
        lastWaveTime = now;
        waveInterval = Math.max(waveInterval * 0.9, 2000);
    }

    plants.forEach(plant => plant.update());
    enemies.forEach(enemy => {
        enemy.update();
        plants.forEach(plant => {
            if (enemy.checkCollision(plant)) {
                plant.harvest();
            }
        });
    });
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    plants.forEach(plant => plant.render());
