}

function drawRoom() {
  tiles.forEach(tile => drawTile(tile.x, tile.y, tile.type));
}

function drawTimer() {
  ctx.fillStyle = '#000';
  ctx.font = '24px Arial';
  ctx.fillText(`Time: ${Math.floor(timer)}s`, 10, 30);
}

