    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

const player = { x: canvas.width / 2, y: canvas.height / 2, radius: 10, speed: 5, color: 'blue' };
const enemies = [];
const powerUps = [];
const bullets = [];
const shootCooldown = 100;
let lastShootTime = 0;
let score = 0;

function spawnEnemy() {
    enemies.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        radius: 8,
        speed: 2 + Math.random() * 2,
        color: 'red'
    });
}

function spawnPowerUp() {
    powerUps.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        radius: 5,
        color: 'green'
    });
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Player movement
    const keys = { w: false, a: false, s: false, d: false };
    document.addEventListener('keydown', e => keys[e.key] = true);
    document.addEventListener('keyup', e => keys[e.key] = false);

    if (keys.w && player.y > player.radius) player.y -= player.speed;
    if (keys.a && player.x > player.radius) player.x -= player.speed;
    if (keys.s && player.y < canvas.height - player.radius) player.y += player.speed;
    if (keys.d && player.x < canvas.width - player.radius) player.x += player.speed;

    // Shooting
    if (keys[' '] && Date.now() - lastShootTime > shootCooldown) {
        bullets.push({
            x: player.x,
            y: player.y,
            radius: 3,
            speed: 10,
            color: 'yellow'
        });
        lastShootTime = Date.now();
    }

    // Bullet movement
    bullets.forEach((bullet, i) => {
        bullet.y -= bullet.speed;
        if (bullet.y < 0) {
            bullets.splice(i, 1);
        }
    });

    // Enemy movement and collision with bullets
    enemies.forEach((enemy, i) => {
        enemy.x += (Math.random() - 0.5) * enemy.speed;
        enemy.y += (Math.random() - 0.5) * enemy.speed;

        bullets.forEach((bullet, j) => {
            const distance = Math.hypot(enemy.x - bullet.x, enemy.y - bullet.y);
            if (distance < enemy.radius + bullet.radius) {
                enemies.splice(i, 1);
                bullets.splice(j, 1);
                score++;
            }
        });

        if (Math.hypot(player.x - enemy.x, player.y - enemy.y) < player.radius + enemy.radius) {
            alert(`Game Over! Your score: ${score}`);
            resetGame();
        }
    });

    // Power-up collision with player
    powerUps.forEach((powerUp, i) => {
        const distance = Math.hypot(player.x - powerUp.x, player.y - powerUp.y);
        if (distance < player.radius + powerUp.radius) {
            powerUps.splice(i, 1);
            player.speed += 0.5;
        }
    });

    // Rendering
    ctx.fillStyle = player.color;
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 20);

    enemies.forEach(enemy => {
        ctx.fillStyle = enemy.color;
        ctx.beginPath();
        ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
        ctx.fill();
    });

    powerUps.forEach(powerUp => {
        ctx.fillStyle = powerUp.color;
        ctx.beginPath();
        ctx.arc(powerUp.x, powerUp.y, powerUp.radius, 0, Math.PI * 2);
        ctx.fill();
    });

