        ctx.beginPath();
        ctx.arc(bullet.x, bullet.y, bullet.radius, 0, Math.PI * 2);
        ctx.fill();
    });

    if (Math.random() < 0.05) spawnEnemy();
    if (Math.random() < 0.02) spawnPowerUp();

    requestAnimationFrame(update);
}

function resetGame() {
    enemies.length = 0;
    powerUps.length = 0;
    bullets.length = 0;
    player.speed = 5;
