// Event Bus
class EventBus {
    constructor() {
        this.events = {};
    }

    emit(eventName, data) {
        if (this.events[eventName]) {
            this.events[eventName].forEach(handler => handler(data));
        }
    }

    subscribe(eventName, handler) {
        if (!this.events[eventName]) {
            this.events[eventName] = [];
        }
        this.events[eventName].push(handler);
    }
}

// Spawner System
class Spawner {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.spawnInterval = 2000; // 2 seconds
    }

    start() {
        setInterval(() => {
            this.spawnEnemy();
        }, this.spawnInterval);
    }

    spawnEnemy() {
        const enemy = { id: Date.now(), health: 100 };
        this.eventBus.emit('enemySpawned', enemy);
        console.log(`Enemy spawned with ID: ${enemy.id}`);
    }
}

// EnemyPool System
class EnemyPool {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.enemies = [];
    }

    start() {
        this.eventBus.subscribe('enemySpawned', this.onEnemySpawned.bind(this));
        this.eventBus.subscribe('enemyHit', this.onEnemyHit.bind(this));
    }

    onEnemySpawned(enemy) {
        this.enemies.push(enemy);
        console.log(`Enemy added to pool. Total enemies: ${this.enemies.length}`);
    }

    onEnemyHit(enemyId, damage) {
        const enemy = this.enemies.find(e => e.id === enemyId);
        if (enemy) {
            enemy.health -= damage;
            if (enemy.health <= 0) {
                this.removeEnemy(enemyId);
                console.log(`Enemy ${enemyId} destroyed.`);
            } else {
                console.log(`Enemy ${enemyId} hit. Remaining health: ${enemy.health}`);
            }
        }
    }

    removeEnemy(enemyId) {
        this.enemies = this.enemies.filter(e => e.id !== enemyId);
    }
}

// Score System
class Score {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.score = 0;
    }

    start() {
        this.eventBus.subscribe('enemyDestroyed', this.onEnemyDestroyed.bind(this));
    }

    onEnemyDestroyed(enemyId) {
        this.score += 100;
        console.log(`Enemy ${enemyId} destroyed. Current score: ${this.score}`);
    }
}

