    constructor(spawnRate, enemyPool) {
        this.spawnRate = spawnRate;
        this.enemyPool = enemyPool;
        this.lastSpawnTime = Date.now();
    }

    spawnEnemy() {
        const currentTime = Date.now();
        if (currentTime - this.lastSpawnTime >= this.spawnRate) {
            this.enemyPool.addEnemy();
            this.lastSpawnTime = currentTime;
        }
    }
}

// EnemyPool system
class EnemyPool {
    constructor() {
        this.enemies = [];
    }

    addEnemy() {
        const newEnemy = { id: Date.now(), health: 100 };
        this.enemies.push(newEnemy);
        console.log(`Enemy spawned with ID: ${newEnemy.id}`);
    }

    getEnemyCount() {
        return this.enemies.length;
    }
}

// Score system
class Score {
    constructor() {
        this.score = 0;
    }

    increaseScore(points) {
        this.score += points;
        console.log(`Score increased by ${points}. Total score: ${this.score}`);
    }

    getScore() {
        return this.score;
    }
}

// Top-level coordinator
class GameCoordinator {
    constructor(spawnRate) {
        this.enemyPool = new EnemyPool();
        this.score = new Score();
        this.spawner = new Spawner(spawnRate, this.enemyPool);
    }

    startGame() {
        setInterval(() => {
            this.spawner.spawnEnemy();
            // Simulate enemy being defeated
            if (this.enemyPool.getEnemyCount() > 0) {
                const enemy = this.enemyPool.enemies.shift();
                console.log(`Enemy with ID ${enemy.id} defeated.`);
                this.score.increaseScore(50);
            }
        }, 1000);
    }
}

// Runnable demo
const game = new GameCoordinator(2000); // Spawn rate of 2 seconds
game.startGame();
