    this.economy = economy;
    this.inventory = inventory;
  }

  purchaseItem(item) {
    const cost = this.economy.getCost(item);
    if (cost > 0) {
      this.economy.debit(cost);
      this.inventory.addItem(item);
      console.log(`Purchased ${item} for ${cost}`);
    } else {
