    this.eventBus = eventBus;
    this.buildings = {};
    this.eventBus.subscribe('resourceGathered', this.onResourceGathered.bind(this));
  }

  constructBuilding(type, cost) {
    if (this.canAfford(cost)) {
      this.eventBus.emit('resourceSpent', cost);
      this.buildings[type] = (this.buildings[type] || 0) + 1;
      console.log(`Constructed ${type} building. Total: ${this.buildings[type]}`);
    } else {
      console.log(`Not enough resources to construct ${type} building.`);
    }
  }

  canAfford(cost) {
    const currentResources = this.eventBus.emitSync('getCurrentResources');
    return Object.keys(cost).every(resource => 
      (currentResources[resource] || 0) >= cost[resource]
    );
  }

  onResourceGathered(gainedResources) {
    console.log(`Resource gained: ${JSON.stringify(gainedResources)}`);
  }
}

class Resource {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.resources = { gold: 0, wood: 0 };
    this.eventBus.subscribe('resourceGathered', this.onResourceGathered.bind(this));
    this.eventBus.subscribe('resourceSpent', this.onResourceSpent.bind(this));
  }

  gatherResource(resourceType, amount) {
    this.resources[resourceType] = (this.resources[resourceType] || 0) + amount;
    this.eventBus.emit('resourceGathered', { [resourceType]: amount });
  }

  onResourceGathered(gainedResources) {
    for (const resource in gainedResources) {
      this.resources[resource] = (this.resources[resource] || 0) + gainedResources[resource];
    }
  }

  onResourceSpent(cost) {
    for (const resource in cost) {
      this.resources[resource] -= cost[resource];
    }
  }

  getCurrentResources() {
    return { ...this.resources };
  }
}

