// Flappy-style gap dodger with countdown timer

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

const gravity = 0.25;
const jumpVelocity = -5;
const gapHeight = 150;
const gapWidth = 50;
const pipeSpeed = 2;
const frameRate = 60;
const fixedTimeStep = 1000 / frameRate;
const countdownDuration = 3;

let pipes = [];
let bird = { x: 50, y: canvas.height / 2, velocity: 0 };
let score = 0;
let countdown = countdownDuration;
let gameRunning = false;
let lastTimestamp = 0;

function startGame() {
    pipes = [];
    bird.y = canvas.height / 2;
    bird.velocity = 0;
    score = 0;
    countdown = countdownDuration;
    gameRunning = true;
    requestAnimationFrame(gameLoop);
}

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTimestamp;
    lastTimestamp = timestamp;

    if (!gameRunning) {
        countdown -= deltaTime / 1000;
        if (countdown <= 0) {
            gameRunning = true;
        }
    } else {
        bird.velocity += gravity;
        bird.y += bird.velocity;

        if (bird.y >= canvas.height || bird.y <= 0) {
            gameRunning = false;
        }

        if (deltaTime >= fixedTimeStep) {
            pipes.forEach(pipe => {
                pipe.x -= pipeSpeed;
                if (pipe.x < -gapWidth) {
                    pipes.shift();
                    score++;
                }
            });

            if (pipes.length === 0 || pipes[pipes.length - 1].x < canvas.width - gapWidth * 2) {
                const randomY = Math.random() * (canvas.height - gapHeight);
                pipes.push({ x: canvas.width, y: randomY });
                pipes.push({ x: canvas.width, y: randomY + gapHeight + gapWidth });
            }

            pipes.forEach(pipe => {
                if (bird.x < pipe.x + gapWidth &&
                    bird.x + 20 > pipe.x &&
                    (bird.y < pipe.y || bird.y + 20 > pipe.y + gapHeight)) {
                    gameRunning = false;
                }
            });
        }
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBird();
    drawPipes();
    drawScore();
    drawCountdown();
    if (gameRunning) {
        requestAnimationFrame(gameLoop);
    } else {
        ctx.font = '48px Arial';
        ctx.fillStyle = 'red';
        ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
        setTimeout(startGame, 2000);
    }
}

function drawBird() {
    ctx.fillStyle = 'yellow';
    ctx.fillRect(bird.x, bird.y, 20, 20);
}

function drawPipes() {
    ctx.fillStyle = 'green';
    pipes.forEach(pipe => {
        ctx.fillRect(pipe.x, 0, gapWidth, pipe.y);
