class Economy {
  constructor(initialBalance = 1000) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
  }

  credit(amount) {
    this.balance += amount;
  }
}

class RarityTable {
  constructor() {
    this.rarityMap = {
      common: 0.7,
      uncommon: 0.2,
      rare: 0.08,
      epic: 0.02
    };
  }

  getRandomRarity() {
    const rand = Math.random();
    let cumulativeProbability = 0;
    for (const rarity in this.rarityMap) {
      cumulativeProbability += this.rarityMap[rarity];
      if (rand <= cumulativeProbability) {
        return rarity;
      }
    }
    return "common"; // Default to common if something goes wrong
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (this.items[item.name]) {
      this.items[item.name].quantity++;
    } else {
      this.items[item.name] = { ...item, quantity: 1 };
    }
  }

  getItems() {
    return this.items;
  }
}

class Store {
  constructor(economy, rarityTable, inventory) {
    this.economy = economy;
    this.rarityTable = rarityTable;
    this.inventory = inventory;
  }

  purchaseItem(price) {
    this.economy.debit(price);
    const rarity = this.rarityTable.getRandomRarity();
    const item = { name: `Item-${rarity}`, rarity };
    this.inventory.addItem(item);
    return item;
  }
}

// Demo
