// Constants
const PARTICLE_COUNT = 50;
const PARTICLE_SIZE = 2;
const PARTICLE_SPEED = 2;
const ASTEROID_COUNT = 5;
const ASTEROID_SIZE = 30;
const ASTEROID_SPEED = 1;
const SHIP_SIZE = 20;
const SHIP_SPEED = 5;
const SHIP_TURN_SPEED = 0.1;
const BURST_RADIUS = 100;
const BURST_DURATION = 0.5;

// Canvas setup
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
let dpr = window.devicePixelRatio;
let rect = canvas.getBoundingClientRect();
canvas.width = rect.width * dpr;
canvas.height = rect.height * dpr;
canvas.style.width = `${rect.width}px`;
canvas.style.height = `${rect.height}px`;
const ctx = canvas.getContext('2d');

// Vectors
function Vector(x, y) {
    this.x = x;
    this.y = y;
}

Vector.prototype.add = function(other) {
    return new Vector(this.x + other.x, this.y + other.y);
};

Vector.prototype.scale = function(scalar) {
    return new Vector(this.x * scalar, this.y * scalar);
};

Vector.prototype.magnitude = function() {
    return Math.sqrt(this.x * this.x + this.y * this.y);
};

Vector.prototype.normalized = function() {
    const mag = this.magnitude();
    return new Vector(this.x / mag, this.y / mag);
};

// Particle
function Particle(position, velocity, lifespan) {
    this.position = position;
    this.velocity = velocity;
    this.lifespan = lifespan;
}

Particle.prototype.update = function(dt) {
    this.position = this.position.add(this.velocity.scale(dt));
    this.lifespan -= dt;
    return this.lifespan > 0;
};

Particle.prototype.draw = function(ctx) {
    ctx.beginPath();
    ctx.arc(this.position.x, this.position.y, PARTICLE_SIZE, 0, 2 * Math.PI);
    ctx.fill();
};

// Asteroid
function Asteroid(position, velocity, size) {
    this.position = position;
    this.velocity = velocity;
    this.size = size;
}

Asteroid.prototype.update = function() {
    this.position = this.position.add(this.velocity);
    if (this.position.x < -this.size) this.position.x = canvas.width + this.size;
    if (this.position.x > canvas.width + this.size) this.position.x = -this.size;
    if (this.position.y < -this.size) this.position.y = canvas.height + this.size;
    if (this.position.y > canvas.height + this.size) this.position.y = -this.size;
};

Asteroid.prototype.draw = function(ctx) {
    ctx.beginPath();
    ctx.arc(this.position.x, this.position.y, this.size, 0, 2 * Math.PI);
    ctx.fill();
};

// Ship
function Ship(position, velocity, direction) {
    this.position = position;
    this.velocity = velocity;
    this.direction = direction;
    this.speed = SHIP_SPEED;
}

Ship.prototype.update = function(dt) {
    this.direction += this.turnSpeed * dt;
    this.velocity = new Vector(this.speed * Math.cos(this.direction), this.speed * Math.sin(this.direction));
    this.position = this.position.add(this.velocity.scale(dt));
    if (this.position.x < 0) this.position.x = canvas.width;
    if (this.position.x > canvas.width) this.position.x = 0;
    if (this.position.y < 0) this.position.y = canvas.height;
    if (this.position.y > canvas.height) this.position.y = 0;
};

Ship.prototype.draw = function(ctx) {
    ctx.beginPath();
    ctx.moveTo(this.position.x + SHIP_SIZE * Math.cos(this.direction), this.position.y + SHIP_SIZE * Math.sin(this.direction));
    ctx.lineTo(this.position.x + SHIP_SIZE * Math.cos(this.direction + 2 * Math.PI / 3), this.position.y + SHIP_SIZE * Math.sin(this.direction + 2 * Math.PI / 3));
    ctx.lineTo(this.position.x + SHIP_SIZE * Math.cos(this.direction - 2 * Math.PI / 3), this.position.y + SHIP_SIZE * Math.sin(this.direction - 2 * Math.PI / 3));
    ctx.closePath();
    ctx.fill();
};

// Game state
let particles = [];
let asteroids = [];
let ship = new Ship(new Vector(canvas.width / 2, canvas.height / 2), new Vector(0, 0), Math.PI / 2);
let burstTime = null;

function createAsteroids(count) {
    for (let i = 0; i < count; i++) {
        let position = new Vector(Math.random() * canvas.width, Math.random() * canvas.height);
        let velocity = new Vector(Math.random() - 0.5, Math.random() - 0.5).normalized().scale(ASTEROID_SPEED);
        asteroids.push(new Asteroid(position, velocity, ASTEROID_SIZE));
    }
}

createAsteroids(ASTEROID_COUNT);

// Input
let keys = {};
window.addEventListener('keydown', function(e) {
    keys[e.key] = true;
});
window.addEventListener('keyup', function(e) {
    keys[e.key] = false;
});

// Update
function update(dt) {
    ship.turnSpeed = 0;
    if (keys['ArrowLeft']) ship.turnSpeed = -SHIP_TURN_SPEED;
    if (keys['ArrowRight']) ship.turnSpeed = SHIP_TURN_SPEED;
    if (keys['ArrowUp']) ship.update(dt);
    if (keys['Space']) {
        if (!burstTime) {
            burstTime = performance.now();
            for (let i = 0; i < PARTICLE_COUNT; i++) {
                let angle = Math.random() * 2 * Math.PI;
                let speed = PARTICLE_SPEED + Math.random() * PARTICLE_SPEED;
                let velocity = new Vector(speed * Math.cos(angle), speed * Math.sin(angle));
                particles.push(new Particle(ship.position, velocity, BURST_DURATION));
            }
        }
    } else {
        burstTime = null;
    }

    for (let i = particles.length - 1; i >= 0; i--) {
        if (!particles[i].update(dt)) {
            particles.splice(i, 1);
        }
    }

    for (let asteroid of asteroids) {
        asteroid.update();
    }
}

// Draw
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    for (let particle of particles) {
        particle.draw(ctx);
    }

    for (let asteroid of asteroids) {
        asteroid.draw(ctx);
    }

    ship.draw(ctx);
}

// Main loop
let lastTime = performance.now();
function loop() {
    let now = performance.now();
    let dt = (now - lastTime) / 1000;
    lastTime = now;

    update(dt);
    draw();

    requestAnimationFrame(loop);
}

loop();
