class Bank {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor(initialPrices = {}) {
        this.prices = { ...initialPrices };
    }

    setPrice(item, price) {
        if (price >= 0) {
            this.prices[item] = price;
            return true;
        }
        return false;
    }

    getPrice(item) {
        return this.prices[item] || null;
    }
}

class Inventory {
    constructor(initialStock = {}) {
        this.stock = { ...initialStock };
    }

    addItem(item, quantity) {
        if (quantity > 0) {
            this.stock[item] = (this.stock[item] || 0) + quantity;
            return true;
        }
        return false;
    }

    removeItem(item, quantity) {
        if (this.stock[item] && quantity > 0 && this.stock[item] >= quantity) {
            this.stock[item] -= quantity;
            return true;
        }
        return false;
    }

    getStock(item) {
        return this.stock[item] || 0;
    }
}

