const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const FPS = 60;
const FIXED_TIMESTEP = 1000 / FPS;
let lastTime = 0;

const player = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  radius: 10,
  health: 100
};

const ball = {
  x: canvas.width / 2,
  y: 0,
  radius: 5,
  velocity: 2
};

const gravity = 0.5;
const damping = 0.8;

function drawCircle(x, y, radius, color) {
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.closePath();
}

function drawHealthBar(health) {
  const barWidth = 200;
  const barHeight = 20;
  const x = (canvas.width - barWidth) / 2;
  const y = 10;
  const fillWidth = (health / 100) * barWidth;

  ctx.fillStyle = '#333';
  ctx.fillRect(x, y, barWidth, barHeight);
  ctx.fillStyle = '#0f0';
  ctx.fillRect(x, y, fillWidth, barHeight);
}

function update(delta) {
  ball.y += ball.velocity * delta;
  ball.velocity += gravity * delta;

  if (ball.y + ball.radius >= player.y - player.radius &&
      ball.x >= player.x - player.radius &&
      ball.x <= player.x + player.radius) {
    player.health -= 10;
    ball.velocity *= -damping;
    ball.y = player.y - player.radius - ball.radius;
  }

  if (ball.y + ball.radius > canvas.height) {
    ball.y = canvas.height - ball.radius;
    ball.velocity *= -damping;
  }

  if (player.health <= 0) {
    player.x = canvas.width / 2;
    player.y = canvas.height / 2;
    player.health = 100;
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawCircle(player.x, player.y, player.radius, '#00f');
  drawCircle(ball.x, ball.y, ball.radius, '#f00');
  drawHealthBar(player.health);
}

function gameLoop(timestamp) {
  const delta = timestamp - lastTime;
  lastTime = timestamp;

  update(delta);
  render();

  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
