let currentBlock = null;
let currentBlockX = 0;
let currentBlockY = 0;
let gameInterval;

function createBlock() {
  return {
    shape: [
      [1, 1, 1, 1]
    ],
    color: `rgb(${Math.random() * 255}, ${Math.random() * 255}, ${Math.random() * 255})`
  };
}

function drawBlock(x, y, block) {
  block.shape.forEach((row, i) => {
    row.forEach((cell, j) => {
      if (cell) {
        ctx.fillStyle = block.color;
        ctx.fillRect((x + j) * BLOCK_SIZE, (y + i) * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
      }
    });
  });
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  blocks.forEach(block => drawBlock(block.x, block.y, block));
  if (currentBlock) {
    drawBlock(currentBlockX, currentBlockY, currentBlock);
  }
}

function moveBlock(dx, dy) {
  if (!currentBlock) return;
  const newX = currentBlockX + dx;
  const newY = currentBlockY + dy;
  if (newX >= 0 && newX + currentBlock.shape[0].length <= COLS && newY + currentBlock.shape.length <= ROWS) {
    currentBlockX = newX;
    currentBlockY = newY;
  }
}

function dropBlock() {
  if (!currentBlock) return;
  if (currentBlockY + currentBlock.shape.length < ROWS) {
    currentBlockY++;
  } else {
    blocks.push({ ...currentBlock, x: currentBlockX, y: currentBlockY });
    currentBlock = null;
    currentBlockX = 0;
    currentBlockY = 0;
  }
}

function gameLoop() {
  dropBlock();
  draw();
  if (!currentBlock) {
    currentBlock = createBlock();
  }
}

function resizeCanvas() {
  dpr = window.devicePixelRatio;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}

window.addEventListener('resize', resizeCanvas);
document.addEventListener('keydown', e => {
  switch (e.key) {
    case 'ArrowLeft':
      moveBlock(-1, 0);
      break;
    case 'ArrowRight':
      moveBlock(1, 0);
      break;
    case 'ArrowDown':
      dropBlock();
      break;
  }
});
canvas.addEventListener('click', e => {
  const rect = canvas.getBoundingClientRect();
  const x = Math.floor((e.clientX - rect.left) / BLOCK_SIZE);
  const y = Math.floor((e.clientY - rect.top) / BLOCK_SIZE);
  moveBlock(x - currentBlockX, y - currentBlockY);
});

gameInterval = setInterval(gameLoop, 500);
resizeCanvas();
draw();
