class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited ${amount}. New balance: ${this.balance}`);
    } else {
      console.log('Deposit amount must be positive.');
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
    } else {
      console.log('Invalid withdrawal amount.');
    }
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices) {
    this.prices = prices; // prices is an object mapping item names to prices
  }

  buyItem(item, amount, bank) {
    if (this.prices[item]) {
      const totalPrice = this.prices[item] * amount;
      if (bank.getBalance() >= totalPrice) {
        bank.withdraw(totalPrice);
        console.log(`Bought ${amount} ${item}(s) for ${totalPrice}.`);
      } else {
        console.log('Insufficient funds.');
      }
    } else {
      console.log('Item not available in the market.');
    }
  }

  sellItem(item, amount, bank, inventory) {
    if (inventory.hasItem(item, amount)) {
      const totalPrice = this.prices[item] * amount;
      bank.deposit(totalPrice);
      inventory.removeItem(item, amount);
      console.log(`Sold ${amount} ${item}(s) for ${totalPrice}.`);
    } else {
      console.log('Insufficient inventory.');
    }
  }
}

class Inventory {
  constructor() {
    this.items = {}; // items is an object mapping item names to quantities
  }

  addItem(item, amount) {
    if (amount > 0) {
      this.items[item] = (this.items[item] || 0) + amount;
      console.log(`Added ${amount} ${item}(s).`);
    } else {
      console.log('Add amount must be positive.');
    }
  }

  removeItem(item, amount) {
    if (this.items[item] && this.items[item] >= amount) {
      this.items[item] -= amount;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      console.log(`Removed ${amount} ${item}(s).`);
    } else {
      console.log('Insufficient inventory.');
    }
  }

  hasItem(item, amount) {
    return this.items[item] && this.items[item] >= amount;
  }

  getInventory() {
    return this.items;
  }
}

// Demo
const bank = new Bank();
const marketPrices = { apple: 1, banana: 2, carrot: 3 };
const market = new Market(marketPrices);
const inventory = new Inventory();

// Bank operations
bank.deposit(10);
bank.withdraw(3);

// Market buy and sell operations
market.buyItem('apple', 2, bank);
market.buyItem('banana', 1, bank);
console.log('Current inventory:', inventory.getInventory());

market.sellItem('apple', 1, bank, inventory);
console.log('Current inventory:', inventory.getInventory());
console.log('Current balance:', bank.getBalance());
