    ctx.fillStyle = '#000';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(timer.toString(), canvas.width / 2, canvas.height / 2);
}

function startGame() {
    resize();
    startTime = Date.now();
    timer = 5;
    isTapping = true;
    gameLoop();
}

function gameLoop() {
    const currentTime = Date.now();
    const elapsedTime = (currentTime - startTime) / 1000;
    timer = Math.max(0, 5 - elapsedTime);
    draw();
    if (timer > 0) {
        requestAnimationFrame(gameLoop);
    } else {
        isTapping = false;
        alert('Game Over! Your score: ' + Math.floor(elapsedTime));
    }
}

function handleTap() {
    if (isTapping) {
        timer += 0.2; // Add 0.2 seconds for each tap
        startTime = Date.now();
    }
}

