// Snake-style grid game with countdown timer
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio || 1;
let grid = 20;
let width = Math.floor(window.innerWidth / grid) * grid;
let height = Math.floor(window.innerHeight / grid) * grid;
canvas.width = width * dpr;
canvas.height = height * dpr;
ctx.scale(dpr, dpr);

let snake = [{ x: width / 2, y: height / 2 }];
let direction = { x: 0, y: 0 };
let food = { x: Math.floor(Math.random() * width / grid) * grid, y: Math.floor(Math.random() * height / grid) * grid };
let score = 0;
let timer = 30; // Countdown timer in seconds
let gameInterval;
let timerInterval;

function init() {
    document.addEventListener('keydown', changeDirection);
    gameInterval = setInterval(gameLoop, 100);
    timerInterval = setInterval(updateTimer, 1000);
}

function changeDirection(e) {
    switch (e.key) {
        case 'ArrowUp':
            if (direction.y === 0) direction = { x: 0, y: -grid };
            break;
        case 'ArrowDown':
            if (direction.y === 0) direction = { x: 0, y: grid };
            break;
        case 'ArrowLeft':
            if (direction.x === 0) direction = { x: -grid, y: 0 };
            break;
        case 'ArrowRight':
            if (direction.x === 0) direction = { x: grid, y: 0 };
            break;
    }
}

function gameLoop() {
    ctx.clearRect(0, 0, width, height);
    drawSnake();
    moveSnake();
    drawFood();
    checkCollision();
}

function drawSnake() {
    ctx.fillStyle = 'green';
    snake.forEach(segment => {
        ctx.fillRect(segment.x, segment.y, grid, grid);
    });
}

function moveSnake() {
    let head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };
    snake.unshift(head);
    if (head.x === food.x && head.y === food.y) {
        score++;
        placeFood();
    } else {
        snake.pop();
    }
}

function drawFood() {
    ctx.fillStyle = 'red';
    ctx.fillRect(food.x, food.y, grid, grid);
}

function placeFood() {
    food.x = Math.floor(Math.random() * width / grid) * grid;
    food.y = Math.floor(Math.random() * height / grid) * grid;
}

function checkCollision() {
    let head = snake[0];
    if (head.x < 0 || head.x >= width || head.y < 0 || head.y >= height || snake.slice(1).some(segment => segment.x === head.x && segment.y === head.y)) {
        endGame();
    }
}

function updateTimer() {
    timer--;
    if (timer < 0) {
        endGame();
    }
}

function endGame() {
    clearInterval(gameInterval);
    clearInterval(timerInterval);
    ctx.fillStyle = 'black';
    ctx.font = '30px Arial';
    ctx.fillText(`Game Over! Score: ${score}`, width / 2 - 100, height / 2);
}

init();
