class Economy {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Store {
  constructor(economy, initialInventory = {}) {
    this.economy = economy;
    this.inventory = initialInventory;
  }

  buy(item, price) {
    if (this.economy.withdraw(price)) {
      this.inventory[item] = (this.inventory[item] || 0) + 1;
      return true;
    }
    return false;
  }

  sell(item, price) {
    if (this.inventory[item] && this.inventory[item] > 0) {
      this.economy.deposit(price);
      this.inventory[item] -= 1;
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.inventory };
  }
}

class Inventory {
  constructor(store) {
    this.store = store;
  }

  addItem(item) {
    if (this.store.getInventory()[item] > 0) {
      this.store.sell(item, 0); // Sell at 0 price to just transfer to inventory
      return true;
    }
    return false;
  }

  removeItem(item) {
    this.store.buy(item, 0); // Buy at 0 price to just transfer from inventory
    return true;
  }

  getContents() {
    return { ...this.store.getInventory() };
  }
}

