      console.log(`Debited ${amount}, remaining balance: ${this.balance}`);
      return true;
    } else {
      console.log(`Insufficient funds to debit ${amount}`);
      return false;
    }
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }
}

class Inventory {
