    this.items = {
      food: 0,
      energy: 0
    };
  }

  addItem(item, quantity) {
    if (this.items[item] !== undefined) {
      this.items[item] += quantity;
      console.log(`Added ${quantity} ${item}(s), current stock: ${this.items[item]}`);
    } else {
      console.log(`Unknown item: ${item}`);
    }
  }
}

class Store {
