  pipes.push({
    x: canvas.width,
    y: 0,
    height,
    draw() {
      ctx.fillStyle = 'green';
      ctx.fillRect(this.x, this.y, pipeWidth, this.height);
      ctx.fillRect(this.x, this.y + this.height + pipeGap, pipeWidth, canvas.height);
    },
    update() {
      this.x -= 2;
    }
  });
}

function checkCollision() {
