class EventBus {
  constructor() {
    this.events = {};
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(callback => callback(data));
    }
  }

  subscribe(eventName, callback) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(callback);
  }
}

class Wallet {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('purchaseAttempt', this.handlePurchaseAttempt.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}. New balance: ${this.balance}`);
  }

  withdraw(amount) {
    if (amount > this.balance) {
      console.log(`Insufficient funds. Current balance: ${this.balance}`);
      return false;
    }
    this.balance -= amount;
    console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
    return true;
  }

  handlePurchaseAttempt(data) {
    if (this.withdraw(data.amount)) {
      this.eventBus.emit('purchaseSuccess', data);
    } else {
      this.eventBus.emit('purchaseFailure', data);
    }
  }
}

class Shop {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {
      'sword': { price: 50 },
      'potion': { price: 10 }
    };
    this.eventBus.subscribe('purchaseSuccess', this.handlePurchaseSuccess.bind(this));
    this.eventBus.subscribe('purchaseFailure', this.handlePurchaseFailure.bind(this));
  }

  purchase(item) {
    const price = this.items[item]?.price;
    if (!price) {
      console.log(`Item ${item} not found.`);
      return;
    }
    this.eventBus.emit('purchaseAttempt', { item, amount: price });
  }

  handlePurchaseSuccess(data) {
    console.log(`Purchase of ${data.item} succeeded.`);
  }

  handlePurchaseFailure(data) {
    console.log(`Purchase of ${data.item} failed due to insufficient funds.`);
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('purchaseSuccess', this.handlePurchaseSuccess.bind(this));
  }

  handlePurchaseSuccess(data) {
    if (!this.items[data.item]) {
      this.items[data.item] = 0;
    }
    this.items[data.item]++;
    console.log(`Added ${data.item} to inventory. Total: ${this.items[data.item]}`);
  }
}

