    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('purchase', this.handlePurchase.bind(this));
  }

  addMoney(amount) {
    this.balance += amount;
    console.log(`Added ${amount} to wallet. New balance: ${this.balance}`);
  }

  handlePurchase(data) {
    if (this.balance >= data.price) {
      this.balance -= data.price;
      console.log(`Purchased ${data.item} for ${data.price}. Remaining balance: ${this.balance}`);
      this.eventBus.emit('itemBought', data.item);
    } else {
      console.log(`Insufficient funds to buy ${data.item}`);
    }
  }
}

class Shop {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {
      sword: 50,
      shield: 30,
      potion: 10
    };
    this.eventBus.subscribe('itemBought', this.handleItemBought.bind(this));
  }

  listItems() {
    console.log('Items available in shop:');
    for (const [item, price] of Object.entries(this.items)) {
      console.log(`${item} - ${price}`);
    }
  }

  buyItem(item) {
    if (this.items[item]) {
      this.eventBus.emit('purchase', { item, price: this.items[item] });
    } else {
      console.log('Item not found in shop.');
    }
  }

  handleItemBought(item) {
    console.log(`Sold ${item} in shop.`);
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = [];
    this.eventBus.subscribe('itemBought', this.addItem.bind(this));
  }

  addItem(item) {
    this.items.push(item);
    console.log(`Added ${item} to inventory. Current inventory: ${this.items.join(', ')}`);
  }
}

