    this.name = name;
    this.level = initialLevel;
  }

  improve(levelIncrease = 1) {
    this.level += levelIncrease;
    console.log(`Skill ${this.name} improved to level ${this.level}`);
  }

  getLevel() {
    return this.level;
  }
}

class Experience {
  constructor(baseExperience = 0) {
    this.experience = baseExperience;
  }

  gain(amount) {
    this.experience += amount;
    console.log(`Gained ${amount} experience. Total: ${this.experience}`);
  }

  getTotalExperience() {
    return this.experience;
  }
}

class LevelUp {
  constructor(skill, experience) {
    this.skill = skill;
    this.experience = experience;
    this.levelThresholds = [10, 20, 30]; // Example thresholds for level 1, 2, 3
  }

  checkLevelUp() {
    const currentExperience = this.experience.getTotalExperience();
    const currentLevel = this.skill.getLevel();

    for (let i = 0; i < this.levelThresholds.length; i++) {
      if (currentExperience >= this.levelThresholds[i] && currentLevel <= i + 1) {
        this.skill.improve();
        this.levelThresholds[i] *= 2; // Example: double the threshold for next level
        console.log(`Reached level ${currentLevel + 1}!`);
      }
    }
  }
}

