factionA.receiveResource('gold', 100);
factionB.receiveResource('wood', 50);

// Trade resources
factionA.tradeResource('gold', 20, factionB);
factionB.tradeResource('wood', 10, factionA);

// Check resources and reputation
console.log('Faction A Resources:', factionA.getResources());
console.log('Faction B Resources:', factionB.getResources());
console.log('Reputation Standing:', reputationSystem.getReputation());
