  angle: 0,
  speed: 5,
  shooting: false,
  combo: 0,
  maxCombo: 5,
  comboMultiplier: 1,
  score: 0
};

const enemies = [];
const bullets = [];

const spawnEnemy = () => {
  const enemy = {
    x: Math.random() * canvas.width,
    y: Math.random() * canvas.height,
    radius: 10,
    speed: 2 + Math.random() * 2
  };
  enemies.push(enemy);
};

const update = (deltaTime) => {
  if (player.shooting) {
    bullets.push({
      x: player.x + Math.cos(player.angle) * player.radius,
      y: player.y + Math.sin(player.angle) * player.radius,
      radius: 2,
      speed: 10,
      angle: player.angle
    });
  }

  bullets.forEach((bullet, index) => {
    bullet.x += Math.cos(bullet.angle) * bullet.speed * deltaTime;
    bullet.y += Math.sin(bullet.angle) * bullet.speed * deltaTime;
    if (bullet.x < 0 || bullet.x > canvas.width || bullet.y < 0 || bullet.y > canvas.height) {
      bullets.splice(index, 1);
    }
  });

  enemies.forEach((enemy, index) => {
    const dx = enemy.x - player.x;
    const dy = enemy.y - player.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < player.radius + enemy.radius) {
      // Collision detected
      enemies.splice(index, 1);
      player.combo++;
      player.score += player.comboMultiplier * 10;
      if (player.combo >= player.maxCombo) {
        player.comboMultiplier++;
        player.maxCombo += 5;
      }
    } else {
      enemy.x += dx / distance * enemy.speed * deltaTime;
      enemy.y += dy / distance * enemy.speed * deltaTime;
    }
  });

  if (Math.random() < 0.02) {
    spawnEnemy();
  }
};

const render = () => {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = 'red';
  bullets.forEach(bullet => {
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, bullet.radius, 0, Math.PI * 2);
    ctx.fill();
  });

  ctx.fillStyle = 'green';
  enemies.forEach(enemy => {
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
    ctx.fill();
  });

  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Combo: ${player.combo}`, 10, 30);
  ctx.fillText(`Multiplier: x${player.comboMultiplier}`, 10, 60);
  ctx.fillText(`Score: ${player.score}`, 10, 90);
};

