class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, callback) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(callback);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(callback => callback(data));
        }
    }
}

class Spawner {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.spawnInterval = 2000; // 2 seconds
        this.startSpawning();
    }

    startSpawning() {
        setInterval(() => {
            this.spawnEnemy();
        }, this.spawnInterval);
    }

    spawnEnemy() {
        const enemyId = Date.now();
        console.log(`Spawning enemy with ID: ${enemyId}`);
        this.eventBus.emit('enemySpawned', enemyId);
    }
}

class EnemyPool {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.activeEnemies = new Set();
        this.subscribeToEvents();
    }

    subscribeToEvents() {
        this.eventBus.subscribe('enemySpawned', this.handleEnemySpawned.bind(this));
        this.eventBus.subscribe('enemyDestroyed', this.handleEnemyDestroyed.bind(this));
    }

    handleEnemySpawned(enemyId) {
        this.activeEnemies.add(enemyId);
        console.log(`EnemyPool: Added enemy with ID ${enemyId}`);
    }

    handleEnemyDestroyed(enemyId) {
        if (this.activeEnemies.has(enemyId)) {
            this.activeEnemies.delete(enemyId);
            console.log(`EnemyPool: Removed enemy with ID ${enemyId}`);
        }
    }
}

class Score {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.currentScore = 0;
        this.subscribeToEvents();
    }

    subscribeToEvents() {
        this.eventBus.subscribe('enemyDestroyed', this.handleEnemyDestroyed.bind(this));
    }

    handleEnemyDestroyed(enemyId) {
        this.currentScore += 10; // 10 points per enemy destroyed
        console.log(`Score: Enemy with ID ${enemyId} destroyed. Current score: ${this.currentScore}`);
    }
}

