// Quest System
class Quest {
  constructor() {
    this.completedQuests = new Set();
  }

  isQuestCompleted(questName) {
    return this.completedQuests.has(questName);
  }

  completeQuest(questName) {
    this.completedQuests.add(questName);
    console.log(`Quest "${questName}" completed.`);
  }
}

// Reward System
class Reward {
  constructor() {
    this.rewards = {
      'Defeat the Dragon': 'Dragon Slaying Sword',
      'Find the Lost City': 'Golden Amulet',
    };
  }

  getRewardForQuest(questName) {
    return this.rewards[questName] || null;
  }

  awardReward(questName, inventory) {
    const reward = this.getRewardForQuest(questName);
    if (reward) {
      inventory.addItem(reward);
      console.log(`Awarded reward: ${reward}`);
    } else {
      console.log(`No reward for quest "${questName}".`);
    }
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
    console.log(`Added to inventory: ${item}`);
  }

  listItems() {
    console.log('Inventory Items:', this.items);
  }
}

// Coordinator to wire the systems together
class GameCoordinator {
  constructor() {
    this.questSystem = new Quest();
    this.rewardSystem = new Reward();
    this.inventorySystem = new Inventory();
  }

  handleQuestCompletion(questName) {
    if (!this.questSystem.isQuestCompleted(questName)) {
      this.questSystem.completeQuest(questName);
      this.rewardSystem.awardReward(questName, this.inventorySystem);
    } else {
      console.log(`Quest "${questName}" is already completed.`);
    }
  }

  listInventory() {
    this.inventorySystem.listItems();
  }
}

