const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let windowWidth = window.innerWidth;
let windowHeight = window.innerHeight;
const dpr = window.devicePixelRatio;

canvas.width = windowWidth * dpr;
canvas.height = windowHeight * dpr;
canvas.style.width = `${windowWidth}px`;
canvas.style.height = `${windowHeight}px`;

function resizeCanvas() {
    windowWidth = window.innerWidth;
    windowHeight = window.innerHeight;
    canvas.width = windowWidth * dpr;
    canvas.height = windowHeight * dpr;
    canvas.style.width = `${windowWidth}px`;
    canvas.style.height = `${windowHeight}px`;
}

window.addEventListener('resize', resizeCanvas);

const maze = {
    width: 10,
    height: 10,
    cellSize: 40 * dpr,
    walls: []
};

function generateMaze() {
    maze.walls = [];
    for (let y = 0; y < maze.height; y++) {
        for (let x = 0; x < maze.width; x++) {
            const wallThickness = 5 * dpr;
            ctx.fillStyle = '#333';
            if (x === 0) {
                ctx.fillRect(x * maze.cellSize, y * maze.cellSize, wallThickness, maze.cellSize);
            }
            if (y === 0) {
                ctx.fillRect(x * maze.cellSize, y * maze.cellSize, maze.cellSize, wallThickness);
            }
            if (x === maze.width - 1) {
                ctx.fillRect((x + 1) * maze.cellSize - wallThickness, y * maze.cellSize, wallThickness, maze.cellSize);
            }
            if (y === maze.height - 1) {
                ctx.fillRect(x * maze.cellSize, (y + 1) * maze.cellSize - wallThickness, maze.cellSize, wallThickness);
            }
        }
    }
}

const player = {
    x: maze.cellSize / 2,
    y: maze.cellSize / 2,
    size: 10 * dpr,
    speed: 4 * dpr,
    color: '#0f0'
};

const enemy = {
    x: (maze.width - 1) * maze.cellSize + maze.cellSize / 2,
    y: (maze.height - 1) * maze.cellSize + maze.cellSize / 2,
    size: 10 * dpr,
    speed: 3 * dpr,
    color: '#f00'
};

let particles = [];

function createParticle(x, y, color) {
    particles.push({
        x, y,
        size: Math.random() * 3 * dpr + 2 * dpr,
        color,
        lifespan: 100
    });
}

function updateParticles() {
    particles.forEach((particle, index) => {
        particle.lifespan--;
        if (particle.lifespan <= 0) {
            particles.splice(index, 1);
        }
    });
}

function renderParticles() {
    ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
    particles.forEach(particle => {
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
        ctx.fill();
    });
}

function handleCollision() {
    if (Math.abs(player.x - enemy.x) < player.size + enemy.size && Math.abs(player.y - enemy.y) < player.size + enemy.size) {
        createParticle(enemy.x, enemy.y, enemy.color);
        generateMaze();
        player.x = maze.cellSize / 2;
        player.y = maze.cellSize / 2;
        enemy.x = (maze.width - 1) * maze.cellSize + maze.cellSize / 2;
        enemy.y = (maze.height - 1) * maze.cellSize + maze.cellSize / 2;
    }
}

function movePlayer(event) {
    const key = event.key;
    if (key === 'ArrowUp' && player.y > maze.cellSize / 2) {
        player.y -= player.speed;
        createParticle(player.x, player.y, player.color);
    }
    if (key === 'ArrowDown' && player.y < (maze.height - 1) * maze.cellSize + maze.cellSize / 2) {
        player.y += player.speed;
        createParticle(player.x, player.y, player.color);
    }
    if (key === 'ArrowLeft' && player.x > maze.cellSize / 2) {
        player.x -= player.speed;
        createParticle(player.x, player.y, player.color);
    }
    if (key === 'ArrowRight' && player.x < (maze.width - 1) * maze.cellSize + maze.cellSize / 2) {
        player.x += player.speed;
        createParticle(player.x, player.y, player.color);
    }
}

function moveEnemy() {
    const direction = Math.random() < 0.5 ? 1 : -1;
    const axis = Math.random() < 0.5 ? 'x' : 'y';
    enemy[axis] += enemy.speed * direction;
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    generateMaze();
    ctx.fillStyle = player.color;
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.size, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = enemy.color;
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.size, 0, Math.PI * 2);
    ctx.fill();
    renderParticles();
}

function gameLoop() {
    updateParticles();
    moveEnemy();
    handleCollision();
    render();
    requestAnimationFrame(gameLoop);
}

generateMaze();
window.addEventListener('keydown', movePlayer);
gameLoop();
