class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Pricing {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('updateDemand', this.updatePrice.bind(this));
  }

  updatePrice(demand) {
    const basePrice = 100;
    const priceAdjustment = demand > 50 ? (demand - 50) * 2 : 0;
    const newPrice = basePrice + priceAdjustment;
    this.eventBus.emit('priceUpdated', newPrice);
    console.log(`Price updated to: $${newPrice}`);
  }
}

class Demand {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.demandLevel = 50;
  }

  simulateDemandChange(change) {
    this.demandLevel += change;
    if (this.demandLevel < 0) {
      this.demandLevel = 0;
    }
    this.eventBus.emit('updateDemand', this.demandLevel);
    console.log(`Demand changed to: ${this.demandLevel}`);
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('priceUpdated', this.updateInventory.bind(this));
  }

  updateInventory(price) {
    const itemsInStock = price > 150 ? 10 : 20;
    console.log(`Items in stock updated to: ${itemsInStock}`);
  }
}

