  add(itemId, amount) {
    this.items[itemId] = (this.items[itemId] || 0) + amount;
  }

  remove(itemId, amount) {
    if (this.items[itemId] < amount) return false;
    this.items[itemId] -= amount;
    return true;
  }
}

