class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(data));
    }
  }
}

// Dialogue System
class Dialogue {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('dialogue.start', this.startDialogue.bind(this));
  }

  startDialogue(data) {
    console.log(`Dialogue started with ${data.character}: ${data.text}`);
    this.eventBus.emit('dialogue.end', { character: data.character, text: 'Goodbye!' });
  }
}

// Flags System
class Flags {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.flags = {};
    this.eventBus.subscribe('flag.set', this.setFlag.bind(this));
    this.eventBus.subscribe('flag.check', this.checkFlag.bind(this));
  }

  setFlag(data) {
    this.flags[data.key] = data.value;
    console.log(`Flag set: ${data.key} = ${data.value}`);
  }

  checkFlag(data) {
