      ctx.strokeRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    }
  }
  drawEnemies();
}

function drawEnemies() {
  ctx.fillStyle = 'red';
  enemies.forEach(enemy => {
