    if (board[y][i] === value) board[y][i] = 0;
    if (board[i][x] === value) board[i][x] = 0;
  }

  // Clear and drop tiles
  for (let i = 0; i < BOARD_SIZE; i++) {
    for (let j = BOARD_SIZE - 1; j >= 0; j--) {
      if (board[j][i] === 0) {
        for (let k = j - 1; k >= 0; k--) {
