// Constants
const TILE_SIZE = 16;
const ROOM_WIDTH = 20;
const ROOM_HEIGHT = 15;
const COUNTDOWN_DURATION = 60; // seconds

// Canvas setup
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio || 1;
canvas.width = ROOM_WIDTH * TILE_SIZE * dpr;
canvas.height = ROOM_HEIGHT * TILE_SIZE * dpr;
ctx.scale(dpr, dpr);

// Room setup
let room = [];
for (let y = 0; y < ROOM_HEIGHT; y++) {
    let row = [];
    for (let x = 0; x < ROOM_WIDTH; x++) {
        row.push(Math.random() > 0.7 ? '#' : '.');
    }
    room.push(row);
}

// Countdown setup
let countdown = COUNTDOWN_DURATION;
let lastTime = performance.now();

// Render function
function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw room
    for (let y = 0; y < ROOM_HEIGHT; y++) {
        for (let x = 0; x < ROOM_WIDTH; x++) {
            let tile = room[y][x];
            ctx.fillStyle = tile === '#' ? 'black' : 'white';
            ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
        }
    }

    // Draw countdown
    ctx.fillStyle = 'black';
    ctx.font = '24px monospace';
    ctx.fillText(`Time: ${countdown.toFixed(1)}`, 10, 30);

    // Update countdown
    let now = performance.now();
    let deltaTime = (now - lastTime) / 1000;
    countdown -= deltaTime;
    lastTime = now;

    if (countdown > 0) {
        requestAnimationFrame(render);
    } else {
        ctx.fillText('Game Over!', 10, 70);
    }
}

// Start the game
requestAnimationFrame(render);
