    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemAdded', this.onItemAdded.bind(this));
    this.eventBus.subscribe('itemRemoved', this.onItemRemoved.bind(this));
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
    this.eventBus.emit('itemAdded', { item, quantity });
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      this.eventBus.emit('itemRemoved', { item, quantity });
    } else {
      console.log(`Not enough ${item} to remove.`);
    }
  }

  onItemAdded({ item, quantity }) {
    console.log(`Inventory: Added ${quantity} ${item}. Total: ${this.items[item]}`);
  }

  onItemRemoved({ item, quantity }) {
    console.log(`Inventory: Removed ${quantity} ${item}. Remaining: ${this.items[item]}`);
  }

  getItems() {
    return { ...this.items };
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('craftRequest', this.onCraftRequest.bind(this));
  }

  addRecipe(name, ingredients) {
    this.recipes[name] = ingredients;
  }

  onCraftRequest(name) {
    if (this.recipes[name]) {
      this.eventBus.emit('craft', { name, ingredients: this.recipes[name] });
    } else {
      console.log(`Recipe not found: ${name}`);
    }
  }
}

class Crafting {
  constructor(eventBus, inventory) {
    this.eventBus = eventBus;
    this.inventory = inventory;
    this.eventBus.subscribe('craft', this.onCraft.bind(this));
  }

  onCraft({ name, ingredients }) {
    let canCraft = true;
    ingredients.forEach(({ item, quantity }) => {
      if (!this.inventory.getItems()[item] || this.inventory.getItems()[item] < quantity) {
        canCraft = false;
        console.log(`Missing ${quantity} ${item} for crafting ${name}.`);
      }
    });

    if (canCraft) {
      ingredients.forEach(({ item, quantity }) => {
        this.inventory.removeItem(item, quantity);
      });
      this.inventory.addItem(name);
      console.log(`Crafted ${name} successfully.`);
    }
  }
}

// Demo
