class Economy {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Store {
  constructor() {
    this.items = {
      "sword": { price: 50 },
      "potion": { price: 20 }
    };
  }

  getItemPrice(itemName) {
    const item = this.items[itemName];
    return item ? item.price : null;
  }

  purchaseItem(itemName, economy) {
    const price = this.getItemPrice(itemName);
    if (price !== null && economy.withdraw(price)) {
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(itemName) {
    if (this.items[itemName]) {
      this.items[itemName]++;
    } else {
      this.items[itemName] = 1;
    }
  }

  getInventory() {
    return this.items;
  }
}

class GameCoordinator {
  constructor(initialBalance = 100) {
    this.economy = new Economy(initialBalance);
    this.store = new Store();
    this.inventory = new Inventory();
  }

  buyItem(itemName) {
    if (this.store.purchaseItem(itemName, this.economy)) {
      this.inventory.addItem(itemName);
      return true;
    }
    return false;
  }

  displayStatus() {
    console.log(`Balance: ${this.economy.getBalance()}`);
    console.log(`Inventory:`, this.inventory.getInventory());
  }
}

