// Constants
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const FISH_SIZE = 50;
const POWERUP_SIZE = 30;
const POWERUP_TYPES = ['speed', 'size', 'score'];
const POWERUP_DURATIONS = { speed: 5000, size: 5000, score: 3000 };
const POWERUP_COLORS = { speed: 'blue', size: 'green', score: 'yellow' };

// Canvas setup
const canvas = document.createElement('canvas');
canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game state
let fish = { x: CANVAS_WIDTH / 2, y: CANVAS_HEIGHT / 2, size: FISH_SIZE, speed: 5 };
let powerups = [];
let score = 0;
let activePowerups = {};

// Fish controls
document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowUp':
            fish.y -= fish.speed;
            break;
        case 'ArrowDown':
            fish.y += fish.speed;
            break;
        case 'ArrowLeft':
            fish.x -= fish.speed;
            break;
        case 'ArrowRight':
            fish.x += fish.speed;
            break;
    }
});

// Powerup generation
function spawnPowerup() {
    const type = POWERUP_TYPES[Math.floor(Math.random() * POWERUP_TYPES.length)];
    const x = Math.random() * (CANVAS_WIDTH - POWERUP_SIZE);
    const y = Math.random() * (CANVAS_HEIGHT - POWERUP_SIZE);
    powerups.push({ x, y, type, color: POWERUP_COLORS[type] });
}

// Powerup activation
function activatePowerup(type) {
    activePowerups[type] = Date.now() + POWERUP_DURATIONS[type];
    switch (type) {
        case 'speed':
            fish.speed += 2;
            break;
        case 'size':
            fish.size += 10;
            break;
        case 'score':
            score += 100;
            break;
    }
}

// Powerup deactivation
function deactivatePowerup(type) {
    delete activePowerups[type];
    switch (type) {
        case 'speed':
            fish.speed -= 2;
            break;
        case 'size':
            fish.size -= 10;
            break;
    }
}

// Collision detection
function checkCollision() {
    powerups.forEach((powerup, index) => {
        const dx = fish.x - powerup.x;
        const dy = fish.y - powerup.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance < fish.size / 2 + POWERUP_SIZE / 2) {
            activatePowerup(powerup.type);
            powerups.splice(index, 1);
        }
    });

    for (const type in activePowerups) {
        if (Date.now() > activePowerups[type]) {
            deactivatePowerup(type);
        }
    }
}

// Game loop
function gameLoop() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw fish
    ctx.fillStyle = 'red';
    ctx.beginPath();
    ctx.arc(fish.x, fish.y, fish.size / 2, 0, Math.PI * 2);
    ctx.fill();

    // Draw powerups
    ctx.font = '20px Arial';
    powerups.forEach((powerup) => {
        ctx.fillStyle = powerup.color;
        ctx.beginPath();
        ctx.arc(powerup.x, powerup.y, POWERUP_SIZE / 2, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = 'black';
        ctx.fillText(powerup.type, powerup.x - 10, powerup.y + 10);
    });

    // Draw score
    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 30);

    // Update game state
    checkCollision();
    spawnPowerup();

    requestAnimationFrame(gameLoop);
}

// Start the game
gameLoop();
