    case 'ArrowLeft':
      player.velocityX = -5;
      break;
    case 'ArrowRight':
      player.velocityX = 5;
      break;
    case 'ArrowUp':
      if (player.onGround) {
        player.velocityY = player.jumpPower;
      }
      break;
  }
});

document.addEventListener('keyup', (e) => {
  switch (e.key) {
    case 'ArrowLeft':
    case 'ArrowRight':
