const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const bird = {
  x: 100,
  y: canvas.height / 2,
  width: 30,
  height: 30,
  velocity: 0,
  gravity: 0.5,
  jumpStrength: -10,
  draw() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  },
  update() {
    this.velocity += this.gravity;
    this.y += this.velocity;
    if (this.y + this.height > canvas.height) {
      this.y = canvas.height - this.height;
      this.velocity = 0;
    }
    if (this.y < 0) {
      this.y = 0;
      this.velocity = 0;
    }
  },
  jump() {
    this.velocity = this.jumpStrength;
  }
};

const pipes = [];
const pipeWidth = 70;
const pipeGap = 150;
let pipeSpeed = 2;

function createPipe() {
  const pipeHeight = Math.random() * (canvas.height - pipeGap);
  pipes.push({
    x: canvas.width,
    height: pipeHeight,
    draw() {
      ctx.fillStyle = 'green';
      ctx.fillRect(this.x, 0, pipeWidth, this.height);
      ctx.fillRect(this.x, this.height + pipeGap, pipeWidth, canvas.height - this.height - pipeGap);
    },
    update() {
      this.x -= pipeSpeed;
    }
  });
}

function checkCollision(pipe) {
  return (bird.x < pipe.x + pipeWidth &&
          bird.x + bird.width > pipe.x &&
          (bird.y < pipe.height || bird.y + bird.height > pipe.height + pipeGap));
}

const powerUps = [];
const powerUpSize = 20;
let powerUpSpeed = 3;

function createPowerUp() {
  const powerUpY = Math.random() * (canvas.height - powerUpSize);
  powerUps.push({
    x: canvas.width,
    y: powerUpY,
    draw() {
      ctx.fillStyle = 'yellow';
      ctx.fillRect(this.x, this.y, powerUpSize, powerUpSize);
    },
    update() {
      this.x -= powerUpSpeed;
    }
  });
}

let score = 0;
let gameOver = false;

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function resetGame() {
  bird.y = canvas.height / 2;
  bird.velocity = 0;
  pipes.length = 0;
  powerUps.length = 0;
  score = 0;
  gameOver = false;
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  bird.update();
  bird.draw();

  if (Math.random() < 0.03) createPipe();
  pipes.forEach(pipe => {
    pipe.update();
    pipe.draw();
    if (checkCollision(pipe)) {
      gameOver = true;
    }
    if (pipe.x + pipeWidth < 0) {
      pipes.shift();
      score++;
    }
  });

  if (Math.random() < 0.01) createPowerUp();
  powerUps.forEach((powerUp, index) => {
    powerUp.update();
    powerUp.draw();
    if (bird.x < powerUp.x + powerUpSize &&
        bird.x + bird.width > powerUp.x &&
        bird.y < powerUp.y + powerUpSize &&
        bird.y + bird.height > powerUp.y) {
      powerUps.splice(index, 1);
      bird.jumpStrength -= 1;
    }
    if (powerUp.x + powerUpSize < 0) {
      powerUps.shift();
    }
  });

  drawScore();

  if (gameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '50px Arial';
    ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
    setTimeout(resetGame, 2000);
  } else {
    requestAnimationFrame(update);
  }
}

document.addEventListener('keydown', (e) => {
  if (e.code === 'Space' && !gameOver) {
    bird.jump();
  }
});

update();
