            throw new Error("Insufficient funds");
        }
        this.balance -= amount;
    }

    credit(amount) {
        this.balance += amount;
    }
}

class Market {
    constructor(prices = {}) {
        this.prices = prices;
    }

    getPrice(item) {
        return this.prices[item] || null;
    }

    setPrice(item, price) {
        this.prices[item] = price;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }
}

class Store {
    constructor(bank, market, inventory) {
        this.bank = bank;
        this.market = market;
        this.inventory = inventory;
    }

    purchaseItem(item, quantity = 1) {
        const price = this.market.getPrice(item);
        if (!price) {
            throw new Error("Item not available in market");
        }
        const totalCost = price * quantity;
        this.bank.debit(totalCost);
