const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const FISH_COUNT = 10;
const FISH_SIZE = 20;
const BAIT_SIZE = 10;
const FPS = 60;
const UPDATE_INTERVAL = 1000 / FPS;

let fish = [];
let bait = { x: canvas.width / 2, y: canvas.height - BAIT_SIZE };
let score = 0;
let highScore = localStorage.getItem('highScore') || 0;

function getRandom(min, max) {
  return Math.random() * (max - min) + min;
}

function initFish() {
  fish = [];
  for (let i = 0; i < FISH_COUNT; i++) {
    fish.push({
      x: getRandom(FISH_SIZE, canvas.width - FISH_SIZE),
      y: getRandom(FISH_SIZE, canvas.height / 2),
      dx: getRandom(1, 3),
      dy: getRandom(1, 3)
    });
  }
}

function updateBait() {
  if (keys.ArrowLeft && bait.x > 0) {
    bait.x -= 5;
  }
  if (keys.ArrowRight && bait.x < canvas.width - BAIT_SIZE) {
    bait.x += 5;
  }
}

function updateFish() {
  fish.forEach(f => {
    f.x += f.dx;
    f.y += f.dy;
    if (f.x + FISH_SIZE > canvas.width || f.x < 0) {
      f.dx *= -1;
    }
    if (f.y + FISH_SIZE > canvas.height / 2 || f.y < 0) {
      f.dy *= -1;
    }
    if (checkCollision(f, bait)) {
      score++;
      f.x = getRandom(FISH_SIZE, canvas.width - FISH_SIZE);
      f.y = getRandom(FISH_SIZE, canvas.height / 2);
    }
  });
}

function checkCollision(f, b) {
  return (
    f.x < b.x + BAIT_SIZE &&
    f.x + FISH_SIZE > b.x &&
    f.y < b.y + BAIT_SIZE &&
    f.y + FISH_SIZE > b.y
  );
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'blue';
  fish.forEach(f => {
    ctx.fillRect(f.x, f.y, FISH_SIZE, FISH_SIZE);
  });
  ctx.fillStyle = 'red';
  ctx.fillRect(bait.x, bait.y, BAIT_SIZE, BAIT_SIZE);
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 20);
  ctx.fillText(`High Score: ${highScore}`, 10, 40);
}

function update() {
  updateBait();
  updateFish();
  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore);
  }
}

let lastTime = performance.now();
function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  if (deltaTime >= UPDATE_INTERVAL) {
    lastTime = timestamp;
    update();
  }
  render();
  requestAnimationFrame(gameLoop);
}

const keys = { ArrowLeft: false, ArrowRight: false };
document.addEventListener('keydown', e => {
  keys[e.key] = true;
});
document.addEventListener('keyup', e => {
  keys[e.key] = false;
});

initFish();
gameLoop();
