    ctx.fillRect(food.x * scale, food.y * scale, scale, scale);

    let head = { x: snake[0].x + dx, y: snake[0].y + dy };

    if (head.x >= cols || head.x < 0 || head.y >= rows || head.y < 0 || checkCollision(head, snake)) {
        alert(`Game Over! Your score: ${score}`);
        snake = [{ x: 9, y: 10 }];
