class Bank {
    constructor(balance = 0) {
        this.balance = balance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            console.log(`Deposited ${amount}. New balance: ${this.balance}`);
        } else {
            console.log('Deposit amount must be positive.');
        }
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
        } else {
            console.log('Invalid withdrawal amount or insufficient funds.');
        }
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor(prices = {}) {
        this.prices = prices;
    }

    getBuyPrice(item) {
        return this.prices[item] ? this.prices[item].buy : null;
    }

    getSellPrice(item) {
        return this.prices[item] ? this.prices[item].sell : null;
    }

    updatePrices(prices) {
        Object.assign(this.prices, prices);
        console.log('Prices updated:', this.prices);
    }
}

class Inventory {
    constructor(items = {}) {
        this.items = items;
    }

    addItem(item, quantity) {
        if (quantity > 0) {
            this.items[item] = (this.items[item] || 0) + quantity;
            console.log(`Added ${quantity} ${item}(s). Current inventory:`, this.items);
        } else {
            console.log('Item quantity must be positive.');
        }
    }

    removeItem(item, quantity) {
        if (quantity > 0 && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            console.log(`Removed ${quantity} ${item}(s). Current inventory:`, this.items);
        } else {
            console.log('Invalid item removal amount or insufficient stock.');
        }
    }

    getInventory() {
        return { ...this.items };
    }
}

// Demo
const bank = new Bank(1000);
const market = new Market({
    apple: { buy: 1, sell: 2 },
    banana: { buy: 2, sell: 3 }
});
const inventory = new Inventory();

// Buy an item
const buyItem = (item, quantity) => {
    const buyPrice = market.getBuyPrice(item);
    const totalCost = buyPrice * quantity;
    if (bank.getBalance() >= totalCost) {
        bank.withdraw(totalCost);
        inventory.addItem(item, quantity);
        console.log(`Bought ${quantity} ${item}(s) for ${totalCost}.`);
    } else {
        console.log('Insufficient funds to buy the item.');
    }
};

// Sell an item
const sellItem = (item, quantity) => {
    const sellPrice = market.getSellPrice(item);
    if (sellPrice && inventory.items[item] >= quantity) {
        bank.deposit(sellPrice * quantity);
        inventory.removeItem(item, quantity);
        console.log(`Sold ${quantity} ${item}(s) for ${sellPrice * quantity}.`);
    } else {
        console.log('Invalid item or insufficient stock to sell.');
    }
};

// Execute demo transactions
buyItem('apple', 10);
sellItem('apple', 5);
buyItem('banana', 20);
sellItem('banana', 10);

console.log('Final bank balance:', bank.getBalance());
console.log('Final inventory:', inventory.getInventory());
