  getEnemy() {
    if (this.enemies.length > 0) {
      return this.enemies.pop();
    } else {
      console.log("No enemies available in the pool.");
      return null;
    }
  }

  returnEnemy(enemy) {
    this.enemies.push(enemy);
    console.log(`Enemy returned to pool: ${enemy}`);
  }
}

