class Spaceship {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.width = 20;
    this.height = 20;
    this.angle = 0;
    this.speed = 5;
  }

  update() {
    const radians = (this.angle * Math.PI) / 180;
    this.x += this.speed * Math.cos(radians);
    this.y -= this.speed * Math.sin(radians);
  }

  draw() {
    ctx.save();
    ctx.translate(this.x, this.y);
    ctx.rotate((this.angle * Math.PI) / 180);
    ctx.beginPath();
    ctx.moveTo(10, 0);
    ctx.lineTo(-10, -10);
    ctx.lineTo(-10, 10);
    ctx.closePath();
    ctx.fillStyle = 'white';
    ctx.fill();
    ctx.restore();
  }
}

class Asteroid {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.speed = 2 + Math.random() * 2;
    this.angle = Math.random() * 360;
  }

  update() {
    const radians = (this.angle * Math.PI) / 180;
    this.x += this.speed * Math.cos(radians);
    this.y += this.speed * Math.sin(radians);

    if (this.x > width + this.size || this.x < -this.size || this.y > height + this.size || this.y < -this.size) {
      this.x = Math.random() * width;
      this.y = Math.random() * height;
    }
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
    ctx.fillStyle = 'gray';
    ctx.fill();
  }
}

