class Economy {
  constructor() {
    this.balances = new Map();
  }

  getBalance(player) {
    return this.balances.get(player) || 0;
  }

  setBalance(player, amount) {
    this.balances.set(player, amount);
  }

  debit(player, amount) {
    const currentBalance = this.getBalance(player);
    if (currentBalance >= amount) {
      this.setBalance(player, currentBalance - amount);
      return true;
    }
    return false;
  }

  credit(player, amount) {
    const currentBalance = this.getBalance(player);
    this.setBalance(player, currentBalance + amount);
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  getInventory(player) {
    return this.items.get(player) || [];
  }

  addItem(player, item) {
    const inventory = this.getInventory(player);
    inventory.push(item);
    this.items.set(player, inventory);
  }

  removeItem(player, item) {
    const inventory = this.getInventory(player);
    const index = inventory.indexOf(item);
    if (index !== -1) {
      inventory.splice(index, 1);
      this.items.set(player, inventory);
    }
  }
}

class Store {
