class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(eventName, listener) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(listener);
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(listener => listener(data));
    }
  }
}

class Combat {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('attack', this.handleAttack.bind(this));
  }

  attack(targetId) {
    this.eventBus.emit('attack', { targetId });
  }

  handleAttack({ targetId }) {
    console.log(`Combat: Attacking target ${targetId}`);
    this.eventBus.emit('damage', { targetId, amount: 10 });
  }
}

class Health {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('damage', this.handleDamage.bind(this));
    this.entities = {};
  }

  addEntity(entityId, initialHealth = 100) {
    this.entities[entityId] = initialHealth;
  }

  handleDamage({ targetId, amount }) {
    if (this.entities[targetId]) {
      this.entities[targetId] -= amount;
      console.log(`Health: Entity ${targetId} now has ${this.entities[targetId]} health`);
      if (this.entities[targetId] <= 0) {
        console.log(`Health: Entity ${targetId} has been defeated`);
        this.eventBus.emit('entityDefeated', { entityId: targetId });
      }
    }
  }
}

class Loot {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('entityDefeated', this.handleEntityDefeated.bind(this));
  }

  handleEntityDefeated({ entityId }) {
    console.log(`Loot: Entity ${entityId} dropped loot`);
    // Simulate loot drop
