}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  balls.forEach(ball => {
    ball.update();
    ball.draw();
  });

  particles = particles.filter(particle => particle.life > 0);
  particles.forEach(particle => {
    particle.update();
    particle.draw();
  });

  requestAnimationFrame(update);
}

