const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TPS = 60;
const MS_PER_UPDATE = 1000 / TPS;
let lastUpdateTime = performance.now();

let player = {
    x: canvas.width / 4,
    y: canvas.height / 2,
    width: 50,
    height: 50,
    speed: 2,
    health: 100
};

let opponent = {
    x: (3 * canvas.width) / 4,
    y: canvas.height / 2,
    width: 50,
    height: 50,
    speed: 2,
    health: 100
};

let powerUps = [];
const POWER_UP_TYPES = ['speed', 'health'];
const POWER_UP_COLORS = ['green', 'red'];

function spawnPowerUp() {
    const type = POWER_UP_TYPES[Math.floor(Math.random() * POWER_UP_TYPES.length)];
    const color = POWER_UP_COLORS[POWER_UP_TYPES.indexOf(type)];
    powerUps.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        radius: 10,
        type: type,
        color: color
    });
}

function collectPowerUp(entity, powerUps) {
    return powerUps.filter(powerUp => {
        const dx = entity.x - powerUp.x;
        const dy = entity.y - powerUp.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance < entity.width / 2 + powerUp.radius) {
            if (powerUp.type === 'speed') {
                entity.speed += 0.5;
            } else if (powerUp.type === 'health') {
                entity.health += 20;
                if (entity.health > 100) entity.health = 100;
            }
            return false;
        }
        return true;
    });
}

function drawEntity(entity, color) {
    ctx.fillStyle = color;
    ctx.fillRect(entity.x, entity.y, entity.width, entity.height);
}

function drawPowerUp(powerUp) {
    ctx.fillStyle = powerUp.color;
    ctx.beginPath();
    ctx.arc(powerUp.x, powerUp.y, powerUp.radius, 0, Math.PI * 2);
    ctx.fill();
}

function update(deltaTime) {
    if (Math.random() < 0.01) spawnPowerUp();

    if (keys.up && player.y > 0) player.y -= player.speed;
    if (keys.down && player.y < canvas.height - player.height) player.y += player.speed;
    if (keys.left && player.x > 0) player.x -= player.speed;
    if (keys.right && player.x < canvas.width - player.width) player.x += player.speed;

    if (keys.w && opponent.y > 0) opponent.y -= opponent.speed;
    if (keys.s && opponent.y < canvas.height - opponent.height) opponent.y += opponent.speed;
    if (keys.a && opponent.x > 0) opponent.x -= opponent.speed;
    if (keys.d && opponent.x < canvas.width - opponent.width) opponent.x += opponent.speed;

    powerUps = collectPowerUp(player, powerUps);
    powerUps = collectPowerUp(opponent, powerUps);
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawEntity(player, 'blue');
    drawEntity(opponent, 'red');
    powerUps.forEach(drawPowerUp);
    ctx.fillStyle = 'black';
    ctx.fillText(`Player Health: ${player.health}`, 10, 20);
    ctx.fillText(`Opponent Health: ${opponent.health}`, 10, 40);
}

const keys = {
    up: false,
    down: false,
    left: false,
    right: false,
    w: false,
    a: false,
    s: false,
    d: false
};

document.addEventListener('keydown', e => {
    if (e.key === 'ArrowUp') keys.up = true;
    if (e.key === 'ArrowDown') keys.down = true;
    if (e.key === 'ArrowLeft') keys.left = true;
    if (e.key === 'ArrowRight') keys.right = true;
    if (e.key === 'w') keys.w = true;
    if (e.key === 'a') keys.a = true;
    if (e.key === 's') keys.s = true;
    if (e.key === 'd') keys.d = true;
});

document.addEventListener('keyup', e => {
    if (e.key === 'ArrowUp') keys.up = false;
    if (e.key === 'ArrowDown') keys.down = false;
    if (e.key === 'ArrowLeft') keys.left = false;
    if (e.key === 'ArrowRight') keys.right = false;
    if (e.key === 'w') keys.w = false;
    if (e.key === 'a') keys.a = false;
    if (e.key === 's') keys.s = false;
    if (e.key === 'd') keys.d = false;
});

function gameLoop() {
    const now = performance.now();
    const deltaTime = now - lastUpdateTime;

    if (deltaTime >= MS_PER_UPDATE) {
        lastUpdateTime = now - (deltaTime % MS_PER_UPDATE);
        update(deltaTime);
    }

    render();
    requestAnimationFrame(gameLoop);
}

gameLoop();
