    this.events = {};
  }

  subscribe(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }
}

// Bank System
class Bank {
  constructor(eventBus) {
    this.balance = 0;
    this.eventBus = eventBus;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited ${amount}, new balance: ${this.balance}`);
      this.eventBus.emit('balanceUpdated', this.balance);
    } else {
      console.log('Invalid deposit amount');
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}, new balance: ${this.balance}`);
      this.eventBus.emit('balanceUpdated', this.balance);
    } else {
      console.log('Invalid withdrawal amount');
    }
  }
}

// Market System
class Market {
  constructor(eventBus) {
    this.prices = { apple: 2, banana: 1, orange: 3 };
    this.eventBus = eventBus;
    this.eventBus.subscribe('buy', this.buy.bind(this));
  }

  buy(item, quantity) {
    if (this.prices[item] !== undefined && quantity > 0) {
      const totalCost = this.prices[item] * quantity;
      this.eventBus.emit('sell', { item, quantity, totalCost });
    } else {
      console.log('Invalid item or quantity');
    }
  }
}

