class Order {
  constructor(item, quantity) {
    this.item = item;
    this.quantity = quantity;
  }
}

class Kitchen {
  constructor(items) {
    this.items = items;
  }

  prepareOrder(order) {
    if (this.items[order.item] >= order.quantity) {
      this.items[order.item] -= order.quantity;
      return true;
    }
    return false;
  }
}

class Customer {
  constructor(name) {
    this.name = name;
  }

  placeOrder(kitchen, order) {
    if (kitchen.prepareOrder(order)) {
      console.log(`${this.name} ordered ${order.quantity} ${order.item}(s).`);
      return true;
    }
    console.log(`${this.name} failed to order ${order.quantity} ${order.item}(s).`);
    return false;
  }
}

class Economy {
  constructor(prices, balance) {
    this.prices = prices;
    this.balance = balance;
  }

  debit(price, quantity) {
    const totalCost = price * quantity;
    if (this.balance >= totalCost) {
      this.balance -= totalCost;
      console.log(`Debited ${totalCost} from Economy. Remaining balance: ${this.balance}.`);
      return true;
    }
    console.log(`Insufficient balance in Economy. Required: ${totalCost}, Available: ${this.balance}.`);
    return false;
  }
}

class Inventory {
  constructor(items) {
    this.items = items;
  }

  addItem(item, quantity) {
    if (this.items[item] !== undefined) {
      this.items[item] += quantity;
      console.log(`Added ${quantity} ${item}(s) to Inventory. Total: ${this.items[item]}.`);
    } else {
      console.log(`Item ${item} not found in Inventory.`);
    }
  }
}

class Store {
  constructor(economy, inventory, kitchen) {
    this.economy = economy;
    this.inventory = inventory;
    this.kitchen = kitchen;
  }

  purchaseItem(customer, order) {
    const price = this.economy.prices[order.item];
    if (price !== undefined && this.economy.debit(price, order.quantity)) {
      this.inventory.addItem(order.item, order.quantity);
      customer.placeOrder(this.kitchen, order);
    } else {
      console.log(`Purchase of ${order.quantity} ${order.item}(s) failed.`);
    }
  }
}

