  let x = Math.random() * (width - 20);
  let y = Math.random() * (height - 20);
  enemies.push({ x, y, size: 10 + difficulty * 2, speed: 1 + difficulty * 0.1 });
  setTimeout(spawnEnemy, enemySpawnRate);
}

function update() {
  ctx.clearRect(0, 0, width, height);

  // Draw farming plot
  ctx.fillStyle = 'green';
  ctx.fillRect(plot.x, plot.y, plot.width, plot.height);

  // Update and draw enemies
  ctx.fillStyle = 'red';
  enemies.forEach((enemy, index) => {
    enemy.x += (Math.random() - 0.5) * enemy.speed;
    enemy.y += (Math.random() - 0.5) * enemy.speed;
    if (enemy.x < 0 || enemy.x > width || enemy.y < 0 || enemy.y > height) {
      enemies.splice(index, 1);
    } else {
      ctx.beginPath();
      ctx.arc(enemy.x, enemy.y, enemy.size, 0, Math.PI * 2);
      ctx.fill();
    }
