    this.level = initialLevel;
  }

  eat(amount) {
    this.level = Math.min(100, this.level + amount);
  }

  consume(amount) {
    this.level = Math.max(0, this.level - amount);
  }

  getLevel() {
    return this.level;
  }
}

class Energy {
  constructor(initialLevel = 100) {
    this.level = initialLevel;
  }

  rest(amount) {
    this.level = Math.min(100, this.level + amount);
  }

  expend(amount) {
    this.level = Math.max(0, this.level - amount);
  }

  getLevel() {
    return this.level;
  }
}

class Clock {
  constructor() {
    this.time = 0;
  }

  tick() {
    this.time += 1;
  }

  getTime() {
    return this.time;
  }
}

