class HealthSystem {
  constructor() {
    this.health = {};
  }

  setHealth(entity, health) {
    this.health[entity] = health;
  }

  takeDamage(entity, damage) {
    if (this.health[entity] !== undefined) {
      this.health[entity] -= damage;
      console.log(`${entity}'s health is now ${this.health[entity]}.`);
      return this.health[entity];
    } else {
      console.log(`${entity} has no health to track.`);
      return 0;
    }
  }
}

class LootSystem {
  constructor() {
    this.loot = {};
  }

  addLoot(entity, item, quantity) {
    if (!this.loot[entity]) {
      this.loot[entity] = {};
    }
    if (!this.loot[entity][item]) {
      this.loot[entity][item] = 0;
    }
    this.loot[entity][item] += quantity;
    console.log(`${entity} receives ${quantity} ${item}.`);
  }

  getLoot(entity) {
    return this.loot[entity] || {};
  }
}

