const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TPS = 60;
const TICK_LENGTH = 1000 / TPS;

let lastTick = Date.now();
let accumulator = 0;

let player = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  width: 20,
  height: 20,
  speed: 200,
  score: 0,
  powerUps: []
};

let enemies = [];
let powerUps = [];

function getRandomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function spawnEnemy() {
  const x = getRandomInt(0, canvas.width);
  const y = getRandomInt(0, canvas.height);
  enemies.push({ x, y, size: 10, speed: 100 });
}

function spawnPowerUp() {
  const x = getRandomInt(0, canvas.width);
  const y = getRandomInt(0, canvas.height);
  powerUps.push({ x, y, size: 10 });
}

function update(deltaTime) {
  // Player movement
  const speed = player.speed * deltaTime;
  if (keys['ArrowUp'] || keys['w']) player.y -= speed;
  if (keys['ArrowDown'] || keys['s']) player.y += speed;
  if (keys['ArrowLeft'] || keys['a']) player.x -= speed;
  if (keys['ArrowRight'] || keys['d']) player.x += speed;

  // Enemy movement
  enemies.forEach(enemy => {
    enemy.x += (Math.random() * 2 - 1) * enemy.speed * deltaTime;
    enemy.y += (Math.random() * 2 - 1) * enemy.speed * deltaTime;
  });

  // Power-up collection
  powerUps = powerUps.filter(powerUp => {
    const dx = player.x - powerUp.x;
    const dy = player.y - powerUp.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < player.width / 2 + powerUp.size / 2) {
      player.powerUps.push(powerUp);
      player.score++;
      return false;
    }
    return true;
  });

  // Enemy collision
  enemies = enemies.filter(enemy => {
    const dx = player.x - enemy.x;
    const dy = player.y - enemy.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < player.width / 2 + enemy.size / 2) {
      alert(`Game Over! Your score: ${player.score}`);
      resetGame();
      return false;
    }
    return true;
  });
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x - player.width / 2, player.y - player.height / 2, player.width, player.height);

  // Draw enemies
  ctx.fillStyle = 'red';
  enemies.forEach(enemy => {
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.size, 0, Math.PI * 2);
    ctx.fill();
  });

  // Draw power-ups
  ctx.fillStyle = 'green';
  powerUps.forEach(powerUp => {
    ctx.beginPath();
    ctx.arc(powerUp.x, powerUp.y, powerUp.size, 0, Math.PI * 2);
    ctx.fill();
  });

  // Draw score
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${player.score}`, 10, 30);
}

function resetGame() {
  player = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    width: 20,
    height: 20,
    speed: 200,
    score: 0,
    powerUps: []
  };
  enemies = [];
  powerUps = [];
  spawnEnemy();
  spawnPowerUp();
}

function gameLoop() {
  const now = Date.now();
  accumulator += now - lastTick;
  lastTick = now;

  while (accumulator >= TICK_LENGTH) {
    update(TICK_LENGTH / 1000);
    accumulator -= TICK_LENGTH;
  }

  render();
  requestAnimationFrame(gameLoop);
}

const keys = {};
window.addEventListener('keydown', (e) => { keys[e.key] = true; });
window.addEventListener('keyup', (e) => { keys[e.key] = false; });

spawnEnemy();
spawnPowerUp();
gameLoop();
