        this.events = {};
    }

    subscribe(event, callback) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(callback);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(callback => callback(data));
        }
    }
}

class Farm {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('harvest', this.onHarvest.bind(this));
        this.eventBus.subscribe('sellCrop', this.onSellCrop.bind(this));
        this.crops = [];
    }

    plantCrop(crop) {
        this.crops.push(crop);
        console.log(`Planted ${crop.name}`);
    }

    harvestCrop(cropName) {
        const crop = this.crops.find(c => c.name === cropName);
        if (crop) {
            this.eventBus.emit('harvest', crop);
            console.log(`Harvested ${cropName}`);
        } else {
            console.log(`Crop ${cropName} not found`);
        }
    }

    onHarvest(crop) {
        console.log(`Crop ${crop.name} ready for sale`);
        this.eventBus.emit('sellCrop', crop);
    }

    onSellCrop(crop) {
        this.crops = this.crops.filter(c => c !== crop);
        console.log(`Crop ${crop.name} sold`);
    }
}

class Crop {
    constructor(name, growthTime) {
        this.name = name;
        this.growthTime = growthTime;
    }
}

class Market {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('sellCrop', this.onSellCrop.bind(this));
        this.inventory = [];
    }

    onSellCrop(crop) {
