// Constants and variables
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let lastTime = 0;
let tapTime = 0;
let score = 0;
let powerUpActive = false;
let powerUpTimer = 0;
const powerUpDuration = 5000; // 5 seconds

// Set canvas size
function resizeCanvas() {
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  ctx.scale(dpr, dpr);
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

// Game loop
function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  lastTime = timestamp;

  update(deltaTime);
  draw();

  requestAnimationFrame(gameLoop);
}

// Update game state
function update(deltaTime) {
  // Handle tap input
  if (powerUpActive) {
    powerUpTimer += deltaTime;
    if (powerUpTimer >= powerUpDuration) {
      powerUpActive = false;
      powerUpTimer = 0;
    }
  }

  // Calculate score based on tap timing
  if (tapTime > 0) {
    const tapSpeed = 1000 / (timestamp - tapTime);
    if (tapSpeed > 200) { // Adjust threshold as needed
      score += powerUpActive ? 5 : 1;
    }
    tapTime = 0;
  }
}

// Draw game elements
function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw tap indicator
  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, 50, 0, Math.PI * 2);
  ctx.fill();

  // Draw score
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.fillText(`Score: ${score}`, canvas.width / 2, 50);

  // Draw power-up indicator if active
  if (powerUpActive) {
    ctx.fillStyle = 'yellow';
    ctx.beginPath();
    ctx.arc(canvas.width / 2, canvas.height / 2 + 70, 30, 0, Math.PI * 2);
    ctx.fill();
  }
}

// Handle taps
function handleTap() {
  tapTime = performance.now();
  if (Math.random() < 0.05) { // 5% chance for power-up
    powerUpActive = true;
    powerUpTimer = 0;
  }
}

// Event listeners
canvas.addEventListener('click', handleTap);
canvas.addEventListener('touchstart', (e) => {
  e.preventDefault();
  handleTap();
});

// Start the game loop
requestAnimationFrame(gameLoop);
