class Farm {
  constructor() {
    this.crops = [];
  }

  plant(seed) {
    const crop = new Crop(seed);
    this.crops.push(crop);
    return crop;
  }

  harvest() {
    return this.crops.filter(crop => crop.isRipe()).map(crop => crop.harvest());
  }
}

class Crop {
  constructor(seed) {
    this.seed = seed;
    this.daysGrown = 0;
  }

  grow() {
    this.daysGrown++;
  }

  isRipe() {
    return this.daysGrown >= 3; // Assume a crop is ripe after 3 days
  }

  harvest() {
    const harvest = { seed: this.seed, quantity: 1 };
    this.daysGrown = 0; // Reset after harvest
    return harvest;
  }
}

class Market {
  constructor() {
    this.inventory = {};
  }

  sell(harvest) {
    if (!this.inventory[harvest.seed]) {
      this.inventory[harvest.seed] = 0;
    }
    this.inventory[harvest.seed] += harvest.quantity;
    return harvest.quantity;
  }

  getInventory() {
    return this.inventory;
  }
}

class Coordinator {
  constructor() {
    this.farm = new Farm();
    this.market = new Market();
  }

  plantAndHarvest(seed) {
    const crop = this.farm.plant(seed);
    for (let i = 0; i < 3; i++) {
      crop.grow();
    }
    const harvest = this.farm.harvest();
    return harvest.map(harvest => this.market.sell(harvest));
  }

  getMarketInventory() {
    return this.market.getInventory();
  }
}

