const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio || 1;
let canvasWidth = window.innerWidth;
let canvasHeight = window.innerHeight;
canvas.width = canvasWidth * dpr;
canvas.height = canvasHeight * dpr;
ctx.scale(dpr, dpr);

canvas.style.width = `${canvasWidth}px`;
canvas.style.height = `${canvasHeight}px`;

const ball = {
    x: canvasWidth / 2,
    y: canvasHeight / 2,
    radius: 10,
    speed: 4,
    dx: 2,
    dy: -2
};

const paddle = {
    width: 100,
    height: 20,
    x: (canvasWidth - 100) / 2,
    y: canvasHeight - 30,
    speed: 7
};

const bricks = {
    row: 5,
    column: 10,
    width: 50,
    height: 20,
    padding: 10,
    offsetX: 45,
    offsetY: 60,
    visible: true
};

const bricksArray = [];
for (let r = 0; r < bricks.row; r++) {
    bricksArray[r] = [];
    for (let c = 0; c < bricks.column; c++) {
        bricksArray[r][c] = { x: 0, y: 0, visible: true };
    }
}

let score = 0;
let lives = 3;
let countdown = 3;
let gameRunning = false;

function drawBall() {
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
    ctx.fillStyle = '#0095DD';
    ctx.fill();
    ctx.closePath();
}

function drawPaddle() {
    ctx.beginPath();
    ctx.rect(paddle.x, paddle.y, paddle.width, paddle.height);
    ctx.fillStyle = '#0095DD';
    ctx.fill();
    ctx.closePath();
}

function drawBricks() {
    for (let r = 0; r < bricks.row; r++) {
        for (let c = 0; c < bricks.column; c++) {
            const b = bricksArray[r][c];
            if (b.visible) {
                ctx.beginPath();
                ctx.rect(bricks.offsetX + (c * (bricks.width + bricks.padding)),
                    bricks.offsetY + (r * (bricks.height + bricks.padding)),
                    bricks.width, bricks.height);
                ctx.fillStyle = '#0095DD';
                ctx.fill();
                ctx.closePath();
            }
        }
    }
}

function drawScore() {
    ctx.font = '16px Arial';
    ctx.fillStyle = '#0095DD';
    ctx.fillText(`Score: ${score}`, 8, 20);
}

function drawLives() {
    ctx.font = '16px Arial';
    ctx.fillStyle = '#0095DD';
    ctx.fillText(`Lives: ${lives}`, canvasWidth - 65, 20);
}

function drawCountdown() {
    ctx.font = '48px Arial';
    ctx.fillStyle = '#0095DD';
    ctx.fillText(countdown, canvasWidth / 2, canvasHeight / 2);
}

function collisionDetection() {
    for (let r = 0; r < bricks.row; r++) {
        for (let c = 0; c < bricks.column; c++) {
            const b = bricksArray[r][c];
            if (b.visible) {
                if (ball.x > b.x && ball.x < b.x + bricks.width && ball.y > b.y && ball.y < b.y + bricks.height) {
                    ball.dy = -ball.dy;
                    b.visible = false;
                    score++;
                    if (score === bricks.row * bricks.column) {
                        alert('YOU WIN, CONGRATULATIONS!');
                        document.location.reload();
                    }
                }
            }
        }
    }
    if (ball.x + ball.dx > canvasWidth - ball.radius || ball.x + ball.dx < ball.radius) {
        ball.dx = -ball.dx;
    }
    if (ball.y + ball.dy < ball.radius) {
        ball.dy = -ball.dy;
    } else if (ball.y + ball.dy > canvasHeight - ball.radius) {
        if (ball.x > paddle.x && ball.x < paddle.x + paddle.width) {
            ball.dy = -ball.dy;
        } else {
            lives--;
            if (!lives) {
                alert('GAME OVER');
                document.location.reload();
            } else {
                ball.x = canvasWidth / 2;
                ball.y = canvasHeight / 2;
                ball.dx = 2;
                ball.dy = -2;
                paddle.x = (canvasWidth - paddle.width) / 2;
            }
        }
    }
}

function movePaddle(event) {
    const relativeX = event.clientX - canvas.offsetLeft;
    if (relativeX > 0 && relativeX < canvasWidth) {
        paddle.x = relativeX - paddle.width / 2;
    }
}

function startGame() {
    if (countdown > 0) {
        countdown--;
    } else {
        gameRunning = true;
    }
}

function gameLoop() {
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);
    drawBricks();
    drawBall();
    drawPaddle();
    drawScore();
    drawLives();
    if (gameRunning) {
        collisionDetection();
        ball.x += ball.dx;
        ball.y += ball.dy;
    } else {
        drawCountdown();
    }
    requestAnimationFrame(gameLoop);
}

document.addEventListener('mousemove', movePaddle);
document.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
        startGame();
    }
});

setInterval(startGame, 1000);
gameLoop();
