```js
// Constants
const COLS = 8;
const ROWS = 8;
const TILE_SIZE = 64;
const FPS = 60;
const POWERUP_RATE = 100; // 1 in 100 chance of spawning a power-up

// HTML5 Canvas Setup
const canvas = document.createElement('canvas');
canvas.width = COLS * TILE_SIZE;
canvas.height = ROWS * TILE_SIZE;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game State
let board = Array.from({ length: ROWS }, () => Array(COLS).fill(0));
let powerups = [];
let lastTime = 0;
let match3Count = 0;

// Colors for Tiles
const COLORS = ['#FF6347', '#4682B4', '#32CD32', '#FFD700', '#8A2BE2', '#FF4500'];

// Power-ups
const POWERUP_TYPES = ['bomb', 'swap', 'color-blast'];
const POWERUP_IMAGES = {
  bomb: '💣',
  swap: '🔄',
  'color-blast': '💥'
};

// Random Functions
function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function randomElement(arr) {
  return arr[randomInt(0, arr.length - 1)];
}

// Initialize Board
function initBoard() {
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      board[y][x] = randomInt(0, COLORS.length - 1);
    }
  }
}

// Check Matches
function checkMatches() {
  let matches = [];

  // Check horizontal matches
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS - 2; x++) {
      if (board[y][x] === board[y][x + 1] && board[y][x] === board[y][x + 2]) {
        let match = [];
        for (let i = 0; i < 3; i++) {
          match.push([y, x + i]);
        }
        matches.push(match);
      }
    }
  }

  // Check vertical matches
  for (let x = 0; x < COLS; x++) {
    for (let y = 0; y < ROWS - 2; y++) {
      if (board[y][x] === board[y + 1][x] && board[y][x] === board[y + 2][x]) {
        let match = [];
        for (let i = 0; i < 3; i++) {
          match.push([y + i, x]);
        }
        matches.push(match);
      }
    }
  }

  return matches;
}

// Clear Matches
function clearMatches(matches) {
  matches.forEach(match => {
    match.forEach(([y, x]) => {
      board[y][x] = null;
    });
  });
}

// Drop Tiles
function dropTiles() {
  for (let x = 0; x < COLS; x++) {
    let emptySlots = [];
    for (let y = ROWS - 1; y >= 0; y--) {
      if (board[y][x] === null) {
        emptySlots.push(y);
      } else if (emptySlots.length > 0) {
        board[emptySlots.pop()][x] = board[y][x];
        board[y][x] = null;
      }
    }
  }
}

// Refill Board
function refillBoard() {
  for (let x = 0; x < COLS; x++) {
    for (let y = 0; y < ROWS; y++) {
      if (board[y][x] === null) {
        board[y][x] = randomInt(0, COLORS.length - 1);
      }
    }
  }
}

// Spawn Power-ups
function spawnPowerups() {
  if (randomInt(1, POWERUP_RATE) === 1) {
    const powerupType = randomElement(POWERUP_TYPES);
    const x = randomInt(0, COLS - 1);
    const y = randomInt(0, ROWS - 1);
    powerups.push({ type: powerupType, x, y });
  }
}

// Apply Power-ups
function applyPowerups() {
  powerups.forEach(powerup => {
    const { type, x, y } = powerup;
    switch (type) {
      case 'bomb':
        for (let i = 0; i < ROWS; i++) {
          board[i][x] = null;
        }
        for (let j = 0; j < COLS; j++) {
          board[y][j] = null;
        }
        break;
      case 'swap':
        if (x > 0) [board[y][x], board[y][x - 1]] = [board[y][x - 1], board[y][x]];
        break;
      case 'color-blast':
        for (let i = 0; i < ROWS; i++) {
          for (let j = 0; j < COLS; j++) {
            board[i][j] = null;
          }
        }
        break;
    }
  });
  powerups = [];
}

// Render
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw Tiles
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      const tile = board[y][x];
      if (tile !== null) {
        ctx.fillStyle = COLORS[tile];
        ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
      }
    }
  }

  // Draw Power-ups
  powerups.forEach(powerup => {
    const { type, x, y } = powerup;
    ctx.fillStyle = 'black';
    ctx.font = '48px Arial';
    ctx.fillText(POWERUP_IMAGES[type], x * TILE_SIZE + 10, y * TILE_SIZE + 50);
  });
}

// Update
function update(timestamp) {
  const deltaTime = timestamp - lastTime;
  const fixedTimeStep = 1000 / FPS;

  if (deltaTime >= fixedTimeStep) {
    lastTime = timestamp - (deltaTime % fixedTimeStep);

    // Game Logic
    const matches = checkMatches();
    if (matches.length > 0) {
      match3Count++;
      clearMatches(matches);
      dropTiles();
      refillBoard();
      applyPowerups();
    }

    // Spawn Power-ups
    spawnPowerups();

    // Render
    render();
  }

  requestAnimationFrame(update);
}

// Initialize Game
initBoard();
update(0);
