class Crafting {
  constructor(recipes) {
    this.recipes = new Map(recipes.map(recipe => [recipe.id, recipe]));
  }

  canCraft(recipeId, inventory) {
    const recipe = this.recipes.get(recipeId);
    if (!recipe) return false;
    for (const [itemId, quantity] of Object.entries(recipe.ingredients)) {
      if (inventory[itemId] < quantity) return false;
    }
    return true;
  }

  craft(recipeId, inventory) {
    const recipe = this.recipes.get(recipeId);
    if (!recipe) return false;
    for (const [itemId, quantity] of Object.entries(recipe.ingredients)) {
      inventory[itemId] -= quantity;
    }
    for (const [itemId, quantity] of Object.entries(recipe.result)) {
      inventory[itemId] = (inventory[itemId] || 0) + quantity;
    }
    return true;
  }
}

