    } else {
      this.items[item] = quantity;
    }
  }

  getItems() {
    return this.items;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item) {
    const price = this.economy.getPrice(item);
    if (price > 0 && this.economy.debit(price)) {
      this.inventory.addItem(item);
      console.log(`Purchased ${item} for ${price}. Remaining balance: ${this.economy.getBalance()}`);
      return true;
    } else {
