    if (this.health < 0) {
      this.health = 0;
    }
    console.log(`Took ${amount} damage. Current health: ${this.health}`);
  }

  heal(amount) {
    this.health += amount;
    if (this.health > 100) {
      this.health = 100;
    }
    console.log(`Healed for ${amount}. Current health: ${this.health}`);
  }
