      potion: 0.3,
      sword: 0.2,
      shield: 0.1
    };
  }

  rollLoot() {
    const roll = Math.random();
    let cumulativeProbability = 0;
    for (const item in this.lootTable) {
      cumulativeProbability += this.lootTable[item];
      if (roll <= cumulativeProbability) {
        console.log(`Rolled ${item} as loot.`);
        return item;
      }
    }
    return null;
  }
}

