const TILE_SIZE = 32;
const POWER_UP_TYPES = ['heal', 'speed', 'damage'];
const POWER_UP_PROBABILITY = 0.1; // 10% chance of spawning a power-up

class Entity {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.health = 100;
    this.speed = 5;
    this.damage = 10;
  }

  draw() {
    ctx.fillStyle = 'black';
    ctx.fillRect(this.x, this.y, TILE_SIZE, TILE_SIZE);
  }

  move(dx, dy) {
    this.x += dx * this.speed;
    this.y += dy * this.speed;
  }

  attack(target) {
    target.health -= this.damage;
  }
}

class Player extends Entity {
  constructor(x, y) {
    super(x, y);
    this.color = 'blue';
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, TILE_SIZE, TILE_SIZE);
  }
}

class Enemy extends Entity {
  constructor(x, y) {
    super(x, y);
    this.color = 'red';
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, TILE_SIZE, TILE_SIZE);
  }
}

class PowerUp {
  constructor(x, y, type) {
    this.x = x;
    this.y = y;
    this.type = type;
    this.radius = 10;
  }

  draw() {
    ctx.fillStyle = 'green';
    ctx.beginPath();
    ctx.arc(this.x + TILE_SIZE / 2, this.y + TILE_SIZE / 2, this.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  collect(player) {
    switch (this.type) {
      case 'heal':
        player.health = Math.min(player.health + 20, 100);
        break;
      case 'speed':
        player.speed += 1;
        break;
      case 'damage':
        player.damage += 1;
        break;
    }
  }
}

let player = new Player(100, 100);
let enemy = new Enemy(600, 100);
let powerUps = [];

function spawnPowerUp() {
  if (Math.random() < POWER_UP_PROBABILITY) {
    const type = POWER_UP_TYPES[Math.floor(Math.random() * POWER_UP_TYPES.length)];
    powerUps.push(new PowerUp(
      Math.floor(Math.random() * (canvas.width / TILE_SIZE)) * TILE_SIZE,
      Math.floor(Math.random() * (canvas.height / TILE_SIZE)) * TILE_SIZE,
      type
    ));
  }
}

function handleInput() {
  const keys = {};
  document.addEventListener('keydown', e => keys[e.key] = true);
  document.addEventListener('keyup', e => keys[e.key] = false);

  let dx = 0, dy = 0;
  if (keys['ArrowUp']) dy = -1;
  if (keys['ArrowDown']) dy = 1;
  if (keys['ArrowLeft']) dx = -1;
  if (keys['ArrowRight']) dx = 1;
  player.move(dx, dy);
}

function checkCollisions() {
  powerUps.forEach(powerUp => {
    if (
      player.x < powerUp.x + TILE_SIZE &&
      player.x + TILE_SIZE > powerUp.x &&
      player.y < powerUp.y + TILE_SIZE &&
      player.y + TILE_SIZE > powerUp.y
    ) {
      powerUp.collect(player);
      powerUps = powerUps.filter(p => p !== powerUp);
    }
  });

  if (
    player.x < enemy.x + TILE_SIZE &&
    player.x + TILE_SIZE > enemy.x &&
    player.y < enemy.y + TILE_SIZE &&
    player.y + TILE_SIZE > enemy.y
  ) {
    player.attack(enemy);
    if (enemy.health <= 0) {
      alert('You win!');
      document.location.reload();
    }
  }
}

function update() {
  spawnPowerUp();
  handleInput();
  checkCollisions();
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  player.draw();
  enemy.draw();
  powerUps.forEach(powerUp => powerUp.draw());
}

function gameLoop() {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

gameLoop();
