class EventBus {
  constructor() {
    this.events = {};
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }

  subscribe(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }
}

class Skill {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.skills = {};
    this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
  }

  learn(skillName, points) {
    if (!this.skills[skillName]) {
      this.skills[skillName] = 0;
    }
    this.skills[skillName] += points;
    console.log(`Learned ${points} points in ${skillName}. Total: ${this.skills[skillName]}`);
  }

  onLevelUp(level) {
    console.log(`Level up to ${level}! Learning new skills...`);
    this.learn('Advanced Technique', 10);
    this.learn('Expertise', 5);
  }
}

class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.experiencePoints = 0;
    this.eventBus.subscribe('gainExperience', this.gainExperience.bind(this));
  }

  gainExperience(points) {
    this.experiencePoints += points;
    console.log(`Gained ${points} experience points. Total: ${this.experiencePoints}`);
    if (this.experiencePoints >= 100) {
      this.levelUp();
    }
  }

  levelUp() {
    const newLevel = Math.floor(this.experiencePoints / 100) + 1;
    console.log(`Leveled up to level ${newLevel}!`);
    this.eventBus.emit('levelUp', newLevel);
    this.experiencePoints %= 100;
  }
}

class LevelUp {
