function update(dt) {
  if (keyboard.right) player.velocityX = player.speed;
  else if (keyboard.left) player.velocityX = -player.speed;
  else player.velocityX = 0;

  if (keyboard.up && player.onGround) {
    player.velocityY = player.jumpForce;
    player.onGround = false;
  }

  player.velocityY += player.gravity * dt;
  player.x += player.velocityX * dt;
  player.y += player.velocityY * dt;

  platforms.forEach(platform => {
    if (player.x < platform.x + platform.width &&
        player.x + player.width > platform.x &&
        player.y < platform.y + platform.height &&
        player.y + player.height > platform.y) {
      if (player.velocityY > 0) {
        player.y = platform.y - player.height;
        player.velocityY = 0;
        player.onGround = true;
      }
    }
  });

  if (player.y > canvas.height) {
    player.health -= 10;
    if (player.health <= 0) {
      player.health = 100;
      player.x = 100;
      player.y = 100;
    }
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);

  ctx.fillStyle = 'green';
  platforms.forEach(platform => ctx.fillRect(platform.x, platform.y, platform.width, platform.height));

  ctx.fillStyle = 'red';
  ctx.fillRect(10, 10, player.health, 20);
}

const keyboard = { right: false, left: false, up: false };
document.addEventListener('keydown', e => {
  if (e.key === 'ArrowRight') keyboard.right = true;
  if (e.key === 'ArrowLeft') keyboard.left = true;
  if (e.key === 'ArrowUp') keyboard.up = true;
});
document.addEventListener('keyup', e => {
  if (e.key === 'ArrowRight') keyboard.right = false;
  if (e.key === 'ArrowLeft') keyboard.left = false;
  if (e.key === 'ArrowUp') keyboard.up = false;
});

function gameLoop(currentTime) {
  const dt = (currentTime - lastTime) / 1000;
  accumulator += dt;

  while (accumulator >= fixedTimeStep) {
    update(fixedTimeStep);
    accumulator -= fixedTimeStep;
  }

  render();
  lastTime = currentTime;
  requestAnimationFrame(gameLoop);
}

