const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const BOARD_SIZE = 8;
const TILE_SIZE = 50;
const GEM_TYPES = 7;
const MATCH_LENGTH = 3;
const SWAP_COOLDOWN = 200;
const COUNTDOWN_START = 120; // seconds

let board = [];
let selectedTile = null;
let swapCooldown = 0;
let countdown = COUNTDOWN_START;
let gameRunning = true;

function randomGem() {
    return Math.floor(Math.random() * GEM_TYPES);
}

function createBoard() {
    for (let y = 0; y < BOARD_SIZE; y++) {
        board[y] = [];
        for (let x = 0; x < BOARD_SIZE; x++) {
            board[y][x] = randomGem();
        }
    }
}

function drawBoard() {
    for (let y = 0; y < BOARD_SIZE; y++) {
        for (let x = 0; x < BOARD_SIZE; x++) {
            ctx.fillStyle = `hsl(${board[y][x] * 360 / GEM_TYPES}, 100%, 50%)`;
            ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
            ctx.strokeStyle = '#000';
            ctx.strokeRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
        }
    }
}

function checkMatches() {
    let matches = [];

    // Check horizontal matches
    for (let y = 0; y < BOARD_SIZE; y++) {
        for (let x = 0; x < BOARD_SIZE - MATCH_LENGTH + 1; x++) {
            let match = true;
            for (let i = 1; i < MATCH_LENGTH; i++) {
                if (board[y][x] !== board[y][x + i]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                for (let i = 0; i < MATCH_LENGTH; i++) {
                    matches.push({ x: x + i, y, type: board[y][x] });
                }
            }
        }
    }

    // Check vertical matches
    for (let x = 0; x < BOARD_SIZE; x++) {
        for (let y = 0; y < BOARD_SIZE - MATCH_LENGTH + 1; y++) {
            let match = true;
            for (let i = 1; i < MATCH_LENGTH; i++) {
                if (board[y][x] !== board[y + i][x]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                for (let i = 0; i < MATCH_LENGTH; i++) {
                    matches.push({ x, y: y + i, type: board[y][x] });
                }
            }
        }
    }

    return matches;
}

function clearMatches(matches) {
    matches.forEach(match => {
        board[match.y][match.x] = null;
    });
}

function dropGems() {
    for (let x = 0; x < BOARD_SIZE; x++) {
        let nullCount = 0;
        for (let y = BOARD_SIZE - 1; y >= 0; y--) {
            if (board[y][x] === null) {
                nullCount++;
            } else if (nullCount > 0) {
                board[y + nullCount][x] = board[y][x];
                board[y][x] = null;
            }
        }
    }
}

function fillBoard() {
    for (let x = 0; x < BOARD_SIZE; x++) {
        for (let y = 0; y < BOARD_SIZE; y++) {
            if (board[y][x] === null) {
                board[y][x] = randomGem();
            }
        }
    }
}

function handleInput(event) {
    if (!gameRunning || swapCooldown > 0) return;

    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((event.clientX - rect.left) / TILE_SIZE);
    const y = Math.floor((event.clientY - rect.top) / TILE_SIZE);

    if (selectedTile === null) {
        selectedTile = { x, y };
    } else {
        const dx = Math.abs(selectedTile.x - x);
        const dy = Math.abs(selectedTile.y - y);

        if ((dx === 1 && dy === 0) || (dx === 0 && dy === 1)) {
            const temp = board[selectedTile.y][selectedTile.x];
            board[selectedTile.y][selectedTile.x] = board[y][x];
            board[y][x] = temp;

            swapCooldown = SWAP_COOLDOWN;
        }

        selectedTile = null;
    }
}

function update() {
    if (swapCooldown > 0) {
        swapCooldown--;
    }

    const matches = checkMatches();
    if (matches.length > 0) {
        clearMatches(matches);
        dropGems();
        fillBoard();
    } else {
        if (swapCooldown === 0) {
            selectedTile = null;
        }
    }

    if (countdown > 0) {
        countdown--;
    } else {
        gameRunning = false;
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBoard();
    ctx.fillStyle = '#000';
    ctx.fillText(`Time: ${Math.floor(countdown / 60)}:${(countdown % 60).toString().padStart(2, '0')}`, 10, 20);
}

function gameLoop() {
    update();
    draw();
    if (gameRunning) {
        requestAnimationFrame(gameLoop);
    }
}

canvas.addEventListener('click', handleInput);
createBoard();
gameLoop();
