        this.name = name;
        this.level = 1;
    }

    improve() {
        this.level += 1;
        console.log(`Skill ${this.name} improved to level ${this.level}`);
    }

    getLevel() {
        return this.level;
    }
}

class Experience {
    constructor() {
        this.points = 0;
    }

    addPoints(points) {
        this.points += points;
        console.log(`Experience points added: ${points}. Total: ${this.points}`);
    }

    getPoints() {
        return this.points;
    }
}

class LevelUp {
    constructor(skill, experience) {
        this.skill = skill;
        this.experience = experience;
        this.thresholds = [10, 20, 30]; // Thresholds for level up
    }

    checkLevelUp() {
        const currentPoints = this.experience.getPoints();
        const currentSkillLevel = this.skill.getLevel();
        const nextThreshold = this.thresholds[currentSkillLevel - 1];

        if (currentPoints >= nextThreshold) {
            this.skill.improve();
            this.experience.addPoints(-nextThreshold); // Deduct points used for level up
        }
    }
}

// Coordinator to wire the systems together
class GameCoordinator {
    constructor() {
        this.skill = new Skill("Coding");
        this.experience = new Experience();
        this.levelUp = new LevelUp(this.skill, this.experience);
    }

    gainExperience(points) {
        this.experience.addPoints(points);
        this.levelUp.checkLevelUp();
    }
}

// Demo
const game = new GameCoordinator();
game.gainExperience(5);  // Output: Experience points added: 5. Total: 5
game.gainExperience(7);  // Output: Experience points added: 7. Total: 12
