class Trade {
    constructor(exchangeRate) {
        this.exchangeRate = exchangeRate;
    }

    trade(amount, currency) {
        if (currency === 'gold') {
            return amount * this.exchangeRate;
        } else if (currency === 'silver') {
            return amount / this.exchangeRate;
        } else {
            throw new Error('Unsupported currency');
        }
    }
}

class Reputation {
    constructor(initialReputation) {
        this.reputation = initialReputation;
    }

    improveReputation(points) {
        this.reputation += points;
        return this.reputation;
    }

    getReputation() {
        return this.reputation;
    }
}

class Faction {
    constructor(name, initialReputation) {
        this.name = name;
        this.reputationSystem = new Reputation(initialReputation);
    }

    performTrade(tradeSystem, amount, currency) {
        const tradedAmount = tradeSystem.trade(amount, currency);
        console.log(`${this.name} traded ${amount} ${currency} for ${tradedAmount} gold.`);
        return tradedAmount;
    }

    gainReputation(points) {
        const newReputation = this.reputationSystem.improveReputation(points);
        console.log(`${this.name} reputation increased to ${newReputation}.`);
        return newReputation;
    }

    getReputation() {
        return this.reputationSystem.getReputation();
    }
}

// Demo
