const factionA = new Faction('Faction A', 50);

console.log('Initial Reputation:', factionA.getReputation());

const tradedGold = factionA.performTrade(tradeSystem, 50, 'silver');
factionA.gainReputation(tradedGold);

console.log('Final Reputation:', factionA.getReputation());
