const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let balls = [];
let combo = 0;
let highestCombo = 0;
let gravity = 0.5;
let bounce = -0.7;
let resetY = 10;
let windowRatio = window.devicePixelRatio;

function resizeCanvas() {
  canvas.width = window.innerWidth * windowRatio;
  canvas.height = window.innerHeight * windowRatio;
  ctx.scale(windowRatio, windowRatio);
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

class Ball {
  constructor(x, y, radius, color) {
    this.x = x;
    this.y = y;
    this.radius = radius;
    this.color = color;
    this.vy = 0;
    this.combo = 0;
  }

  update() {
    this.vy += gravity;
    this.y += this.vy;

    if (this.y + this.radius > canvas.height) {
      this.y = canvas.height - this.radius;
      this.vy *= bounce;
      this.combo = 0;
    }
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
    ctx.fillStyle = this.color;
    ctx.fill();
  }

  reset() {
    this.y = resetY;
    this.vy = 0;
  }

  checkCollision(other) {
    const dx = this.x - other.x;
    const dy = this.y - other.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    return distance < this.radius + other.radius;
  }
}

function spawnBall() {
  const x = Math.random() * canvas.width;
  const radius = Math.random() * 10 + 5;
  const color = `hsl(${Math.random() * 360}, 50%, 50%)`;
  balls.push(new Ball(x, resetY, radius, color));
}

function checkCollisions() {
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      if (balls[i].checkCollision(balls[j])) {
        balls[i].reset();
        balls[j].reset();
        combo++;
        highestCombo = Math.max(highestCombo, combo);
      }
    }
  }
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  balls.forEach(ball => {
    ball.update();
    ball.draw();
  });

  checkCollisions();

  if (Math.random() < 0.02) {
    spawnBall();
  }

  requestAnimationFrame(update);
}

update();

document.addEventListener('click', () => {
  combo = 0;
  balls = [];
});
