class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited ${amount}. New balance: ${this.balance}`);
    } else {
      console.log('Deposit amount must be positive.');
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
    } else {
      console.log('Invalid withdrawal amount.');
    }
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getMarketPrice(item) {
    return this.prices[item] !== undefined ? this.prices[item] : null;
  }

  updatePrice(item, newPrice) {
    if (newPrice >= 0) {
      this.prices[item] = newPrice;
      console.log(`Updated price of ${item} to ${newPrice}`);
    } else {
      console.log('Price must be non-negative.');
    }
  }

  getMarketPrices() {
    return { ...this.prices };
  }
}

class Inventory {
  constructor(items = {}) {
    this.items = items;
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      console.log(`Added ${quantity} ${item}(s). New total: ${this.items[item]}`);
    } else {
      console.log('Quantity must be positive.');
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] !== undefined && quantity > 0 && quantity <= this.items[item]) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      console.log(`Removed ${quantity} ${item}(s). Remaining: ${this.items[item]}`);
    } else {
      console.log('Invalid removal quantity.');
    }
  }

  getInventory() {
    return { ...this.items };
  }
}

class GameCoordinator {
  constructor() {
    this.bank = new Bank(1000);
    this.market = new Market({ apple: 2, banana: 3 });
    this.inventory = new Inventory();
  }

  buyItem(item, quantity) {
    const price = this.market.getMarketPrice(item);
    if (price !== null) {
      const totalCost = price * quantity;
      if (this.bank.getBalance() >= totalCost) {
        this.bank.withdraw(totalCost);
        this.inventory.addItem(item, quantity);
        console.log(`Bought ${quantity} ${item}(s) for ${totalCost}.`);
      } else {
        console.log('Insufficient funds.');
      }
    } else {
      console.log(`Item ${item} not found in market.`);
    }
  }

  sellItem(item, quantity) {
    if (this.inventory.items[item] !== undefined && this.inventory.items[item] >= quantity) {
      const price = this.market.getMarketPrice(item);
      if (price !== null) {
        const totalEarnings = price * quantity;
        this.bank.deposit(totalEarnings);
        this.inventory.removeItem(item, quantity);
        console.log(`Sold ${quantity} ${item}(s) for ${totalEarnings}.`);
      } else {
        console.log(`Item ${item} not found in market.`);
      }
    } else {
      console.log('Invalid sell quantity.');
    }
  }

  displayStatus() {
    console.log('Bank Balance:', this.bank.getBalance());
    console.log('Market Prices:', this.market.getMarketPrices());
    console.log('Inventory:', this.inventory.getInventory());
  }
}

