  ctx.scale(dpr, dpr);
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

const keys = {};
window.addEventListener('keydown', (e) => keys[e.key] = true);
window.addEventListener('keyup', (e) => keys[e.key] = false);

const powerUps = [];
function spawnPowerUp() {
  powerUps.push({
    x: Math.random() * canvas.width,
    y: Math.random() * canvas.height,
    size: 10,
    collected: false
  });
}
setInterval(spawnPowerUp, 2000);

let score = 0;
let typingSpeed = 0;
let startTime = performance.now();
let currentText = '';
let inputText = '';
let textX = 20;
let textY = 50;
let textFont = '30px Arial';
let textColor = 'black';
let gameOver = false;
let gameStartTime = performance.now();
let gameDuration = 60000;

function generateText(length) {
  let result = '';
  const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
  for (let i = 0; i < length; i++) {
    result += characters.charAt(Math.floor(Math.random() * characters.length));
  }
  return result;
}

function update() {
  if (gameOver) return;

  const now = performance.now();
  typingSpeed = (inputText.length / ((now - startTime) / 1000)) * 60;
  if (inputText === currentText) {
    score += currentText.length;
    inputText = '';
    currentText = generateText(5 + Math.floor(score / 100));
    textX = Math.random() * (canvas.width - ctx.measureText(currentText).width);
    textY = Math.random() * (canvas.height - 50);
    startTime = now;
  }

  powerUps.forEach((powerUp, index) => {
    if (!powerUp.collected && inputText.endsWith(currentText.substring(0, inputText.length))) {
      const dx = Math.abs(powerUp.x - textX);
      const dy = Math.abs(powerUp.y - textY);
      if (dx < powerUp.size && dy < powerUp.size) {
        powerUp.collected = true;
        score += 50;
      }
    }
    if (!powerUp.collected) {
      powerUp.y += 1;
      if (powerUp.y > canvas.height) {
        powerUps.splice(index, 1);
      }
    }
  });

  if (now - gameStartTime > gameDuration) {
    gameOver = true;
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.font = textFont;
  ctx.fillStyle = textColor;
  ctx.fillText(currentText, textX, textY);

  powerUps.forEach((powerUp) => {
    if (!powerUp.collected) {
      ctx.beginPath();
      ctx.arc(powerUp.x, powerUp.y, powerUp.size, 0, Math.PI * 2);
      ctx.fillStyle = 'blue';
      ctx.fill();
      ctx.closePath();
    }
  });

  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Speed: ${typingSpeed.toFixed(2)} CPM`, 10, 60);
  ctx.fillText(`Time: ${Math.floor((gameDuration - (performance.now() - gameStartTime)) / 1000)}s`, 10, 90);

  if (gameOver) {
    ctx.font = '40px Arial';
    ctx.fillStyle = 'red';
    ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
  }
}

function gameLoop() {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

function onInput(e) {
  if (!gameOver) {
    inputText += e.key;
  }
}

window.addEventListener('keydown', onInput);
gameLoop();
