// Event Bus Implementation
class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

// Combat System
class Combat {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('attack', this.handleAttack.bind(this));
  }

  initiateAttack(target, damage) {
    this.eventBus.emit('attack', { target, damage });
  }

  handleAttack({ target, damage }) {
    console.log(`Combat: ${target} takes ${damage} damage.`);
    this.eventBus.emit('health-damage', { target, damage });
  }
}

// Health System
class Health {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.healthMap = {};
    this.eventBus.subscribe('health-damage', this.handleHealthDamage.bind(this));
    this.eventBus.subscribe('heal', this.handleHeal.bind(this));
  }

  setHealth(target, health) {
    this.healthMap[target] = health;
    console.log(`Health: ${target} has ${health} health.`);
  }

  handleHealthDamage({ target, damage }) {
    if (this.healthMap[target] !== undefined) {
      this.healthMap[target] -= damage;
      if (this.healthMap[target] <= 0) {
        this.healthMap[target] = 0;
        console.log(`Health: ${target} is defeated.`);
        this.eventBus.emit('death', { target });
      } else {
        console.log(`Health: ${target} now has ${this.healthMap[target]} health.`);
      }
    }
  }

  handleHeal({ target, amount }) {
    if (this.healthMap[target] !== undefined) {
      this.healthMap[target] += amount;
      console.log(`Health: ${target} now has ${this.healthMap[target]} health.`);
    }
  }
}

// Loot System
class Loot {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('death', this.handleDeath.bind(this));
  }

  handleDeath({ target }) {
    console.log(`Loot: ${target} drops loot.`);
    // Example loot drop logic
    const loot = ['potion', 'gold', 'weapon'];
    console.log(`Loot: ${target} drops ${loot.join(', ')}.`);
  }
}

