class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }

  emit(event, ...args) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(...args));
    }
  }
}

class Recipe {
  constructor(id, ingredients, result) {
    this.id = id;
    this.ingredients = ingredients;
    this.result = result;
  }
}

class CraftingSystem {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = [];
    this.eventBus.subscribe('recipe.register', this.registerRecipe.bind(this));
    this.eventBus.subscribe('craft.item', this.craftItem.bind(this));
  }

  registerRecipe(recipe) {
    this.recipes.push(recipe);
    console.log(`Recipe registered: ${recipe.id}`);
  }

  craftItem(itemId) {
    const recipe = this.recipes.find(recipe => recipe.result === itemId);
    if (recipe) {
      this.eventBus.emit('inventory.use', recipe.ingredients);
      this.eventBus.emit('inventory.add', recipe.result);
      console.log(`Crafted ${recipe.result} from ${recipe.ingredients.join(', ')}`);
    } else {
      console.log(`No recipe found for item: ${itemId}`);
    }
  }
}

class InventorySystem {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('inventory.add', this.addItem.bind(this));
    this.eventBus.subscribe('inventory.use', this.useItems.bind(this));
  }

  addItem(item) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item]++;
    console.log(`Added ${item} to inventory`);
  }

  useItems(items) {
    items.forEach(item => {
      if (this.items[item] > 0) {
        this.items[item]--;
        console.log(`Used ${item} from inventory`);
      } else {
        console.log(`Not enough ${item} in inventory`);
      }
    });
  }
}

