class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor() {
    this.prices = {
      apple: 1,
      banana: 2,
      carrot: 3
    };
  }

  getPrice(item) {
    return this.prices[item] || null;
  }

  sell(item, price) {
    if (price > 0) {
      this.prices[item] = price;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity) {
    if (quantity > 0 && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Coordinator {
  constructor() {
    this.bank = new Bank(100);
    this.market = new Market();
    this.inventory = new Inventory();
  }

  buyItem(item, quantity) {
    const price = this.market.getPrice(item);
    const totalPrice = price * quantity;

    if (price && this.bank.withdraw(totalPrice)) {
      this.inventory.addItem(item, quantity);
      console.log(`Bought ${quantity} ${item}(s) for ${totalPrice}.`);
      return true;
    }
    console.log(`Failed to buy ${quantity} ${item}(s).`);
    return false;
  }

  sellItem(item, quantity, price) {
    if (this.inventory.removeItem(item, quantity) && this.market.sell(item, price)) {
      this.bank.deposit(quantity * price);
      console.log(`Sold ${quantity} ${item}(s) for ${quantity * price}.`);
      return true;
    }
    console.log(`Failed to sell ${quantity} ${item}(s).`);
    return false;
  }

  showStatus() {
    console.log(`Bank Balance: ${this.bank.getBalance()}`);
    console.log(`Inventory:`, this.inventory.items);
    console.log(`Market Prices:`, this.market.prices);
  }
}

