const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 400;
const ctx = canvas.getContext('2d');

const gridSize = 4;
const cellSize = canvas.width / gridSize;
const maxScore = 2048;
let board = Array.from({ length: gridSize }, () => Array(gridSize).fill(0));
let score = 0;
let gameOver = false;

function getRandomEmptyCell() {
    const emptyCells = [];
    for (let y = 0; y < gridSize; y++) {
        for (let x = 0; x < gridSize; x++) {
            if (board[y][x] === 0) {
                emptyCells.push({ x, y });
            }
        }
    }
    return emptyCells[Math.floor(Math.random() * emptyCells.length)];
}

function spawnNewTile() {
    const cell = getRandomEmptyCell();
    if (cell) {
        board[cell.y][cell.x] = Math.random() < 0.9 ? 2 : 4;
    }
}

function mergeRow(row) {
    const newRow = [];
    let skipNext = false;
    for (let i = 0; i < row.length; i++) {
        if (skipNext) {
            skipNext = false;
            continue;
        }
        if (row[i] !== 0) {
            if (i < row.length - 1 && row[i] === row[i + 1]) {
                newRow.push(row[i] * 2);
                score += row[i] * 2;
                skipNext = true;
            } else {
                newRow.push(row[i]);
            }
        }
    }
    while (newRow.length < gridSize) {
        newRow.push(0);
    }
    return newRow;
}

function moveLeft() {
    let changed = false;
    for (let y = 0; y < gridSize; y++) {
        const newRow = mergeRow(board[y]);
        if (newRow.some((val, index) => val !== board[y][index])) {
            changed = true;
        }
        board[y] = newRow;
    }
    return changed;
}

function moveRight() {
    let changed = false;
    for (let y = 0; y < gridSize; y++) {
        const newRow = mergeRow(board[y].slice().reverse()).reverse();
        if (newRow.some((val, index) => val !== board[y][index])) {
            changed = true;
        }
        board[y] = newRow;
    }
    return changed;
}

function moveUp() {
    let changed = false;
    for (let x = 0; x < gridSize; x++) {
        const newRow = mergeRow(board.map(row => row[x]));
        if (newRow.some((val, index) => val !== board[index][x])) {
            changed = true;
        }
        for (let y = 0; y < gridSize; y++) {
            board[y][x] = newRow[y];
        }
    }
    return changed;
}

function moveDown() {
    let changed = false;
    for (let x = 0; x < gridSize; x++) {
        const newRow = mergeRow(board.map(row => row[x]).reverse()).reverse();
        if (newRow.some((val, index) => val !== board[index][x])) {
            changed = true;
        }
        for (let y = 0; y < gridSize; y++) {
            board[y][x] = newRow[y];
        }
    }
    return changed;
}

function handleInput(event) {
    if (gameOver) return;
    let changed = false;
    if (event.key === 'ArrowLeft') {
        changed = moveLeft();
    } else if (event.key === 'ArrowRight') {
        changed = moveRight();
    } else if (event.key === 'ArrowUp') {
        changed = moveUp();
    } else if (event.key === 'ArrowDown') {
        changed = moveDown();
    }
    if (changed) {
        spawnNewTile();
        checkGameOver();
    }
}

canvas.addEventListener('click', (event) => {
    const x = Math.floor(event.clientX / cellSize);
    const y = Math.floor(event.clientY / cellSize);
    let changed = false;
    if (event.offsetX < event.offsetY && event.offsetX < canvas.width - event.offsetY) {
        changed = moveUp();
    } else if (event.offsetX > event.offsetY && event.offsetX > canvas.width - event.offsetY) {
        changed = moveDown();
    } else if (event.offsetX < event.offsetY) {
        changed = moveLeft();
    } else {
        changed = moveRight();
    }
    if (changed) {
        spawnNewTile();
        checkGameOver();
    }
});

function checkGameOver() {
    gameOver = board.every(row => row.every(cell => cell !== 0 && (cell === row[row.indexOf(cell) + 1] || cell === board[row.indexOf(row) + 1][row.indexOf(cell)])));
    if (gameOver) {
        alert('Game Over! Your score: ' + score);
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < gridSize; y++) {
        for (let x = 0; x < gridSize; x++) {
            const cellValue = board[y][x];
            ctx.fillStyle = cellValue === 0 ? '#CDC1B4' : (cellValue === maxScore ? '#FFFFFF' : `#E${(6 - Math.log2(cellValue) / Math.log2(2)).toString(16).repeat(3)}`);
            ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            ctx.strokeStyle = '#AAA';
            ctx.strokeRect(x * cellSize, y * cellSize, cellSize, cellSize);
            if (cellValue !== 0) {
                ctx.fillStyle = '#776E65';
                ctx.font = `${Math.min(cellSize, 60)}px Arial`;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(cellValue.toString(), x * cellSize + cellSize / 2, y * cellSize + cellSize / 2);
            }
        }
    }
    ctx.fillStyle = '#776E65';
    ctx.font = '24px Arial';
    ctx.textAlign = 'right';
    ctx.fillText('Score: ' + score, canvas.width - 10, 30);
}

function update() {
    handleInput();
    render();
}

function gameLoop(timestamp) {
    const frameTime = 1000 / 60;
    const delta = timestamp - lastTime;
    if (delta > frameTime) {
        lastTime = timestamp - (delta % frameTime);
        update();
    }
    requestAnimationFrame(gameLoop);
}

let lastTime = performance.now();
spawnNewTile();
spawnNewTile();
document.addEventListener('keydown', handleInput);
requestAnimationFrame(gameLoop);
