const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

canvas.width = 800;
canvas.height = 600;

const bird = {
    x: 50,
    y: canvas.height / 2,
    width: 20,
    height: 20,
    velocity: 0,
    gravity: 0.5,
    jumpPower: -10
};

const pipes = [];
const pipeWidth = 60;
const gapSize = 150;
let pipeSpawnInterval = 2000;
let lastPipeSpawnTime = 0;

const particles = [];
const particleCount = 10;
const particleLifetime = 1000;

function spawnPipe() {
    const height = Math.random() * (canvas.height - gapSize);
    pipes.push({ x: canvas.width, y: 0, height });
    pipes.push({ x: canvas.width, y: height + gapSize, height: canvas.height - (height + gapSize) });
}

function updateParticles(dt) {
    particles.forEach(p => {
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.life -= dt;
    });
    particles.filter(p => p.life > 0);
}

function drawParticles() {
    ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
    particles.forEach(p => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
    });
}

function spawnParticles(x, y) {
    for (let i = 0; i < particleCount; i++) {
        particles.push({
            x, y,
            vx: (Math.random() - 0.5) * 5,
            vy: (Math.random() - 0.5) * 5,
            size: Math.random() * 2 + 1,
            life: particleLifetime
        });
    }
}

function update(dt) {
    bird.velocity += bird.gravity * dt;
    bird.y += bird.velocity * dt;

    if (Date.now() - lastPipeSpawnTime > pipeSpawnInterval) {
        spawnPipe();
        lastPipeSpawnTime = Date.now();
    }

    pipes.forEach(pipe => {
        pipe.x -= 2 * dt;
    });

    pipes = pipes.filter(pipe => pipe.x + pipeWidth > 0);

    updateParticles(dt);
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#0f0';
    ctx.fillRect(bird.x, bird.y, bird.width, bird.height);

    ctx.fillStyle = '#f00';
    pipes.forEach(pipe => {
        ctx.fillRect(pipe.x, pipe.y, pipeWidth, pipe.height);
    });

    drawParticles();
}

function checkCollision() {
    const birdRect = {
        x: bird.x,
        y: bird.y,
        width: bird.width,
        height: bird.height
    };

    for (const pipe of pipes) {
        const pipeRect = {
            x: pipe.x,
            y: pipe.y,
            width: pipeWidth,
            height: pipe.height
        };

        if (birdRect.x < pipeRect.x + pipeRect.width &&
            birdRect.x + birdRect.width > pipeRect.x &&
            birdRect.y < pipeRect.y + pipeRect.height &&
            birdRect.y + birdRect.height > pipeRect.y) {
            return true;
        }
    }

    return bird.y + bird.height > canvas.height || bird.y < 0;
}

function gameLoop(timestamp) {
    const dt = Math.min(100, timestamp - lastTimestamp);
    lastTimestamp = timestamp;

    if (checkCollision()) {
        alert('Game Over!');
        document.location.reload();
        return;
    }

    update(dt);
    draw();

    requestAnimationFrame(gameLoop);
}

let lastTimestamp = 0;
requestAnimationFrame(gameLoop);

document.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
        bird.velocity = bird.jumpPower;
        spawnParticles(bird.x + bird.width / 2, bird.y + bird.height / 2);
    }
});
