class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Skill {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
  }

  learnSkill(skillName) {
    console.log(`Learning ${skillName}`);
    this.eventBus.emit('skillLearned', { skillName });
  }

  onLevelUp(data) {
    console.log(`Gained a new level! Learning a new skill...`);
    this.learnSkill(`Skill Level ${data.level}`);
  }
}

class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.experiencePoints = 0;
    this.eventBus.subscribe('skillLearned', this.onSkillLearned.bind(this));
  }

  earnExperience(points) {
    this.experiencePoints += points;
    console.log(`Earned ${points} experience points. Total: ${this.experiencePoints}`);
    this.checkLevelUp();
  }

  onSkillLearned(data) {
    console.log(`Skill ${data.skillName} learned. Earning experience...`);
    this.earnExperience(100); // Arbitrary experience gain per skill
  }

  checkLevelUp() {
    const level = Math.floor(this.experiencePoints / 1000) + 1;
    this.eventBus.emit('levelUp', { level });
  }
}

class LevelUp {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.level = 1;
    this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
  }

  onLevelUp(data) {
    this.level = data.level;
    console.log(`Congratulations! You are now level ${this.level}!`);
  }
}

// Demo
