const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');

const asteroids = [];
const bullets = [];
const powerUps = [];
const player = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  radius: 10,
  speed: 5,
  angle: 0,
  score: 0,
  lives: 3
};

const keys = {
  right: false,
  left: false,
  up: false,
  space: false
};

function getRandom(min, max) {
  return Math.random() * (max - min) + min;
}

function createAsteroid() {
  const size = getRandom(10, 40);
  const x = getRandom(0, canvas.width);
  const y = getRandom(0, canvas.height);
  const speed = getRandom(1, 3);
  const angle = getRandom(0, Math.PI * 2);
  asteroids.push({ x, y, size, speed, angle });
}

function createPowerUp(x, y) {
  powerUps.push({ x, y, collected: false });
}

function drawCircle(ctx, x, y, radius, color) {
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.closePath();
}

function drawText(ctx, text, x, y, size, color) {
  ctx.font = `${size}px Arial`;
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
}

function updatePlayer() {
  if (keys.right) player.angle += 0.05;
  if (keys.left) player.angle -= 0.05;
  if (keys.up) {
    player.x += player.speed * Math.cos(player.angle);
    player.y += player.speed * Math.sin(player.angle);
  }

  if (player.x < 0) player.x = canvas.width;
  if (player.x > canvas.width) player.x = 0;
  if (player.y < 0) player.y = canvas.height;
  if (player.y > canvas.height) player.y = 0;
}

function updateBullets() {
  bullets.forEach((bullet, index) => {
    bullet.x += bullet.speed * Math.cos(bullet.angle);
    bullet.y += bullet.speed * Math.sin(bullet.angle);

    if (bullet.x < 0 || bullet.x > canvas.width || bullet.y < 0 || bullet.y > canvas.height) {
      bullets.splice(index, 1);
    }
  });
}

function updateAsteroids() {
  asteroids.forEach((asteroid, index) => {
    asteroid.x += asteroid.speed * Math.cos(asteroid.angle);
    asteroid.y += asteroid.speed * Math.sin(asteroid.angle);

    if (asteroid.x < 0) asteroid.x = canvas.width;
    if (asteroid.x > canvas.width) asteroid.x = 0;
    if (asteroid.y < 0) asteroid.y = canvas.height;
    if (asteroid.y > canvas.height) asteroid.y = 0;

    asteroids.forEach((otherAsteroid, otherIndex) => {
      if (index !== otherIndex && Math.hypot(asteroid.x - otherAsteroid.x, asteroid.y - otherAsteroid.y) < asteroid.size + otherAsteroid.size) {
        const tempAngle = asteroid.angle;
        asteroid.angle = otherAsteroid.angle;
        otherAsteroid.angle = tempAngle;
      }
    });
  });
}

function checkCollisions() {
  bullets.forEach((bullet, bulletIndex) => {
    asteroids.forEach((asteroid, asteroidIndex) => {
      if (Math.hypot(bullet.x - asteroid.x, bullet.y - asteroid.y) < asteroid.size) {
        asteroids.splice(asteroidIndex, 1);
        bullets.splice(bulletIndex, 1);
        player.score += 100;
        createPowerUp(asteroid.x, asteroid.y);
      }
    });
  });

  asteroids.forEach(asteroid => {
    if (Math.hypot(player.x - asteroid.x, player.y - asteroid.y) < player.radius + asteroid.size) {
      asteroids.splice(asteroids.indexOf(asteroid), 1);
      player.lives--;
      if (player.lives <= 0) {
        alert(`Game Over! Your score: ${player.score}`);
        resetGame();
      }
    }
  });

  powerUps.forEach((powerUp, powerUpIndex) => {
    if (!powerUp.collected && Math.hypot(player.x - powerUp.x, player.y - powerUp.y) < player.radius + 10) {
      powerUps.splice(powerUpIndex, 1);
      player.lives++;
    }
  });
}

function drawPlayer() {
  ctx.save();
  ctx.translate(player.x, player.y);
  ctx.rotate(player.angle);
  drawCircle(ctx, 0, 0, player.radius, 'blue');
  ctx.restore();
}

function drawBullets() {
  bullets.forEach(bullet => {
    drawCircle(ctx, bullet.x, bullet.y, 3, 'white');
  });
}

function drawAsteroids() {
  asteroids.forEach(asteroid => {
    drawCircle(ctx, asteroid.x, asteroid.y, asteroid.size, 'gray');
  });
}

function drawPowerUps() {
  powerUps.forEach(powerUp => {
    if (!powerUp.collected) {
      drawCircle(ctx, powerUp.x, powerUp.y, 5, 'green');
    }
  });
}

function drawScore() {
  drawText(ctx, `Score: ${player.score}`, 20, 30, 20, 'white');
}

function drawLives() {
  drawText(ctx, `Lives: ${player.lives}`, 20, 60, 20, 'white');
}

function resetGame() {
  player.x = canvas.width / 2;
  player.y = canvas.height / 2;
  player.lives = 3;
  player.score = 0;
  asteroids.length = 0;
  bullets.length = 0;
  powerUps.length = 0;
  for (let i = 0; i < 5; i++) {
    createAsteroid();
  }
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  updatePlayer();
  updateBullets();
  updateAsteroids();
  checkCollisions();

  drawPlayer();
  drawBullets();
  drawAsteroids();
  drawPowerUps();
  drawScore();
  drawLives();

  if (asteroids.length === 0) {
    for (let i = 0; i < 5; i++) {
      createAsteroid();
    }
  }

  requestAnimationFrame(update);
}

document.addEventListener('keydown', event => {
  if (event.key === 'ArrowRight') keys.right = true;
  if (event.key === 'ArrowLeft') keys.left = true;
  if (event.key === 'ArrowUp') keys.up = true;
  if (event.key === ' ') keys.space = true;
});

document.addEventListener('keyup', event => {
