    this.crops = [];
  }

  plantCrop(crop) {
    this.crops.push(crop);
  }

  growCrops() {
    this.crops.forEach(crop => crop.grow());
  }

  harvestReadyCrops() {
    return this.crops.filter(crop => crop.isReadyToHarvest()).map(crop => crop.getName());
  }
}

class Market {
  constructor(prices) {
    this.prices = prices;
  }

  sellCrop(cropName) {
    if (this.prices[cropName]) {
      return this.prices[cropName];
    }
    return 0;
  }
}

