class Energy {
  constructor(clock) {
    this.energy = 100;
    this.clock = clock;
  }

  consume(amount) {
    this.energy -= amount;
    if (this.energy < 0) {
      this.energy = 0;
    }
    console.log(`Energy Consumed: ${amount}, Remaining Energy: ${this.energy}`);
  }

  regenerate() {
    if (this.clock.time % 10 === 0) {
      this.energy += 10;
      if (this.energy > 100) {
        this.energy = 100;
      }
      console.log(`Energy Regenerated, New Energy: ${this.energy}`);
    }
  }
}

class Hunger {
  constructor(clock, energy) {
    this.hunger = 0;
    this.clock = clock;
    this.energy = energy;
  }

  eat(amount) {
    this.hunger -= amount;
    if (this.hunger < 0) {
      this.hunger = 0;
    }
    console.log(`Ate: ${amount}, Remaining Hunger: ${this.hunger}`);
  }

  increase() {
    if (this.clock.time % 5 === 0) {
      this.hunger += 5;
      console.log(`Hunger Increased, New Hunger: ${this.hunger}`);
    }
  }

  consumeEnergyForHunger() {
    if (this.hunger > 20) {
      const energyCost = Math.min(this.hunger - 20, this.energy.energy);
      this.energy.consume(energyCost);
      console.log(`Consumed Energy for Hunger: ${energyCost}`);
    }
  }
}

