class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
    return amount;
  }

  credit(amount) {
    this.balance += amount;
  }
}

class Shop {
  constructor(prices) {
    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item];
  }

  purchase(item) {
    return this.prices[item];
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  getInventory() {
    return this.items;
  }
}

class Economy {
  constructor(prices) {
    this.wallet = new Wallet();
    this.shop = new Shop(prices);
    this.inventory = new Inventory();
  }

  setBalance(amount) {
    this.wallet.credit(amount);
  }

  purchaseItem(item) {
    const price = this.shop.getPrice(item);
    if (price === undefined) {
      throw new Error("Item not available");
    }
    const amount = this.wallet.debit(price);
    this.inventory.addItem(item);
    return amount;
  }

  getInventory() {
    return this.inventory.getInventory();
  }

  getBalance() {
    return this.wallet.getBalance();
  }
}

